# ── Thread-safety for terminal output ────────────────────────────────────────
# Concurrent port-scan workers all write to the same stdout.  Without a lock
# their lines interleave into garbage.  Every print() call inside a worker
# (or any function it calls) must hold _PRINT_LOCK via _tprint().
_PRINT_LOCK = threading.Lock()


def _tprint(*args, **kwargs):
    """Thread-safe wrapper for print() — use inside concurrent workers."""
    with _PRINT_LOCK:
        print(*args, **kwargs)


# ─────────────────────────────────────────────
# Vantage integration layer
# ─────────────────────────────────────────────
import queue as _queue
import uuid as _uuid

# Detect when running as a managed subprocess under Vantage
_CRUCIBLE_MANAGED = os.environ.get("CRUCIBLE_MANAGED", "") == "1"

_CP_LOG    = "__CRUCIBLE_LOG__:"
_CP_ERR    = "__CRUCIBLE_ERR__:"
_CP_PROMPT = "__CRUCIBLE_PROMPT__:"
_CP_STATUS = "__CRUCIBLE_STATUS__:"
_CP_TARGET = "__CRUCIBLE_TARGET__:"
_CP_PORT   = "__CRUCIBLE_PORT__:"
_CP_ACTION = "__CRUCIBLE_ACTION_ITEM__:"


class VantageConsole:
    """Dual-mode console output.

    When CRUCIBLE_MANAGED=1: emits protocol tokens that Crucible intercepts for
    structured logs, errors, prompts, and phase-status updates.
    When running in a real terminal: falls back to ANSI-coloured text.
    """

    def __init__(self) -> None:
        self._managed = _CRUCIBLE_MANAGED
        self._lock    = threading.Lock()

    @property
    def managed(self) -> bool:
        return self._managed

    def log(self, message: str, level: str = "INFO") -> None:
        with self._lock:
            if self._managed:
                entry = {
                    "ts":      datetime.now().isoformat(),
                    "level":   level,
                    "message": message,
                }
                sys.stdout.write(_CP_LOG + json.dumps(entry) + "\n")
                sys.stdout.flush()
            else:
                _colours = {
                    "INFO":    Fore.CYAN,
                    "SUCCESS": Fore.GREEN,
                    "WARNING": Fore.YELLOW,
                    "ERROR":   Fore.RED,
                    "DEBUG":   Fore.WHITE,
                }
                _tags = {
                    "INFO": "[*]", "SUCCESS": "[+]", "WARNING": "[~]",
                    "ERROR": "[!]", "DEBUG": "[.]",
                }
                c   = _colours.get(level, "")
                tag = _tags.get(level, "[*]")
                _tprint(f"{c}{tag}{Style.RESET_ALL} {message}")

    def error(self, message: str, source: str = "scattershot3",
              detail: str = "", category: str = "") -> None:
        with self._lock:
            if self._managed:
                entry = {
                    "ts":       datetime.now().isoformat(),
                    "source":   source,
                    "message":  message,
                    "detail":   detail,
                    "category": category or self._categorise(message),
                }
                sys.stderr.write(_CP_ERR + json.dumps(entry) + "\n")
                sys.stderr.flush()
            else:
                _tprint(f"{Fore.RED}[!] {message}{Style.RESET_ALL}")

    def status(self, phase: str, label: str = "", status: str = "running",
               step: str = "", progress: int = 0, total: int = 0,
               tools: "dict | None" = None,
               active_tool: str = "", active_tools: "list | None" = None) -> None:
        _S3_PHASE[0] = phase   # §14h: current phase for per-request HTTP evidence
        with self._lock:
            if self._managed:
                entry = {
                    "phase":    phase,
                    "label":    label or phase,
                    "status":   status,
                    "step":     step,
                    "progress": progress,
                    "total":    total,
                    "ts":       datetime.now().isoformat(),
                }
                if tools is not None:
                    entry["tools"] = tools
                if active_tool:
                    entry["active_tool"] = active_tool
                if active_tools is not None:
                    entry["active_tools"] = active_tools
                sys.stdout.write(_CP_STATUS + json.dumps(entry) + "\n")
                sys.stdout.flush()
        # §14j: persist the phase transition to scan.log + scan.log.json with a
        # timestamp, unconditionally (the status token above is ephemeral / live-UI).
        try:
            with self._log_lock:
                with self.log_file.open("a", encoding="utf-8") as _f:
                    _f.write(f"[{self._ts()}] EVENT phase={phase} status={status}"
                             + (f" step={step}" if step else "") + "\n")
                _append_json_array(self.json_log_file, {
                    "timestamp": self._ts(), "level": "EVENT",
                    "phase": phase, "status": status, "step": step})
        except Exception:
            pass

    def target(self, ip: str, hostname: "str | None" = None,
               scope: "str | None" = None, alive: bool = True,
               source: str = "nmap") -> None:
        """Emit a live target-discovery event so Vantage can incrementally
        update the Targets tab as IPs are confirmed alive (no-op when run
        outside Vantage)."""
        if not self._managed:
            return
        entry = {
            "ts":       datetime.now().isoformat(),
            "ip":       ip,
            "hostname": hostname,
            "scope":    scope,
            "alive":    alive,
            "source":   source,
        }
        with self._lock:
            sys.stdout.write(_CP_TARGET + json.dumps(entry) + "\n")
            sys.stdout.flush()

    def port(self, ip: str, port: int, proto: str = "tcp",
             name: str = "", product: str = "", version: str = "",
             extrainfo: str = "", state: str = "open",
             scope: "str | None" = None,
             hostname: "str | None" = None) -> None:
        """Emit a live port-discovery event so Vantage can incrementally
        update the Targets tab as open ports are found (no-op when run
        outside Vantage)."""
        if not self._managed:
            return
        entry = {
            "ts":        datetime.now().isoformat(),
            "ip":        ip,
            "port":      int(port),
            "proto":     proto,
            "name":      name,
            "product":   product,
            "version":   version,
            "extrainfo": extrainfo,
            "state":     state,
            "scope":     scope,
            "hostname":  hostname,
        }
        with self._lock:
            sys.stdout.write(_CP_PORT + json.dumps(entry) + "\n")
            sys.stdout.flush()

    def action_item(self, entry: dict) -> None:
        """Emit a live action-item event so Vantage can update the
        Action Items tab in real time (no-op outside Vantage)."""
        if not self._managed:
            return
        with self._lock:
            sys.stdout.write(_CP_ACTION + json.dumps(entry) + "\n")
            sys.stdout.flush()

    def prompt(self, question: str, prompt_type: str = "text",
               options: list = None, skippable: bool = False) -> str:
        """Request user input.  Blocks until an answer is received."""
        if self._managed:
            payload = {
                "id":       str(_uuid.uuid4()),
                "question": question,
                "type":     prompt_type,
                "options":  options or [],
                "skippable": skippable,
            }
            with self._lock:
                sys.stdout.write(_CP_PROMPT + json.dumps(payload) + "\n")
                sys.stdout.flush()
            try:
                return sys.stdin.readline().rstrip("\n")
            except Exception:
                return ""
        else:
            if prompt_type == "password":
                import getpass as _gp
                return _gp.getpass(f"  {question}: ")
            elif options:
                _tprint(f"\n[?] {question}")
                for i, opt in enumerate(options, 1):
                    _tprint(f"    [{i}] {opt}")
                raw = input("    Select: ").strip()
                if raw.isdigit():
                    idx = int(raw) - 1
                    if 0 <= idx < len(options):
                        return options[idx]
                return raw
            else:
                return input(f"  [?] {question}: ").strip()

    @staticmethod
    def _categorise(msg: str) -> str:
        m = msg.lower()
        if any(k in m for k in ("connection", "socket", "timeout",
                                  "refused", "network", "unreachable")):
            return "Network"
        if any(k in m for k in ("tool", "binary", "not found",
                                  "command", "executable", "stderr")):
            return "Tool"
        return "Scan"


class ProgressManager:
    """Thread-safe checkpoint manager for scan recovery.

    Persists phase state to a JSON file atomically so that a scan can be
    resumed from the last completed phase after an interruption.
    """

    def __init__(self, checkpoint_file: "str | Path") -> None:
        self._file  = Path(checkpoint_file)
        self._lock  = threading.Lock()
        self._state = self._load()

    def _load(self) -> dict:
        if self._file.exists():
            try:
                data = json.loads(self._file.read_text(encoding="utf-8"))
                data.setdefault("version", 1)
                data.setdefault("started", datetime.now().isoformat())
                data.setdefault("completed_phases", [])
                data.setdefault("phase_status", {})
                data.setdefault("runtime_state", {})
                return data
            except Exception:
                pass
        return {
            "version":          1,
            "started":          datetime.now().isoformat(),
            "completed_phases": [],
            "phase_status":     {},
            "runtime_state":    {},
        }

    def _save(self) -> None:
        import tempfile as _tf
        self._file.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = _tf.mkstemp(dir=str(self._file.parent), suffix=".tmp")
        try:
            os.fchmod(fd, 0o644)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self._state, f, indent=2)
            os.replace(tmp, str(self._file))
        except Exception:
            try:
                os.unlink(tmp)
            except Exception:
                pass

    def is_phase_complete(self, phase: str) -> bool:
        with self._lock:
            return phase in self._state.get("completed_phases", [])

    def set_phase_status(self, phase: str, status: str,
                         label: str = "", detail: str = "") -> None:
        with self._lock:
            self._state.setdefault("phase_status", {})[phase] = {
                "status":     status,
                "label":      label or phase,
                "detail":     detail,
                "updated_at": datetime.now().isoformat(),
            }
            if status == "complete":
                lst = self._state.setdefault("completed_phases", [])
                if phase not in lst:
                    lst.append(phase)
            self._save()

    def get_state(self) -> dict:
        with self._lock:
            return dict(self._state)

    def save_runtime_state(self, state: dict) -> None:
        """Persist runtime accumulators so a resume can restore full scan state."""
        with self._lock:
            self._state["runtime_state"] = state
            self._state["runtime_state"]["_saved_at"] = datetime.now().isoformat()
            self._save()

    def load_runtime_state(self) -> dict:
        with self._lock:
            return dict(self._state.get("runtime_state", {}))

    def get_interrupted_phases(self) -> list:
        """Return phases that were 'running' when the scan was interrupted."""
        with self._lock:
            ps = self._state.get("phase_status", {})
            return [k for k, v in ps.items() if v.get("status") == "running"]

    def prepare_resume(self) -> list:
        """Transition running→pending; remove from completed_phases. Returns affected phase keys."""
        with self._lock:
            interrupted = []
            ps = self._state.get("phase_status", {})
            cp = self._state.get("completed_phases", [])
            for k, v in ps.items():
                if v.get("status") == "running":
                    v["status"] = "pending"
                    v["detail"] = "Interrupted — will re-run on resume"
                    v["updated_at"] = datetime.now().isoformat()
                    interrupted.append(k)
                    if k in cp:
                        cp.remove(k)
            self._save()
            return interrupted


# Module-level singleton console; ProgressManager is created in main()
_vc: VantageConsole = VantageConsole()
_pm: "ProgressManager | None" = None
_pause: "_pp.PauseManager | None" = None  # type: ignore[name-defined]

# Crash-log state — set at main() start so signal handlers can find log files
_CRASH_PROJECT_ROOT: "Path | None" = None


def _write_crash_log(reason: str) -> None:
    """Best-effort: append a crash/stop message to all active scan log files."""
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    msg = f"\n[{ts}] FATAL — {reason}\n"
    if _CRASH_PROJECT_ROOT is None:
        return
    for _scope in ("int", "ext"):
        _scope_dir = _CRASH_PROJECT_ROOT / _scope
        if not _scope_dir.is_dir():
            continue
        for _logname in ("errors.log", "scan.log"):
            try:
                with (_scope_dir / _logname).open("a", encoding="utf-8") as _f:
                    _f.write(msg)
            except Exception:
                pass
    try:
        with (_CRASH_PROJECT_ROOT / "crash.log").open("a", encoding="utf-8") as _f:
            _f.write(msg)
    except Exception:
        pass


def _handle_sigterm(signum, frame):
    reason = (
        "Process terminated by SIGTERM — killed externally "
        "(Crucible stop, Vantage stop, systemd, kill command, or OOM reaper)"
    )
    try:
        _vc.log(f"SIGTERM received — {reason}", "ERROR")
    except Exception:
        pass
    if _pause is not None:
        _pause.write_stop_reason("killed_crucible", reason, initiated_by="external")
    _write_crash_log(reason)
    sys.exit(1)



# ─────────────────────────────────────────────────────────────────────────────
# Credential store — CredentialStore class is defined later in this file,
# after the Responder integration section it depends on.
# ─────────────────────────────────────────────────────────────────────────────

# ─────────────────────────────────────────────────────────────────────────────
# Plaintext credential extraction from web content
# ─────────────────────────────────────────────────────────────────────────────

_CRED_PATTERNS: list[tuple[str, re.Pattern]] = [
    # KEY=VALUE style: password=secret, passwd=secret, pwd=secret
    ("env/config key=value",
     re.compile(
         r"""(?:^|[\s;,\[])(?P<key>password|passwd|pass|pwd|secret|api[_\-]?key|token|auth[_\-]?key)\s*[=:]\s*['"]?(?P<password>[^\s'"&#;,\]]{4,128})""",
         re.IGNORECASE | re.MULTILINE,
     )),
    # URL with embedded credentials: http://user:pass@host
    ("URL embedded credentials",
     re.compile(
         r"""https?://(?P<user>[^:@\s/]{1,64}):(?P<password>[^@\s/]{4,128})@""",
         re.IGNORECASE,
     )),
    # HTTP Basic Auth header: Authorization: Basic <base64>
    ("HTTP Basic Auth header",
     re.compile(
         r"""Authorization:\s*Basic\s+(?P<b64>[A-Za-z0-9+/=]{8,256})""",
         re.IGNORECASE,
     )),
    # HTML form hidden/input field with value
    ("HTML form password field",
     re.compile(
         r"""<input[^>]+type\s*=\s*['"]?password['"]?[^>]+value\s*=\s*['"](?P<password>[^'"]{4,128})['"]""",
         re.IGNORECASE,
     )),
    # PHP/ASP variable assignment: $password = "secret";
    ("PHP/ASP variable assignment",
     re.compile(
         r"""(?:password|passwd|pass|pwd|secret)\s*[=:]\s*['"](?P<password>[^'"]{4,128})['"]""",
         re.IGNORECASE,
     )),
    # JSON key-value: "password": "secret"
    ("JSON credential field",
     re.compile(
         r'''"(?:password|passwd|pass|pwd|secret|token|api[_\-]?key)"\s*:\s*"(?P<password>[^"]{4,128})"''',
         re.IGNORECASE,
     )),
]

# Values that are obviously not real credentials — skip them
_CRED_FALSE_POSITIVE_VALUES: frozenset = frozenset({
    "", "null", "none", "undefined", "true", "false", "your_password",
    "your-password", "changeme", "change_me", "password", "passwd",
    "placeholder", "example", "secret", "xxxxxx", "xxxxxxxx",
    "enter_password_here", "<password>", "${password}", "%(password)s",
    "{password}", "[[password]]",
})

import base64 as _base64


def extract_credentials_from_text(
    text: str,
    source_desc: str,
    ip: str,
    cred_store: "CredentialStore",
) -> int:
    """
    Scan *text* for plaintext credentials using _CRED_PATTERNS.
    Returns the number of new credentials added to cred_store.

    Only adds credentials where the username is non-blank — patterns that
    match a password without an associated username are skipped to reduce
    false positives from config-file value-only matches.
    """
    added = 0
    for pattern_name, pattern in _CRED_PATTERNS:
        for m in pattern.finditer(text):
            gd = m.groupdict()

            # Handle HTTP Basic Auth — decode base64
            if "b64" in gd:
                try:
                    decoded = _base64.b64decode(gd["b64"]).decode("utf-8", errors="replace")
                    if ":" in decoded:
                        user, _, pwd = decoded.partition(":")
                        user = user.strip()
                        # Require non-blank username for web credential harvesting
                        if user and _is_real_cred_value(pwd):
                            if cred_store.add(user, pwd, f"{pattern_name} in {source_desc}", ip=ip):
                                added += 1
                except Exception:
                    pass
                continue

            user = gd.get("user", "").strip()
            pwd  = gd.get("password", "").strip()

            if not _is_real_cred_value(pwd):
                continue

            # Skip entries without a username — reduces false positives from
            # bare key=value password patterns in config files/JS where no
            # corresponding username field was matched.
            if not user:
                continue

            if cred_store.add(user, pwd, f"{pattern_name} in {source_desc}", ip=ip):
                added += 1

    return added


def _is_real_cred_value(value: str) -> bool:
    """Return False for obvious placeholder/false-positive credential values."""
    if not value or len(value) < 4:
        return False
    clean = value.strip("\"'").lower()
    return clean not in _CRED_FALSE_POSITIVE_VALUES


# ── Cross-platform subprocess helpers ────────────────────────────────────────
# On Windows, child processes inherit the parent console by default, causing a
# brief flash of a black CMD window for each nmap / sslscan / nuclei call.
# CREATE_NO_WINDOW suppresses this while still capturing stdout/stderr.
# On Linux/macOS the flag doesn't exist — we supply an empty dict instead.
_SUBPROCESS_FLAGS: dict = (
    {"creationflags": subprocess.CREATE_NO_WINDOW}   # type: ignore[attr-defined]
    if sys.platform == "win32"
    else {}
)


def _popen(cmd: list, **kwargs) -> subprocess.Popen:
    """
    subprocess.Popen wrapper that applies platform-specific flags and
    per-subprocess memory limits.  Go binaries get GOMEMLIMIT in the
    environment instead of RLIMIT_AS (Go pre-reserves huge virtual arenas
    that trip the AS limit long before real memory is consumed).
    """
    if "preexec_fn" not in kwargs and sys.platform != "win32":
        _bin = Path(cmd[0]).stem if cmd else ""
        if _bin in _GO_BINARIES:
            kwargs["preexec_fn"] = _setsid_only_preexec
            env = kwargs.get("env") or dict(os.environ)
            env.setdefault("GOMEMLIMIT", _GO_SUBPROCESS_MEM_LIMIT)
            kwargs["env"] = env
        else:
            kwargs["preexec_fn"] = _mem_limit_preexec
    proc = subprocess.Popen(cmd, **_SUBPROCESS_FLAGS, **kwargs)
    _track_proc(proc)
    return proc


def _run(cmd: list, **kwargs) -> subprocess.CompletedProcess:
    """
    subprocess.run wrapper that applies platform-specific flags and
    per-subprocess memory limits.  Go binaries use GOMEMLIMIT instead.
    """
    if "preexec_fn" not in kwargs and sys.platform != "win32":
        _bin = Path(cmd[0]).stem if cmd else ""
        if _bin in _GO_BINARIES:
            kwargs["preexec_fn"] = _setsid_only_preexec
            env = kwargs.get("env") or dict(os.environ)
            env.setdefault("GOMEMLIMIT", _GO_SUBPROCESS_MEM_LIMIT)
            kwargs["env"] = env
        else:
            kwargs["preexec_fn"] = _mem_limit_preexec
    return subprocess.run(cmd, **_SUBPROCESS_FLAGS, **kwargs)


# Suppress InsecureRequestWarning for verify=False probes.
# Accessed via requests.packages so no separate urllib3 import is needed —
# urllib3 is always present as a requests dependency.
#
# SECURITY NOTE: verify=False is intentional here — we are scanning arbitrary
# hosts whose certificates we do not trust a priori, and the purpose of the
# scan is to discover and *report* certificate problems (done via sslscan /
# testssl).  Suppressing the warning avoids thousands of noisy console lines
# that would obscure actionable output.  Do NOT copy this pattern into
# production application code where certificate validation matters.
requests.packages.urllib3.disable_warnings(
    requests.packages.urllib3.exceptions.InsecureRequestWarning
)

# ─────────────────────────────────────────────
# Module-level constants — performance
# ─────────────────────────────────────────────
#
# Regex patterns and the HTTP session are compiled/created once at import
# time and reused across every function call.  This avoids the overhead of
# re.compile() and connection setup inside tight loops.

# ── Shared HTTP session ───────────────────────────────────────────────────
# A single requests.Session reuses TCP connections (keep-alive) across all
# probe_http() calls, cutting per-request latency and file-descriptor churn.
# The HTTPAdapter caps the connection pool to 20 hosts; fine for sequential
# scanning but can be raised if concurrency is ever added.
from requests.adapters import HTTPAdapter  # noqa: E402  (after _warn_missing_dependencies)

_HTTP_SESSION = requests.Session()
_HTTP_SESSION.mount("https://", HTTPAdapter(pool_connections=20, pool_maxsize=20))
_HTTP_SESSION.mount("http://",  HTTPAdapter(pool_connections=20, pool_maxsize=20))
_HTTP_SESSION.headers.update({"User-Agent": "scattershot3/1.0"})

# §13c/§14h helpers
_S3_PHASE = ["recon"]          # current phase label for per-request HTTP evidence
_S3_EVIDENCE_DIR = [None]      # active scope root; updated as int/ext scopes run


def _set_s3_evidence_dir(d) -> None:
    _S3_EVIDENCE_DIR[0] = str(d) if d else None


def _s3_rel_output_file(output_file_str, root) -> str:
    """Convert a comma/newline-separated output_file string to scope-root-relative paths."""
    if not output_file_str:
        return ""
    out = []
    # Split on both comma and newline so callers can use either delimiter.
    for part in re.split(r"[,\n]", str(output_file_str)):
        part = part.strip()
        if not part:
            continue
        try:
            out.append(str(Path(part).resolve().relative_to(Path(root).resolve())))
        except Exception:
            out.append(part)
    return ",".join(dict.fromkeys(out))


