# ── Precompiled regexes ──────────────────────────────────────────────────
# Patterns used inside scan/parse loops that would otherwise be recompiled
# on every iteration.  Named with a leading underscore to flag them as
# private module-level constants rather than public API.

# Infrastructure cookie patterns — load balancer, CDN, WAF, reverse-proxy
# cookies whose missing security flags are not a session-hijack vector.
_INFRA_COOKIE_RE = re.compile(
    r'^(BIGipServer|AWSALB|AWSELB|__cf|_cf_bm|cf_clearance|'
    r'incap_ses|visid_incap|nlbi_|GCLB|SERVERID|HAProxy|'
    r'route|__RequestVerificationToken|__AntiXsrf|'
    r'AWSALBCORS|AWSELBCORS|__cflb|__cfruid|'
    r'pps_magic|AzureAppProxy)',
    re.I,
)


def _is_deletion_cookie(sc_raw: str) -> bool:
    """Return True when a Set-Cookie header is a deletion instruction."""
    parts = sc_raw.split(";")
    nv = parts[0].strip()
    val = nv.split("=", 1)[1].strip() if "=" in nv else ""
    if val and val not in ('""', "''"):
        return False
    for p in parts[1:]:
        p = p.strip().lower()
        if p.startswith("expires=") and ("1970" in p or "1969" in p):
            return True
        if p.startswith("max-age="):
            try:
                if int(p[8:].strip()) <= 0:
                    return True
            except ValueError:
                pass
    return False


# HTML <title> extraction used in probe_http()
_RE_TITLE      = re.compile(r"<title[^>]*>(.*?)</title>", re.IGNORECASE | re.DOTALL)

# sslscan output patterns
_RE_SS_PROTO   = re.compile(r"(SSLv[23]|TLSv[\d.]+)\s+(enabled|disabled)", re.IGNORECASE)
_RE_SS_CIPHER  = re.compile(r"Accepted\s+(\S+)\s+(\d+)\s+bits\s+(\S+)", re.IGNORECASE)
_RE_SS_SUBJECT = re.compile(r"Subject:\s+(.+)")
_RE_SS_ISSUER  = re.compile(r"Issuer:\s+(.+)")
_RE_SS_EXPIRY  = re.compile(r"Not valid after:\s+(.+)", re.IGNORECASE)
_RE_SS_SELF    = re.compile(r"self[- ]signed", re.IGNORECASE)
_RE_SS_VERIFY  = re.compile(r"certificate verify ok", re.IGNORECASE)
_RE_SS_HB      = re.compile(r"heartbleed.*?(vulnerable|not vulnerable|safe)", re.IGNORECASE)

# testssl output patterns
_RE_TS_PROTO   = re.compile(
    # testssl 3.x uses "TLS 1", "TLS 1.1", "TLS 1.2", "TLS 1.3" (space-separated,
    # not dot-prefix like TLSv1).  "SSLv2"/"SSLv3" keep their original form.
    r"(SSLv[23]|TLS\s+[\d.]+)\s+(offered|not offered)(.*)", re.IGNORECASE
)
_RE_TS_VULN    = re.compile(
    r"(Heartbleed|ROBOT|BEAST|POODLE|CRIME|BREACH|DROWN|LOGJAM|"
    r"FREAK|Sweet32|LUCKY13|RC4|TICKETBLEED|GOLDENDOODLE|"
    r"0-RTT|RACCOON|Zombie POODLE|Sleeping POODLE|POODLE.*TLS)\s+(.*)",
    re.IGNORECASE,
)
# testssl cipher *category* lines — a whole class offered/not offered, e.g.:
#   " LOW: 64 Bit + DES, RC[2,4], MD5 (w/o export)   not offered (OK)"
#   " Triple DES Ciphers / IDEA   offered"
#   " NULL ciphers (no encryption)   not offered (OK)"
_RE_TS_CIPHER_CAT = re.compile(
    r"^\s*(NULL ciphers?|Anonymous.*Ciphers?|Export ciphers?|LOW[:\s].*|"
    r"Triple DES.*|Obsoleted CBC.*)\s+(not offered|offered)(.*)",
    re.IGNORECASE,
)
# Individual accepted cipher lines from testssl --show-each output:
#   " xc02c   ECDHE-ECDSA-AES256-GCM-SHA384   ECDH 521   AESGCM   256   TLS_..."
_RE_TS_CIPHER_LINE = re.compile(
    r"^\s*x[0-9a-f]{4}\s+(\S+)\s+\S+\s+\S+\s+(\d+)",
    re.IGNORECASE,
)
# Kept for compat; no longer drives cipher findings (superseded by _RE_TS_CIPHER_CAT)
_RE_TS_CIPHER  = re.compile(r"(LOW|MEDIUM|HIGH|CRITICAL|WARN|OK|INFO)\s+(.+)")
_RE_TS_SUBJECT = re.compile(r"subject\s*[:/]\s*(.+)", re.IGNORECASE)
_RE_TS_ISSUER  = re.compile(r"issuer\s*[:/]\s*(.+)", re.IGNORECASE)
_RE_TS_EXPIRY  = re.compile(r"expires\s*[:/]\s*(.+)", re.IGNORECASE)
_RE_TS_SAN     = re.compile(r"subjectAltName.*?:\s*(.+)", re.IGNORECASE)
_RE_TS_GRADE   = re.compile(r"Overall Grade\s*[:\-]\s*([A-F][+-]?)", re.IGNORECASE)

# Protocol weakness checks (shared between sslscan + testssl parsing)
# Note: testssl 3.x outputs "TLS 1" and "TLS 1.1" (space-separated); sslscan
# outputs "TLSv1" and "TLSv1.1".  Both forms handled here.
_RE_SSL2       = re.compile(r"SSLv2", re.IGNORECASE)
_RE_SSL3       = re.compile(r"SSLv3", re.IGNORECASE)
_RE_WEAK_SSL   = re.compile(r"SSLv2|SSLv3", re.IGNORECASE)
_RE_WEAK_TLS   = re.compile(
    # Matches both sslscan "TLSv1"/"TLSv1.1" and testssl "TLS 1"/"TLS 1.1" forms.
    # Negative lookahead (?!\s*[23]|\.[23]) prevents TLS 1.2/1.3 from matching.
    r"TLSv1(?:\.0|\.1|(?!\.[23]))\b|TLS\s+1(?:\.[01]|\s|$)(?!\.[23])",
    re.IGNORECASE,
)
_RE_WEAK_PROTO = re.compile(
    r"SSLv|TLSv1(?:\.0|\.1|(?!\.[23]))\b|TLS\s+1(?:\.[01]|\s|$)(?!\.[23])",
    re.IGNORECASE,
)


def _proto_risk(proto_name: str) -> str:
    """Return the appropriate risk level for a deprecated/weak protocol.

    SSLv2            → HIGH    (broken, DROWN-class attacks)
    SSLv3            → MEDIUM  (POODLE; less commonly exposed now)
    TLS 1.0 / 1.1   → LOW     (deprecated by RFC 8996; low practical risk)
    """
    if _RE_SSL2.search(proto_name):
        return "HIGH"
    if _RE_SSL3.search(proto_name):
        return "MEDIUM"
    return "LOW"

# Weak cipher name check used in sslscan parsing + print_ssl_results
_RE_WEAK_CIPHER = re.compile(r"RC4|DES|EXPORT|NULL|anon|MD5|3DES", re.IGNORECASE)

# Banner sanitisation (used in _sanitize_banner)
_RE_BANNER_CTRL  = re.compile(r"[^\x09\x0a\x0d\x20-\x7e]")  # non-printable chars
_RE_BLANK_LINES  = re.compile(r"\n{3,}")                      # excessive blank lines

# Filename safety (used in OutputManager._safe_filename)
_RE_UNSAFE_FNAME = re.compile(r"[^\w.\-]")

# Semver extraction (used in get_tool_version)
_RE_SEMVER       = re.compile(r"(\d+\.\d+[\.\d]*(?:[-\w]+)?)")

# sslscan --version output parsing
