_RE_SSLSCAN_VER    = re.compile(r"Version\s+([\d]+\.[\d.]+[\w.-]*)", re.IGNORECASE)
_RE_SSLSCAN_OPENSSL = re.compile(r"OpenSSL\s+([\d]+\.[\d.]+\w*)", re.IGNORECASE)

# ANSI escape-code stripper — removes colour/style codes from tool output
_RE_ANSI = re.compile(r'\x1b(?:\[[0-9;]*[A-Za-z]|[^[])')

