def _identify_service_via_nc(ip: str, port: int, proto: str = "tcp",
                             timeout: int = 5) -> "tuple[str, str]":
    """Probe a single TCP port with netcat-equivalent to elicit a banner.

    Returns (banner_first_line, full_response_bytes_text). Empty strings
    on connection failure or timeout. Used both as a service-identification
    fallback for nmap's "unknown" results AND as the non-web evidence
    capture for Phase F.
    """
    import socket as _socket_nc
    try:
        with _socket_nc.create_connection((ip, port), timeout=timeout) as _sk:
            _sk.settimeout(timeout)
            # Send a generic probe that elicits responses from most TCP
            # banners (HTTP, FTP, SSH, SMTP, Redis, etc.). Many services
            # banner on connect without input; for those that don't this
            # carriage-return-newline often nudges a usage message out.
            try:
                _sk.sendall(b"\r\n")
            except OSError:
                pass
            try:
                _buf = b""
                while len(_buf) < 4096:
                    _chunk = _sk.recv(2048)
                    if not _chunk:
                        break
                    _buf += _chunk
            except (OSError, _socket_nc.timeout):
                _buf = b""
    except (OSError, _socket_nc.timeout, ValueError):
        return ("", "")
    _txt = _buf.decode("utf-8", errors="replace") if _buf else ""
    _first = _txt.splitlines()[0][:200] if _txt else ""
    return (_first, _txt)


_SENSITIVE_ROBOTS_PATTERNS = re.compile(
    r"(?:admin|backup|config|\.env|\.git|\.svn|\.htaccess|\.htpasswd|"
    r"wp-admin|phpmyadmin|cgi-bin|server-status|server-info|\.sql|"
    r"\.bak|\.old|\.orig|private|secret|credentials|api[/-]?key|"
    r"debug|console|staging|test|internal|phpinfo|\.log|\.xml|"
    r"sitemap|\.json|\.yaml|\.yml|\.conf|\.ini|\.sh|\.bash|"
    r"\.db|\.sqlite|upload|dump|export)",
    re.IGNORECASE,
)


def _analyze_robots_txt(body: str) -> "list[str]":
    """Return sensitive Disallow paths found in a robots.txt body."""
    hits = []
    for line in body.splitlines():
        stripped = line.strip()
        if stripped.lower().startswith("disallow:"):
            path = stripped.split(":", 1)[1].strip()
            if path and _SENSITIVE_ROBOTS_PATTERNS.search(path):
                hits.append(path)
    return hits


def _curl_probe_web(ip: str, port: int, scheme: str = "http",
                    timeout: int = 8) -> dict:
    """Run a curl GET against a web port and return {url, status, headers,
    body, time_total, redirect, raw_request_estimate}. Used for Phase E
    evidence capture. Falls back to requests when curl is unavailable.
    """
    if (scheme == "https" and port == 443) or (scheme == "http" and port == 80):
        _url = f"{scheme}://{ip}/"
    else:
        _url = _clean_url(scheme, ip, port)
    _curl = shutil.which("curl")
    if _curl:
        # Capture status, headers, body, and timing in one shot.
        try:
            _proc = subprocess.run(
                [_curl, "-sk", "-D", "-",
                 "--max-time", str(timeout),
                 "-w", "\n\n__TIMING__\n%{http_code}\n%{time_total}\n%{redirect_url}\n",
                 _url],
                capture_output=True, text=True, timeout=timeout + 2,
                errors="replace",
            )
            _raw = _proc.stdout or ""
            # Split header section from body and the trailing __TIMING__ block.
            _hdr_part, _body_part = "", _raw
            if "\r\n\r\n" in _raw:
                _hdr_part, _body_part = _raw.split("\r\n\r\n", 1)
            _timing = ""
            if "\n\n__TIMING__\n" in _body_part:
                _body_part, _timing = _body_part.split("\n\n__TIMING__\n", 1)
            _t_lines = _timing.strip().splitlines()
            _status   = _t_lines[0] if len(_t_lines) > 0 else ""
            _time_tot = _t_lines[1] if len(_t_lines) > 1 else ""
            _redirect = _t_lines[2] if len(_t_lines) > 2 else ""
            return {
                "url":          _url,
                "scheme":       scheme,
                "status":       _status,
                "headers":      _hdr_part.strip(),
                "body":         _body_part,
                "time_total":   _time_tot,
                "redirect":     _redirect,
                "tool":         "curl",
                "cmd":          f"curl -sk -D - --max-time {timeout} {_url}",
            }
        except (subprocess.TimeoutExpired, OSError):
            return {"url": _url, "scheme": scheme, "status": "", "headers": "",
                    "body": "", "time_total": "", "redirect": "",
                    "tool": "curl", "cmd": "(timeout / OS error)"}
    return {"url": _url, "scheme": scheme, "status": "", "headers": "",
            "body": "", "time_total": "", "redirect": "",
            "tool": "curl-unavailable", "cmd": ""}


def probe_uncertain_and_nonstandard_ports(
    ip: str,
    results: "dict[int, dict]",
    output_mgr: "OutputManager | None",
    hostname: "str | None" = None,
) -> None:
    """Phase D + E + F + G unified post-port-scan helper.

    For every open port in *results*:
      • If nmap left service unknown / tcpwrapped / blank → netcat-probe
        to elicit a banner (Phase D — service identification).
      • If the port is a known WEB port OR the service looks web →
        curl-probe and save the response as web/<port>/ evidence
        (Phase E).
      • Otherwise → netcat-probe and save the captured bytes as
        services/<port>_<service>.txt evidence (Phase F).
      • If the (service, port) pair is "uncommon" — service identified
        but running on a port other than its standard — emit an
        informational finding (Phase G).
      • If the port is a web port not in the canonical WEB_PORTS list,
        emit a "Non-Standard Web Port" informational finding.
    """
    if output_mgr is None or not results:
        return

    _scanner_ips = _get_local_ips()
    _host_dir = output_mgr.host_path(ip)
    for _port, _pinfo in sorted(results.items()):
        if not isinstance(_pinfo, dict):
            continue
        _svc_raw     = (_pinfo.get("name") or "").strip().lower()
        _product     = (_pinfo.get("product") or "").strip()
        _service     = _svc_raw
        _identified_via = ""

        # ── Phase D: identify the service when nmap left it blank/unknown ──
        if not _svc_raw or _svc_raw in ("unknown", "tcpwrapped"):
            _banner_first, _banner_full = _identify_service_via_nc(ip, _port)
            if _banner_first:
                # Coarse identification from the first banner line
                _bl = _banner_first.lower()
                if _bl.startswith("ssh-"):                 _service = "ssh"
                elif _bl.startswith(("http/", "html ")):    _service = "http"
                elif _bl.startswith("220 "):                _service = "ftp"
                elif _bl.startswith("220-") and "ftp" in _bl: _service = "ftp"
                elif _bl.startswith("220 ") and "smtp" in _bl: _service = "smtp"
                elif _bl.startswith("-err") or _bl.startswith("+ok"): _service = "pop3"
                elif _bl.startswith("* ok"):                _service = "imap"
                elif _bl.startswith("+pong") or _bl.startswith("+ok pong"): _service = "redis"
                elif "mysql" in _bl:                        _service = "mysql"
                elif "rfb 0" in _bl:                        _service = "vnc"
                else:
                    _service = "unknown"
                if _service != "unknown":
                    _identified_via = "nc-banner"
                    _pinfo["name"]    = _service
                    _pinfo["banner"]  = _pinfo.get("banner") or {}
                    if isinstance(_pinfo["banner"], dict):
                        _pinfo["banner"]["banner"] = _banner_first
                        _pinfo["banner"]["raw_bytes"] = len(_banner_full or "")

        # ── Phase D.2: service-specific unauthenticated probes ────────────
        # GAP-01: Docker API (2375/2376)
        if _port in (2375, 2376):
            try:
                _dk_scheme = "https" if _port == 2376 else "http"
                _dk_resp = _HTTP_SESSION.get(
                    f"{_dk_scheme}://{ip}:{_port}/version",
                    timeout=5, verify=False)
                if _dk_resp.status_code == 200:
                    try:
                        _dk_data = _dk_resp.json()
                        if "ApiVersion" in _dk_data or "Version" in _dk_data:
                            output_mgr.log_finding(
                                title="Unauthenticated Docker API Accessible",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -sk {_dk_scheme}://{ip}:{_port}/version",
                                risk="CRITICAL",
                                description=(
                                    f"The Docker Engine API is accessible without "
                                    f"authentication at {ip}:{_port}. An attacker "
                                    f"can create privileged containers, mount the host "
                                    f"filesystem, execute arbitrary commands on the host, "
                                    f"and achieve full host compromise."
                                ),
                                output=json.dumps(_dk_data)[:500],
                                sources="scattershot3-docker-probe",
                                affected=f"{ip}:{_port}",
                            )
                    except Exception:
                        pass
            except Exception:
                pass

        # GAP-03: CouchDB (5984)
        if _port == 5984:
            try:
                _cdb_resp = _HTTP_SESSION.get(
                    f"http://{ip}:{_port}/_all_dbs",
                    timeout=5, verify=False)
                if _cdb_resp.status_code == 200:
                    try:
                        _cdb_data = _cdb_resp.json()
                        if isinstance(_cdb_data, list) and len(_cdb_data) > 0:
                            output_mgr.log_finding(
                                title="CouchDB Unauthenticated Database Listing",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -s http://{ip}:{_port}/_all_dbs",
                                risk="CRITICAL",
                                description=(
                                    f"CouchDB at {ip}:{_port} allows unauthenticated "
                                    f"access to /_all_dbs, listing {len(_cdb_data)} "
                                    f"databases. An attacker can read/modify/delete "
                                    f"all database contents."
                                ),
                                output=f"Databases: {json.dumps(_cdb_data)[:300]}",
                                sources="scattershot3-couchdb-probe",
                                affected=f"{ip}:{_port}",
                            )
                    except Exception:
                        pass
            except Exception:
                pass

        # GAP-05: Grafana unauthenticated API (3000)
        if _port == 3000:
            try:
                _gf_resp = _HTTP_SESSION.get(
                    f"http://{ip}:{_port}/api/org",
                    timeout=5, verify=False)
                if _gf_resp.status_code == 200:
                    try:
                        _gf_data = _gf_resp.json()
                        if "name" in _gf_data or "id" in _gf_data:
                            output_mgr.log_finding(
                                title="Grafana API Accessible Without Authentication",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -s http://{ip}:{_port}/api/org",
                                risk="HIGH",
                                description=(
                                    f"The Grafana API at {ip}:{_port} responds to "
                                    f"unauthenticated requests. An attacker can access "
                                    f"dashboards, data sources (which may contain database "
                                    f"credentials), and organization configuration."
                                ),
                                output=json.dumps(_gf_data)[:300],
                                sources="scattershot3-grafana-probe",
                                affected=f"{ip}:{_port}",
                            )
                    except Exception:
                        pass
            except Exception:
                pass

        # GAP-06: Kibana unauthenticated API (5601)
        if _port == 5601:
            try:
                _kb_resp = _HTTP_SESSION.get(
                    f"http://{ip}:{_port}/api/status",
                    timeout=5, verify=False,
                    headers={"kbn-xsrf": "true"})
                if _kb_resp.status_code == 200:
                    try:
                        _kb_data = _kb_resp.json()
                        if "version" in _kb_data or "status" in _kb_data:
                            output_mgr.log_finding(
                                title="Kibana API Accessible Without Authentication",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -s -H 'kbn-xsrf: true' http://{ip}:{_port}/api/status",
                                risk="HIGH",
                                description=(
                                    f"The Kibana API at {ip}:{_port} responds to "
                                    f"unauthenticated requests. An attacker can access "
                                    f"Elasticsearch indices, read log data, and potentially "
                                    f"execute queries against backend data stores."
                                ),
                                output=json.dumps(_kb_data)[:300],
                                sources="scattershot3-kibana-probe",
                                affected=f"{ip}:{_port}",
                            )
                    except Exception:
                        pass
            except Exception:
                pass

        # GAP-07: Cassandra native protocol (9042)
        if _port == 9042 and _service in ("", "unknown", "tcpwrapped", "cassandra"):
            try:
                _cass_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                _cass_sock.settimeout(5)
                _cass_sock.connect((ip, _port))
                _cass_options = bytes([
                    0x04,  # version 4
                    0x00,  # flags
                    0x00, 0x00,  # stream id
                    0x05,  # opcode OPTIONS
                    0x00, 0x00, 0x00, 0x00,  # length 0
                ])
                _cass_sock.sendall(_cass_options)
                _cass_reply = _cass_sock.recv(1024)
                _cass_sock.close()
                if len(_cass_reply) >= 9 and _cass_reply[4] == 0x06:
                    output_mgr.log_finding(
                        title="Cassandra Native Protocol Accessible Without Authentication",
                        ip=ip, port=_port, hostname=hostname,
                        command=f"cqlsh {ip} {_port}",
                        risk="HIGH",
                        description=(
                            f"Cassandra at {ip}:{_port} responded to a native protocol "
                            f"OPTIONS request without authentication. An attacker can "
                            f"connect with cqlsh and read/modify all keyspaces and tables."
                        ),
                        output=f"CQL protocol v4 SUPPORTED response received ({len(_cass_reply)} bytes)",
                        sources="scattershot3-cassandra-probe",
                        affected=f"{ip}:{_port}",
                    )
            except Exception:
                pass

        # GAP-02: PostgreSQL trust authentication (5432)
        if _port == 5432 and _service in ("", "unknown", "tcpwrapped", "postgresql"):
            try:
                _pg_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                _pg_sock.settimeout(5)
                _pg_sock.connect((ip, _port))
                _pg_user = b"postgres"
                _pg_db = b"postgres"
                _pg_startup = (
                    b"\x00\x03\x00\x00"  # protocol 3.0
                    + b"user\x00" + _pg_user + b"\x00"
                    + b"database\x00" + _pg_db + b"\x00"
                    + b"\x00"
                )
                _pg_len = len(_pg_startup) + 4
                _pg_msg = _pg_len.to_bytes(4, "big") + _pg_startup
                _pg_sock.sendall(_pg_msg)
                _pg_reply = _pg_sock.recv(1024)
                _pg_sock.close()
                if _pg_reply and _pg_reply[0:1] == b"R":
                    _pg_auth_type = int.from_bytes(_pg_reply[5:9], "big") if len(_pg_reply) >= 9 else -1
                    if _pg_auth_type == 0:
                        output_mgr.log_finding(
                            title="PostgreSQL Trust Authentication — No Password Required",
                            ip=ip, port=_port, hostname=hostname,
                            command=f"psql -h {ip} -p {_port} -U postgres -d postgres",
                            risk="CRITICAL",
                            description=(
                                f"PostgreSQL at {ip}:{_port} accepted a connection as "
                                f"user 'postgres' without requiring a password (trust "
                                f"authentication). An attacker gains full database "
                                f"superuser access including data, OS command execution "
                                f"via COPY/lo_*, and file read/write."
                            ),
                            output="AuthenticationOk (auth type 0) received without password",
                            sources="scattershot3-postgresql-probe",
                            affected=f"{ip}:{_port}",
                        )
            except Exception:
                pass

        # ── Phase E: web ports → curl probe, save evidence ─────────────────
        # Only treat a port as web when curl actually returns a real HTTP
        # response code (100–599). curl's -w %{http_code} writes the
        # literal string "000" when the port accepts TCP but doesn't
        # speak HTTP (raw banner, reset mid-handshake, etc.) — that's a
        # non-empty truthy string and used to slip past the previous
        # `if _r["status"]` gate, polluting hosts/<ip>/web/<port>/ with
        # curl evidence for non-HTTP services AND emitting bogus "Non-
        # Standard Web Port Detected" findings on plain banner ports.
        _is_web_port_known = _port in WEB_PORTS
        _is_web_via_name   = port_looks_like_web(_port, _service)
        _got_http = False
        if _is_web_via_name:
            for _scheme in (("https",) if (_port in (443, 8443, 4443, 7443, 9443)
                                          or _service in ("https", "ssl/http",
                                                           "ssl/https", "https-alt"))
                            else ("http", "https")):
                _r = _curl_probe_web(ip, _port, _scheme)
                try:
                    _status_int = int(_r["status"])
                except (ValueError, TypeError):
                    _status_int = 0
                if not (100 <= _status_int <= 599):
                    continue   # not a real HTTP response — try next scheme
                _got_http = True
                _web_dir = output_mgr.web_path(ip, _port)
                _web_dir.mkdir(parents=True, exist_ok=True)
                _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                _curl_path = _web_dir / f"{ip.replace('.', '_')}_{_port}_curl_{_scheme}_{_ts}.txt"
                try:
                    _curl_path.write_text(
                        (f"URL: {_r['url']}\n"
                         f"Status: {_r['status']}\n"
                         f"Time (s): {_r['time_total']}\n"
                         f"Redirect: {_r['redirect']}\n"
                         f"Command: {_r['cmd']}\n"
                         f"\n--- HEADERS ---\n{_r['headers']}\n"
                         f"\n--- BODY (first 8 KB) ---\n{(_r['body'] or '')[:8192]}\n"),
                        encoding="utf-8",
                    )
                    output_mgr.log_command(
                        _r["tool"], "curl", _r["cmd"], _curl_path,
                        extra={"target": f"{ip}:{_port}",
                               "scheme": _scheme,
                               "http_status": _r["status"]},
                    )
                    # Phase G: non-standard web port informational finding
                    if not _is_web_port_known:
                        output_mgr.log_finding(
                            title="Non-Standard Web Port Detected",
                            ip=ip, port=_port, hostname=hostname,
                            command=_r["cmd"], risk="INFO",
                            description=(
                                f"A web service responding to {_scheme.upper()} "
                                f"was identified on port {_port}, which is not "
                                f"in the canonical web-port list. Custom-port "
                                f"web services increase the chance of being "
                                f"missed by routine vulnerability scans and "
                                f"often run with default credentials / dev "
                                f"settings. Verify the service is intentional, "
                                f"properly hardened, and included in regular "
                                f"vulnerability management."
                            ),
                            output=(
                                f"URL: {_r['url']}\n"
                                f"HTTP status: {_r['status']}\n"
                                f"Curl command: {_r['cmd']}"
                            ),
                            sources="fracture-recon-port",
                            affected=f"{ip}:{_port}",
                            output_file=str(_curl_path.relative_to(output_mgr.root)),
                        )
                    # Phase G.3: internal IP disclosure in response body/headers
                    _rfc1918_text = (_r.get("body") or "") + "\n" + (_r.get("headers") or "")
                    _rfc1918_found = set()
                    for _m in _RE_RFC1918_IN_TEXT.finditer(_rfc1918_text):
                        _candidate = _m.group(1)
                        if _candidate == ip or _candidate in _scanner_ips:
                            continue
                        try:
                            _caddr = ipaddress.ip_address(_candidate)
                            if any(_caddr in _net for _net in _RFC1918_NETWORKS):
                                _rfc1918_found.add(_candidate)
                        except ValueError:
                            pass
                    if _rfc1918_found:
                        _rfc_risk = "MEDIUM" if getattr(output_mgr, "scope", "ext") == "ext" else "LOW"
                        _rfc_ips_str = ", ".join(sorted(_rfc1918_found))
                        output_mgr.log_finding(
                            title="Information Disclosure: Internal IP in HTTP Response",
                            ip=ip, port=_port, hostname=hostname,
                            command=_r["cmd"], risk=_rfc_risk,
                            description=(
                                f"The HTTP response from {_scheme}://{ip}:{_port}/ "
                                f"contains RFC 1918 private IP address(es): "
                                f"{_rfc_ips_str}. This discloses internal network "
                                f"topology to external observers, aiding "
                                f"reconnaissance and potentially enabling "
                                f"targeted attacks against internal hosts."
                            ),
                            output=(
                                f"Disclosed internal IP(s): {_rfc_ips_str}\n"
                                f"Source URL: {_r['url']}\n"
                                f"HTTP status: {_r['status']}"
                            ),
                            sources="scattershot3-curl-probe",
                            affected=f"{ip}:{_port}",
                            output_file=str(_curl_path.relative_to(output_mgr.root)),
                        )
                    # Phase G.4: outdated / unnecessary website detection
                    _od_body = (_r.get("body") or "")
                    _od_hdrs = (_r.get("headers") or "")
                    _od_indicators = []
                    _od_body_len = len(_od_body)
                    # Skip SPA shells — minimal HTML with a JS app mount point
                    _is_spa_shell = (
                        _od_body_len < 4000
                        and re.search(r'<div\s+id=["\'](?:app|root|__next|__nuxt)["\']', _od_body, re.IGNORECASE)
                        and re.search(r'<script\b', _od_body, re.IGNORECASE)
                    )
                    if not _is_spa_shell:
                        # 1. Copyright year > 2 years old (skip JS library footers)
                        _od_copy_re = re.compile(
                            r'(?:©|\b[Cc]opyright)\s*(?:©\s*)?(\d{4})'
                        )
                        # Strip <script>…</script> blocks to avoid JS library dates
                        _od_body_noscript = re.sub(
                            r'<script\b[^>]*>.*?</script>', '', _od_body,
                            flags=re.DOTALL | re.IGNORECASE,
                        )
                        for _yr_m in _od_copy_re.finditer(_od_body_noscript):
                            _yr_val = int(_yr_m.group(1))
                            if 1990 <= _yr_val <= datetime.now().year - 2:
                                _od_indicators.append(
                                    f"Copyright year {_yr_val} (>{datetime.now().year - _yr_val} years old)"
                                )
                                break  # one copyright hit is enough
                        # 2. Under-construction / placeholder phrases
                        _od_construction = [
                            r'\bunder\s+construction\b',
                            r'\bcoming\s+soon\b',
                            r'\bsite\s+maintenance\b',
                            r'\bcheck\s+back\s+later\b',
                            r'\blaunching\s+soon\b',
                            r'\bbeing\s+updated\b',
                            r'\bunder\s+development\b',
                            r'\bparked\s+domain\b',
                        ]
                        for _cpat in _od_construction:
                            if re.search(_cpat, _od_body, re.IGNORECASE):
                                _od_indicators.append(
                                    f"Page contains placeholder text matching '{_cpat.replace(chr(92)+'b','').strip()}'"
                                )
                        # 3. Default server / CMS pages
                        #    "It works!" only counts on short pages (likely entire body)
                        _od_defaults = [
                            (r'Apache2?\s+.{0,30}Default\s+Page', 'Apache default page'),
                            (r'Welcome\s+to\s+nginx', 'Nginx default page'),
                            (r'IIS\s+Windows\s+Server', 'IIS default page'),
                            (r'Plesk\s+Default\s+Page', 'Plesk default page'),
                            (r'\byour\s+cPanel\b', 'cPanel default page'),
                            (r'Hello\s+world!.*?WordPress', 'WordPress default page'),
                            (r'Just\s+another\s+WordPress\s+site', 'WordPress default tagline'),
                            (r'Congratulations.*?\byour\s+new\s+site\b', 'Default CMS page'),
                            (r'Apache\s+HTTP\s+Server\s+Test\s+Page', 'Apache test page'),
                        ]
                        for _dpat, _dlabel in _od_defaults:
                            if re.search(_dpat, _od_body, re.IGNORECASE):
                                _od_indicators.append(_dlabel)
                        # "It works!" — only on small pages where it's likely the whole body
                        if _od_body_len < 2000 and re.search(r'\bIt\s+works!\s*', _od_body):
                            _od_indicators.append('Apache "It works!" test page')
                        # 4. Last-Modified header older than 2 years
                        _od_lm = re.search(r'Last-Modified:\s*(.+)', _od_hdrs, re.IGNORECASE)
                        if _od_lm:
                            try:
                                from email.utils import parsedate_to_datetime as _parsedate
                                _od_lm_dt = _parsedate(_od_lm.group(1).strip())
                                _od_age = (datetime.now(_od_lm_dt.tzinfo) - _od_lm_dt).days
                                if _od_age > 730:
                                    _od_indicators.append(
                                        f"Last-Modified header is {_od_age} days old ({_od_lm.group(1).strip()})"
                                    )
                            except Exception:
                                pass
                    if _od_indicators:
                        _od_ind_str = "; ".join(_od_indicators)
                        output_mgr.log_finding(
                            title="Unnecessary/Outdated Website Available",
                            ip=ip, port=_port, hostname=hostname,
                            command=_r["cmd"], risk="INFO",
                            description=(
                                f"The website at {ip}:{_port} shows signs of being "
                                f"outdated or unnecessary: {_od_ind_str}. Outdated "
                                f"websites may contain unpatched vulnerabilities, use "
                                f"deprecated frameworks, or expose unnecessary attack "
                                f"surface."
                            ),
                            output=(
                                "Indicators found:\n"
                                + "\n".join(f"  - {_i}" for _i in _od_indicators)
                            ),
                            sources="scattershot3-curl-probe",
                            affected=f"{ip}:{_port}",
                            output_file=str(_curl_path.relative_to(output_mgr.root)),
                        )
                    # Phase G.5: .git exposure (SS-078)
                    try:
                        _git_r = subprocess.run(
                            f"curl -sk --max-time 5 {_scheme}://{_curl_host}:{_port}/.git/HEAD",
                            shell=True, capture_output=True, timeout=10,
                        )
                        _git_body = _git_r.stdout.decode("utf-8", errors="replace").strip()
                        if "ref: refs/" in _git_body:
                            output_mgr.log_finding(
                                title="Git Repository Exposed via Web",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -sk {_scheme}://{_curl_host}:{_port}/.git/HEAD",
                                risk="HIGH",
                                description=(
                                    f"The web server at {_scheme}://{ip}:{_port} exposes "
                                    f"a .git directory. The /.git/HEAD file returned a valid "
                                    f"Git ref. An attacker can reconstruct the full source "
                                    f"code repository, including commit history, credentials "
                                    f"in old commits, and internal configuration. Block access "
                                    f"to .git directories in the web server configuration."
                                ),
                                output=f".git/HEAD content: {_git_body[:256]}",
                                sources="scattershot3-curl-probe",
                                affected=f"{ip}:{_port}",
                                output_file=str(_curl_path.relative_to(output_mgr.root)),
                            )
                            _tprint(
                                f"  {Fore.RED}[!!!] .git exposed {_scheme}://{ip}:{_port}{Style.RESET_ALL}"
                            )
                    except Exception:
                        pass
                    # Phase G.6: HTTP methods enumeration (SS-079/SS-080)
                    try:
                        _opt_r = subprocess.run(
                            f"curl -sk --max-time 5 -X OPTIONS -I {_scheme}://{_curl_host}:{_port}/",
                            shell=True, capture_output=True, timeout=10,
                        )
                        _opt_out = _opt_r.stdout.decode("utf-8", errors="replace")
                        _allow_match = re.search(r"(?i)^allow:\s*(.+)$", _opt_out, re.MULTILINE)
                        if _allow_match:
                            _methods = [m.strip().upper() for m in _allow_match.group(1).split(",")]
                            _dangerous = [m for m in _methods if m in ("PUT", "DELETE", "MOVE", "COPY", "PROPFIND")]
                            if _dangerous:
                                output_mgr.log_finding(
                                    title="HTTP Methods: Unsafe Methods Enabled",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk -X OPTIONS -I {_scheme}://{_curl_host}:{_port}/",
                                    risk="MEDIUM",
                                    description=(
                                        f"The web server at {_scheme}://{ip}:{_port} allows "
                                        f"dangerous HTTP methods: {', '.join(_dangerous)}. "
                                        f"PUT/DELETE can allow file upload and deletion, "
                                        f"MOVE/COPY enable WebDAV manipulation, and PROPFIND "
                                        f"discloses directory structure. Disable unused HTTP "
                                        f"methods in the web server configuration."
                                    ),
                                    output=f"Allow: {_allow_match.group(1).strip()}",
                                    sources="scattershot3-curl-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=str(_curl_path.relative_to(output_mgr.root)),
                                )
                    except Exception:
                        pass
                    try:
                        _trace_r = subprocess.run(
                            f"curl -sk --max-time 5 -X TRACE {_scheme}://{_curl_host}:{_port}/",
                            shell=True, capture_output=True, timeout=10,
                        )
                        _trace_body = _trace_r.stdout.decode("utf-8", errors="replace")
                        if "TRACE / HTTP" in _trace_body:
                            output_mgr.log_finding(
                                title="HTTP Methods: Unsafe Methods Enabled",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"curl -sk -X TRACE {_scheme}://{_curl_host}:{_port}/",
                                risk="MEDIUM",
                                description=(
                                    f"The web server at {_scheme}://{ip}:{_port} responds "
                                    f"to HTTP TRACE requests by echoing the request. The "
                                    f"TRACE method can be exploited for Cross-Site Tracing "
                                    f"(XST) attacks to steal credentials from HTTP headers. "
                                    f"Disable the TRACE method in the web server configuration."
                                ),
                                output=_trace_body[:512],
                                sources="scattershot3-curl-probe",
                                affected=f"{ip}:{_port}",
                                output_file=str(_curl_path.relative_to(output_mgr.root)),
                            )
                    except Exception:
                        pass
                    # Phase G.7: Apache server-status / server-info (SS-081)
                    for _status_ep, _status_label in (
                        ("/server-status", "Apache Server Status"),
                        ("/server-info", "Apache Server Info"),
                    ):
                        try:
                            _ss_r = subprocess.run(
                                f"curl -sk --max-time 5 {_scheme}://{_curl_host}:{_port}{_status_ep}",
                                shell=True, capture_output=True, timeout=10,
                            )
                            _ss_body = _ss_r.stdout.decode("utf-8", errors="replace")
                            if ("Apache Server" in _ss_body and
                                    ("Server Version" in _ss_body or "Current Time" in _ss_body
                                     or "Scoreboard" in _ss_body or "Server Built" in _ss_body)):
                                output_mgr.log_finding(
                                    title=f"{_status_label} Page Exposed",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk {_scheme}://{_curl_host}:{_port}{_status_ep}",
                                    risk="MEDIUM",
                                    description=(
                                        f"The {_status_label} page at {_scheme}://{ip}:{_port}"
                                        f"{_status_ep} is publicly accessible. This exposes "
                                        f"server version, uptime, active connections, client "
                                        f"IPs, and request URIs. Restrict access to "
                                        f"mod_status and mod_info via .htaccess or "
                                        f"Apache configuration directives."
                                    ),
                                    output=_ss_body[:1024],
                                    sources="scattershot3-curl-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=str(_curl_path.relative_to(output_mgr.root)),
                                )
                                _tprint(
                                    f"  {Fore.YELLOW}[!] {_status_label} exposed "
                                    f"{_scheme}://{ip}:{_port}{_status_ep}{Style.RESET_ALL}"
                                )
                        except Exception:
                            pass
                    # Phase G.8: Internal hostname disclosure (SS-082)
                    _ihn_text = (_r.get("headers") or "") + "\n" + (_r.get("body") or "")[:4096]
                    _ihn_found = set()
                    for _ihm in _RE_INTERNAL_HOSTNAME.finditer(_ihn_text):
                        _ihn_found.add(_ihm.group(0).lower())
                    if _ihn_found:
                        _ihn_str = ", ".join(sorted(_ihn_found))
                        output_mgr.log_finding(
                            title="Information Disclosure: Internal Hostname in HTTP Response",
                            ip=ip, port=_port, hostname=hostname,
                            command=_r["cmd"], risk="LOW",
                            description=(
                                f"The HTTP response from {_scheme}://{ip}:{_port}/ "
                                f"contains internal hostname(s): {_ihn_str}. Internal "
                                f"naming conventions disclose domain structure, "
                                f"environment names, and infrastructure layout. "
                                f"Remove internal hostnames from response headers "
                                f"and body content."
                            ),
                            output=f"Internal hostname(s): {_ihn_str}",
                            sources="scattershot3-curl-probe",
                            affected=f"{ip}:{_port}",
                            output_file=str(_curl_path.relative_to(output_mgr.root)),
                        )
                    # Phase G.9: Debug endpoints (SS-083)
                    for _dbg_ep, _dbg_label in (
                        ("/actuator", "Spring Boot Actuator"),
                        ("/actuator/env", "Spring Boot Actuator Env"),
                        ("/debug", "Debug endpoint"),
                        ("/__debug__", "Django Debug Toolbar"),
                        ("/console", "Web Console"),
                    ):
                        try:
                            _dbg_r = subprocess.run(
                                f"curl -sk --max-time 5 {_scheme}://{_curl_host}:{_port}{_dbg_ep}",
                                shell=True, capture_output=True, timeout=10,
                            )
                            _dbg_body = _dbg_r.stdout.decode("utf-8", errors="replace").strip()
                            _dbg_ok = False
                            if _dbg_ep == "/actuator" and _dbg_body.startswith("{") and '"_links"' in _dbg_body:
                                _dbg_ok = True
                            elif _dbg_ep == "/actuator/env" and _dbg_body.startswith("{") and ('"propertySources"' in _dbg_body or '"activeProfiles"' in _dbg_body):
                                _dbg_ok = True
                            elif _dbg_ep in ("/debug", "/__debug__") and ("Traceback" in _dbg_body or "debug" in _dbg_body.lower()[:200]) and len(_dbg_body) > 100:
                                _dbg_ok = True
                            elif _dbg_ep == "/console" and ("console" in _dbg_body.lower()[:500] and ("<form" in _dbg_body.lower() or "h2" in _dbg_body.lower())):
                                _dbg_ok = True
                            if _dbg_ok:
                                output_mgr.log_finding(
                                    title=f"Debug Endpoint Exposed: {_dbg_label}",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk {_scheme}://{_curl_host}:{_port}{_dbg_ep}",
                                    risk="MEDIUM",
                                    description=(
                                        f"The {_dbg_label} endpoint at "
                                        f"{_scheme}://{ip}:{_port}{_dbg_ep} is accessible. "
                                        f"Debug endpoints expose environment variables, "
                                        f"configuration, database connection strings, and "
                                        f"internal application state. Disable debug "
                                        f"endpoints in production or restrict access."
                                    ),
                                    output=_dbg_body[:1024],
                                    sources="scattershot3-curl-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=str(_curl_path.relative_to(output_mgr.root)),
                                )
                                _tprint(
                                    f"  {Fore.YELLOW}[!] Debug endpoint "
                                    f"{_dbg_ep} exposed on {ip}:{_port}{Style.RESET_ALL}"
                                )
                        except Exception:
                            pass
                    # Phase G.10: phpinfo exposure (SS-084)
                    for _php_ep in ("/phpinfo.php", "/info.php"):
                        try:
                            _php_r = subprocess.run(
                                f"curl -sk --max-time 5 {_scheme}://{_curl_host}:{_port}{_php_ep}",
                                shell=True, capture_output=True, timeout=10,
                            )
                            _php_body = _php_r.stdout.decode("utf-8", errors="replace")
                            if "phpinfo()" in _php_body or "PHP Version" in _php_body:
                                _php_ver = ""
                                _php_vm = re.search(r"PHP Version\s*</td><td[^>]*>\s*([0-9.]+)", _php_body)
                                if _php_vm:
                                    _php_ver = _php_vm.group(1)
                                output_mgr.log_finding(
                                    title="PHP Info Page Exposed",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk {_scheme}://{_curl_host}:{_port}{_php_ep}",
                                    risk="HIGH",
                                    description=(
                                        f"A phpinfo() page is accessible at "
                                        f"{_scheme}://{ip}:{_port}{_php_ep}"
                                        f"{f' (PHP {_php_ver})' if _php_ver else ''}. "
                                        f"phpinfo() exposes the full PHP configuration, "
                                        f"loaded modules, environment variables (which "
                                        f"may contain credentials), file paths, and "
                                        f"server details. Remove phpinfo files from "
                                        f"production servers."
                                    ),
                                    output=f"PHP info page found: {_php_ep}"
                                           f"{f' (PHP {_php_ver})' if _php_ver else ''}",
                                    sources="scattershot3-curl-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=str(_curl_path.relative_to(output_mgr.root)),
                                )
                                _tprint(
                                    f"  {Fore.RED}[!!!] phpinfo exposed "
                                    f"{_scheme}://{ip}:{_port}{_php_ep}{Style.RESET_ALL}"
                                )
                                break  # one phpinfo finding per port
                        except Exception:
                            pass
                    # Phase G.11: Directory listing detection
                    _body_lo = (_r.get("body") or "").lower()[:4096]
                    if ("index of /" in _body_lo or
                            "<title>directory listing" in _body_lo or
                            "parent directory</a>" in _body_lo):
                        output_mgr.log_finding(
                            title="Enumeration: Directory Listing Enabled",
                            ip=ip, port=_port, hostname=hostname,
                            command=_r["cmd"], risk="MEDIUM",
                            description=(
                                f"The web server at {_scheme}://{ip}:{_port}/ has "
                                f"directory listing enabled. Directory listings "
                                f"expose file names, sizes, and modification dates, "
                                f"allowing attackers to discover backup files, "
                                f"configuration files, and other sensitive content. "
                                f"Disable directory listing (Options -Indexes for "
                                f"Apache, autoindex off for Nginx)."
                            ),
                            output=(_r.get("body") or "")[:512],
                            sources="scattershot3-curl-probe",
                            affected=f"{ip}:{_port}",
                            output_file=str(_curl_path.relative_to(output_mgr.root)),
                        )
                    # Phase G.12: robots.txt sensitive paths (SS-088)
                    try:
                        _rob_r = subprocess.run(
                            f"curl -sk --max-time 5 {_scheme}://{_curl_host}:{_port}/robots.txt",
                            shell=True, capture_output=True, timeout=10,
                        )
                        _rob_body = _rob_r.stdout.decode("utf-8", errors="replace")
                        if ("disallow:" in _rob_body.lower() or
                                "user-agent:" in _rob_body.lower()):
                            _sensitive_paths = _analyze_robots_txt(_rob_body)
                            if _sensitive_paths:
                                _sp_str = ", ".join(_sensitive_paths[:15])
                                output_mgr.log_finding(
                                    title="Information Disclosure: Sensitive Path in robots.txt",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk {_scheme}://{_curl_host}:{_port}/robots.txt",
                                    risk="INFO",
                                    description=(
                                        f"The robots.txt file at {_scheme}://{ip}:{_port} "
                                        f"contains Disallow entries for potentially "
                                        f"sensitive paths: {_sp_str}. While robots.txt "
                                        f"instructs well-behaved crawlers to skip these "
                                        f"paths, it also advertises them to attackers. "
                                        f"Review whether these paths should exist on the "
                                        f"production server and ensure they require "
                                        f"authentication."
                                    ),
                                    output=(
                                        f"Sensitive Disallow paths ({len(_sensitive_paths)}):\n"
                                        + "\n".join(f"  {p}" for p in _sensitive_paths[:20])
                                    ),
                                    sources="scattershot3-curl-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=str(_curl_path.relative_to(output_mgr.root)),
                                )
                    except Exception:
                        pass
                except OSError:
                    pass
                break   # one successful probe per port

        # ── Cloud metadata endpoint probe ─────────────────────────────────
        # After a web-port is confirmed, check for cloud metadata SSRF paths.
        def _cloud_metadata_looks_real(provider, body):
            """Return True only when *body* contains markers specific to a real
            cloud metadata response, not a generic error/ban/default page."""
            b = body.lower()
            if provider == "AWS EC2":
                _aws_markers = ("ami-id", "instance-id", "local-ipv4",
                                "hostname", "iam/", "placement/",
                                "network/", "public-keys/")
                return sum(1 for m in _aws_markers if m in b) >= 3
            if provider == "Azure IMDS":
                return '"compute"' in b and '"network"' in b
            if provider == "GCP":
                _gcp_markers = ("project/", "instance/", "attributes/")
                return sum(1 for m in _gcp_markers if m in b) >= 2
            return False
        if _got_http and getattr(output_mgr, "scope", "ext") == "int":
            _meta_paths = [
                ("/latest/meta-data/", "AWS EC2"),
                ("/metadata/instance?api-version=2021-02-01&format=json", "Azure IMDS"),
                ("/computeMetadata/v1/", "GCP"),
            ]
            for _meta_path, _cloud in _meta_paths:
                try:
                    _meta_url = f"http://{ip}:{_port}{_meta_path}"
                    _meta_hdrs = {"Host": ip}
                    if _cloud == "GCP":
                        _meta_hdrs["Metadata-Flavor"] = "Google"
                    _meta_resp = _HTTP_SESSION.get(
                        _meta_url, timeout=3, verify=False,
                        headers=_meta_hdrs,
                    )
                    if _meta_resp.status_code == 200 and len(_meta_resp.text) > 10 and _cloud_metadata_looks_real(_cloud, _meta_resp.text):
                        output_mgr.log_finding(
                            title=f"Cloud Metadata Endpoint Accessible ({_cloud})",
                            ip=ip, port=_port, hostname=hostname,
                            command=f"HTTP GET {_meta_url}",
                            risk="CRITICAL",
                            description=(
                                f"The {_cloud} cloud metadata endpoint is accessible "
                                f"via {_meta_url}. An attacker who can reach this "
                                f"endpoint (via SSRF or direct access) can retrieve "
                                f"IAM credentials, instance identity tokens, and "
                                f"cloud configuration. Restrict metadata access via "
                                f"IMDSv2 (AWS), network rules, or metadata concealment."
                            ),
                            output=_meta_resp.text[:2000],
                            sources="cloud-metadata-probe",
                            affected=f"{ip}:{_port}",
                        )
                        try:
                            _cloud_steps = {
                                "AWS": (
                                    f"  1. curl -s http://{ip}:{_port}/latest/meta-data/iam/security-credentials/\n"
                                    "  2. Append the role name to that URL to get AccessKeyId/SecretAccessKey/Token\n"
                                    "  3. aws sts get-caller-identity --profile stolen\n"
                                    "  4. Enumerate with: aws s3 ls / aws ec2 describe-instances / aws iam list-roles"
                                ),
                                "GCP": (
                                    f"  1. curl -s -H 'Metadata-Flavor: Google' http://{ip}:{_port}/computeMetadata/v1/instance/service-accounts/default/token\n"
                                    "  2. Use the access_token with: gcloud auth activate-service-account\n"
                                    "  3. Enumerate with: gcloud projects list / gcloud compute instances list"
                                ),
                                "Azure": (
                                    f"  1. curl -s -H 'Metadata: true' 'http://{ip}:{_port}/metadata/identity/oauth2/token?api-version=2018-02-01&resource=https://management.azure.com/'\n"
                                    "  2. Use the access_token with: az account get-access-token\n"
                                    "  3. Enumerate with: az resource list / az vm list"
                                ),
                            }
                            output_mgr.log_action_item(
                                item_type="manual_verification",
                                recommended_tool="Manual",
                                target=f"{ip}:{_port}",
                                ip=ip, port=_port,
                                title="Extract Cloud IAM Credentials from Metadata",
                                description=(
                                    f"Retrieve IAM role credentials from {_cloud} metadata endpoint.\n"
                                    "Next steps:\n"
                                    + _cloud_steps.get(_cloud, f"  curl -s http://{ip}:{_port}/")
                                ),
                                hostname=hostname,
                                source_finding=f"Cloud Metadata Endpoint Accessible ({_cloud})",
                                priority="CRITICAL",
                            )
                        except Exception:
                            pass
                        break  # One cloud provider per port
                except Exception:
                    pass

        # ── Phase G.5: web-port information leakage probes (GAP-04/26/28/14) ──
        if _got_http:
            _gp_scheme = "https" if _port in (443, 8443, 4443, 7443, 9443) else "http"
            _gp_base = f"{_gp_scheme}://{ip}:{_port}"

            # GAP-04: .git/HEAD exposure
            try:
                _git_resp = _HTTP_SESSION.get(
                    f"{_gp_base}/.git/HEAD", timeout=5, verify=False)
                if (_git_resp.status_code == 200
                        and _git_resp.text.strip().startswith("ref: refs/")):
                    output_mgr.log_finding(
                        title="Exposed .git Repository",
                        ip=ip, port=_port, hostname=hostname,
                        command=f"curl -sk {_gp_base}/.git/HEAD",
                        risk="CRITICAL",
                        description=(
                            f"The .git directory is publicly accessible at "
                            f"{_gp_base}/.git/HEAD. An attacker can reconstruct "
                            f"the full source code, commit history, and any "
                            f"secrets ever committed."
                        ),
                        output=f".git/HEAD content: {_git_resp.text.strip()[:200]}",
                        sources="scattershot3-git-probe",
                        affected=f"{ip}:{_port}",
                    )
            except Exception:
                pass

            # GAP-28: Apache server-status / server-info
            for _ss_path, _ss_label in [
                ("/server-status", "Apache server-status"),
                ("/server-info", "Apache server-info"),
            ]:
                try:
                    _ss_resp = _HTTP_SESSION.get(
                        f"{_gp_base}{_ss_path}", timeout=5, verify=False)
                    if (_ss_resp.status_code == 200
                            and ("Apache Server Status" in _ss_resp.text
                                 or "Server Version:" in _ss_resp.text
                                 or "Apache Server Information" in _ss_resp.text)):
                        output_mgr.log_finding(
                            title=f"{_ss_label} Page Accessible",
                            ip=ip, port=_port, hostname=hostname,
                            command=f"curl -sk {_gp_base}{_ss_path}",
                            risk="MEDIUM",
                            description=(
                                f"The {_ss_label} page at {_gp_base}{_ss_path} "
                                f"is publicly accessible, disclosing active "
                                f"connections, client IPs, request URIs, server "
                                f"uptime, and module configuration."
                            ),
                            output=_ss_resp.text[:500],
                            sources="scattershot3-serverstatus-probe",
                            affected=f"{ip}:{_port}",
                        )
                except Exception:
                    pass

            # GAP-26: OPTIONS / TRACE methods
            for _hm in ("OPTIONS", "TRACE"):
                try:
                    _hm_resp = _HTTP_SESSION.request(
                        _hm, _gp_base + "/", timeout=5, verify=False)
                    if _hm_resp.status_code == 200:
                        if _hm == "OPTIONS":
                            _allow = _hm_resp.headers.get("Allow", "")
                            if _allow and any(m in _allow.upper() for m in ("PUT", "DELETE", "TRACE")):
                                _opt_ev = _S3_HTTP_RECORDER.last_paths() if _S3_HTTP_RECORDER else {}
                                _opt_of = ",".join(p for p in (
                                    _opt_ev.get("request", ""), _opt_ev.get("response", ""),
                                    _opt_ev.get("log", "")) if p) or None
                                output_mgr.log_finding(
                                    title="HTTP Methods: Unsafe Methods Enabled",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk -X OPTIONS {_gp_base}/",
                                    risk="MEDIUM",
                                    description=(
                                        f"The web server at {ip}:{_port} allows "
                                        f"potentially dangerous HTTP methods: {_allow}."
                                    ),
                                    output=f"Allow: {_allow}",
                                    sources="scattershot3-options-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=_opt_of,
                                )
                        elif _hm == "TRACE":
                            if "TRACE" in _hm_resp.text[:200].upper():
                                _tr_ev = _S3_HTTP_RECORDER.last_paths() if _S3_HTTP_RECORDER else {}
                                _tr_of = ",".join(p for p in (
                                    _tr_ev.get("request", ""), _tr_ev.get("response", ""),
                                    _tr_ev.get("log", "")) if p) or None
                                output_mgr.log_finding(
                                    title="HTTP Methods: Unsafe Methods Enabled",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"curl -sk -X TRACE {_gp_base}/",
                                    risk="MEDIUM",
                                    description=(
                                        f"The web server at {ip}:{_port} responds "
                                        f"to TRACE requests by echoing the full "
                                        f"request including headers. This enables "
                                        f"Cross-Site Tracing (XST) attacks to steal "
                                        f"cookies and authorization headers."
                                    ),
                                    output=_hm_resp.text[:300],
                                    sources="scattershot3-trace-probe",
                                    affected=f"{ip}:{_port}",
                                    output_file=_tr_of,
                                )
                except Exception:
                    pass

            # GAP-14: Internal hostname disclosure in HTTP response
            _ihn_re = re.compile(
                r'\b([a-zA-Z][a-zA-Z0-9\-]{1,60}\.(?:internal|local|corp|'
                r'intra|private|lan|home|localdomain))\b', re.I)
            _ihn_text = (_r.get("body") or "") + "\n" + (_r.get("headers") or "")
            _ihn_found = set()
            for _ihn_m in _ihn_re.finditer(_ihn_text):
                _ihn_found.add(_ihn_m.group(1).lower())
            if _ihn_found:
                output_mgr.log_finding(
                    title="Information Disclosure: Internal Hostname in HTTP Response",
                    ip=ip, port=_port, hostname=hostname,
                    command=_r.get("cmd", f"curl -sk {_gp_base}/"),
                    risk="LOW",
                    description=(
                        f"The HTTP response from {ip}:{_port} contains internal "
                        f"hostname(s): {', '.join(sorted(_ihn_found))}. This "
                        f"reveals internal naming conventions and network topology."
                    ),
                    output=f"Internal hostnames: {', '.join(sorted(_ihn_found))}",
                    sources="scattershot3-hostname-probe",
                    affected=f"{ip}:{_port}",
                )

        # ── Phase F: netcat banner probe ───────────────────────────────────
        # Runs for any port the curl Phase E didn't already confirm as
        # HTTP — that covers genuinely non-web ports AND web-looking
        # ports that turned out to not speak HTTP. The banner is useful
        # in both cases.
        if not _got_http:
            _first, _full = _identify_service_via_nc(ip, _port)
            if _first or _full:
                _svc_dir = output_mgr.host_path(ip) / "services"
                _svc_dir.mkdir(parents=True, exist_ok=True)
                _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                _svc_label = (_service or "unknown")[:20]
                _nc_path = _svc_dir / f"{ip.replace('.', '_')}_{_port}_{_svc_label}_nc_{_ts}.txt"
                try:
                    _nc_path.write_text(
                        (f"Target: {ip}:{_port}\n"
                         f"Service (best guess): {_service or 'unknown'}\n"
                         f"Identified via: {_identified_via or 'nmap'}\n"
                         f"\n--- First banner line ---\n{_first}\n"
                         f"\n--- Full response ({len(_full or '')} bytes) ---\n"
                         f"{(_full or '')[:8192]}\n"),
                        encoding="utf-8",
                    )
                    output_mgr.log_command(
                        "nc-probe", "nc",
                        f"nc {ip} {_port}  # banner probe", _nc_path,
                        extra={"target": f"{ip}:{_port}",
                               "service": _service or "unknown"},
                    )
                except OSError:
                    pass

        # ── GAP-23: DNS version.bind CHAOS query ─────────────────────────
        if _port == 53 or _service == "dns" or _service == "domain":
            try:
                import struct as _st
                _txid = os.urandom(2)
                _dns_q = (
                    _txid
                    + b"\x00\x00"       # flags: standard query
                    + b"\x00\x01"       # 1 question
                    + b"\x00\x00\x00\x00\x00\x00"  # 0 answer/auth/additional
                    + b"\x07version\x04bind\x00"    # QNAME: version.bind
                    + b"\x00\x10"       # QTYPE: TXT
                    + b"\x00\x03"       # QCLASS: CH (CHAOS)
                )
                _dns_sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                _dns_sock.settimeout(5)
                _dns_sock.sendto(_dns_q, (ip, _port))
                _dns_reply, _ = _dns_sock.recvfrom(4096)
                _dns_sock.close()
                if len(_dns_reply) > 12:
                    _dns_flags = _st.unpack("!H", _dns_reply[2:4])[0]
                    _dns_ancount = _st.unpack("!H", _dns_reply[6:8])[0]
                    _dns_rcode = _dns_flags & 0x0F
                    if _dns_rcode == 0 and _dns_ancount > 0:
                        _dns_txt = ""
                        _dns_pos = 12
                        while _dns_pos < len(_dns_reply) and _dns_reply[_dns_pos] != 0:
                            _dns_pos += _dns_reply[_dns_pos] + 1
                        _dns_pos += 5  # skip null + QTYPE + QCLASS
                        if _dns_pos + 12 < len(_dns_reply):
                            _dns_pos += 2  # skip name pointer
                            _dns_pos += 8  # skip type, class, TTL
                            _dns_rdlen = _st.unpack("!H", _dns_reply[_dns_pos:_dns_pos+2])[0]
                            _dns_pos += 2
                            if _dns_rdlen > 1 and _dns_pos + _dns_rdlen <= len(_dns_reply):
                                _dns_txt_len = _dns_reply[_dns_pos]
                                _dns_txt = _dns_reply[_dns_pos+1:_dns_pos+1+_dns_txt_len].decode("utf-8", errors="replace")
                        if _dns_txt:
                            output_mgr.log_finding(
                                title="DNS Server Version Disclosed via CHAOS Query",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"dig @{ip} version.bind CHAOS TXT",
                                risk="LOW",
                                description=(
                                    f"The DNS server at {ip}:{_port} responds to "
                                    f"version.bind CHAOS TXT queries, disclosing "
                                    f"its software version: '{_dns_txt}'. This aids "
                                    f"an attacker in identifying specific CVEs."
                                ),
                                output=f"version.bind: {_dns_txt}",
                                sources="scattershot3-dns-chaos-probe",
                                affected=f"{ip}:{_port}",
                            )
            except Exception:
                pass

        # ── GAP-24: SMTP EXPN / VRFY user enumeration ────────────────────
        if _port in (25, 587, 465, 2525) or _service == "smtp":
            try:
                _smtp_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                _smtp_sock.settimeout(5)
                _smtp_sock.connect((ip, _port))
                _smtp_banner = _smtp_sock.recv(1024).decode("utf-8", errors="replace")
                if "220" in _smtp_banner[:10]:
                    _smtp_sock.sendall(b"EHLO test.local\r\n")
                    _smtp_sock.recv(4096)
                    for _smtp_cmd, _smtp_label in [
                        (b"EXPN root\r\n", "EXPN"),
                        (b"VRFY root\r\n", "VRFY"),
                    ]:
                        _smtp_sock.sendall(_smtp_cmd)
                        _smtp_reply = _smtp_sock.recv(1024).decode("utf-8", errors="replace")
                        if _smtp_reply.startswith("250"):
                            output_mgr.log_finding(
                                title=f"Enumeration: SMTP {_smtp_label} User Enumeration Enabled",
                                ip=ip, port=_port, hostname=hostname,
                                command=f"echo '{_smtp_label} root' | nc {ip} {_port}",
                                risk="MEDIUM",
                                description=(
                                    f"The SMTP server at {ip}:{_port} responds to "
                                    f"{_smtp_label} commands, allowing user enumeration. "
                                    f"An attacker can discover valid email accounts "
                                    f"for targeted phishing or brute-force attacks."
                                ),
                                output=f"{_smtp_label} root → {_smtp_reply.strip()[:200]}",
                                sources="scattershot3-smtp-probe",
                                affected=f"{ip}:{_port}",
                            )
                            break
                _smtp_sock.sendall(b"QUIT\r\n")
                _smtp_sock.close()
            except Exception:
                pass

        # ── GAP-27: Certificate hostname mismatch ────────────────────────
        if _service in ("ssl/http", "https", "ssl/https", "https-alt", "ssl"):
            try:
                import ssl as _ssl_mod
                _cert_ctx = _ssl_mod.create_default_context()
                _cert_ctx.check_hostname = False
                _cert_ctx.verify_mode = _ssl_mod.CERT_NONE
                _cert_sock = socket.create_connection((ip, _port), timeout=5)
                _cert_wrapped = _cert_ctx.wrap_socket(_cert_sock, server_hostname=ip)
                _cert_der = _cert_wrapped.getpeercert(binary_form=True)
                _cert_wrapped.close()
                if _cert_der:
                    from cryptography import x509 as _x509
                    _cert_obj = _x509.load_der_x509_certificate(_cert_der)
                    _cert_cn = ""
                    for _attr in _cert_obj.subject:
                        if _attr.oid == _x509.oid.NameOID.COMMON_NAME:
                            _cert_cn = _attr.value
                            break
                    _cert_sans = []
                    try:
                        _san_ext = _cert_obj.extensions.get_extension_for_class(
                            _x509.SubjectAlternativeName)
                        _cert_sans = _san_ext.value.get_values_for_type(_x509.DNSName)
                    except Exception:
                        pass
                    _cert_all_names = set()
                    if _cert_cn:
                        _cert_all_names.add(_cert_cn.lower())
                    _cert_all_names.update(s.lower() for s in _cert_sans)
                    if hostname and hostname.lower() not in _cert_all_names:
                        _wildcard_match = any(
                            n.startswith("*.") and hostname.lower().endswith(n[1:])
                            for n in _cert_all_names
                        )
                        if not _wildcard_match:
                            _cert_hn_is_ip = False
                            try:
                                ipaddress.ip_address(hostname)
                                _cert_hn_is_ip = True
                            except ValueError:
                                pass
                            if not _cert_hn_is_ip:
                                _cert_ev_of = None
                                try:
                                    from datetime import datetime as _dt_cert
                                    _cev_dir = os.path.join(
                                        str(_S3_EVIDENCE_DIR[0] or output_mgr.root),
                                        "evidence", "cert_check")
                                    os.makedirs(_cev_dir, exist_ok=True)
                                    _cev_ts = _dt_cert.now().strftime("%Y%m%d_%H%M%S")
                                    _cev_fn = f"{ip}_{_port}_cert_mismatch_{_cev_ts}.txt"
                                    _cev_abs = os.path.join(_cev_dir, _cev_fn)
                                    _cev_lines = [
                                        f"# TLS Certificate Hostname Mismatch Evidence",
                                        f"# Host: {ip}:{_port}",
                                        f"# Expected hostname: {hostname}",
                                        f"# Captured: {_cev_ts}",
                                        f"",
                                        f"Expected hostname: {hostname}",
                                        f"Certificate CN:    {_cert_cn}",
                                        f"Certificate SANs:  {', '.join(_cert_sans[:20])}",
                                        f"All names:         {', '.join(sorted(_cert_all_names))}",
                                        f"",
                                        f"Issuer: {_cert_obj.issuer.rfc4514_string()}",
                                        f"Not Before: {_cert_obj.not_valid_before_utc}",
                                        f"Not After:  {_cert_obj.not_valid_after_utc}",
                                        f"Serial:     {_cert_obj.serial_number}",
                                    ]
                                    with open(_cev_abs, "w") as _cev_f:
                                        _cev_f.write("\n".join(_cev_lines) + "\n")
                                    _cert_ev_of = os.path.join(
                                        "evidence", "cert_check", _cev_fn)
                                except Exception:
                                    pass
                                output_mgr.log_finding(
                                    title="TLS Certificate Hostname Mismatch",
                                    ip=ip, port=_port, hostname=hostname,
                                    command=f"openssl s_client -connect {ip}:{_port} -servername {hostname}",
                                    risk="MEDIUM",
                                    description=(
                                        f"The TLS certificate at {ip}:{_port} does not "
                                        f"match the expected hostname '{hostname}'. "
                                        f"Certificate names: {', '.join(sorted(_cert_all_names))}. "
                                        f"This may indicate a misconfigured service or "
                                        f"enable MITM attacks when certificate validation "
                                        f"is improperly handled."
                                    ),
                                    output=(
                                        f"Expected: {hostname}\n"
                                        f"Certificate CN: {_cert_cn}\n"
                                        f"Certificate SANs: {', '.join(_cert_sans[:10])}"
                                    ),
                                    sources="scattershot3-cert-mismatch",
                                    affected=f"{ip}:{_port}",
                                    output_file=_cert_ev_of,
                                )
            except ImportError:
                pass
            except Exception:
                pass

        # ── Phase G: non-standard port for a known service ─────────────────
        _std_port = _STANDARD_PORT_FOR_SERVICE.get(_service)
        if _std_port and _port != _std_port and not _is_web_via_name:
            output_mgr.log_finding(
                title=f"Non-Standard Port for {_service.upper()}",
                ip=ip, port=_port, hostname=hostname,
                command=f"# service identification on {ip}:{_port}",
                risk="INFO",
                description=(
                    f"The {_service.upper()} service was identified on "
                    f"{ip}:{_port}, but the standard port for {_service.upper()} "
                    f"is {_std_port}. Services on non-standard ports often slip "
                    f"past vulnerability-management automation that scans only "
                    f"well-known ports, and they may carry weaker hardening "
                    f"than their canonical-port counterparts."
                ),
                output=(
                    f"Service:        {_service}\n"
                    f"Observed port:  {_port}\n"
                    f"Standard port:  {_std_port}\n"
                    f"Identified via: {_identified_via or 'nmap -sV'}"
                ),
                sources="fracture-recon-port",
                affected=f"{ip}:{_port}",
            )


def port_scan(
    ip: str,
    fast: bool = False,
    output_mgr: "OutputManager | None" = None,
    nmap_path: str = "nmap",
    hostname: str | None = None,
    rustscan_path: "str | None" = None,
    scope: str = "int",
) -> "dict[int, dict]":
    """
    TCP port scan with service/version detection for a single host.

    Each call creates its own nmap.PortScanner() instance, making this
    function safe to call from multiple threads simultaneously — python-nmap
    stores scan state on the PortScanner object, so sharing one instance
    across threads would corrupt results.

    Concurrency is managed by the caller (_port_scan_worker via scan_scope's
    ThreadPoolExecutor of 20 workers), not inside this function.

    nmap flags:
      -n                     suppress nmap DNS resolution (results keyed by IP)
      -Pn                    skip host discovery (callers confirm hosts alive)
      -sV                    service/version detection
      --version-intensity 5  balanced accuracy vs speed (0=fast, 9=thorough)
      -T4                    aggressive timing (LAN / reliable network)
      --host-timeout 300s    fast mode only: 5-min ceiling safe for top-1000
      --top-ports 1000       fast mode: 1000 most common ports
      -p-                    full mode: all 65535 ports (no host-timeout —
                             scanning 65535 ports with -sV takes several minutes;
                             a 60 s or even 300 s ceiling would fire before
                             completion, silently returning empty results)

    Scope-aware tuning (v1.27.0)
    ----------------------------
    External targets ("ext") commonly sit behind strict stateful firewalls
    that silently drop most probes.  LAN-tuned RTT ceilings and low retry
    counts cause nmap to abandon probes before the open ports respond.

      Internal: --max-retries 2, --max-rtt-timeout 1000ms (LAN)
      External: --max-retries 3, --max-rtt-timeout 3000ms, --min-rate 500

    --min-rate 500 prevents nmap from over-throttling when it sees thousands
    of filtered (no-response) ports.  Without it, nmap progressively slows
    its send rate, potentially taking hours per host or timing out before
    covering all 65535 ports.

    Returns
    -------
    dict keyed by port number (int).  Only "open" / "open|filtered" ports
    are included.  Empty dict if host is unreachable or has no open ports.
    """
    # ── Base scan arguments ───────────────────────────────────────────────────
    # -n      : no DNS — results always keyed by IP, never by hostname
    # -Pn     : skip host discovery (callers already confirmed alive)
    # -sV     : service/version detection
    # --version-intensity 3 : lighter probe set, faster than default (7)
    # -T4     : aggressive timing
    #
    # NOTE: python-nmap runs nmap as "nmap -oX - <args> <host>" internally —
    # it pipes XML to stdout and parses it.  Passing -oX/-oA/-oN in arguments
    # raises "Xml output can't be redirected from command line."
    # We therefore use nm.scan() for parsing and write the -oA files ourselves
    # from the XML that python-nmap already captured in nm.get_nmap_last_output().
    #
    # NOTE: SMB scripts (smb-enum-shares, smb-system-info, smb-protocols) and
    # sshv1 are intentionally excluded from the base scan — they only apply to
    # specific ports and cause nmap to stall/error on hosts that don't have those
    # services.  They are run as a targeted second pass after open ports are known.
    # Base scan: pure port discovery + service version — NO NSE scripts here.
    # Scripts are run in Phase B as targeted passes once open ports are known.
    # Keeping the base scan script-free avoids two failure modes:
    #   • vulners NSE requires the script to be installed and can stall/fail
    #   • SMB/SSH scripts on wrong ports cause nmap to report zero hosts
    #
    # Scope-aware timing (v1.27.0):
    #   INT: --max-retries 2, --max-rtt-timeout 1000ms, --min-rtt-timeout 100ms
    #        Tuned for LAN — low latency, minimal packet loss.
    #   EXT: --max-retries 3, --max-rtt-timeout 3000ms, --min-rtt-timeout 100ms,
    #        --min-rate 500
    #        Tuned for filtered external targets — firewalls silently drop most
    #        probes, so nmap needs higher per-probe ceilings, more retries, and
    #        a rate floor to prevent over-throttling across 65535 mostly-filtered
    #        ports.
    if scope == "ext":
        nmap_args = (
            "-n -Pn -sV --version-intensity 3 -T4 "
            "--max-retries 3 --min-rtt-timeout 100ms --max-rtt-timeout 3000ms "
            "--min-rate 500 --host-timeout 45m"
        )
    else:
        nmap_args = (
            "-n -Pn -sV --version-intensity 3 -T4 "
            "--max-retries 2 --min-rtt-timeout 100ms --max-rtt-timeout 1000ms "
            "--host-timeout 30m"
        )
    if fast:
        nmap_args += " --top-ports 1000"
    else:
        nmap_args += " -p-"

    ts_safe  = datetime.now().strftime("%Y%m%d_%H%M%S")
    oA_base  = None
    if output_mgr:
        safe_ip = ip.replace(".", "_")
        oA_base = str(output_mgr.host_path(ip) / f"portscan_{ts_safe}")

    # cmd_list is what gets logged (python-nmap builds the real subprocess itself)
    if scope == "ext":
        cmd_list = [nmap_path, "-n", "-Pn", "-sV", "--version-intensity", "3",
                    "-T4", "--max-retries", "3",
                    "--min-rtt-timeout", "100ms", "--max-rtt-timeout", "3000ms",
                    "--min-rate", "500", "--host-timeout", "45m"]
    else:
        cmd_list = [nmap_path, "-n", "-Pn", "-sV", "--version-intensity", "3",
                    "-T4", "--max-retries", "2",
                    "--min-rtt-timeout", "100ms", "--max-rtt-timeout", "1000ms",
                    "--host-timeout", "30m"]
    if fast:
        cmd_list += ["--top-ports", "1000"]
    else:
        cmd_list += ["-p-"]
    if oA_base:
        cmd_list += ["-oA", oA_base]
    cmd_list += [ip]

    # ── RustScan fast port discovery ─────────────────────────────────────────
    # Use rustscan to quickly identify open ports, then run nmap only on those
    # ports for service detection. Falls back to full nmap scan if unavailable.
    # Auto-detect RustScan if the caller did not supply an explicit path.
    # This makes the speedup automatic whenever rustscan is on PATH, without
    # requiring callers to opt in via rustscan_path.
    _effective_rustscan = rustscan_path or shutil.which("rustscan")
    if _effective_rustscan:
        _rs_cmd = [_effective_rustscan, "-a", ip, "--ulimit", "5000", "--greppable"]
        # Always scan the full port range — RustScan's async TCP connect scan
        # completes in seconds even across 65535 ports.  Restricting to 1-1000
        # numerically in fast mode would miss high-numbered common ports
        # (3306, 3389, 5432, 5900, 8080, 8443 …) that nmap's --top-ports 1000
        # covers by frequency, not by port number order.
        _rs_cmd += ["-p", "1-65535"]
        try:
            _rs_proc = _popen(_rs_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            # 90 s is ample for RustScan's TCP connect phase; falling back to
            # nmap sooner is preferable to blocking the worker for 5 minutes.
            _rs_out, _ = _rs_proc.communicate(timeout=90)
            _rs_text = _rs_out.decode("utf-8", errors="replace")
            _rs_ports: list[int] = []
            for _rs_line in _rs_text.splitlines():
                _rs_m = re.search(r'Open\s+[\d.]+:(\d+)', _rs_line) or re.search(r'Open\s+(\d+)', _rs_line)
                if _rs_m:
                    _rs_ports.append(int(_rs_m.group(1)))
            if _rs_ports:
                _port_list = ",".join(str(p) for p in sorted(_rs_ports))
                if scope == "ext":
                    nmap_args = (
                        f"-n -Pn -sV --version-intensity 3 -T4 "
                        f"--max-retries 3 --min-rtt-timeout 100ms --max-rtt-timeout 3000ms "
                        f"--min-rate 500 --host-timeout 45m -p {_port_list}"
                    )
                    cmd_list = [nmap_path, "-n", "-Pn", "-sV", "--version-intensity", "3",
                                "-T4", "--max-retries", "3",
                                "--min-rtt-timeout", "100ms", "--max-rtt-timeout", "3000ms",
                                "--min-rate", "500", "--host-timeout", "45m", "-p", _port_list]
                else:
                    nmap_args = (
                        f"-n -Pn -sV --version-intensity 3 -T4 "
                        f"--max-retries 2 --min-rtt-timeout 100ms --max-rtt-timeout 1000ms "
                        f"--host-timeout 30m -p {_port_list}"
                    )
                    cmd_list = [nmap_path, "-n", "-Pn", "-sV", "--version-intensity", "3",
                                "-T4", "--max-retries", "2",
                                "--min-rtt-timeout", "100ms", "--max-rtt-timeout", "1000ms",
                                "--host-timeout", "30m", "-p", _port_list]
                if oA_base:
                    cmd_list += ["-oA", oA_base]
                cmd_list += [ip]
                _tprint(f"  {Fore.CYAN}    rustscan: {len(_rs_ports)} port(s) → nmap -p {_port_list[:50]}...{Style.RESET_ALL}")
            elif _rs_ports == [] and _rs_proc.returncode == 0:
                # RustScan's TCP connect scan found nothing.  For internal
                # scope this is reliable; for external scope, filtered
                # firewalls may silently drop RustScan's connect() probes
                # while still allowing SYN-scan through — fall back to nmap.
                if scope != "ext":
                    return {}, None
                _tprint(f"  {Fore.YELLOW}    rustscan: 0 ports on {ip} "
                        f"(external, falling back to nmap -sS){Style.RESET_ALL}")
        except (subprocess.TimeoutExpired, OSError, ValueError):
            pass  # fall back to full nmap scan

    results: dict[int, dict] = {}

    try:
        # ── Phase A: base scan via python-nmap (parses XML from its own pipe) ─
        nm = nmap.PortScanner()
        nm.scan(hosts=ip, arguments=nmap_args)

        out_path = None
        if output_mgr:
            # Capture the XML python-nmap already has
            raw_bytes = (nm.get_nmap_last_output()
                         if hasattr(nm, "get_nmap_last_output") else b"")
            raw = _decode_nmap_output(raw_bytes) or nm.csv() or "(no output)"

            # Save the captured XML AND synthesised .gnmap + .nmap siblings
            # as the -oA trio. python-nmap won't allow real -oA in its args
            # so we generate them from the XML it captured.
            _nmap_xml_path = output_mgr.host_path(ip) / f"portscan_{ts_safe}.xml"
            if raw.lstrip().startswith("<?xml"):
                try:
                    output_mgr.write_nmap_oA_siblings(
                        _nmap_xml_path.with_suffix(""), raw
                    )
                except OSError:
                    pass

            # Write placeholder .txt (human-readable summary written after parse)
            out_path = output_mgr.host_path(ip) / f"portscan_{ts_safe}.txt"
            out_path.parent.mkdir(parents=True, exist_ok=True)
            out_path.write_text(f"Nmap port scan: {ip}\n(results will appear after parsing)\n",
                                encoding="utf-8")

            output_mgr.log_command(
                "nmap", nmap_path, cmd_list, out_path,
                extra={
                    "target":    ip,
                    "hostname":  hostname,
                    "scan_type": "port_scan",
                    "mode":      "fast (top-1000)" if fast else "full (all ports)",
                },
            )

        if ip not in nm.all_hosts():
            return results  # host went down between discovery and port scan

        for proto in nm[ip].all_protocols():
            for port in sorted(nm[ip][proto].keys()):
                port_data = nm[ip][proto][port]
                # startswith("open") catches both "open" and "open|filtered"
                # without admitting "closed" or "filtered".
                if port_data["state"].startswith("open"):
                    # Collect NSE script output for this port
                    script_output: dict = {}
                    raw_scripts = port_data.get("script", {})
                    if raw_scripts:
                        script_output = dict(raw_scripts)

                    results[port] = {
                        "proto":     proto,
                        "state":     port_data["state"],
                        "name":      port_data.get("name", ""),
                        "product":   port_data.get("product", ""),
                        "version":   port_data.get("version", ""),
                        "extrainfo": port_data.get("extrainfo", ""),
                        "scripts":   script_output,
                    }
                    # Parse and distribute NSE script findings
                    if output_mgr and script_output:
                        _parse_nse_findings(
                            output_mgr, ip, port, hostname,
                            script_output, cmd_list,
                        )
                    # Record nmap -sV software identifications.
                    # ONLY record when nmap has a confirmed version string — a
                    # product name without a version means nmap is guessing
                    # based solely on the port number (e.g. "Microsoft Windows
                    # RPC", "Microsoft Terminal Services", "tcpwrapped").
                    # Port-number-based guesses must not create software
                    # inventory entries; only plugin/probe-confirmed detections
                    # (product + version together) are recorded.
                    product = port_data.get("product", "")
                    version = port_data.get("version", "")
                    if output_mgr and product and version:
                        _nmap_ev_line = (
                            f"{port}/{proto}  open  "
                            f"{port_data.get('name', ''):<16}  "
                            f"{product} {version}"
                            + (f"  ({port_data.get('extrainfo', '')})" if port_data.get("extrainfo") else "")
                        ).rstrip()
                        record_software(
                            output_mgr, ip, port, hostname,
                            software_name=product,
                            version=version,
                            os_info=None,
                            method="nmap -sV",
                            extrainfo=port_data.get("extrainfo") or None,
                            evidence_line=_nmap_ev_line,
                        )
                        check_eol_and_vulns(
                            output_mgr, ip, port, hostname,
                            software_name=product,
                            version=version,
                            method="nmap -sV",
                        )
                        # If nmap detected an OS hint alongside the version, check EOL.
                        # Prefer the parsed OS suffix (e.g. "Ubuntu 3ubuntu0.6") from
                        # the version field over the generic extrainfo string, so that
                        # _resolve_ssh_os() can map it to the canonical OS label.
                        _, _nm_parsed_os, _ = _parse_nmap_version_field(version, "")
                        _nm_os_hint = _nm_parsed_os or port_data.get("extrainfo", "") or ""
                        if _nm_os_hint:
                            # Convert nmap "Ubuntu 3ubuntu0.6" → "Ubuntu-3ubuntu0.6"
                            # to match _SSH_OS_BANNER_COMPILED patterns and get a real
                            # version label, avoiding vague strings like "Ubuntu Linux"
                            _nm_resolved, _ = _resolve_ssh_os(_nm_os_hint.replace(" ", "-"))
                            if _nm_resolved:
                                _nm_os_hint = _nm_resolved
                            check_os_eol(
                                output_mgr, ip, port, hostname,
                                os_name=_nm_os_hint,
                                method="nmap -sV",
                            )

        # ── Phase B: targeted NSE second pass ────────────────────────────────
        # Run service-specific scripts only against the ports that actually have
        # those services open, avoiding the hangs and errors that happen when
        # smb-enum-shares / smb-protocols are run against hosts without SMB,
        # or vulners is called when not installed.
        def _script_exists(name: str) -> bool:
            """Return True if an NSE script is present in any standard location."""
            candidates = [
                Path("/usr/share/nmap/scripts") / f"{name}.nse",
                Path("/usr/local/share/nmap/scripts") / f"{name}.nse",
                Path("/opt/homebrew/share/nmap/scripts") / f"{name}.nse",
            ]
            return any(p.exists() for p in candidates)

        ssh_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("ssh", "openssh")
                     or p == 22]
        smb_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("microsoft-ds", "netbios-ssn", "smb")
                     or p in (139, 445)]
        rdp_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("ms-wbt-server", "rdp", "ms-term-serv")
                     or p == 3389]
        ipmi_ports = [p for p, d in results.items()
                      if d.get("name", "").lower() in ("ipmi", "asf-rmcp", "asf-rmcp+")
                      or p == 623]
        nfs_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("nfs", "nfsd", "rpcbind",
                                                      "sunrpc", "portmapper")
                     or p in (111, 2049)]
        mysql_ports = [p for p, d in results.items()
                       if d.get("name", "").lower() in ("mysql", "mysql-proxy")
                       or p == 3306]
        ftp_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("ftp", "ftps")
                     or p == 21]
        smtp_ports = [p for p, d in results.items()
                      if d.get("name", "").lower() in ("smtp", "smtps", "submission")
                      or p in (25, 465, 587)]
        dns_ports = [p for p, d in results.items()
                     if d.get("name", "").lower() in ("domain", "dns")
                     or p == 53]
        http_ports = [p for p, d in results.items()
                      if d.get("name", "").lower() in ("http", "https", "http-proxy",
                                                        "http-alt", "https-alt")
                      or p in (80, 443, 8080, 8443)]
        redis_ports = [p for p, d in results.items()
                       if d.get("name", "").lower() in ("redis",)
                       or p == 6379]
        mongo_ports = [p for p, d in results.items()
                       if d.get("name", "").lower() in ("mongodb", "mongod")
                       or p == 27017]
        all_open  = list(results.keys())

        nse_passes: list[tuple[list[int], str]] = []
        if ssh_ports:
            # Canonical NSE script name is 'sshv1' (no hyphen). The earlier
            # 'ssh-v1' name caused nmap 7.99+ to abort with
            # "'ssh-v1' did not match a category, filename, or directory".
            # Existence-check matches the pattern used for the other scripts
            # so we degrade gracefully when nmap-scripts is uninstalled.
            ssh_script_list: list = []
            if _script_exists("sshv1"):
                ssh_script_list.append("sshv1")
            if _script_exists("ssh-auth-methods"):
                ssh_script_list.append("ssh-auth-methods")
            if _script_exists("ssh2-enum-algos"):
                ssh_script_list.append("ssh2-enum-algos")
            if ssh_script_list:
                nse_passes.append((ssh_ports, ",".join(ssh_script_list)))
        if smb_ports:
            smb_scripts = "smb-security-mode,smb-os-discovery,smb-enum-shares,smb-system-info,smb-protocols"
            if _script_exists("smb-vuln-ms17-010"):
                smb_scripts += ",smb-vuln-ms17-010"
            if _script_exists("smb-vuln-cve-2020-0796"):
                smb_scripts += ",smb-vuln-cve-2020-0796"
            nse_passes.append((smb_ports, smb_scripts))
        if rdp_ports:
            rdp_scripts = []
            for _s in ("rdp-vuln-ms12-020", "rdp-enum-encryption"):
                if _script_exists(_s):
                    rdp_scripts.append(_s)
            if rdp_scripts:
                nse_passes.append((rdp_ports, ",".join(rdp_scripts)))
        if ipmi_ports:
            ipmi_scripts = []
            for _s in ("ipmi-cipher-zero", "ipmi-version"):
                if _script_exists(_s):
                    ipmi_scripts.append(_s)
            if ipmi_scripts:
                nse_passes.append((ipmi_ports, ",".join(ipmi_scripts)))
        if nfs_ports:
            nfs_scripts = []
            for _s in ("nfs-showmount", "nfs-ls", "nfs-statfs", "rpcinfo"):
                if _script_exists(_s):
                    nfs_scripts.append(_s)
            if nfs_scripts:
                nse_passes.append((nfs_ports, ",".join(nfs_scripts)))
        if mysql_ports:
            mysql_scripts = []
            for _s in ("mysql-empty-password", "mysql-info", "mysql-databases"):
                if _script_exists(_s):
                    mysql_scripts.append(_s)
            if mysql_scripts:
                nse_passes.append((mysql_ports, ",".join(mysql_scripts)))
        if ftp_ports:
            ftp_nse = []
            for _s in ("ftp-anon", "ftp-bounce", "ftp-syst",
                        "ftp-vsftpd-backdoor", "ftp-proftpd-backdoor"):
                if _script_exists(_s):
                    ftp_nse.append(_s)
            if ftp_nse:
                nse_passes.append((ftp_ports, ",".join(ftp_nse)))
        if smtp_ports:
            smtp_nse = []
            for _s in ("smtp-commands",):
                if _script_exists(_s):
                    smtp_nse.append(_s)
            if smtp_nse:
                nse_passes.append((smtp_ports, ",".join(smtp_nse)))
        if dns_ports:
            dns_nse = []
            for _s in ("dns-recursion",):
                if _script_exists(_s):
                    dns_nse.append(_s)
            if dns_nse:
                nse_passes.append((dns_ports, ",".join(dns_nse)))
        if http_ports:
            http_nse = []
            for _s in ("http-methods",):
                if _script_exists(_s):
                    http_nse.append(_s)
            if http_nse:
                nse_passes.append((http_ports, ",".join(http_nse)))
        if redis_ports:
            redis_nse = []
            for _s in ("redis-info",):
                if _script_exists(_s):
                    redis_nse.append(_s)
            if redis_nse:
                nse_passes.append((redis_ports, ",".join(redis_nse)))
        if mongo_ports:
            mongo_nse = []
            for _s in ("mongodb-info", "mongodb-databases"):
                if _script_exists(_s):
                    mongo_nse.append(_s)
            if mongo_nse:
                nse_passes.append((mongo_ports, ",".join(mongo_nse)))
        if all_open and _script_exists("vulners"):
            nse_passes.append((all_open, "vulners"))

        for target_ports, scripts in nse_passes:
            ports_str   = ",".join(str(p) for p in target_ports)
            nse_args    = (f"-n -Pn --script {scripts} -p {ports_str} "
                           f"-T4 --max-retries 1 --host-timeout 2m")
            nse_cmd     = [nmap_path, "-n", "-Pn", "--script", scripts,
                           "-p", ports_str, "-T4", "--max-retries", "1",
                           "--host-timeout", "2m", ip]
            try:
                nm_nse = nmap.PortScanner()
                nm_nse.scan(hosts=ip, arguments=nse_args)
                if ip in nm_nse.all_hosts():
                    # Collect (port, scripts_dict) pairs — findings are logged
                    # after nse_out is written so the output_file path is known.
                    _nse_pending: list[tuple] = []
                    for proto in nm_nse[ip].all_protocols():
                        for port in nm_nse[ip][proto].keys():
                            nse_scripts_out = nm_nse[ip][proto][port].get("script", {})
                            if nse_scripts_out and port in results:
                                # Merge script output into existing port result
                                results[port].setdefault("scripts", {}).update(
                                    nse_scripts_out
                                )
                                if output_mgr:
                                    _nse_pending.append((port, nse_scripts_out))
                if output_mgr:
                    nse_raw = _decode_nmap_output(
                        nm_nse.get_nmap_last_output()
                        if hasattr(nm_nse, "get_nmap_last_output") else b""
                    )
                    # SSH NSE scans go to ssh/ directory; all others to nmap/
                    _is_ssh_nse = any(
                        s in scripts
                        for s in ("sshv1", "ssh-auth-methods", "ssh2-enum-algos")
                    )
                    if _is_ssh_nse:
                        _ssh_dir = output_mgr.service_path(ip, "ssh")
                        _ssh_fname = output_mgr._safe_filename(
                            [ip, "ssh_nse", datetime.now().strftime("%Y%m%d_%H%M%S")], "txt"
                        )
                        nse_out = _ssh_dir / _ssh_fname
                        nse_out.write_text(nse_raw, encoding="utf-8")
                    else:
                        nse_out = output_mgr.write_nmap_output(
                            ip, f"nse_{scripts.split(',')[0]}", nse_raw
                        )
                    # Now parse findings — output_file is known
                    for _nse_port, _nse_scripts in _nse_pending:
                        _parse_nse_findings(
                            output_mgr, ip, _nse_port, hostname,
                            _nse_scripts, nse_cmd,
                            output_file=str(nse_out),
                        )
                    # Also persist as .xml + synthesised .gnmap + .nmap so
                    # analysts get the full -oA trio for every NSE pass.
                    if nse_raw.lstrip().startswith("<?xml"):
                        try:
                            output_mgr.write_nmap_oA_siblings(
                                nse_out.with_suffix(""), nse_raw
                            )
                        except OSError:
                            pass
                    output_mgr.log_command(
                        "nmap-nse", nmap_path, nse_cmd, nse_out,
                        extra={"target": ip, "scripts": scripts,
                               "ports": ports_str},
                    )
            except Exception as nse_exc:
                if output_mgr:
                    output_mgr.log_error(
                        "nmap-nse", nmap_path, nse_cmd, str(nse_exc),
                        extra={"target": ip, "scripts": scripts},
                    )

        # ── ssh-audit: deep SSH algorithm + CVE assessment per port ─────────
        # Runs after the NSE pass so banner-derived OS / version hints are
        # already in the software inventory. ssh-audit produces a structured
        # JSON report covering banner CVEs, KEX/host-key/cipher/MAC algorithm
        # severity, and configuration recommendations — strictly more detail
        # than the ssh-auth-methods / ssh2-enum-algos NSE scripts. Per-port
        # so a host running both 22/tcp and 2222/tcp gets both audited.
        if output_mgr and ssh_ports:
            for _ssh_port in ssh_ports:
                run_ssh_audit(ip, _ssh_port, hostname, output_mgr)

        # ── SMB UDP scan: smb-security-mode against U:137 and T:139 ─────────
        # Run as a direct subprocess (not python-nmap) so we can pass -sU -sS
        # and -oX simultaneously — python-nmap forbids -oX in its argument string.
        if smb_ports:
            ts_safe_udp = datetime.now().strftime("%Y%m%d_%H%M%S")
            safe_ip_udp = ip.replace(".", "_")
            smb_udp_cmd = [
                nmap_path, "-n", "-Pn", "-sU", "-sS",
                "--script", "smb-security-mode",
                "-p", "U:137,T:139",
                "-T4", "--max-retries", "1", "--host-timeout", "2m",
            ]
            if output_mgr:
                _xml_smb = str(
                    output_mgr.host_path(ip) /
                    f"smb_udp_{ts_safe_udp}.xml"
                )
                smb_udp_cmd += ["-oX", _xml_smb]
            smb_udp_cmd.append(ip)
            try:
                udp_proc = subprocess.run(
                    smb_udp_cmd, capture_output=True, text=True, timeout=180,
                )
                udp_out = udp_proc.stdout + (udp_proc.stderr or "")
                if output_mgr:
                    _udp_txt = (
                        output_mgr.host_path(ip) /
                        f"smb_udp_{ts_safe_udp}.txt"
                    )
                    try:
                        _udp_txt.parent.mkdir(parents=True, exist_ok=True)
                        _udp_txt.write_text(udp_out, encoding="utf-8")
                    except OSError:
                        pass
                    output_mgr.log_command(
                        "nmap-smb-udp", nmap_path, smb_udp_cmd, _udp_txt,
                        extra={"target": ip, "scan_type": "smb_udp_137_139"},
                    )
                    # Parse smb-security-mode from the subprocess text output
                    if "smb-security-mode" in udp_out:
                        _parse_nse_findings(
                            output_mgr, ip, 137, hostname,
                            {"smb-security-mode": udp_out},
                            smb_udp_cmd,
                        )
            except subprocess.TimeoutExpired:
                _tprint(
                    f"{Fore.YELLOW}  [~] SMB UDP scan timed out for "
                    f"{ip}{Style.RESET_ALL}"
                )
                _log_timeout_action(output_mgr, "nmap", ip, 137, hostname, 30)
            except Exception as _smb_udp_exc:
                if output_mgr:
                    output_mgr.log_error(
                        "nmap-smb-udp", nmap_path, smb_udp_cmd,
                        str(_smb_udp_exc), extra={"target": ip},
                    )

    except Exception as e:
        err_msg = str(e)
        _tprint(f"{Fore.RED}  [!] Port scan error for {ip}: {err_msg}{Style.RESET_ALL}")
        if output_mgr:
            output_mgr.log_error(
                "nmap", nmap_path, cmd_list, err_msg,
                extra={"target": ip, "hostname": hostname, "scan_type": "port_scan"},
            )

    # Generate human-readable .txt summary now that results are fully parsed
    if output_mgr and out_path and results:
        try:
            _txt_lines = [
                f"Nmap port scan: {ip}",
                f"Timestamp    : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
                "",
                f"{'PORT':<14} {'STATE':<8} {'SERVICE':<18} VERSION",
                "─" * 70,
            ]
            for _p, _pi in sorted(results.items()):
                _ptag = f"{_p}/{_pi.get('proto', 'tcp')}"
                _svc  = _pi.get("name", "")
                _ver  = " ".join(filter(None, [
                    _pi.get("product", ""), _pi.get("version", ""),
                    f"({_pi['extrainfo']})" if _pi.get("extrainfo") else "",
                ])).strip()
                _txt_lines.append(
                    f"{_ptag:<14} {'open':<8} {_svc:<18} {_ver}"
                )
            out_path.write_text("\n".join(_txt_lines) + "\n", encoding="utf-8")
        except Exception:
            pass

    # ── Phase D + E + F + G ────────────────────────────────────────────────
    # After base scan + NSE pass + SSH-audit + SMB UDP have all completed,
    # run a unified per-port enrichment:
    #   • identify services nmap left blank/unknown via netcat banner
    #   • curl every web port (canonical or not) and save the response
    #   • netcat every non-web port and save the banner
    #   • emit informational findings for non-standard web ports AND
    #     for known services running on non-standard ports
    try:
        probe_uncertain_and_nonstandard_ports(
            ip, results, output_mgr, hostname=hostname,
        )
    except Exception as _pu_exc:
        if output_mgr:
            output_mgr.log_error(
                "port-enrich", "scattershot3", "(internal)", str(_pu_exc),
                extra={"target": ip},
            )

    return results, out_path


def _port_scan_worker(
    ip: str,
    hostname: str | None,
    fast: bool,
    output_mgr: "OutputManager",
    nmap_path: str,
    args,
    sslscan_path: "str | None" = None,
    testssl_path:  "str | None" = None,
    snmpwalk_path: "str | None" = None,
    smbmap_path:   "str | None" = None,
    enum4linux_path: "str | None" = None,
    adenum_path:   "str | None" = None,
    scope: str = "int",
    cred_store: "CredentialStore | None" = None,
    gobuster_path: "str | None" = None,
    wpscan_path:   "str | None" = None,
    webanalyze_path: "str | None" = None,
    shcheck_path:  "str | None" = None,
    wpscan_token:  "str | None" = None,
    showmount_path: "str | None" = None,
    ipmitool_path:  "str | None" = None,
    rustscan_path: "str | None" = None,
    resolve_hostname: bool = False,
    nmblookup_path: "str | None" = None,
    avahi_resolve_path: "str | None" = None,
    hostnames_out: "dict | None" = None,
) -> "tuple[str, dict]":
    """
    Self-contained worker: port scan one IP then run all per-port secondary
    tasks (web probe, banner, sslscan, testssl, web-file download).

    Called concurrently from scan_scope's ThreadPoolExecutor (20 workers).
    Each call creates its own nmap.PortScanner() via port_scan(), so there
    is no shared mutable nmap state between threads.

    Port scanning (nmap)
    --------------------
    port_scan() runs a single nmap subprocess for this IP.  nmap handles
    its own probe-level parallelism internally via its timing engine (-T4).

    Per-port secondary tasks
    ------------------------
    Once port_scan() returns, all secondary tasks for this host's open ports
    are dispatched concurrently via a nested ThreadPoolExecutor.  sslscan,
    testssl, and web-file download all start as soon as a TLS/web port is
    identified — concurrent with each other and with tasks on other ports of
    the same host.

    Hostname tracking
    -----------------
    hostnames_by_port : dict mapping port int → FQDN
      Populated from TLS certificate SANs (preferred) or SNI from testssl.
      The first non-wildcard SAN for each port is stored, keeping the
      FQDN–port association intact for multi-vhost IPs.

    Returns (ip, host_result_dict).
    """
    # ── Per-host hostname resolution (when chunked pipeline is active) ────
    if resolve_hostname and hostname is None:
        hostname = _resolve_hostname_single(
            ip, output_mgr,
            nmblookup_path=nmblookup_path,
            avahi_resolve_path=avahi_resolve_path,
        )
        if hostnames_out is not None:
            hostnames_out[ip] = hostname

    _tprint(f"  {Fore.WHITE}[>] Scanning {ip}...{Style.RESET_ALL}", flush=True)

    open_ports, _ps_out_path = port_scan(
        ip,
        fast=fast,
        output_mgr=output_mgr,
        nmap_path=nmap_path,
        hostname=hostname,
        rustscan_path=rustscan_path,
        scope=scope,
    )

    # ── UDP supplementary scan ────────────────────────────────────────────
    _udp_unconfirmed: "dict[int, dict]" = {}
    _udp_xml_path: "str | None" = None
    if not getattr(args, "no_udp", False) and output_mgr:
        _udp_top = getattr(args, "udp_top_ports", 20)
        try:
            _udp_confirmed, _udp_unconfirmed, _udp_xml_path = run_udp_scan(
                ip, output_mgr, nmap_path=nmap_path,
                hostname=hostname, scope=scope, top_ports=_udp_top,
            )
            # Merge only confirmed UDP ports into open_ports (findings).
            # TCP ports take precedence.
            if _udp_confirmed:
                for _udp_port, _udp_info in _udp_confirmed.items():
                    if _udp_port not in open_ports:
                        open_ports[_udp_port] = _udp_info
            # Emit unconfirmed (open|filtered) ports to Vantage for
            # informational display — they do NOT generate findings.
            for _uf_port, _uf_info in _udp_unconfirmed.items():
                _vc.port(
                    ip=ip,
                    port=_uf_port,
                    proto="udp",
                    name=_uf_info.get("name", "") or "",
                    product=_uf_info.get("product", "") or "",
                    version=_uf_info.get("version", "") or "",
                    extrainfo=_uf_info.get("extrainfo", "") or "",
                    state="open|filtered",
                    scope=scope,
                    hostname=hostname,
                )
            # Rewrite the portscan .txt to include UDP ports — the original
            # was written inside port_scan() with TCP-only results, so UDP
            # ports would be missing from the evidence file.
            if _ps_out_path and (_udp_confirmed or _udp_unconfirmed):
                try:
                    _txt_lines = [
                        f"Nmap port scan: {ip}",
                        f"Timestamp    : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
                        "",
                        f"{'PORT':<14} {'STATE':<16} {'SERVICE':<18} VERSION",
                        "─" * 78,
                    ]
                    for _p, _pi in sorted(open_ports.items()):
                        _ptag = f"{_p}/{_pi.get('proto', 'tcp')}"
                        _svc  = _pi.get("name", "")
                        _ver  = " ".join(filter(None, [
                            _pi.get("product", ""), _pi.get("version", ""),
                            f"({_pi['extrainfo']})" if _pi.get("extrainfo") else "",
                        ])).strip()
                        _txt_lines.append(
                            f"{_ptag:<14} {'open':<16} {_svc:<18} {_ver}"
                        )
                    # Append unconfirmed UDP ports in a separate section
                    if _udp_unconfirmed:
                        _txt_lines.append("")
                        _txt_lines.append(f"{'─' * 78}")
                        _txt_lines.append("Unconfirmed UDP ports (open|filtered — no response received):")
                        _txt_lines.append(f"{'─' * 78}")
                        for _p, _pi in sorted(_udp_unconfirmed.items()):
                            _ptag = f"{_p}/udp"
                            _svc  = _pi.get("name", "")
                            _ver  = " ".join(filter(None, [
                                _pi.get("product", ""), _pi.get("version", ""),
                                f"({_pi['extrainfo']})" if _pi.get("extrainfo") else "",
                            ])).strip()
                            _txt_lines.append(
                                f"{_ptag:<14} {'open|filtered':<16} {_svc:<18} {_ver}"
                            )
                    Path(_ps_out_path).write_text(
                        "\n".join(_txt_lines) + "\n", encoding="utf-8",
                    )
                except Exception:
                    pass
        except Exception as _udp_exc:
            _tprint(f"  {Fore.RED}[!] UDP scan error for {ip}: {_udp_exc}{Style.RESET_ALL}")

    _uf_count = len(_udp_unconfirmed)
    if not open_ports and not _uf_count:
        _tprint(f"  {Fore.YELLOW}    {ip} — no open ports found.{Style.RESET_ALL}")
    else:
        _parts = []
        if open_ports:
            _parts.append(f"{len(open_ports)} open port(s)")
        if _uf_count:
            _parts.append(f"{_uf_count} unconfirmed UDP")
        _tprint(f"  {Fore.GREEN}    {ip} — {' · '.join(_parts)}{Style.RESET_ALL}")
        # Log "Discovery: Open Ports" immediately — before port handlers run —
        # so single-port hosts (where the handler may be the only slow task)
        # still produce this finding regardless of later handler timing/errors.
        if output_mgr and open_ports:
            _op_affected = []
            for _op_port, _op_info in sorted(open_ports.items()):
                _op_proto = _op_info.get("proto", "tcp")
                _op_parts = [x for x in [
                    _op_info.get("name", ""),
                    _op_info.get("product", ""),
                    _op_info.get("version", ""),
                ] if x]
                _op_svc = " / ".join(_op_parts) if _op_parts else "unknown service"
                _op_affected.append(f"{ip}  {_op_port}/{_op_proto}  {_op_svc}")
                # Live-emit so Vantage's Targets tab adds the port row as
                # soon as it is discovered, without waiting for targets.json.
                _vc.port(
                    ip=ip,
                    port=_op_port,
                    proto=_op_proto,
                    name=_op_info.get("name", "") or "",
                    product=_op_info.get("product", "") or "",
                    version=_op_info.get("version", "") or "",
                    extrainfo=_op_info.get("extrainfo", "") or "",
                    state=_op_info.get("state", "open"),
                    scope=scope,
                    hostname=hostname,
                )
            output_mgr.log_finding(
                title="Discovery: Open Ports",
                ip=ip, port=0,
                command=f"nmap -sV {ip}",
                hostname=hostname,
                risk="INFO",
                description=(
                    "TCP or UDP ports were confirmed open on the target host, indicating "
                    "exposed services that contribute to the overall network attack surface."
                ),
                sources="nmap",
                output="\n".join(_op_affected),
                affected=ip,
                output_file=str(_ps_out_path) if _ps_out_path else None,
            )
        # Log unconfirmed (open|filtered) UDP ports as a separate INFO finding
        if output_mgr and _udp_unconfirmed:
            _uf_affected = []
            for _uf_port, _uf_info in sorted(_udp_unconfirmed.items()):
                _uf_parts = [x for x in [
                    _uf_info.get("name", ""),
                    _uf_info.get("product", ""),
                    _uf_info.get("version", ""),
                ] if x]
                _uf_svc = " / ".join(_uf_parts) if _uf_parts else "unknown service"
                _uf_affected.append(f"{ip}  {_uf_port}/udp  {_uf_svc}")
            output_mgr.log_finding(
                title="Unconfirmed UDP Ports (open|filtered)",
                ip=ip, port=0,
                command=f"nmap -sU --top-ports {getattr(args, 'udp_top_ports', 20)} {ip}",
                hostname=hostname,
                risk="INFO",
                description=(
                    "The following UDP ports were reported as open|filtered by nmap. "
                    "This means no response was received — the port may be open (silently "
                    "accepting packets) or filtered by a firewall. Unlike confirmed open "
                    "ports, these did not produce an actual UDP response and should be "
                    "considered unconfirmed. Manual verification is recommended for any "
                    "ports of interest."
                ),
                sources="nmap",
                output="\n".join(_uf_affected),
                affected=ip,
                output_file=",".join(filter(None, [
                    str(_udp_xml_path) if _udp_xml_path else None,
                    str(_ps_out_path) if _ps_out_path else None,
                ])) or None,
            )

    host_result: dict = {
        "alive":             True,
        "hostname":          hostname,
        "hostnames_by_port": {},    # port → FQDN from cert SANs / SNI
        "open_ports":        {},
        "unconfirmed_ports": dict(_udp_unconfirmed),  # open|filtered UDP
        "web_services":      [],
        "ssl_results":       {},
        "web_files":         {},    # port → list[str] of downloaded file paths
    }
    # Internal mutable state shared between nested closures (Python 3 nonlocal)
    hbp: dict[int, str] = {}        # hostnames_by_port accumulator

    def _handle_port(port: int, info: dict) -> dict:
        """
        Run all secondary tasks for one port and return the updated info dict.

        Executed inside the per-host thread pool so all ports are handled
        concurrently.  Submits sslscan / testssl / web-download as sub-tasks
        to a nested ThreadPoolExecutor that runs them concurrently with each
        other, then waits for all to finish before returning.
        """
        out = dict(info)
        out["web"]    = None
        out["banner"] = None
        out["ssl"]    = {}

        is_web = port_looks_like_web(port, info.get("name", ""))
        is_tls = port_is_tls(port, None)

        # ── Web probe ──────────────────────────────────────────────────────
        web_result = None
        if is_web and not getattr(args, "no_web", False):
            web_result = probe_http(ip, port, timeout=args.web_timeout)
            out["web"] = web_result
            if web_result.get("responds"):
                with _PRINT_LOCK:
                    host_result["web_services"].append(
                        {"port": port, "hostname": hostname, **web_result}
                    )
                # Save HTTP response summary to http/ directory
                if output_mgr:
                    try:
                        _http_dir = output_mgr.service_path(ip, "http")
                        _http_safe_ip = ip.replace(".", "_")
                        _http_file = _http_dir / f"{port}_http.txt"
                        _http_scheme = (web_result.get("scheme")
                                        or ("https" if port_is_tls(port, web_result) else "http"))
                        _http_url = _clean_url(_http_scheme, ip, port)
                        _http_lines = [
                            f"URL       : {_http_url}",
                            f"Status    : {web_result.get('status_code', 'unknown')}",
                            f"Server    : {web_result.get('server', '(none)')}",
                        ]
                        if web_result.get("title"):
                            _http_lines.append(f"Title     : {web_result['title']}")
                        if web_result.get("redirect"):
                            _http_lines.append(f"Redirect  : {web_result['redirect']}")
                        _sc_list = web_result.get("set_cookies") or []
                        if _sc_list:
                            _http_lines.append("")
                            for _sc_hdr in _sc_list:
                                _http_lines.append(f"Set-Cookie: {_sc_hdr}")
                        _http_file.write_text("\n".join(_http_lines), encoding="utf-8")
                        output_mgr.log_finding(
                            title="Discovery: Web Page",
                            ip=ip, port=port, command=[],
                            hostname=hostname,
                            risk="INFO",
                            description=f"HTTP service responded at {_http_url}",
                            sources="http",
                            output="\n".join(_http_lines),
                            affected=_http_url,
                            output_file=str(_http_file),
                        )
                        # ── Action Item: web app → Fracture ──────────
                        output_mgr.log_action_item(
                            item_type="web_app",
                            recommended_tool="Fracture",
                            target=_http_url,
                            ip=ip, port=port,
                            title="Web Application Identified — Fracture Testing Recommended",
                            description=(
                                f"HTTP service detected at {_http_url}. "
                                "Recommend Fracture for comprehensive web application "
                                "penetration testing (OWASP Top 10, injection, "
                                "authentication, session management, etc.)."
                            ),
                            hostname=hostname,
                            source_finding="Discovery: Web Page",
                            priority="HIGH",
                        )
                        # ── Action Item: API indicators → Siphon ─────
                        _ai_body  = (web_result.get("body") or "").lower()
                        _ai_title = (web_result.get("title") or "").lower()
                        _api_indicators = (
                            "swagger" in _ai_body
                            or "openapi" in _ai_body
                            or "graphql" in _ai_body
                            or "/api/" in _ai_body
                            or "api-docs" in _ai_body
                            or "swagger-ui" in _ai_body
                            or "redoc" in _ai_body
                            or '"paths"' in _ai_body
                            or "swagger" in _ai_title
                            or "api" in _ai_title
                        )
                        if _api_indicators:
                            output_mgr.log_action_item(
                                item_type="api",
                                recommended_tool="Siphon",
                                target=_http_url,
                                ip=ip, port=port,
                                title="API Endpoint Identified — Siphon Testing Recommended",
                                description=(
                                    f"API indicators detected at {_http_url}. "
                                    "Recommend Siphon for API penetration testing "
                                    "(OWASP API Top 10, BOLA, BFLA, mass assignment, "
                                    "rate limiting, data exposure, etc.)."
                                ),
                                hostname=hostname,
                                source_finding="Discovery: Web Page",
                                priority="HIGH",
                            )
                    except Exception:
                        pass

                # ── Cookie attribute checking ──────────────────────────────
                _sc_cookies = web_result.get("set_cookies") or []
                _is_https   = web_result.get("scheme") == "https"
                _sc_cmd_str = f"HTTP GET {web_result.get('scheme','http')}://{ip}:{port}/"
                for _sc in _sc_cookies:
                    if not _sc:
                        continue
                    _sc_lo   = _sc.lower()
                    _cname   = (_sc.split("=")[0].strip() if "=" in _sc
                                else _sc.split(";")[0].strip())
                    if _INFRA_COOKIE_RE.match(_cname):
                        continue
                    if _is_deletion_cookie(_sc):
                        continue
                    _sc_out  = f"Set-Cookie: {_sc[:300]}"
                    if "httponly" not in _sc_lo:
                        output_mgr.log_finding(
                            title="Cookies: Missing HttpOnly Flag",
                            ip=ip, port=port, hostname=hostname, risk="LOW",
                            command=_sc_cmd_str,
                            description=(
                                f"Cookie '{_cname}' does not have the HttpOnly attribute. "
                                "Without HttpOnly, the cookie is accessible to JavaScript, "
                                "exposing it to XSS-based theft."
                            ),
                            output=_sc_out,
                            sources="http",
                            affected=_http_url,
                            output_file=str(_http_file),
                        )
                    if _is_https and "secure" not in _sc_lo:
                        output_mgr.log_finding(
                            title="Cookies: Missing Secure Flag",
                            ip=ip, port=port, hostname=hostname, risk="LOW",
                            command=_sc_cmd_str,
                            description=(
                                f"Cookie '{_cname}' does not have the Secure attribute on an "
                                "HTTPS site. Without Secure, the cookie can be transmitted "
                                "over unencrypted HTTP connections."
                            ),
                            output=_sc_out,
                            sources="http",
                            affected=_http_url,
                            output_file=str(_http_file),
                        )
                    _ss_m = re.search(r'samesite\s*=\s*([^\s;,]+)', _sc_lo)
                    if not _ss_m:
                        output_mgr.log_finding(
                            title="Cookies: Missing SameSite Attribute",
                            ip=ip, port=port, hostname=hostname, risk="LOW",
                            command=_sc_cmd_str,
                            description=(
                                f"Cookie '{_cname}' does not have the SameSite attribute. "
                                "Without SameSite, the cookie is sent with cross-site requests, "
                                "increasing CSRF risk."
                            ),
                            output=_sc_out,
                            sources="http",
                            affected=_http_url,
                            output_file=str(_http_file),
                        )
                    else:
                        _ss_val = _ss_m.group(1).strip()
                        if _ss_val not in ("strict", "lax", "none"):
                            output_mgr.log_finding(
                                title="Cookies: Misconfigured SameSite Attribute",
                                ip=ip, port=port, hostname=hostname, risk="LOW",
                                command=_sc_cmd_str,
                                description=(
                                    f"Cookie '{_cname}' has SameSite set to an unrecognised "
                                    f"value '{_ss_val}'. Browsers treat it as SameSite=None."
                                ),
                                output=_sc_out,
                                sources="http",
                                affected=_http_url,
                                output_file=str(_http_file),
                            )
                        elif _ss_val == "none" and "secure" not in _sc_lo:
                            output_mgr.log_finding(
                                title="Cookies: Misconfigured SameSite Attribute",
                                ip=ip, port=port, hostname=hostname, risk="LOW",
                                command=_sc_cmd_str,
                                description=(
                                    f"Cookie '{_cname}' has SameSite=None without the Secure "
                                    "attribute. Browsers reject or block such cookies."
                                ),
                                output=_sc_out,
                                sources="http",
                                affected=_http_url,
                                output_file=str(_http_file),
                            )

                # Record server header software
                server_hdr = (web_result.get("server") or "").strip()
                if server_hdr and output_mgr:
                    sw_name, sw_ver = _parse_server_header(server_hdr)
                    record_software(
                        output_mgr, ip, port, hostname,
                        software_name=sw_name, version=sw_ver,
                        os_info=None, method="HTTP Server header",
                        evidence_line=f"Server: {server_hdr}",
                    )
                    if sw_ver:
                        check_eol_and_vulns(
                            output_mgr, ip, port, hostname,
                            software_name=sw_name, version=sw_ver,
                            method="HTTP Server header",
                        )
            # Re-check TLS using the actual HTTP probe result
            is_tls = port_is_tls(port, web_result)

        # ── Banner grab ────────────────────────────────────────────────────
        if not getattr(args, "no_banner", False):
            banner_result = grab_banner_smart(
                ip, port, info.get("name", ""), web_result,
                timeout=args.banner_timeout,
            )
            out["banner"] = banner_result
            if banner_result is not None:
                output_mgr.log_banner(ip, port, banner_result, hostname=hostname)
                btext = (banner_result.get("banner") or "").strip()
                if btext and output_mgr:
                    first_line = btext.splitlines()[0][:120]

                    # ── SSH banner: "SSH-2.0-OpenSSH_8.9p1 Ubuntu-3ubuntu0.6"
                    _ssh_m = re.match(
                        r"SSH-[\d.]+-(?P<product>[A-Za-z][A-Za-z0-9_.-]+?)_"
                        r"(?P<version>[\d][^\s]*)(?:\s+(?P<os_str>\S+))?",
                        first_line,
                    )
                    if _ssh_m:
                        sw_name  = _ssh_m.group("product")              # e.g. "OpenSSH"
                        sw_ver   = _ssh_m.group("version")              # e.g. "8.9p1"
                        _os_str  = (_ssh_m.group("os_str") or "").strip()
                        # Resolve OS name from the banner's OS component
                        _os_disp, _os_eol_key = _resolve_ssh_os(_os_str)
                        # Persist product/version back into the port_info dict so
                        # build_correlated_report can read them from open_ports.
                        info["product"] = sw_name
                        info["version"] = sw_ver
                        record_software(
                            output_mgr, ip, port, hostname,
                            software_name=sw_name, version=sw_ver,
                            os_info=_os_disp or None, method="SSH banner",
                            evidence_line=first_line,
                        )
                        check_eol_and_vulns(
                            output_mgr, ip, port, hostname,
                            software_name=sw_name, version=sw_ver,
                            method="SSH banner",
                        )
                        # Check OS EOL if we resolved a real OS name
                        if _os_disp:
                            check_os_eol(
                                output_mgr, ip, port, hostname,
                                os_name=_os_eol_key or _os_disp,
                                method="SSH banner",
                            )
                    else:
                        # Generic heuristic: "ProductName X.Y.Z ..."
                        bparts = first_line.split()
                        if len(bparts) >= 2 and re.match(r"\d", bparts[1]):
                            record_software(
                                output_mgr, ip, port, hostname,
                                software_name=bparts[0], version=bparts[1],
                                os_info=None, method="banner grab",
                                evidence_line=first_line,
                            )
                            check_eol_and_vulns(
                                output_mgr, ip, port, hostname,
                                software_name=bparts[0], version=bparts[1],
                                method="banner grab",
                            )
                            info["product"] = bparts[0]
                            info["version"] = bparts[1]

        # ── Concurrent SSL / web-download sub-tasks ────────────────────────
        # Launched as soon as we know the port is web/TLS — no need to wait
        # for other ports or other hosts.
        if (is_web or is_tls) and not getattr(args, "no_ssl", False):
            sub_futures: list[tuple[str, "Future"]] = []
            with ThreadPoolExecutor(max_workers=min(5, _SCAN_SEM.limit)) as sub:
                if is_tls:
                    if sslscan_path:
                        sub_futures.append(("sslscan", sub.submit(
                            run_sslscan, ip, port, sslscan_path,
                            args.sslscan_timeout, output_mgr, hostname,
                        )))
                    if testssl_path:
                        sub_futures.append(("testssl", sub.submit(
                            run_testssl, ip, port, testssl_path,
                            args.testssl_timeout, output_mgr, hostname,
                        )))
                if is_web and web_result and web_result.get("responds"):
                    sub_futures.append(("webdl", sub.submit(
                        download_web_files,
                        ip, port,
                        web_result.get("scheme", "http"),
                        hostname,
                        output_mgr,
                        args.web_timeout,
                        cred_store,
                    )))
                    # Screenshot — submitted concurrently with the file download
                    if not getattr(args, "no_screenshots", False):
                        sub_futures.append(("screenshot", sub.submit(
                            take_web_screenshot,
                            ip, port,
                            web_result.get("scheme", "http"),
                            output_mgr,
                            hostname,
                            getattr(args, "screenshot_timeout_ms", 15_000),
                        )))

                ssl_entry: dict = {}
                for tag, fut in sub_futures:
                    try:
                        res = fut.result()
                        if tag == "sslscan":
                            ssl_entry["sslscan"] = res
                            # Harvest SANs for FQDN–port mapping
                            for san in res.get("cert_san", []):
                                san = san.strip()
                                if san and not san.startswith("*."):
                                    hbp.setdefault(port, san)
                                    break
                            # Record sslscan scanner version only (not OpenSSL — that's
                            # the scanner's bundled library, not the target's software)
                            ss_ver, _ossl_ver = _parse_sslscan_version(sslscan_path)
                            if ss_ver and ss_ver != "unknown":
                                record_software(
                                    output_mgr, ip, port,
                                    hbp.get(port, hostname),
                                    software_name="sslscan", version=ss_ver,
                                    os_info=None, method="sslscan --version",
                                )
                        elif tag == "testssl":
                            ssl_entry["testssl"] = res
                            for san in res.get("cert_san", []):
                                san = san.strip()
                                if san and not san.startswith("*."):
                                    hbp.setdefault(port, san)
                                    break
                        elif tag == "webdl":
                            with _PRINT_LOCK:
                                host_result["web_files"][port] = res
                            # Scan downloaded files for embedded credentials
                            if res and cred_store:
                                try:
                                    extract_web_credentials(
                                        ip, port, res, cred_store,
                                        output_mgr, hostname=hostname,
                                    )
                                except Exception:
                                    pass
                        elif tag == "screenshot":
                            # res is the path string or None — no further action needed;
                            # take_web_screenshot handles its own logging
                            pass
                    except Exception as exc:
                        _tprint(
                            f"{Fore.RED}  [!] {tag} failed for "
                            f"{ip}:{port}: {exc}{Style.RESET_ALL}"
                        )

                out["ssl"] = ssl_entry
                with _PRINT_LOCK:
                    if ssl_entry:
                        host_result["ssl_results"][port] = ssl_entry

        # ── SNMP community string check + snmpwalk ─────────────────────
        svc_name = info.get("name", "").lower()
        is_snmp  = (svc_name in ("snmp", "snmptrap") or port in (161, 162))
        if is_snmp and snmpwalk_path and not getattr(args, "no_snmp", False):
            try:
                run_snmp_checks(ip, port, snmpwalk_path, output_mgr,
                                hostname=hostname, scope=scope)
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] SNMP check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── FTP checks (anon + rate limiting + default creds) ─────────
        is_ftp = (svc_name in ("ftp", "ftps") or port == 21)
        if is_ftp and not getattr(args, "no_enum", False):
            try:
                run_ftp_anon_check(ip, port, output_mgr,
                                   hostname=hostname, scope=scope)
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] FTP anon check error {ip}:{port}: {exc}{Style.RESET_ALL}")
            _ftp_delay = 0.0
            try:
                _rl = _detect_ftp_rate_limit(ip, port, output_mgr,
                                             hostname=hostname, scope=scope)
                _ftp_delay = _rl.get("delay", 0.0)
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] FTP rate-limit probe error {ip}:{port}: {exc}{Style.RESET_ALL}")
            try:
                run_ftp_default_cred_check(
                    ip, port, output_mgr, hostname=hostname, scope=scope,
                    cred_store=cred_store, inter_attempt_delay=_ftp_delay,
                )
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] FTP default cred check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── SMB null session ───────────────────────────────────────────
        is_smb = (svc_name in ("microsoft-ds", "netbios-ssn", "smb") or port in (139, 445))
        if is_smb and not getattr(args, "no_enum", False):
            try:
                run_smb_null_session(ip, port, output_mgr,
                                     hostname=hostname, scope=scope,
                                     smbmap_path=smbmap_path)
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] SMB null session error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── RPC null session ───────────────────────────────────────────
        is_rpc = (svc_name in ("msrpc", "rpcbind", "epmap") or port in (111, 135, 593))
        if is_rpc and not getattr(args, "no_enum", False):
            try:
                run_rpc_null_session(ip, port, output_mgr,
                                     hostname=hostname, scope=scope)
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] RPC null session error {ip}:{port}: {exc}{Style.RESET_ALL}")
            if svc_name in ("rpcbind",) or port == 111:
                try:
                    output_mgr.log_action_item(
                        "rpc_enum", "Manual (rpcinfo / nfs)", f"{ip}:{port}",
                        ip, port,
                        title="RPC: Enumerate Exported Services",
                        description=(
                            f"RPC portmapper detected on {ip}:{port}. Enumerate "
                            f"registered RPC services to identify NFS exports, "
                            f"mountd, statd, and other exploitable services.\n"
                            f"Next steps:\n"
                            f"  1. rpcinfo -p {ip}\n"
                            f"  2. showmount -e {ip}\n"
                            f"  3. nmap -sV -p 111 --script=rpcinfo,nfs-ls,nfs-showmount {ip}\n"
                            f"  4. If NFS exports found: mount -t nfs {ip}:/<share> /mnt/nfs"
                        ),
                        hostname=hostname,
                        source_finding="RPC: Null Session Permitted",
                        priority="MEDIUM",
                    )
                except Exception:
                    pass

        # ── libSSH auth bypass check ───────────────────────────────────
        # Banner was already grabbed above; pass it through for version check.
        _is_ssh = (svc_name in ("ssh", "openssh") or port == 22)
        if _is_ssh and out.get("banner"):
            _ssh_banner = (out["banner"].get("banner") or "")
            if "libssh" in _ssh_banner.lower():
                try:
                    run_libssh_check(ip, port, output_mgr,
                                     hostname=hostname, scope=scope,
                                     banner=_ssh_banner)
                except Exception as exc:
                    _tprint(f"{Fore.RED}  [!] libSSH check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── Dredge: SSH on Windows endpoint ───────────────────────────
        if _is_ssh and out.get("banner"):
            _ssh_ban_lo = (out["banner"].get("banner") or "").lower()
            _is_win_ssh = ("openssh_for_windows" in _ssh_ban_lo
                           or "win32-openssh" in _ssh_ban_lo
                           or "windows" in (info.get("extrainfo") or "").lower())
            if _is_win_ssh:
                try:
                    output_mgr.log_action_item(
                        "endpoint_audit", "Dredge", f"{ip}:{port}",
                        ip, port,
                        title="Dredge: Windows endpoint audit via SSH",
                        description=(
                            f"SSH on {ip}:{port} is running on a Windows host "
                            f"(banner: {out['banner'].get('banner', '')[:80]}). "
                            f"Dredge can SCP its PowerShell collection script to "
                            f"the target, execute it via SSH, retrieve the endpoint "
                            f"security assessment results, and clean up.\n"
                            f"Access method: SSH\n"
                            f"Port: {port}\n"
                            f"Credentials: required (use discovered credentials "
                            f"or supply via Crucible)"
                        ),
                        hostname=hostname,
                        source_finding="SSH on Windows Endpoint",
                        priority="MEDIUM",
                        metadata={
                            "access_method": "ssh",
                            "ssh_port": port,
                            "ssh_banner": out["banner"].get("banner", "")[:200],
                            "credentials": None,
                        },
                    )
                except Exception:
                    pass

        # ── SMTP open relay + user enumeration ─────────────────────────
        is_smtp = (svc_name in ("smtp", "smtps", "submission") or port in (25, 465, 587))
        if is_smtp and not getattr(args, "no_enum", False):
            try:
                run_smtp_checks(ip, port, output_mgr, hostname=hostname,
                                scope=scope, timeout=getattr(args, "banner_timeout", 10))
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] SMTP check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── MySQL auth bypass ──────────────────────────────────────────
        is_mysql = (svc_name in ("mysql", "mysql-proxy") or port == 3306)
        if is_mysql and not getattr(args, "no_enum", False):
            try:
                run_mysql_auth_check(ip, port, output_mgr, hostname=hostname,
                                     scope=scope, timeout=getattr(args, "banner_timeout", 10))
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] MySQL check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── SIP user enumeration ───────────────────────────────────────
        is_sip = (svc_name in ("sip", "sip-tls") or port in (5060, 5061))
