        # ── Printer (PJL/JetDirect) enumeration ───────────────────────
        is_printer = (svc_name in ("jetdirect", "pjl", "pdl-datastream") or port == 9100)
        if is_printer and not getattr(args, "no_enum", False):
            try:
                run_printer_enum(ip, port, output_mgr, hostname=hostname,
                                 scope=scope, timeout=getattr(args, "banner_timeout", 10))
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] Printer enum error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── Redis unauthenticated access ───────────────────────────────
        is_redis = (svc_name in ("redis",) or port == 6379)
        if is_redis and not getattr(args, "no_enum", False):
            try:
                run_redis_check(ip, port, output_mgr, hostname=hostname,
                                scope=scope, timeout=getattr(args, "banner_timeout", 10))
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] Redis check error {ip}:{port}: {exc}{Style.RESET_ALL}")

        # ── Database service → Auger action item ──────────────────────
        _db_type = _DB_SERVICES.get(svc_name) or _DB_PORTS.get(port)
        # Skip Auger action items for ambiguous UDP ports —
        # open|filtered means nmap got no response (likely filtered).
        _udp_ambiguous = (info.get("proto") == "udp"
                          and info.get("state") == "open|filtered")
        if _db_type and output_mgr and not _udp_ambiguous:
            _db_version = ""
            _db_product = info.get("product", "")
            _db_ver     = info.get("version", "")
            if _db_product:
                _db_version = f" ({_db_product}"
                if _db_ver:
                    _db_version += f" {_db_ver}"
                _db_version += ")"
            # MSSQL Browser (UDP/TCP 1434) is a discovery service —
            # the actual database listener is on TCP 1433.
            _auger_port = port
            if _db_type == "MSSQL" and port == 1434:
                _auger_port = 1433
            output_mgr.log_action_item(
                item_type="database",
                recommended_tool="Auger",
                target=f"{ip}:{_auger_port}",
                ip=ip, port=_auger_port,
                title=f"{_db_type} Database Identified — Auger Audit Recommended",
                description=(
                    f"{_db_type} database service detected on {ip}:{port}{_db_version}. "
                    "Recommend Auger for comprehensive database security auditing "
                    "(authentication, authorization, encryption, configuration, "
                    "stored procedures, user privileges, etc.)."
                ),
                hostname=hostname,
                source_finding=f"{_db_type} service detection",
                priority="HIGH",
                metadata={
                    "db_type": _db_type.lower(),
                    "product": _db_product,
                    "version": _db_ver,
                },
            )

        # ── RDP security audit (protocols, NLA, encryption) ─────────
        is_rdp = (svc_name in ("ms-wbt-server", "rdp", "ms-term-serv") or port == 3389)
        if is_rdp and not getattr(args, "no_enum", False):
            try:
                run_rdp_check(ip, port, output_mgr, hostname=hostname,
                              scope=scope, timeout=getattr(args, "banner_timeout", 10))
            except Exception as exc:
                _tprint(f"{Fore.RED}  [!] RDP security audit error {ip}:{port}: {exc}{Style.RESET_ALL}")
            try:
                output_mgr.log_action_item(
                    "endpoint_audit", "Manual", f"{ip}:{port}",
                    ip, port,
                    title="Dredge: Windows endpoint audit (manual — RDP access)",
                    description=(
                        f"RDP is available on {ip}:{port}. If valid credentials "
                        f"are obtained, connect via RDP and manually run the "
                        f"Dredge PowerShell collection script on the target:\n"
                        f"  1. Copy dredge_collect.ps1 to the target\n"
                        f"  2. Open PowerShell as Administrator\n"
                        f"  3. .\\dredge_collect.bat\n"
                        f"  4. Retrieve the output JSON file\n"
                        f"  5. Delete dredge_collect.ps1 and the output JSON\n"
                        f"  6. Import the JSON into Crucible for analysis\n\n"
                        f"If WinRM is also available on this host, prefer the "
                        f"automated WinRM delivery method instead."
                    ),
                    hostname=hostname,
                    source_finding="RDP Service Detected",
                    priority="LOW",
                    metadata={
                        "access_method": "rdp",
                        "rdp_port": port,
                        "credentials": None,
                        "manual": True,
                    },
                )
            except Exception:
                pass

        # ── IPMI hash dumping ──────────────────────────────────────────
        is_ipmi = (svc_name in ("ipmi", "asf-rmcp", "asf-rmcp+") or port == 623)
