# TLS_PORTS is the broader set used by port_is_tls() to decide whether to
# run SSL scanners at all.  It overlaps with TLS_WRAP_PORTS but also includes
# ports that are TLS-only without needing the banner-grabber to wrap them
# (e.g. 5671 AMQPS, 8883 MQTT-TLS) because the SSL tools handle them directly.
TLS_PORTS = {443, 8443, 4443, 9443, 7443, 465, 587, 993, 995, 636, 5671, 8883}

COMMON_TESTSSL_PATHS = {
    "Darwin": ["/usr/local/bin/testssl.sh", "/opt/homebrew/bin/testssl.sh",
               "/usr/local/bin/testssl", "/opt/homebrew/bin/testssl"],
    "Linux":  ["/usr/bin/testssl.sh", "/usr/local/bin/testssl.sh",
               "/usr/bin/testssl",    "/usr/local/bin/testssl"],
    "Windows": [],  # testssl.sh is a bash script; works via WSL/Git Bash but not native
}

COMMON_SSLSCAN_PATHS = {
    "Darwin": ["/usr/local/bin/sslscan", "/opt/homebrew/bin/sslscan"],
    "Linux":  ["/usr/bin/sslscan", "/usr/local/bin/sslscan"],
    "Windows": [
        r"C:\Program Files\SSLScan\sslscan.exe",
        r"C:\Program Files (x86)\SSLScan\sslscan.exe",
    ],
}


def find_tool(name: str, extra_paths: list) -> str | None:
    """
    Return the path to *name* by checking PATH first, then a list of
    known absolute paths.  Returns None if not found anywhere.
    """
    found = shutil.which(name)
    if found:
        return found
    for p in extra_paths:
        if Path(p).exists():
            return p
    return None


def find_testssl() -> str | None:
    """Locate testssl.sh or testssl on the current system."""
    paths = COMMON_TESTSSL_PATHS.get(platform.system(), [])
    # testssl may be installed as either testssl.sh or testssl
    return find_tool("testssl.sh", paths) or find_tool("testssl", paths)


def find_sslscan() -> str | None:
    """Locate sslscan on the current system."""
    return find_tool("sslscan", COMMON_SSLSCAN_PATHS.get(platform.system(), []))


def check_ssl_tool(tool: str) -> str | None:
    """
    Check for testssl or sslscan. Warn and return None if missing.

    scattershot3 does not install SSL tools itself — use `python3 install.py`
    or Arsenal to install/repair (CLAUDE.md standing rule).
    """
    finder = find_testssl if tool == "testssl" else find_sslscan
    path = finder()
    if path:
        return path

    os_name = platform.system()

    # testssl.sh doesn't run natively on Windows
    if tool == "testssl" and os_name == "Windows":
        print(f"{Fore.YELLOW}[!] testssl.sh is not natively supported on Windows "
              f"(requires bash). Use WSL or Git Bash.{Style.RESET_ALL}")
        return None

    manual_hints = {
        "testssl": {
            "Linux":   "  sudo apt install testssl.sh   OR   https://testssl.sh",
            "Darwin":  "  brew install testssl   OR   https://testssl.sh",
            "Windows": "  Use WSL: sudo apt install testssl.sh",
        },
        "sslscan": {
            "Linux":   "  sudo apt install sslscan   OR   https://github.com/rbsec/sslscan",
            "Darwin":  "  brew install sslscan",
            "Windows": "  choco install sslscan   OR   https://github.com/rbsec/sslscan/releases",
        },
    }
    hint = manual_hints[tool].get(os_name, "  See https://github.com/rbsec/sslscan")

    print(f"{Fore.YELLOW}[!] {tool} not found — {tool} checks will be skipped.{Style.RESET_ALL}")
    print(f"    Install via toolkit installer:")
    print(f"      python3 install.py        (from the Scattershot3 repo)")
    print(f"      OR launch Arsenal and reinstall Scattershot3.")
    print(f"    Manual fallback: {hint.strip()}")
    return None


