def find_vulners_nse() -> "str | None":
    """Return path to vulners.nse if it exists in any known nmap scripts directory."""
    for d in COMMON_NMAP_SCRIPT_PATHS.get(platform.system(), []):
        p = Path(d) / "vulners.nse"
