def _normalize_os_name(raw: str) -> str:
    """Lowercase and normalise an OS name for _EOL_OS_DB lookup."""
    raw = raw.lower().strip()
    # Normalise common abbreviations
    raw = re.sub(r"\brhel\b", "rhel", raw)
    raw = re.sub(r"\bwindows srv\b|\bwin srv\b", "windows server", raw)
    raw = re.sub(r"\bwin\b", "windows", raw)
    return raw


def check_os_eol(
    output_mgr: "OutputManager",
    ip: str,
    port: int,
    hostname: "str | None",
    os_name: str,
    method: str = "",
) -> None:
    """
    Check *os_name* against _EOL_OS_DB and emit findings if the OS is EOL.

    Searches for the normalised os_name as a substring of each EOL DB key.
    Emits HIGH finding for fully EOL systems, MEDIUM for systems past standard
    support but still in extended/LTS support.
    """
    if not os_name:
        return
    today = datetime.now().strftime("%Y-%m-%d")
    norm  = _normalize_os_name(os_name)

    # Direct key lookup, then substring search.
    # Guard: bare distro names ("ubuntu", "debian") without a version must NOT
    # match versioned keys ("ubuntu 12.04") — substring containment is only
    # valid when *norm* contains a digit (i.e. it carries a version hint).
    entry = _EOL_OS_DB.get(norm)
    if entry is None:
        _norm_has_version = bool(re.search(r"\d", norm))
        for key, val in _EOL_OS_DB.items():
            if key in norm or (_norm_has_version and norm in key):
                entry = val
                break
    if entry is None:
        return

    eol      = entry.get("eol")
    ext_eol  = entry.get("extended_eol")
    label    = entry.get("label", os_name)

    if eol and today > eol:
        _os_src = method.split()[0].lower() if method else "nmap"
        _eol_inv_rel = _eol_evidence_file(output_mgr, ip, port)
        if ext_eol and today <= ext_eol:
            # Past standard EOL but within extended/LTS support
            output_mgr.log_finding(
                title=f"OS End-of-Life (Extended Support): {label}",
                ip=ip, port=port, hostname=hostname, command=method,
                risk="MEDIUM",
                description=(
                    f"{label} reached end of standard support on {eol}. "
                    f"Extended/LTS support continues until {ext_eol}."
                ),
                sources=_os_src,
                output=(
                    f"OS: {label}\n"
                    f"Raw OS name: {os_name}\n"
                    f"Standard EOL: {eol}\n"
                    f"Extended EOL: {ext_eol}\n"
                    f"Detection method: {method}"
                ),
                affected=f"{ip}",
                output_file=_eol_inv_rel,
            )
        else:
            # Fully EOL (past both standard and extended support)
            output_mgr.log_finding(
                title=f"OS End-of-Life: {label}",
                ip=ip, port=port, hostname=hostname, command=method,
                risk="HIGH",
                description=(
                    f"{label} reached end of life on {eol}"
                    + (f" (extended support ended {ext_eol})" if ext_eol else "")
                    + ". No further security patches are available."
                ),
                sources=_os_src,
                output=(
                    f"OS: {label}\n"
                    f"Raw OS name: {os_name}\n"
                    f"Standard EOL: {eol}\n"
                    + (f"Extended EOL: {ext_eol}\n" if ext_eol else "")
                    + f"Detection method: {method}"
                ),
                affected=f"{ip}",
                output_file=_eol_inv_rel,
            )


def _eol_evidence_file(
    output_mgr: "OutputManager",
    ip: str,
    port: int,
) -> "str | None":
    """
    Extract software inventory entries for *ip* and write them to a
    per-host evidence file under the host directory.  Returns the
    run-dir-relative path (for output_file) or None on error.

    This keeps EOL finding evidence scoped to the affected host instead
    of pointing at the entire software_inventory.json.
    """
    try:
        all_entries = json.loads(
            output_mgr.software_inventory.read_text(encoding="utf-8")
        )
        host_entries = [e for e in all_entries if e.get("ip") == ip]
        if not host_entries:
            return str(output_mgr.software_inventory.relative_to(output_mgr.root))
        ev_dir = output_mgr.host_path(ip)
        ev_dir.mkdir(parents=True, exist_ok=True)
        ev_file = ev_dir / "software_inventory.json"
        ev_file.write_text(json.dumps(host_entries, indent=2), encoding="utf-8")
        return str(ev_file.relative_to(output_mgr.root))
    except Exception:
        return str(output_mgr.software_inventory.relative_to(output_mgr.root))


# ─────────────────────────────────────────────
# Vulners REST API integration
# ─────────────────────────────────────────────
# Results are cached per (software, version) tuple to avoid duplicate API
# calls when the same software version is detected on multiple ports.
_VULNERS_API_CACHE: dict[tuple, list] = {}
_VULNERS_API_LOCK  = threading.Lock()
_VULNERS_API_URL   = "https://vulners.com/api/v3/burp/softwareVersion/"


def query_vulners(
    output_mgr: "OutputManager",
    ip: str,
    port: int,
    hostname: "str | None",
    software_name: str,
    version: str,
    method: str = "",
) -> None:
    """
    Query the Vulners REST API for vulnerabilities in *software_name* *version*.

    Requires VULNERS_API_KEY environment variable — silently skipped if absent.
    Results are cached per (software, version) and saved to api/ in the scope dir.
    Each vulnerability found is emitted as a log_finding() call.
    """
    api_key = os.environ.get("VULNERS_API_KEY", "").strip()
    if not api_key or not software_name or not version:
        return

    cache_key = (software_name.lower(), version.lower())
    with _VULNERS_API_LOCK:
        if cache_key in _VULNERS_API_CACHE:
            cached_vulns = _VULNERS_API_CACHE[cache_key]
        else:
            cached_vulns = None

    if cached_vulns is None:
        try:
            resp = requests.post(
                _VULNERS_API_URL,
                json={
                    "software":           software_name,
                    "version":            version,
                    "type":               "software",
                    "maxVulnerabilities": 20,
                    "apiKey":             api_key,
                },
                timeout=15,
                headers={"User-Agent": "Vantage/1.0"},
            )
            resp.raise_for_status()
            data = resp.json()
        except Exception:
            return

        # Save raw API response to api/ directory
        if output_mgr:
            try:
                _api_dir  = output_mgr.web_path(ip, port) / "api"
                _api_dir.mkdir(parents=True, exist_ok=True)
                _safe_sw  = re.sub(r"[^\w.-]", "_", software_name.lower())
                _safe_ver = re.sub(r"[^\w.-]", "_", version.lower())
                _api_file = _api_dir / f"vulners_{_safe_sw}_{_safe_ver}.json"
                _api_file.write_text(json.dumps(data, indent=2), encoding="utf-8")
            except Exception:
                pass

        # Extract vulnerabilities from response
        vulns: list[dict] = []
        try:
            result_obj = data.get("data", {})
            # The search results may be under "search" or directly as a list
            search_list = result_obj.get("search", []) if isinstance(result_obj, dict) else []
            for item in search_list:
                src = item.get("_source", {}) if isinstance(item, dict) else {}
                cve_id    = src.get("id", "")
                title     = src.get("title", "") or cve_id
                desc      = src.get("description", "")
                cvss_obj  = src.get("cvss3", {}) or src.get("cvss2", {}) or {}
                score     = cvss_obj.get("score", 0.0) if isinstance(cvss_obj, dict) else 0.0
                href      = src.get("href", "")
                if not cve_id:
                    continue
                risk = (
                    "CRITICAL" if score >= 9.0 else
                    "HIGH"     if score >= 7.0 else
                    "MEDIUM"   if score >= 4.0 else
                    "LOW"
                )
                vulns.append({
                    "id": cve_id, "title": title, "desc": desc,
                    "score": score, "risk": risk, "href": href,
                })
        except Exception:
            vulns = []

        with _VULNERS_API_LOCK:
            _VULNERS_API_CACHE[cache_key] = vulns
        cached_vulns = vulns

    # Emit findings for each vulnerability
    _src = method.split()[0].lower() if method else "nmap"
    _vuln_inv_rel = str(output_mgr.software_inventory.relative_to(output_mgr.root))
    for v in cached_vulns:
        _vuln_out_lines = [
            f"CVE: {v['id']}",
            f"Affected software: {software_name} {version}",
            f"CVSS: {v.get('score', '')}",
            f"Risk: {v['risk']}",
        ]
        if v.get("title"):
            _vuln_out_lines.append(f"Title: {v['title']}")
        if v.get("href"):
            _vuln_out_lines.append(f"Reference: {v['href']}")
        if v.get("desc"):
            _vuln_out_lines.append(f"Description: {v['desc'][:600]}")
        output_mgr.log_finding(
            title=f"CVE: {v['id']} — {software_name} {version}",
            ip=ip, port=port, hostname=hostname, command=method,
            risk=v["risk"],
            description=v["desc"] or v["title"],
            cves=v["id"],
            sources=_src,
            output="\n".join(_vuln_out_lines),
            affected=f"{ip}:{port}" if port else ip,
            output_file=_vuln_inv_rel,
        )


def _vulners_cve_risk(cve_ids: list) -> str:
    """
    Query Vulners API for CVSS scores of specific CVE IDs.

    Returns the highest risk tier found across all supplied CVEs.
    Falls back to "MEDIUM" when the API is unreachable, no key is configured,
    or the CVE list is empty.
    """
    api_key = os.environ.get("VULNERS_API_KEY", "").strip()
    if not api_key or not cve_ids:
        return "MEDIUM"

    scores: list = []
    for cve_id in cve_ids:
        try:
            resp = requests.post(
                "https://vulners.com/api/v3/search/id/",
                json={"id": cve_id, "apiKey": api_key},
                timeout=10,
                headers={"User-Agent": "Vantage/1.0"},
            )
            resp.raise_for_status()
            data = resp.json()
            doc  = (data.get("data", {}).get("documents", {}) or {}).get(cve_id, {})
            cvss = doc.get("cvss3", {}) or doc.get("cvss2", {}) or {}
            score = float(cvss.get("score", 0.0)) if isinstance(cvss, dict) else 0.0
            scores.append(score)
        except Exception:
            pass

    if not scores:
        return "MEDIUM"  # API unreachable — safe fallback

    top = max(scores)
    return (
        "CRITICAL" if top >= 9.0 else
        "HIGH"     if top >= 7.0 else
        "MEDIUM"   if top >= 4.0 else
        "LOW"
    )


