_SW_INV_LOCK = threading.Lock()


# Compiled patterns for parsing nmap version/extrainfo fields
# nmap appends OS/distro information as a parenthesised suffix in the
# version field, e.g. "8.9p1 Ubuntu 3ubuntu0.6" or "2.0.31 Debian 3".
# It also encodes the protocol version in the version field for services
# like OpenSSH: "8.9p1 Ubuntu 3ubuntu0.6" → version "8.9p1", os "Ubuntu".
_RE_NM_OS_SUFFIX   = re.compile(
    r"^(\S+)\s+(Ubuntu|Debian|CentOS|RHEL|Fedora|Alpine|Arch|Gentoo"
    r"|openSUSE|Raspbian|Kali|Parrot|Mint|Manjaro|Rocky|Alma|Oracle"
    r"|Windows|Red Hat|Amazon)\s*(\S+)?$",
    re.IGNORECASE,
)
# "protocol 2.0" appears in nmap extrainfo for SSH and similar services
_RE_NM_PROTOCOL    = re.compile(r"^protocol\s+([\d.]+)$", re.IGNORECASE)


def _parse_nmap_version_field(
    raw_version: str | None,
    raw_extrainfo: str | None,
) -> "tuple[str | None, str | None, str | None]":
    """
    Split nmap version/extrainfo strings into (clean_version, os, protocol).

    nmap stuffs several pieces of information into its version and extrainfo
    fields that belong in separate inventory columns:

    version field
      "8.9p1 Ubuntu 3ubuntu0.6"  →  version "8.9p1",  os "Ubuntu 3ubuntu0.6"
      "2.0.31 Debian 3"          →  version "2.0.31",  os "Debian 3"
      "2.4.57 Debian"            →  version "2.4.57",  os "Debian"

    extrainfo field
      "protocol 2.0"             →  protocol "2.0"
      "Ubuntu Linux; protocol 2.0"
                                 →  os "Ubuntu Linux",  protocol "2.0"

    Returns (clean_version, os_string, protocol_string).  Any of the three
    may be None if the corresponding information was not present.
    """
    version  : str | None = (raw_version  or "").strip() or None
    os_out   : str | None = None
    protocol : str | None = None

    # ── Parse version field ────────────────────────────────────────────────
    if version:
        m = _RE_NM_OS_SUFFIX.match(version)
        if m:
            ver_part = m.group(1).strip()
            os_name  = m.group(2).strip()
            os_build = (m.group(3) or "").strip()
            version  = ver_part if ver_part else None
            os_out   = f"{os_name} {os_build}".strip() if os_build else os_name

    # ── Parse extrainfo field ──────────────────────────────────────────────
    if raw_extrainfo:
        for part in raw_extrainfo.split(";"):
            part = part.strip()
            pm = _RE_NM_PROTOCOL.match(part)
            if pm:
                protocol = pm.group(1)
            elif part and os_out is None:
                # Treat remaining non-protocol parts as OS hints
                os_out = part

    return version, os_out, protocol


# Compiled once; matches the three common HTTP "Server:" header shapes:
#   Apache/2.4.41 (Ubuntu)     → name=Apache,  ver=2.4.41
#   nginx/1.18.0               → name=nginx,   ver=1.18.0
#   Jetty(9.4.58.v20250814)    → name=Jetty,   ver=9.4.58.v20250814
# The previous `split("/", 1)` collapsed Jetty's parenthesised form into
# software="Jetty(9.4.58.v20250814)" / version=null, diverging from the
# nmap -sV record for the same port and breaking EOL / CVE lookups that
# key off (software_name, version).
_RE_SERVER_HEADER = re.compile(
    r'^\s*([A-Za-z][\w.+-]*)'        # software name
    r'(?:[/(\s]+([0-9][\w.+-]*))?'   # opt. separator (/ ( or space) + version
)

def _parse_server_header(server_hdr: str) -> "tuple[str, str | None]":
    """Split an HTTP `Server:` header into (software_name, version).

    Returns (software_name, version) where version may be None when the
    header carries no recognisable version token.
    """
    if not server_hdr:
        return "", None
    m = _RE_SERVER_HEADER.match(server_hdr)
    if m:
        return m.group(1), m.group(2)
    return server_hdr.strip(), None


