def _ver_tuple(v: str) -> tuple:
    """Convert a dotted version string to a comparable tuple of ints."""
    try:
        return tuple(int(x) for x in re.split(r"[.\-]", v) if x.isdigit())
    except Exception:
        return (0,)


def check_eol_and_vulns(
    output_mgr: "OutputManager",
    ip: str,
    port: int,
    hostname: str | None,
    software_name: str,
    version: str | None,
    method: str,
) -> list[dict]:
    """
    Check *software_name*/*version* against _EOL_DB.

    Each match is written directly to findings.json and findings.csv via
    output_mgr.log_finding() — the full detail (EOL date, CVE reference) is
    embedded in the finding title so it appears in both files without needing
    a separate eol_vulns.json.

    Matching: the _EOL_DB key is matched as a case-insensitive substring of
    the normalised software name, so "Apache httpd" matches "apache".

    Returns a list of finding dicts (may be empty).
    """
    if not software_name or not version:
        return []

    key = software_name.lower().strip()
    db_entry = _EOL_DB.get(key)
    if db_entry is None:
        for db_key in _EOL_DB:
            if db_key in key:
                db_entry = _EOL_DB[db_key]
                key = db_key
                break
    if db_entry is None:
        return []

    findings: list[dict] = []
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ver_t = _ver_tuple(version)

    # ── EOL check ─────────────────────────────────────────────────────────
    eol_t = _ver_tuple(db_entry["eol_before"])
    if ver_t and eol_t and ver_t < eol_t:
        _eol_date         = db_entry.get("eol_date", "unknown")
        _ext_support_end  = db_entry.get("extended_support_end")  # YYYY-MM-DD or None
        _eol_label        = db_entry.get("eol_label", f"{software_name} (legacy branch)")
        today             = datetime.now().strftime("%Y-%m-%d")
        _in_ext_support   = bool(_ext_support_end and today <= _ext_support_end)

        detail = (
            f"Version {version} is end-of-life "
            f"(EOL before {db_entry['eol_before']}; "
            f"EOL date: {_eol_date})"
        )

        if _in_ext_support:
            _eol_description = (
                f"{software_name} {version} has reached end-of-life but is currently "
                f"within an extended support window.\n"
                f"Software: {_eol_label}\n"
                f"Detected Version: {version}\n"
                f"EOL Date: {_eol_date}\n"
                f"Extended Support Until: {_ext_support_end}\n"
                f"Security patches are limited to the extended support programme. "
                f"Plan for migration before extended support ends."
            )
            _eol_title = f"EOL Software (Extended Support): {software_name} {version}"
            _eol_risk  = "MEDIUM"
        else:
            _eol_description = (
                f"{software_name} {version} has reached end-of-life and no longer "
                f"receives security patches or updates.\n"
                f"Software: {_eol_label}\n"
                f"Detected Version: {version}\n"
                f"EOL Date: {_eol_date}\n"
                + (f"Extended Support Ended: {_ext_support_end}\n" if _ext_support_end else "Extended Support: N/A\n")
                + f"Versions below {db_entry['eol_before']} are considered end-of-life."
            )
            _eol_title = f"EOL Software: {software_name} {version}"
            _eol_risk  = "HIGH"

        findings.append({
            "type":                "end-of-life",
            "software":            software_name,
            "version":             version,
            "ip":                  ip,
            "port":                port,
            "hostname":            hostname,
            "detail":              detail,
            "eol_date":            _eol_date,
            "extended_support_end": _ext_support_end,
            "in_extended_support": _in_ext_support,
            "datetime":            ts,
            "method":              method,
        })
        if output_mgr:
            _eol_src = method.split()[0].lower() if method else "nmap"
            _eol_inv_rel = _eol_evidence_file(output_mgr, ip, port)
            output_mgr.log_finding(
                title=_eol_title,
                ip=ip, port=port, hostname=hostname,
                command=method, risk=_eol_risk,
                description=_eol_description,
                sources=_eol_src,
                output=(
                    f"Software: {software_name}\n"
                    f"Version: {version}\n"
                    f"EOL threshold: {db_entry['eol_before']}\n"
                    f"EOL date: {_eol_date}\n"
                    + (f"Extended support end: {_ext_support_end}\n" if _ext_support_end else "")
                    + f"Detection method: {method}"
                ),
                affected=f"{ip}:{port}" if port else ip,
                output_file=_eol_inv_rel,
            )

    # ── Known-CVE spot check ───────────────────────────────────────────────
    for vuln_prefix, cve_desc in db_entry.get("known_vulns", []):
        if version.startswith(vuln_prefix):
            findings.append({
                "type":     "known-vulnerability",
                "software": software_name,
                "version":  version,
                "ip":       ip,
                "port":     port,
                "hostname": hostname,
                "detail":   cve_desc,
                "datetime": ts,
                "method":   method,
            })
            if output_mgr:
                _cve_matches = re.findall(r'CVE-\d{4}-\d+', cve_desc, re.IGNORECASE)
                _cve_str = ",".join(sorted(set(m.upper() for m in _cve_matches)))
                _vuln_src = method.split()[0].lower() if method else "nmap"
                _vuln_inv_rel = _eol_evidence_file(output_mgr, ip, port)
                output_mgr.log_finding(
                    title=f"Known Vulnerability: {software_name} {version} — {cve_desc}",
                    ip=ip, port=port, hostname=hostname,
                    command=method, risk="CRITICAL",
                    description=cve_desc,
                    sources=_vuln_src, cves=_cve_str,
                    output=(
                        f"Software: {software_name}\n"
                        f"Version: {version}\n"
                        f"Vulnerable version prefix: {vuln_prefix}\n"
                        f"Detail: {cve_desc}\n"
                        f"Detection method: {method}"
                    ),
                    affected=f"{ip}:{port}" if port else ip,
                    output_file=_vuln_inv_rel,
                )

    return findings


# ─────────────────────────────────────────────
# Web file downloader
# ─────────────────────────────────────────────

# Extensions worth retrieving
_WEB_EXTS = frozenset({
    ".html", ".htm", ".php", ".asp", ".aspx", ".jsp", ".jsf",
    ".js", ".json", ".xml", ".txt", ".config", ".conf",
    ".yaml", ".yml", ".ini", ".env", ".bak", ".sql", ".css",
})

# Well-known paths always attempted
_WELL_KNOWN_PATHS = [
    "/",
    "/robots.txt",
    "/sitemap.xml",
    "/.well-known/security.txt",
    "/crossdomain.xml",
    "/web.config",
    "/humans.txt",
]

# Maximum linked files to follow from the index page (excluding well-known)
_MAX_WEB_LINKS  = 50
# Maximum bytes per downloaded file
_MAX_FILE_BYTES = 5 * 1024 * 1024   # 5 MB


def _web_path_to_filename(path: str) -> str:
    """Convert a URL path component to a safe flat filename preserving extension."""
    path = path.split("?")[0].strip("/")  # strip query and leading/trailing slash
    name = path.replace("/", "__") or "index"
    if "." not in name.rsplit("/", 1)[-1]:
        name += ".html"
    return _RE_UNSAFE_FNAME.sub("_", name)[:200]


def download_web_files(
    ip: str,
    port: int,
    scheme: str,
    hostname: str | None,
    output_mgr: "OutputManager",
    timeout: int = 10,
    cred_store: "CredentialStore | None" = None,
) -> list[str]:
    """
    Download web files reachable at scheme://ip:port/ and save them.

    Files are stored under  <scope>/web/<ip>_<port>/  using flat filenames
    derived from their URL paths.

    Strategy
    --------
    1. Fetch each path in _WELL_KNOWN_PATHS.
    2. Parse the index page (/) for href/src links with recognised extensions.
    3. Download up to _MAX_WEB_LINKS additional files from the same host.

    Deduplication
    -------------
    Each response body is hashed (SHA-256).  A file is only written if its
    hash has not been seen before in this session.  This prevents saving the
    same 404 or redirect page under dozens of different filenames.

    If a hostname (FQDN) is known, it is sent as the HTTP Host header so that
    SNI-based virtual hosts respond correctly.

    Returns a list of absolute local file paths that were written.
    """
    base_url = _clean_url(scheme, ip, port, "")
    save_dir = output_mgr.web_path(ip, port)

    host_hdr = hostname or ip
    visited:   set[str]   = set()      # URL paths already attempted
    seen_hashes: set[str] = set()      # SHA-256 digests of saved file bodies
    to_fetch:  list[str]  = list(_WELL_KNOWN_PATHS)
    saved:     list[str]  = []

    def _get_and_save(path: str) -> "str | None":
        if path in visited:
            return None
        visited.add(path)
        url = base_url + path if path.startswith("/") else path
        try:
            resp = _HTTP_SESSION.get(
                url,
                timeout=timeout,
                verify=False,
                allow_redirects=True,
                stream=True,
                headers={"Host": host_hdr},
            )
            body = b""
            for chunk in resp.iter_content(8192):
                body += chunk
                if len(body) >= _MAX_FILE_BYTES:
                    break

            # ── Deduplication: skip if content identical to a previously saved file
            digest = hashlib.sha256(body).hexdigest()
            if digest in seen_hashes:
                return None
            seen_hashes.add(digest)

            text  = body.decode("utf-8", errors="replace")
            fname = _web_path_to_filename(path)
            fpath = save_dir / fname
            fpath.write_text(text, encoding="utf-8")
            return str(fpath)
        except Exception:
            return None

    # Fetch well-known paths; parse index page for additional links
    for path in _WELL_KNOWN_PATHS:
        fpath = _get_and_save(path)
        if fpath:
            saved.append(fpath)
            if path in ("/", "/index.html", "/index.php"):
                try:
                    text = Path(fpath).read_text(encoding="utf-8", errors="replace")
                    for m in re.finditer(
                        r'(?:href|src)=["\']([^"\'>\s]+)["\']', text, re.IGNORECASE
                    ):
                        href = m.group(1)
                        if not any(href.lower().endswith(ext) for ext in _WEB_EXTS):
                            continue
                        if href.startswith("http"):
                            # Only follow links that stay on this host
                            if f"{ip}:{port}" in href or (
                                hostname and hostname in href
                            ):
                                after_host = re.sub(r"^https?://[^/]+", "", href)
                                to_fetch.append(after_host or "/")
                        else:
                            to_fetch.append(
                                href if href.startswith("/") else "/" + href
                            )
                except Exception:
                    pass

    # Fetch discovered links (skip already-handled well-known paths)
    for path in to_fetch:
        if path in _WELL_KNOWN_PATHS:
            continue
        if len(saved) >= _MAX_WEB_LINKS:
            break
        fpath = _get_and_save(path)
        if fpath:
            saved.append(fpath)

    if saved and output_mgr:
        output_mgr.log_command(
            "web-download", "requests",
            f"GET {base_url}/ (+{len(saved)-1} linked files)",
            save_dir,
            extra={
                "target":      f"{ip}:{port}",
                "hostname":    hostname,
                "files_saved": len(saved),
                "save_dir":    str(save_dir),
            },
        )

    # ── Login form detection ───────────────────────────────────────────────
    # For each saved HTML file, check whether it contains a login form.
    # This complements check_default_webpage() which only checks the root path.
    _HTML_EXTS = (".html", ".htm", ".php", ".asp", ".aspx", ".jsp", ".xhtml")
    for _lf_fpath in saved:
        _lf_path_str = _lf_fpath.replace(str(save_dir), "")
        if not any(_lf_path_str.lower().endswith(e) for e in _HTML_EXTS) and \
                not _lf_path_str.strip("/").find(".") == -1:
            continue  # skip non-HTML files
        try:
            _lf_text = Path(_lf_fpath).read_text(encoding="utf-8", errors="replace")
            _lf_url  = base_url + (_lf_path_str if _lf_path_str.startswith("/")
                                   else "/" + _lf_path_str)
            detect_login_form(_lf_text, _lf_url, ip, port, hostname, output_mgr,
                              output_file=_lf_fpath)
        except Exception:
            pass

    # ── Credential extraction from saved files ─────────────────────────────
    # Scan every downloaded file for plaintext credentials.  Findings are
    # added to the shared CredentialStore and also logged as findings.
    if cred_store and saved:
        for fpath_str in saved:
            try:
                text = Path(fpath_str).read_text(encoding="utf-8", errors="replace")
                added = extract_credentials_from_text(
                    text,
                    source_desc=f"{base_url}{fpath_str.replace(str(save_dir), '')}",
                    ip=ip,
                    cred_store=cred_store,
                )
                if added and output_mgr:
                    _cred_url = f"{base_url}{fpath_str.replace(str(save_dir), '')}"
                    try:
                        _cred_rel = str(Path(fpath_str).resolve().relative_to(output_mgr.root))
                    except Exception:
                        _cred_rel = fpath_str
                    output_mgr.log_finding(
                        title=f"Information Disclosure: Plaintext Credentials in Web Content",
                        ip=ip, port=port,
                        command=f"credential-extraction {fpath_str}",
                        hostname=hostname,
                        risk="CRITICAL",
                        description=(
                            f"{added} credential(s) extracted from "
                            f"{fpath_str}. Saved to credentials.txt."
                        ),
                        sources="web-download",
                        output=(
                            f"Source URL: {_cred_url}\n"
                            f"Saved file: {fpath_str}\n"
                            f"Credentials extracted: {added}"
                        ),
                        affected=_cred_url,
                        output_file=_cred_rel,
                    )
                    _tprint(
                        f"  {Fore.RED}[!] Plaintext credential(s) found in "
                        f"{Path(fpath_str).name} on {ip}:{port}{Style.RESET_ALL}"
                    )
            except Exception:
                pass

    return saved



