def find_shcheck() -> "str | None":
    """
    Locate shcheck.  shcheck is typically distributed as a Python script
    at /opt/shcheck/shcheck.py; a wrapper binary may also exist on PATH.
    Returns the path (binary or .py script) if found, else None.
    """
    # Try a binary wrapper first (e.g. from pip or package manager)
    found = find_tool("shcheck", [])
    if found:
        return found
    # Fall back to known Python script locations
    for p in COMMON_SHCHECK_PATHS.get(platform.system(), []):
        if Path(p).exists():
            return p
    return None


def _find_gobuster_wordlist() -> "str | None":
    """Return the first GoBuster wordlist that exists on this system, or None."""
    for wl in _GOBUSTER_WORDLISTS:
        if Path(wl).exists():
            return wl
    return None


_RAFT_MEDIUM_URL = (
    "https://raw.githubusercontent.com/danielmiessler/SecLists/master"
    "/Discovery/Web-Content/raft-medium-directories.txt"
)


def _ensure_gobuster_wordlist() -> "str | None":
    """
    Download raft-medium-directories.txt next to scattershot3.py if no wordlist is found.
    Returns the path on success, None on failure.
    """
    dest = Path(__file__).parent / "raft-medium-directories.txt"
    if dest.exists():
        return str(dest)
    if _CRUCIBLE_MANAGED:
        sys.stdout.write("[Vantage] Downloading gobuster wordlist (raft-medium-directories.txt)...\n")
        sys.stdout.flush()
    else:
        print(f"{Fore.CYAN}[*] Downloading gobuster wordlist → {dest}{Style.RESET_ALL}")
    try:
        import urllib.request
        urllib.request.urlretrieve(_RAFT_MEDIUM_URL, str(dest))
        if _CRUCIBLE_MANAGED:
            sys.stdout.write(f"[Vantage] Wordlist downloaded: {dest}\n")
            sys.stdout.flush()
        else:
            print(f"{Fore.GREEN}[+] Wordlist saved: {dest}{Style.RESET_ALL}")
        return str(dest)
    except Exception as exc:
        if _CRUCIBLE_MANAGED:
            sys.stdout.write(f"[Vantage] Wordlist download failed: {exc}\n")
            sys.stdout.flush()
        else:
            print(f"{Fore.YELLOW}[~] Wordlist download failed: {exc}{Style.RESET_ALL}")
        return None


