def _find_go_binary(name: str) -> "str | None":
    """Locate a Go-installed binary, checking all plausible GOPATH/GOBIN locations."""
    found = shutil.which(name)
    if found:
        return found
    home = Path.home()
    candidates = [
        home / "go" / "bin" / name,
        Path("/root/go/bin") / name,
        Path("/usr/local/go/bin") / name,
        Path("/opt/go/bin") / name,
    ]
    gobin = os.environ.get("GOBIN", "").strip()
    if gobin:
        candidates.insert(0, Path(gobin) / name)
    gopath = os.environ.get("GOPATH", "").strip()
    if gopath:
        candidates.insert(0, Path(gopath) / "bin" / name)
    for p in candidates:
        if p.exists() and os.access(str(p), os.X_OK):
            return str(p)
    return None


def _find_cargo_binary(name: str) -> "str | None":
    """Locate a Cargo-installed binary, checking $CARGO_HOME/bin and /root/.cargo/bin."""
    found = shutil.which(name)
    if found:
        return found
    home = Path.home()
    cargo_home = os.environ.get("CARGO_HOME", "").strip()
    candidates = [
        home / ".cargo" / "bin" / name,
        Path("/root/.cargo/bin") / name,
    ]
    if cargo_home:
        candidates.insert(0, Path(cargo_home) / "bin" / name)
    for p in candidates:
        if p.exists() and os.access(str(p), os.X_OK):
            return str(p)
    return None


