# Known brew binary locations (checked when root's PATH omits Homebrew dirs).
_BREW_KNOWN_PATHS = ["/opt/homebrew/bin/brew", "/usr/local/bin/brew"]


def _resolve_brew() -> "str | None":
    """Return the full path to the brew binary, or None if not installed."""
    found = shutil.which("brew")
    if found:
        return found
    for p in _BREW_KNOWN_PATHS:
        if os.path.isfile(p) and os.access(p, os.X_OK):
            return p
    return None


def _brew_cmd(cmd: list[str]) -> list[str]:
    """
    Rewrite a brew install command so it succeeds when the caller is root.

    Homebrew refuses to run as root, and /opt/homebrew/bin is absent from
    root's default PATH on Apple Silicon.  When scattershot is invoked via
    ``sudo`` (e.g. from Vantage), SUDO_USER is set to the original user.
    This function:
      1. Substitutes the bare 'brew' token with the resolved full path.
      2. Prefixes the command with ``sudo -u $SUDO_USER`` so Homebrew runs
         in the correct user context rather than as root.
    """
    if cmd[0] != "brew":
        return cmd
    brew = _resolve_brew()
    if not brew:
        return cmd
    resolved = [brew if t == "brew" else t for t in cmd]
    sudo_user = os.environ.get("SUDO_USER", "").strip()
    if os.geteuid() == 0 and sudo_user:
        return ["sudo", "-u", sudo_user] + resolved
    return resolved




def check_tool_generic(
    tool_name: str,
    finder_fn,
    install_hint: str,
) -> "str | None":
    """Locate a system/pentesting tool via *finder_fn*. WARN-ONLY if missing.

    scattershot3 itself never installs tools at runtime. When a tool is not
    found:
      • Print a clear warning naming the tool.
      • Point the operator at the canonical fixes: `python3 install.py`
        or Arsenal.
      • Print the per-tool manual-fallback hint from _TOOL_MANUAL_HINTS.
      • Return None so the caller can skip the affected feature.

    See CLAUDE.md and the project owner's standing rule: install / repair
    happens in install.py or Arsenal, never here.
    """
    path = finder_fn()
    if path:
        print(f"{Fore.CYAN}[*] {tool_name:<14}: {path}{Style.RESET_ALL}")
        return path

    hint = _TOOL_MANUAL_HINTS.get(tool_name.lower(), install_hint)
    print(f"{Fore.YELLOW}[!] {tool_name:<14}: not found — feature disabled.{Style.RESET_ALL}")
    print(f"    Install via toolkit installer:")
    print(f"      python3 install.py        (from the Scattershot3 repo)")
    print(f"      OR launch Arsenal and reinstall Scattershot3.")
    print(f"    Manual fallback: {hint}")
    return None

# ─────────────────────────────────────────────────────────────────────────────
# SNMP scanning
# ─────────────────────────────────────────────────────────────────────────────

def run_snmpwalk(
    ip: str,
    port: int,
    community: str,
    snmpwalk_path: str,
    output_mgr: "OutputManager",
    hostname: "str | None" = None,
    timeout: int = 30,
) -> "dict | None":
    """
    Run snmpwalk against ip:port with the given community string.
    Returns a dict with raw output and parsed OIDs on success, None on failure.
    """
    cmd = [
        snmpwalk_path,
        "-v", "2c",
        "-c", community,
        "-t", str(timeout),
        "-r", "1",
        f"{ip}:{port}",
    ]
    out_dir = output_mgr.service_path(ip, "snmp")
    safe_ip = ip.replace(".", "_")
    out_path = out_dir / f"{safe_ip}_{port}_{community}_snmpwalk.txt"

    _tprint(f"  {Fore.CYAN}[*] snmpwalk {ip}:{port} community='{community}'{Style.RESET_ALL}")
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            stdout_b, stderr_b = proc.communicate(timeout=timeout + 5)
        except subprocess.TimeoutExpired:
            _kill_proc_tree(proc)
            stdout_b, stderr_b = proc.communicate()
            # Timeout is the expected negative result when brute-forcing
            # community strings — wrong string = no response = timeout.
            # Not an error; log at DEBUG only.
            _vc.log(f"snmpwalk no response on {ip}:{port} community='{community}' (not accepted)", "DEBUG")
            _ensure_output_file(out_path, " ".join(cmd),
                                f"(snmpwalk timed out after {timeout + 5}s — community='{community}' not accepted)")
            return None

        raw = stdout_b.decode("utf-8", errors="replace")
        if not raw.strip() or proc.returncode != 0:
            _vc.log(f"snmpwalk produced no output on {ip}:{port} community='{community}'", "INFO")
            _ensure_output_file(out_path, " ".join(cmd),
                                f"(snmpwalk completed with no output for community='{community}' — community string not accepted or no MIB data)")
            return None

        out_path.write_text(raw, encoding="utf-8")

        output_mgr.log_command(
            "snmpwalk", snmpwalk_path, cmd, out_path,
            extra={"target": f"{ip}:{port}", "community": community},
        )
        _tprint(f"  {Fore.GREEN}[+] snmpwalk complete: {ip}:{port} community='{community}' → {out_path.name}{Style.RESET_ALL}")
        return {"community": community, "raw": raw, "output_file": str(out_path)}

    except Exception as exc:
        _vc.log(f"snmpwalk failed on {ip}:{port} community='{community}': {exc}", "ERROR")
        _vc.error(f"snmpwalk error on {ip}:{port}", source="snmpwalk",
                  detail=str(exc), category="Tool")
        output_mgr.log_error("snmpwalk", snmpwalk_path, cmd, str(exc),
                             extra={"target": f"{ip}:{port}"})
        _ensure_output_file(out_path, " ".join(cmd),
                            f"(snmpwalk encountered an error: {exc})")
        return None


def run_snmp_checks(
    ip: str,
    port: int,
    snmpwalk_path: str,
    output_mgr: "OutputManager",
    hostname: "str | None" = None,
    scope: str = "int",
) -> None:
    """
    Probe SNMP on ip:port:
      1. Try each community string in _SNMP_COMMUNITY_STRINGS.
      2. On success, run a full snmpwalk with that community.
      3. Log findings for any community string that works.
    """
    _tprint(f"  {Fore.CYAN}[*] SNMP community string check: {ip}:{port}{Style.RESET_ALL}")
    cmd_ref = [snmpwalk_path, "-v", "2c", "-c", "<community>", f"{ip}:{port}"]

    for community in _SNMP_COMMUNITY_STRINGS:
        result = run_snmpwalk(ip, port, community, snmpwalk_path, output_mgr,
                              hostname=hostname, timeout=10)
        if result:
            _tprint(
                f"  {Fore.RED}[!] SNMP community string accepted: "
                f"'{community}' on {ip}:{port}{Style.RESET_ALL}"
            )
            risk = "HIGH" if scope == "ext" else "MEDIUM"
            output_mgr.log_finding(
                title="SNMP Default Community String Accepted",
                ip=ip, port=port,
                command=cmd_ref,
                hostname=hostname,
                risk=risk,
                description=(
                    "The SNMP service accepts a well-known default community string "
                    f"(e.g., public/private), allowing unauthenticated read (and potentially "
                    f"write) access to device configuration data. Community: '{community}'."
                ),
                sources="snmpwalk",
                output=(
                    f"Accepted community: {community}\n"
                    f"SNMP version: 2c\n"
                    f"Sample output (first 1500 chars):\n"
                    + (result.get("raw", "") or "")[:1500]
                ),
                affected=f"{ip}:{port}",
                output_file=result["output_file"],
            )
            output_mgr.log_action_item(
                "config_audit", "Bastion", f"{ip}:{port}",
                ip, port,
                title="Bastion: Audit SNMP configuration",
                description=(
                    f"SNMP default community string '{community}' accepted on "
                    f"{ip}:{port}. Bastion can audit the SNMP configuration for "
                    f"SNMPv3 migration readiness, view restrictions, ACL "
                    f"enforcement, and write-community exposure."
                ),
                hostname=hostname,
                source_finding="SNMP Default Community String Accepted",
                priority="MEDIUM",
            )
            # After first successful community, do a full walk and stop brute-forcing
            run_snmpwalk(ip, port, community, snmpwalk_path, output_mgr,
                         hostname=hostname, timeout=60)
            break
    else:
        _tprint(f"  {Fore.GREEN}[+] SNMP check complete: {ip}:{port} — no community strings accepted{Style.RESET_ALL}")


