# FTP anonymous login check
# ─────────────────────────────────────────────────────────────────────────────

def run_ftp_anon_check(
    ip: str,
    port: int,
    output_mgr: "OutputManager",
    hostname: "str | None" = None,
    scope: str = "int",
    timeout: float = 10.0,
) -> None:
    """
    Attempt an FTP anonymous login via raw socket.  Reports a finding if
    the server accepts 'anonymous' / 'anonymous@example.com'.
    """
    _tprint(f"  {Fore.CYAN}[*] FTP anonymous login check: {ip}:{port}{Style.RESET_ALL}")
    cmd_ref = f"ftp-anon-check {ip}:{port}"
    try:
        import ftplib
        ftp = ftplib.FTP()
        ftp.connect(ip, port, timeout=timeout)
        ftp.login("anonymous", "anonymous@example.com")
        # If we reach here, anonymous login succeeded
        welcome = ftp.getwelcome()
        try:
            ftp.quit()
        except Exception:
            pass
        _tprint(
            f"  {Fore.RED}[!] FTP anonymous login accepted on {ip}:{port}{Style.RESET_ALL}"
        )
        risk = "HIGH" if scope == "ext" else "MEDIUM"
        # Collect full directory listing for the output column
        ftp_output_lines = [f"Welcome: {welcome or '(none)'}"]
        try:
            listing = []
            ftp2 = ftplib.FTP()
            ftp2.connect(ip, port, timeout=timeout)
            ftp2.login("anonymous", "anonymous@example.com")
            ftp2.retrlines("LIST", listing.append)
            ftp2.quit()
            if listing:
                ftp_output_lines.append("Directory listing (/):")
                ftp_output_lines.extend(listing)
        except Exception:
            pass
        ftp_output = "\n".join(ftp_output_lines)
        # Persist the raw FTP anonymous-login evidence
        try:
            _ftp_dir = output_mgr.service_path(ip, "ftp")
            _ftp_ts  = datetime.now().strftime("%Y%m%d_%H%M%S")
            _ftp_file = _ftp_dir / output_mgr._safe_filename(
                [ip, f"ftp-anon_{port}", _ftp_ts], "txt"
            )
            _ftp_file.write_text(ftp_output, encoding="utf-8")
            _ftp_rel = str(_ftp_file.relative_to(output_mgr.root))
        except Exception:
            _ftp_rel = None
        output_mgr.log_finding(
            title="FTP Anonymous Login Permitted",
            ip=ip, port=port,
            command=cmd_ref,
            hostname=hostname,
            risk=risk,
            description=(
                "The FTP service accepts the anonymous username without credentials, "
                "potentially exposing hosted files or allowing unauthenticated file upload."
            ),
            output=ftp_output,
            sources="ftp-check",
            affected=f"{ip}:{port}",
            output_file=_ftp_rel,
        )
        output_mgr.log_action_item(
            "credential_reuse", "Isotope", f"{ip}:{port}",
            ip, port,
            title="Isotope: Analyze FTP anonymous access files",
            description=(
                f"FTP anonymous login accepted on {ip}:{port}. "
                f"Isotope can download and analyze accessible files for "
                f"credentials, configuration data, and sensitive information "
                f"that enables lateral movement."
            ),
            hostname=hostname,
            source_finding="FTP Anonymous Login Permitted",
            priority="HIGH",
        )
    except Exception:
        # Login refused or connection error — not a finding
        _tprint(f"  {Fore.GREEN}[+] FTP anon check complete: {ip}:{port} — login denied{Style.RESET_ALL}")


