def _find_wordlist_ss3(candidates: "list[str]") -> "str | None":
    """Return the first existing wordlist path from the candidate list."""
    for p in candidates:
        if os.path.isfile(p):
            return p
    return None


def _detect_domain_controllers(all_results: dict) -> "list[tuple[str, str | None]]":
    """Return (ip, hostname) for hosts with Kerberos (88), LDAP (389), or GC (3268) open."""
    dcs = []
    for ip, data in all_results.items():
        ports = data.get("open_ports", {})
        if 88 in ports or 389 in ports or 3268 in ports:
            dcs.append((ip, data.get("hostname")))
    return dcs


def run_ldapdomaindump(
    dc_ip: str, output_mgr: "OutputManager",
    domain: "str | None" = None,
    username: "str | None" = None, password: "str | None" = None,
    hostname: "str | None" = None, timeout: int = 120,
) -> None:
    """Run ldapdomaindump to enumerate domain objects via LDAP."""
    lddd_path = shutil.which("ldapdomaindump") or shutil.which("ldapdomaindump3")
    if not lddd_path:
        _tprint(f"  {Fore.YELLOW}[~] ldapdomaindump not installed — pip install ldapdomaindump{Style.RESET_ALL}")
        return
    ldap_dir = output_mgr.scope_tool_path("ldap")
    out_dir = ldap_dir / dc_ip.replace(".", "_")
    out_dir.mkdir(parents=True, exist_ok=True)
    cmd = [lddd_path, "--no-html", "-o", str(out_dir)]
    if username and password:
        uarg = f"{domain}\\{username}" if domain else username
        cmd += ["-u", uarg, "-p", password]
    else:
        cmd += ["-u", "", "-p", ""]
    cmd.append(dc_ip)
    _tprint(f"  {Fore.CYAN}[*] ldapdomaindump: {dc_ip}{Style.RESET_ALL}")
    output_mgr.log_command("ldapdomaindump", lddd_path, cmd, out_dir)
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out_b, err_b = proc.communicate(timeout=timeout)
        raw = out_b.decode("utf-8", errors="replace")
        users_file = out_dir / "domain_users.json"
        if users_file.exists():
            try:
                users = json.loads(users_file.read_text(encoding="utf-8"))
                if isinstance(users, list):
                    _tprint(f"  {Fore.GREEN}[+] ldapdomaindump: {len(users)} domain user(s){Style.RESET_ALL}")
                    _sample_users = [
                        str(u.get("sAMAccountName", u.get("cn", "")))
                        for u in users[:30]
                    ]
                    output_mgr.log_finding(
                        title="LDAP: Domain User Enumeration",
                        ip=dc_ip, port=389, hostname=hostname,
                        command=" ".join(str(c) for c in cmd), risk="MEDIUM",
                        description=f"ldapdomaindump enumerated {len(users)} domain accounts from {dc_ip}.",
                        sources="ldapdomaindump",
                        output=f"Total accounts enumerated: {len(users)}\n"
                               f"First {len(_sample_users)} accounts:\n"
                               + "\n".join(_sample_users),
                        affected=f"{dc_ip}:389", output_file=str(users_file),
                    )
                    admin_kw = re.compile(r'admin|svc_|service|backup|sql', re.I)
                    flagged = [str(u.get("sAMAccountName", u.get("cn", "")))
                               for u in users if admin_kw.search(json.dumps(u))]
                    if flagged:
                        output_mgr.log_finding(
                            title="Enumeration: Privileged Domain Accounts Identified",
                            ip=dc_ip, port=389, hostname=hostname,
                            command=" ".join(str(c) for c in cmd), risk="HIGH",
                            description=f"Accounts matching admin/service patterns: {', '.join(flagged[:20])}",
                            sources="ldapdomaindump",
                            output=f"Total flagged accounts: {len(flagged)}\n"
                                   f"First {min(20, len(flagged))} flagged accounts:\n"
                                   + "\n".join(flagged[:20]),
                            affected=f"{dc_ip}:389",
                            output_file=str(users_file),
                        )
            except Exception:
                pass
        if "PASSWD_NOTREQD" in raw or "passwordnotrequired" in raw.lower():
            # Persist the raw ldapdomaindump stdout that triggered this
            try:
                _lddd_raw_file = out_dir / "ldapdomaindump_stdout.txt"
                _lddd_raw_file.write_text(raw, encoding="utf-8")
                _lddd_raw_rel = str(_lddd_raw_file.relative_to(output_mgr.root))
            except Exception:
                _lddd_raw_rel = None
            output_mgr.log_finding(
                title="Enumeration: Domain Accounts with Password Not Required",
                ip=dc_ip, port=389, hostname=hostname,
                command=" ".join(str(c) for c in cmd), risk="HIGH",
                description="LDAP dump revealed PASSWD_NOTREQD accounts.",
                sources="ldapdomaindump",
                affected=f"{dc_ip}:389",
                output=(
                    "ldapdomaindump output contained PASSWD_NOTREQD / "
                    "passwordnotrequired markers indicating one or more domain "
                    "accounts have the 'password not required' flag set.\n\n"
                    + "\n".join(
                        l for l in raw.splitlines()
                        if "PASSWD_NOTREQD" in l or "passwordnotrequired" in l.lower()
                    )[:2000]
                ),
                output_file=_lddd_raw_rel,
            )
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        _log_timeout_action(output_mgr, "ldapdomaindump", dc_ip, 389, hostname, timeout)
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] ldapdomaindump error: {exc}{Style.RESET_ALL}")


def run_kerbrute(
    dc_ip: str, domain: str, output_mgr: "OutputManager", kerbrute_path: str,
    hostname: "str | None" = None, cred_store: "CredentialStore | None" = None,
    timeout: int = 300,
) -> "list[str]":
    """Kerbrute username enumeration via AS-REQ — no lockout risk."""
    userlist = _find_wordlist_ss3([
        "/usr/share/seclists/Usernames/xato-net-10-million-usernames-dup.txt",
        "/usr/share/seclists/Usernames/top-usernames-shortlist.txt",
        "/usr/share/seclists/Usernames/Names/names.txt",
        "/usr/share/wordlists/metasploit/unix_users.txt",
    ])
    if not userlist:
        _tprint(f"  {Fore.YELLOW}[~] kerbrute: no username wordlist — skipping{Style.RESET_ALL}")
        return []
    kerb_dir = output_mgr.scope_tool_path("kerbrute")
    out_file = kerb_dir / f"valid_users_{dc_ip.replace('.', '_')}.txt"
    cmd = [kerbrute_path, "userenum", "--domain", domain, "--dc", dc_ip,
           "--output", str(out_file), "--threads", "10", userlist]
    _tprint(f"  {Fore.CYAN}[*] kerbrute: userenum {domain} @ {dc_ip}{Style.RESET_ALL}")
    output_mgr.log_command("kerbrute", kerbrute_path, cmd, out_file)
    valid_users: list[str] = []
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out_b, _ = proc.communicate(timeout=timeout)
        raw = out_b.decode("utf-8", errors="replace")
        for line in raw.splitlines():
            m = re.search(r'VALID USERNAME:\s*(\S+)', line, re.I)
            if m:
                valid_users.append(m.group(1))
        if valid_users:
            _tprint(f"  {Fore.RED}[!] kerbrute: {len(valid_users)} valid user(s){Style.RESET_ALL}")
            output_mgr.log_finding(
                title="Enumeration: Valid Kerberos Usernames",
                ip=dc_ip, port=88, hostname=hostname,
                command=" ".join(cmd), risk="MEDIUM",
                description=f"kerbrute confirmed {len(valid_users)} domain account(s).",
                sources="kerbrute",
                output=f"Total valid usernames: {len(valid_users)}\n"
                       f"Domain: {domain}\n"
                       f"First {min(50, len(valid_users))} usernames:\n"
                       + "\n".join(valid_users[:50]),
                affected=f"{dc_ip}:88", output_file=str(out_file),
            )
            if cred_store:
                for u in valid_users:
                    cred_store.add(u.split("@")[0], "", f"kerbrute valid user @ {dc_ip}", ip=dc_ip)
        else:
            _tprint(f"  {Fore.YELLOW}[~] kerbrute: no valid users found{Style.RESET_ALL}")
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        _log_timeout_action(output_mgr, "kerbrute", dc_ip, 88, hostname, timeout)
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] kerbrute error: {exc}{Style.RESET_ALL}")
    return valid_users


def run_bloodhound_python(
    dc_ip: str, domain: str, output_mgr: "OutputManager", bloodhound_path: str,
    username: "str | None" = None, password: "str | None" = None,
    hostname: "str | None" = None, timeout: int = 600,
) -> None:
    """bloodhound-python — collect AD graph data for BloodHound CE analysis."""
    bh_dir = output_mgr.scope_tool_path("bloodhound")
    cmd = [bloodhound_path, "-d", domain, "--dns-tcp", "-ns", dc_ip,
           "-c", "all", "--zip", "--output-prefix", str(bh_dir / "bh")]
    if username and password:
        cmd += ["-u", username, "-p", password]
    _tprint(f"  {Fore.CYAN}[*] bloodhound-python: collecting AD data for {domain}{Style.RESET_ALL}")
    output_mgr.log_command("bloodhound-python", bloodhound_path, cmd, bh_dir)
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out_b, err_b = proc.communicate(timeout=timeout)
        raw = out_b.decode("utf-8", errors="replace")
        zip_files = list(bh_dir.glob("*.zip"))
        json_files = list(bh_dir.glob("*.json"))
        if zip_files or json_files:
            _tprint(f"  {Fore.GREEN}[+] bloodhound-python: collection complete — "
                    f"{len(zip_files)} zip, {len(json_files)} JSON{Style.RESET_ALL}")
            output_mgr.log_finding(
                title="Enumeration: BloodHound AD Graph Data Collected",
                ip=dc_ip, port=389, hostname=hostname,
                command=" ".join(str(c) for c in cmd), risk="INFO",
                description=(
                    f"bloodhound-python collected AD data for {domain}. "
                    f"Import into BloodHound CE to map privilege escalation paths and "
                    f"shortest paths to Domain Admin."
                ),
                sources="bloodhound-python",
                affected=f"{dc_ip}:389",
                output=(
                    f"Domain: {domain}\n"
                    f"DC IP: {dc_ip}\n"
                    f"ZIP files produced: {len(zip_files)}\n"
                    f"JSON files produced: {len(json_files)}\n"
                    + "\n".join(str(f) for f in (zip_files + json_files)[:10])
                ),
                output_file=str(zip_files[0]) if zip_files else str(json_files[0]) if json_files else "",
            )
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        _log_timeout_action(output_mgr, "bloodhound-python", dc_ip, 389, hostname, timeout)
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] bloodhound-python error: {exc}{Style.RESET_ALL}")


def run_db_attacks(
    ip: str, open_ports: "dict[int, dict]", output_mgr: "OutputManager",
    hostname: "str | None" = None,
    odat_path: "str | None" = None, msdat_path: "str | None" = None,
    enumdb_path: "str | None" = None, cred_store: "CredentialStore | None" = None,
) -> None:
    """Dispatch database attack tools (odat/msdat/enumdb) based on open ports."""
    creds = cred_store.get_all() if cred_store else []
    uname = creds[0].get("username") if creds else None
    passwd = creds[0].get("password") if creds else None
    for port in open_ports:
        if port in _ORACLE_PORTS and odat_path:
            _run_odat(ip, port, output_mgr, odat_path, hostname, uname, passwd)
        if port in _MSSQL_PORTS:
            if msdat_path:
                _run_msdat(ip, port, output_mgr, msdat_path, hostname, uname, passwd)
            if enumdb_path:
                _run_enumdb(ip, port, "mssql", output_mgr, enumdb_path, hostname, uname, passwd)
        if port in _MYSQL_PORTS and enumdb_path:
            _run_enumdb(ip, port, "mysql", output_mgr, enumdb_path, hostname, uname, passwd)


def _run_odat(ip, port, output_mgr, odat_path, hostname=None, username=None, password=None, timeout=300):
    """odat — Oracle Database Attacking Tool."""
    out_dir = output_mgr.service_path(ip, "odat")
    out_file = out_dir / f"{ip.replace('.','_')}_{port}.txt"
    cmd = [odat_path, "all", "-s", ip, "-p", str(port)]
    if username and password:
        cmd += ["-U", username, "-P", password]
    _tprint(f"  {Fore.CYAN}[*] odat: Oracle {ip}:{port}{Style.RESET_ALL}")
    output_mgr.log_command("odat", odat_path, cmd, out_file)
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out_b, _ = proc.communicate(timeout=timeout)
        raw = out_b.decode("utf-8", errors="replace")
        out_file.write_text(raw, encoding="utf-8")
        if re.search(r'CVE-|vulnerable|xterm|OK\b', raw, re.I):
            output_mgr.log_finding(
                title="Oracle Database Vulnerability (odat)", ip=ip, port=port, hostname=hostname,
                command=" ".join(cmd), risk="HIGH",
                description=(
                    "odat identified an Oracle Database vulnerability or "
                    "exploitable misconfiguration on this target. Review the "
                    "saved odat output for details."
                ),
                output=raw,
                sources="odat",
                affected=f"{ip}:{port}",
                output_file=str(out_file),
            )
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        _log_timeout_action(output_mgr, "odat", ip, port, hostname, timeout)
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] odat: {exc}{Style.RESET_ALL}")


