def _run_enumdb(ip, port, db_type, output_mgr, enumdb_path, hostname=None, username=None, password=None, timeout=180):
    """enumdb — MySQL/MSSQL database enumeration."""
    out_dir = output_mgr.service_path(ip, "enumdb")
    out_file = out_dir / f"{ip.replace('.','_')}_{port}_{db_type}.txt"
    u = username or ("root" if db_type == "mysql" else "sa")
    p = password or ""
    cmd = [enumdb_path, "-u", u, "-p", p, "-H", ip, "-d", db_type, "--report", "txt"]
    _tprint(f"  {Fore.CYAN}[*] enumdb: {db_type.upper()} {ip}:{port}{Style.RESET_ALL}")
    output_mgr.log_command("enumdb", enumdb_path, cmd, out_file)
    try:
        proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out_b, _ = proc.communicate(timeout=timeout)
        raw = out_b.decode("utf-8", errors="replace")
        out_file.write_text(raw, encoding="utf-8")
        if re.search(r'Database|Table|Found|records', raw, re.I):
            output_mgr.log_finding(
                title=f"{db_type.upper()} Database Enumerated (enumdb)",
                ip=ip, port=port, hostname=hostname,
                command=" ".join(cmd), risk="MEDIUM",
                description=(
                    f"enumdb successfully enumerated {db_type.upper()} content "
                    f"on {ip}:{port}. Tables, databases, or rows were retrieved "
                    f"using the configured credentials."
                ),
                output=raw,
                sources="enumdb",
                affected=f"{ip}:{port}",
                output_file=str(out_file),
            )
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        _log_timeout_action(output_mgr, "enumdb", ip, port, hostname, timeout)
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] enumdb: {exc}{Style.RESET_ALL}")


# ── WAF / block-page / SSO form signatures that cause hydra FPs ──────────
# These patterns match response bodies from WAFs, proxies, content filters,
# and form-based SSO portals that return HTTP 200 regardless of HTTP basic
# auth credentials, making hydra report every login attempt as successful.
_WAF_BODY_SIGNATURES = (
    # FortiGate / FortiGuard
    "globalurl.fortinet.net",
    "Web Page Blocked",
    "FortiGuard Web Filtering",
    # Network appliance block pages
    "Access Denied by Web Filter",
    "Blocked by Sophos",
    "Palo Alto Networks",
    "URL has been blocked",
    "This site is blocked",
    "Websense",
    "Blue Coat",
    "ProxySG",
    "Content Keeper",
    "iboss",
    "SonicWall",
    "WatchGuard",
    "Untangle",
    "pfSense",
    "squidGuard",
    "SquidGuard",
    "DansGuardian",
    "SmartFilter",
    "This page is blocked",
    "web filter block",
    # SSO / form-based login portals (not HTTP basic auth)
    "quicklaunch.io",
    "WSO2 Identity Server",
    "ClearPassMutualLogin",
    "Okta Sign-In",
    "okta.com/oauth2",
    "login.microsoftonline.com",
    "adfs/ls",
    "Shibboleth",
    "CASServerUrlPrefix",
    "cas/login",
    "PingFederate",
    "OneLogin",
    "auth0.com",
    "keycloak",
)


# ── Hydra post-verification: lockout / error patterns that indicate FP ───
# When hydra claims a credential, we replay the login and check the response
# body for these patterns.  Their presence means the server returned a lockout,
# error, or block page — not an authenticated session.
_HYDRA_FP_BODY_PATTERNS_LITERAL = (
    "too many attempts",
    "too many failed",
    "too many login",
    "account locked",
    "account has been locked",
    "temporarily locked",
    "login attempts exceeded",
    "access denied",
    "access blocked",
    "your account has been disabled",
    "your ip has been blocked",
    "login attempted from ip",
    "rate limit",
    "throttled",
    "captcha",
    "recaptcha",
    "g-recaptcha",
    "challenge-form",
    "are you a robot",
    "verify you are human",
    "unauthorized",
    "forbidden",
    "session expired",
    "invalid credentials",
    "authentication failed",
    "login failed",
    "incorrect password",
    "invalid username or password",
    "bad credentials",
    "information services department",
)
_HYDRA_FP_BODY_PATTERNS_REGEX = (
    r"maximum.{0,30}attempts",
    r"please\s+contact.{0,60}department",
    r"please\s+contact.{0,60}administrator",
    r"please\s+contact.{0,60}support",
    r"please\s+contact.{0,60}help\s*desk",
    r"exceeded.{0,30}login.{0,20}attempts",
    r"too\s+many.{0,30}requests",
    r"try\s+again.{0,30}(later|minutes|seconds)",
)

_HYDRA_FP_BODY_RE = re.compile(
    "|".join(
        [re.escape(p) for p in _HYDRA_FP_BODY_PATTERNS_LITERAL]
        + list(_HYDRA_FP_BODY_PATTERNS_REGEX)
    ),
    re.IGNORECASE,
)


def _verify_hydra_credential(
    ip: str, port: int, scheme: str, user: str, pwd: str,
    auth_info: "dict | None", output_mgr: "OutputManager",
    hostname: "str | None" = None,
) -> "tuple[bool, str, str]":
    """Replay a Hydra-claimed credential and verify the response.

    Returns (verified, response_body, screenshot_path).
    verified is False if the response contains lockout/error FP patterns.
    """
    import urllib.request
    import urllib.parse
    import ssl

    resp_body = ""
    screenshot_path = ""

    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        if auth_info and auth_info.get("type") == "form":
            action = auth_info["action"]
            base_url = f"{scheme}://{ip}:{port}"
            post_url = urllib.parse.urljoin(base_url, action)
            form_data = {
                auth_info["user_field"]: user,
                auth_info["pass_field"]: pwd,
            }
            if auth_info.get("extra_params"):
                for pair in auth_info["extra_params"].split("&"):
                    if "=" in pair:
                        k, v = pair.split("=", 1)
                        form_data[k] = v
            encoded = urllib.parse.urlencode(form_data).encode("utf-8")
            req = urllib.request.Request(
                post_url, data=encoded,
                headers={"User-Agent": "Mozilla/5.0",
                         "Content-Type": "application/x-www-form-urlencoded"},
            )
        else:
            url = f"{scheme}://{ip}:{port}/"
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            import base64
            cred_b64 = base64.b64encode(f"{user}:{pwd}".encode()).decode()
            req.add_header("Authorization", f"Basic {cred_b64}")

        _resp_code = 0
        try:
            resp = urllib.request.urlopen(req, timeout=10, context=ctx)
            _resp_code = resp.getcode() or 0
            resp_body = resp.read(65536).decode("utf-8", errors="replace")
        except urllib.error.HTTPError as he:
            _resp_code = he.code
            resp_body = he.read(65536).decode("utf-8", errors="replace") if he.fp else ""
        except Exception:
            pass

        # Save the verification response
        verify_dir = output_mgr.scope_tool_path("hydra")
        verify_file = verify_dir / f"{ip.replace('.','_')}_{port}_verify_response.html"
        try:
            verify_file.write_text(resp_body or "(no response)", encoding="utf-8")
        except Exception:
            pass

        # Take a screenshot of the post-login page
        try:
            ss = take_web_screenshot(ip, port, scheme, output_mgr,
                                     hostname=hostname, timeout_ms=10_000)
            if ss:
                screenshot_path = ss
        except Exception:
            pass

        # Reject on HTTP error status codes
        if _resp_code in (401, 403, 429, 503):
            return False, resp_body, screenshot_path

        # Check for FP patterns in response body
        if resp_body and _HYDRA_FP_BODY_RE.search(resp_body):
            return False, resp_body, screenshot_path

        # Follow-up GET to the login page — lockout messages often appear
        # on the login page, not in the POST response (which may redirect
        # to a generic page or return a non-HTML response).
        if auth_info and auth_info.get("type") == "form":
            try:
                login_url = auth_info.get("login_url") or f"{scheme}://{ip}:{port}/"
                get_req = urllib.request.Request(
                    login_url, headers={"User-Agent": "Mozilla/5.0"})
                try:
                    get_resp = urllib.request.urlopen(
                        get_req, timeout=10, context=ctx)
                    login_body = get_resp.read(65536).decode(
                        "utf-8", errors="replace")
                except urllib.error.HTTPError as _he2:
                    login_body = (_he2.read(65536).decode(
                        "utf-8", errors="replace") if _he2.fp else "")
                except Exception:
                    login_body = ""
                if login_body and _HYDRA_FP_BODY_RE.search(login_body):
                    return False, login_body, screenshot_path
            except Exception:
                pass

        if not resp_body:
            return False, "(no response body captured)", screenshot_path

        return True, resp_body, screenshot_path

    except Exception:
        return False, resp_body, screenshot_path


# CSRF-like hidden field indicators — forms with these are CSRF-protected
# and hydra cannot handle dynamic per-request tokens.
_CSRF_INDICATORS = (
    "csrf", "xsrf", "antiforgery", "authenticity_token",
    "verification_token", "form_token", "form_key",
    "viewstate", "eventvalidation",
)


def _extract_login_form(html: str, page_url: str) -> "dict | None":
    """Extract login form details from HTML for hydra http-post-form.

    Returns dict with form action, field names, and extra params when a
    usable login form is found, or None if no parseable login form exists.
    """
    import re
    from urllib.parse import urljoin, urlparse

    for form_match in re.finditer(
            r'<form\b([^>]*)>(.*?)</form>', html, re.DOTALL | re.IGNORECASE):
        form_attrs = form_match.group(1)
        form_body = form_match.group(2)

        # Must have a password input
        pass_inputs = re.findall(
            r'<input\b[^>]*type=["\']password["\'][^>]*>',
            form_body, re.IGNORECASE)
        if not pass_inputs:
            continue

        # Extract password field name
        pass_name_m = re.search(
            r'name=["\']([^"\']+)["\']', pass_inputs[0], re.IGNORECASE)
        if not pass_name_m:
            continue
        pass_field = pass_name_m.group(1)

        # Find username field — try explicit text/email inputs first
        user_field = None
        for inp in re.finditer(
                r'<input\b[^>]*type=["\'](?:text|email)["\'][^>]*>',
                form_body, re.IGNORECASE):
            nm = re.search(r'name=["\']([^"\']+)["\']',
                           inp.group(0), re.IGNORECASE)
            if nm:
                user_field = nm.group(1)
                break
        # Fallback: inputs with login-related names
        if not user_field:
            for inp in re.finditer(
                    r'<input\b[^>]*name=["\']([^"\']+)["\'][^>]*>',
                    form_body, re.IGNORECASE):
                fn = inp.group(1).lower()
                if any(k in fn for k in ("user", "login", "email",
                                          "name", "account", "uid")):
                    tp_m = re.search(r'type=["\']([^"\']+)["\']',
                                     inp.group(0), re.IGNORECASE)
                    tp = tp_m.group(1).lower() if tp_m else "text"
                    if tp not in ("password", "hidden", "submit",
                                  "button", "checkbox", "radio"):
                        user_field = inp.group(1)
                        break

        if not user_field:
            continue

        # Collect hidden fields, check for CSRF protection
        has_csrf = False
        hidden_parts: "list[str]" = []
        for hidden in re.finditer(
                r'<input\b[^>]*type=["\']hidden["\'][^>]*>',
                form_body, re.IGNORECASE):
            h_nm = re.search(r'name=["\']([^"\']+)["\']',
                             hidden.group(0), re.IGNORECASE)
            h_vl = re.search(r'value=["\']([^"\']*)["\']',
                             hidden.group(0), re.IGNORECASE)
            if not h_nm:
                continue
            h_name = h_nm.group(1)
            hn_norm = h_name.lower().replace("-", "_")
            if any(ind in hn_norm for ind in _CSRF_INDICATORS):
                has_csrf = True
                break
            h_val = h_vl.group(1) if h_vl else ""
            hidden_parts.append(f"{h_name}={h_val}")

        if has_csrf:
            continue  # CSRF-protected — hydra can't handle dynamic tokens

        # Extract form action
        action_m = re.search(r'action=["\']([^"\']*)["\']',
                             form_attrs, re.IGNORECASE)
        raw_action = action_m.group(1) if action_m else ""
        if raw_action:
            parsed = urlparse(raw_action)
            if not parsed.scheme:
                action = urlparse(urljoin(page_url, raw_action)).path or "/"
            else:
                action = parsed.path or "/"
        else:
            action = urlparse(page_url).path or "/"

        extra = "&".join(hidden_parts)

        return {
            "type": "form",
            "action": action,
            "user_field": user_field,
            "pass_field": pass_field,
            "extra_params": extra,
            "login_url": page_url,
        }

    return None


def _check_hydra_http_target(ip: str, port: int,
                             scheme: str = "http") -> "dict | str":
    """Determine if and how hydra should brute-force an HTTP endpoint.

    Three-layer gate:
    1. WAF / SSO body signatures → skip (false positives)
    2. HTTP 401 + WWW-Authenticate: Basic → proceed with http-get
    3. Login form with password field → proceed with http-post-form

    Returns:
        dict — auth mechanism detected; proceed with hydra
            {"type": "basic"}  → HTTP basic auth, use http-get/https-get
            {"type": "form", "action": ..., "user_field": ...,
             "pass_field": ..., "extra_params": ...}  → form login,
             use http-post-form / https-post-form
        str  — reason to skip hydra (no auth, WAF, CSRF, etc.)
    """
    import urllib.request
    import ssl
    url = _clean_url(scheme, ip, port)
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        try:
            resp = urllib.request.urlopen(req, timeout=8, context=ctx)
            body = resp.read(65536).decode("utf-8", errors="replace")
            body_lower = body.lower()

            # WAF / SSO body signatures → false positive risk
            for sig in _WAF_BODY_SIGNATURES:
                if sig.lower() in body_lower:
                    return f"WAF/SSO detected ({sig})"

            # Check for a login form with username + password fields
            form = _extract_login_form(body, resp.url or url)
            if form:
                return form

            # Password inputs exist but not in a parseable <form>
            # (JS-rendered SPA login — hydra can't interact with it)
            import re
            if re.search(r'<input\b[^>]*type=["\']password["\']',
                         body, re.IGNORECASE):
                return "JS-rendered login (no parseable form for hydra)"

            # No authentication mechanism on this page
            return "no login form or HTTP basic auth detected"

        except urllib.error.HTTPError as he:
            if he.code == 401:
                www_auth = he.headers.get("WWW-Authenticate", "")
                if "basic" in www_auth.lower():
                    return {"type": "basic"}
                return f"401 but not Basic auth ({www_auth[:40]})"
            elif he.code == 403:
                return "403 Forbidden (no auth prompt)"
            return f"HTTP {he.code} (no auth prompt)"
    except Exception:
        pass
    return "connection error (host unreachable or refused)"


def _is_redirect_out_of_scope(ip: str, port: int, scheme: str,
                              scope_ips: "set[str]") -> "str | None":
    """Check if an HTTP endpoint redirects to an out-of-scope destination.

    Rules (per user specification):
    - In-scope IP, no redirect → None (proceed)
    - Redirect to out-of-scope IP → reason string (skip)
    - Redirect to domain resolving to in-scope IP → None (proceed)
    - Redirect to domain resolving to out-of-scope IP → reason string (skip)

    Returns a reason string if hydra should skip, None if OK to proceed.
    """
    import urllib.request
    import ssl
    import socket
    url = _clean_url(scheme, ip, port)
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        # Build a request that does NOT follow redirects — we need to inspect
        # the Location header ourselves.
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})

        class _NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                raise urllib.error.HTTPError(
                    newurl, code, msg, headers, fp)

        opener = urllib.request.build_opener(
            _NoRedirect,
            urllib.request.HTTPSHandler(context=ctx),
        )
        try:
            resp = opener.open(req, timeout=8)
            # No redirect — original IP is the target, which is in scope
            return None
        except urllib.error.HTTPError as he:
            if he.code not in (301, 302, 303, 307, 308):
                # Non-redirect HTTP error (401, 403, etc) — not a redirect issue
                return None
            location = he.headers.get("Location", "")
            if not location:
                return None
    except Exception:
        # Connection error — can't determine, let hydra try
        return None

    # Parse the redirect destination
    from urllib.parse import urlparse
    parsed = urlparse(location)
    redirect_host = parsed.hostname
    if not redirect_host:
        return None

    # Check if redirect_host is an IP address or a domain
    try:
        socket.inet_aton(redirect_host)
        # It's an IP address — check directly against scope
        if redirect_host in scope_ips:
            return None
        return (f"redirects to out-of-scope IP {redirect_host} "
                f"(Location: {location[:80]})")
    except socket.error:
        pass

    # It's a domain/subdomain — resolve to IP and check scope
    try:
        resolved_ips = {r[4][0] for r in socket.getaddrinfo(
            redirect_host, None, socket.AF_INET, socket.SOCK_STREAM)}
    except socket.gaierror:
        # Can't resolve — treat as out-of-scope (safe default)
        return (f"redirects to unresolvable host {redirect_host} "
                f"(Location: {location[:80]})")
    if resolved_ips & scope_ips:
        # At least one resolved IP is in scope
        return None
    resolved_str = ", ".join(sorted(resolved_ips)) if resolved_ips else "no A records"
    return (f"redirects to {redirect_host} which resolves to "
            f"out-of-scope IP(s) [{resolved_str}] "
            f"(Location: {location[:80]})")


def run_hydra_brute(
    ip: str, open_ports: "dict[int, dict]", output_mgr: "OutputManager",
    hydra_path: str, hostname: "str | None" = None,
    cred_store: "CredentialStore | None" = None,
    extra_users: "list[str] | None" = None, timeout: int = 300,
    scope_ips: "set[str] | None" = None,
) -> None:
    """Hydra credential brute force against detected services."""
    passlist = _find_wordlist_ss3(_HYDRA_PASSWORD_LISTS)
    if not passlist:
        _tprint(f"  {Fore.YELLOW}[~] Hydra: no password wordlist — skipping{Style.RESET_ALL}")
        return
    userlist = _find_wordlist_ss3(_HYDRA_USER_LISTS)
    hydra_dir = output_mgr.scope_tool_path("hydra")
    effective_userlist = userlist
    if extra_users:
        aug_file = hydra_dir / "augmented_users.txt"
        base: list[str] = []
        if userlist:
            try:
                base = open(userlist, encoding="utf-8", errors="replace").read().splitlines()
            except Exception:
                pass
        merged = list(dict.fromkeys(extra_users + base))[:500]
        aug_file.write_text("\n".join(merged) + "\n", encoding="utf-8")
        effective_userlist = str(aug_file)
    for port, info in open_ports.items():
        svc = _HYDRA_SERVICES.get(port)
        if not svc:
            continue
        out_file = hydra_dir / f"{ip.replace('.','_')}_{port}_{svc}.txt"
        # Hydra's own -o file (machine-parseable credentials-only) lives
        # alongside the human-readable scan log. Use a sidecar filename so
        # the main out_file isn't clobbered.
        creds_file = hydra_dir / f"{ip.replace('.','_')}_{port}_{svc}_creds.txt"
        _use_form = False
        if svc in ("http-get", "https-get"):
            _scheme = "https" if svc == "https-get" else "http"
            # Authentication detection: determine if the endpoint has HTTP
            # basic auth, a form-based login, or no auth mechanism at all.
            # Also checks for WAF/SSO pages that cause false positives.
            _auth = _check_hydra_http_target(ip, port, _scheme)
            if isinstance(_auth, str):
                _tprint(f"  {Fore.YELLOW}[~] Hydra: skipping {ip}:{port} — "
                        f"{_auth}{Style.RESET_ALL}")
                continue
            # Scope-aware redirect check: skip if endpoint redirects to
            # an out-of-scope destination (IP or domain resolving outside scope)
            if scope_ips:
                _redir_reason = _is_redirect_out_of_scope(ip, port, _scheme, scope_ips)
                if _redir_reason:
                    _tprint(f"  {Fore.YELLOW}[~] Hydra: skipping {ip}:{port} — "
                            f"{_redir_reason}{Style.RESET_ALL}")
                    continue
            if _auth["type"] == "form":
                _use_form = True
                _form_svc = "https-post-form" if _scheme == "https" else "http-post-form"
                _form_params = (f"{_auth['user_field']}=^USER^&"
                                f"{_auth['pass_field']}=^PASS^")
                if _auth.get("extra_params"):
                    _form_params += f"&{_auth['extra_params']}"
                _form_spec = f"{_auth['action']}:{_form_params}:F=password"
                _effective_svc = _form_svc
            else:
                target = f"{svc}://{ip}:{port}/admin"
                _effective_svc = svc
        else:
            target = f"{svc}://{ip}:{port}"
            _effective_svc = svc
        # Drop -q so stdout actually carries the scan progress and
        # credential-match lines we parse below. Without -q, hydra prints
        # status updates and the canonical "[port][svc] host: X  login: Y  password: Z"
        # format on stdout which the regex relies on.
        cmd = [hydra_path, "-t", "4", "-f"]
        if effective_userlist:
            cmd += ["-L", effective_userlist]
        else:
            cmd += ["-l", "admin"]
        if _use_form:
            cmd += ["-P", passlist, "-s", str(port), ip,
                    _form_svc, _form_spec, "-o", str(creds_file)]
        else:
            cmd += ["-P", passlist, target, "-o", str(creds_file)]
        _tprint(f"  {Fore.CYAN}[*] Hydra: {_effective_svc} → {ip}:{port}{Style.RESET_ALL}")
        output_mgr.log_command("hydra", hydra_path, cmd, out_file)
        try:
            # Merge stderr into stdout so connection errors/warnings are visible
            # in the saved log.
            proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            out_b, _ = proc.communicate(timeout=timeout)
            raw = out_b.decode("utf-8", errors="replace")
            # Build a combined human-readable scan log: header + full hydra
            # output + the credentials sidecar contents. Never overwrites
            # hydra's structured -o file.
            _combined = [
                f"# Command : {' '.join(cmd)}",
                f"# Target  : {_form_spec if _use_form else target}",
                f"# Started : {datetime.now().isoformat()}",
                f"# Exit    : {proc.returncode}",
                f"# Creds   : {creds_file.name}",
                "",
                "# ── Hydra output (stdout + stderr) ─────────────────────────────",
                raw if raw.strip() else "(no output captured)",
            ]
            if creds_file.exists():
                _creds_txt = creds_file.read_text(encoding="utf-8", errors="replace").strip()
                _combined += [
                    "",
                    "# ── Successful credentials (from hydra -o sidecar) ─────────────",
                    _creds_txt if _creds_txt else "(no successful credentials)",
                ]
            out_file.write_text("\n".join(_combined), encoding="utf-8")
            for line in raw.splitlines():
                m = re.search(r'host:\s*\S+.*?login:\s*(\S+)\s+password:\s*(\S+)', line)
                if m:
                    user, pwd = m.group(1), m.group(2)
                    _tprint(f"  {Fore.CYAN}[*] Hydra claims: {user}:{pwd} @ {ip}:{port} ({_effective_svc}) — verifying...{Style.RESET_ALL}")
                    _hyd_scheme = "https" if "https" in _effective_svc else "http"
                    _auth_for_verify = _auth if _use_form else None
                    _verified, _vbody, _vss = _verify_hydra_credential(
                        ip, port, _hyd_scheme, user, pwd,
                        _auth_for_verify, output_mgr, hostname=hostname,
                    )
                    if not _verified:
                        _fp_match = _HYDRA_FP_BODY_RE.search(_vbody) if _vbody else None
                        _fp_reason = _fp_match.group(0) if _fp_match else "no valid response"
                        _tprint(f"  {Fore.YELLOW}[~] Hydra FP: {user}:{pwd} @ {ip}:{port} — "
                                f"verification failed ({_fp_reason}){Style.RESET_ALL}")
                        _tprint(f"  {Fore.YELLOW}    Response indicates lockout/error, not valid auth{Style.RESET_ALL}")
                        output_mgr.log_command(
                            "hydra-verify", "hydra", cmd,
                            output_mgr.scope_tool_path("hydra") / f"{ip.replace('.','_')}_{port}_verify_response.html",
                        )
                        continue
                    _tprint(f"  {Fore.RED}[!] Hydra VERIFIED: {user}:{pwd} @ {ip}:{port} ({_effective_svc}){Style.RESET_ALL}")
                    _hyd_target = _form_spec if _use_form else target
                    _verify_note = ""
                    if _vss:
                        _verify_note = f"\nVerification screenshot: {_vss}"
                    output_mgr.log_finding(
                        title="Brute Force: Web Server Permits Weak/Default Passwords",
                        ip=ip, port=port, hostname=hostname,
                        command=" ".join(cmd), risk="CRITICAL",
                        description=f"Hydra confirmed {user}:{pwd} for {_effective_svc.upper()} on {ip}:{port}. Credential verified by replay.",
                        sources="hydra",
                        affected=f"{ip}:{port}",
                        output=(
                            f"Service: {_effective_svc}\n"
                            f"Target: {_hyd_target}\n"
                            f"Username: {user}\n"
                            f"Password: {pwd}\n"
                            f"Source line: {line.strip()}\n"
                            f"Verification: PASSED — authenticated response received"
                            f"{_verify_note}"
                        ),
                        output_file=str(out_file),
                    )
                    if cred_store:
                        cred_store.add(user, pwd, f"hydra {_effective_svc} @ {ip}:{port}", ip=ip)
        except subprocess.TimeoutExpired:
            _kill_proc_tree(proc)
            _log_timeout_action(output_mgr, "hydra", ip, port, hostname, timeout)
        except Exception as exc:
            _tprint(f"  {Fore.RED}[!] Hydra {ip}:{port}: {exc}{Style.RESET_ALL}")


def _collect_param_urls(output_mgr: "OutputManager", all_results: dict) -> "list[str]":
    """Collect URLs with query parameters from gobuster, HTTP responses, and web bodies."""
    param_re = re.compile(r'https?://[^\s"\'<>]+\?[^\s"\'<>]+')
    param_urls: list[str] = []
    seen: set[str] = set()
    def _add(url: str) -> None:
        url = url.strip().rstrip("\"'")
        if url and url not in seen:
            seen.add(url); param_urls.append(url)
    hosts_root = output_mgr.root / "hosts"
    if hosts_root.exists():
        for f in hosts_root.rglob("*gobuster*.txt"):
            try:
                for line in f.read_text(encoding="utf-8", errors="replace").splitlines():
                    for m in param_re.finditer(line):
                        _add(m.group(0))
            except Exception:
                pass
        for f in hosts_root.rglob("*_http.txt"):
            try:
                for m in param_re.finditer(f.read_text(encoding="utf-8", errors="replace")):
                    _add(m.group(0))
            except Exception:
                pass
    return param_urls


def run_sqlmap(
    param_urls: "list[str]", output_mgr: "OutputManager",
    sqlmap_path: str, scope_ips: "list[str]", timeout: int = 300,
) -> None:
    """sqlmap SQL injection testing against in-scope parameterized URLs."""
    if not param_urls:
        _tprint(f"  {Fore.YELLOW}[~] sqlmap: no parameterized URLs — skipping{Style.RESET_ALL}")
        return
    import urllib.parse as _up
    sqlmap_dir = output_mgr.scope_tool_path("sqlmap")
    in_scope = [u for u in param_urls
                if any(_up.urlparse(u).hostname == ip for ip in scope_ips)]
    if not in_scope:
        _tprint(f"  {Fore.YELLOW}[~] sqlmap: no in-scope parameterized URLs{Style.RESET_ALL}")
        return
    _tprint(f"  {Fore.CYAN}[*] sqlmap: {len(in_scope)} in-scope URL(s){Style.RESET_ALL}")
    for url in in_scope[:10]:
        safe = re.sub(r'[^\w]', '_', url)[:40]
        out_dir = sqlmap_dir / safe
        out_dir.mkdir(parents=True, exist_ok=True)
        cmd = [sqlmap_path, "-u", url, "--batch", "--level", "2", "--risk", "1",
               "--output-dir", str(out_dir), "--timeout", "30", "--retries", "1"]
        output_mgr.log_command("sqlmap", sqlmap_path, cmd, out_dir)
        try:
            proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out_b, _ = proc.communicate(timeout=timeout)
            raw = out_b.decode("utf-8", errors="replace")
            # sqlmap confirms injection with lines like:
            #   "Parameter: id (GET)" followed by "Type: ..." payload lines
            #   "... is vulnerable" (positive confirmation)
            # But also prints negatives like "does not seem to be injectable"
            # and "do not appear to be injectable".  Only report when sqlmap
            # confirms at least one injection AND doesn't end with the
            # "all tested parameters do not appear to be injectable" verdict.
            _sm_negative = bool(re.search(
                r'do not appear to be injectable|'
                r'does not seem to be injectable|'
                r'all tested parameters .* not .* injectable',
                raw, re.IGNORECASE))
            _sm_positive = bool(re.search(
                r'(?:Parameter:.*\n.*Type:.*\n.*Payload:)|'
                r'\bis vulnerable\b|'
                r'sqlmap identified the following injection point',
                raw, re.IGNORECASE | re.DOTALL))
            if _sm_positive and not _sm_negative:
                host = _up.urlparse(url).hostname or ""
                try:
                    _sm_log = out_dir / "sqlmap_stdout.txt"
                    _sm_log.write_text(raw, encoding="utf-8")
                    _sm_rel = str(_sm_log.relative_to(output_mgr.root))
                except Exception:
                    _sm_rel = str(out_dir)
                _sm_trigger = "\n".join(
                    l for l in raw.splitlines()
                    if re.search(r'is vulnerable|Type:.*injection|Payload:|injection point', l, re.IGNORECASE)
                )[:1500]
                output_mgr.log_finding(
                    title="SQL Injection (Error-Based)",
                    ip=host, port=0, command=" ".join(cmd), risk="CRITICAL",
                    description=(
                        "User-controlled input is incorporated into SQL queries without "
                        "parameterisation, allowing an attacker to read, modify, or delete "
                        "database contents."
                    ),
                    sources="sqlmap",
                    affected=url,
                    output=(
                        f"URL: {url}\n"
                        f"sqlmap trigger lines:\n{_sm_trigger}"
                    ),
                    output_file=_sm_rel,
                )
                _tprint(f"  {Fore.RED}[!] sqlmap: SQLi FOUND in {url}{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _kill_proc_tree(proc)
            _log_timeout_action(output_mgr, "sqlmap", url, 0, "", timeout, cmd=" ".join(cmd))
        except Exception as exc:
            _tprint(f"  {Fore.RED}[!] sqlmap: {exc}{Style.RESET_ALL}")


def run_xsstrike(
    web_targets: "list[str]", output_mgr: "OutputManager",
    xsstrike_path: str, timeout: int = 120,
) -> None:
    """XSStrike XSS vulnerability scanner against web targets."""
    if not web_targets:
        return
    xs_dir = output_mgr.scope_tool_path("xsstrike")
    _tprint(f"  {Fore.CYAN}[*] XSStrike: {len(web_targets)} target(s){Style.RESET_ALL}")
    # XSStrike marks confirmed vulnerabilities with these specific phrases. We
    # match against them — NOT a naive r'XSS|Vulnerable' regex, because
    # 'XSS' is a substring of 'XSStrike' (the tool's own banner) which would
    # match every run and produce a false positive for every target.
    _XS_HIT_RE = re.compile(
        r'\[\+\]\s*Vulnerable\s*webpage\s*:'
        r'|\[\!\]\s*Vulnerable\s*webpage\s*:'
        r'|\[\+\]\s*Payload\s*:'
        r'|\[\+\]\s*Vector\s*:'
        r'|reflections\s+found',
        re.IGNORECASE
    )
    for url in web_targets[:10]:
        safe = re.sub(r'[^\w]', '_', url)[:40]
        out_file = xs_dir / f"{safe}.txt"
        # Drop --silent so the saved output file actually contains the scan
        # progress and any [+] Vulnerable webpage / [+] Payload / [+] Vector
        # markers XSStrike emits when it confirms an XSS. With --silent the
        # file was a near-empty banner-only artifact, which made debugging
        # impossible AND made the false-positive regex trigger on the banner.
        cmd = [sys.executable, xsstrike_path, "-u", url, "--crawl"]
        output_mgr.log_command("xsstrike", xsstrike_path, cmd, out_file)
        try:
            # Merge stderr into stdout — XSStrike writes connection errors
            # and warnings to stderr that we want preserved in the log.
            proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            out_b, _ = proc.communicate(timeout=timeout)
            raw = out_b.decode("utf-8", errors="replace")
            # Write a header + the full XSStrike output so the file is useful
            # for review even when no XSS was found.
            _combined = [
                f"# Command : {' '.join(str(c) for c in cmd)}",
                f"# Target  : {url}",
                f"# Started : {datetime.now().isoformat()}",
                f"# Exit    : {proc.returncode}",
                "",
                "# ── XSStrike output (stdout + stderr) ─────────────────────────",
                raw if raw.strip() else "(no output captured)",
            ]
            out_file.write_text("\n".join(_combined), encoding="utf-8")
            if _XS_HIT_RE.search(raw):
                import urllib.parse as _up2
                host = _up2.urlparse(url).hostname or ""
                # Snippet of the lines that triggered the XSStrike match
                _xs_trigger = "\n".join(
                    l for l in raw.splitlines() if _XS_HIT_RE.search(l)
                )[:1500]
                output_mgr.log_finding(
                    title="Reflected Cross-Site Scripting (XSS)", ip=host, port=0,
                    command=" ".join(str(c) for c in cmd), risk="HIGH",
                    description=(
                        "User-controlled input is reflected or stored and rendered in a "
                        "browser context without proper encoding, enabling arbitrary script "
                        "execution. XSStrike confirmed the vulnerability — see output file "
                        "for the payload / vector that fired."
                    ),
                    sources="xsstrike",
                    affected=url,
                    output=(
                        f"URL: {url}\n"
                        f"XSStrike trigger lines:\n{_xs_trigger}"
                    ),
                    output_file=str(out_file),
                )
                _tprint(f"  {Fore.RED}[!] XSStrike: XSS FOUND in {url}{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _kill_proc_tree(proc)
            _log_timeout_action(output_mgr, "XSStrike", url, 0, "", timeout, cmd=" ".join(str(c) for c in cmd))
        except Exception as exc:
            _tprint(f"  {Fore.RED}[!] XSStrike: {exc}{Style.RESET_ALL}")


def run_zap_dast(
    web_targets: "list[str]", output_mgr: "OutputManager",
    zap_path: str, scope: str, timeout: int = 600,
) -> None:
    """OWASP ZAP daemon-mode DAST: spider + active scan via REST API."""
    if not web_targets:
        return
    import time as _time
    import urllib.request as _ur2
    import urllib.parse as _up3
    zap_dir = output_mgr.scope_tool_path("zap")
    ZAP_PORT = 8091
    ZAP_API  = f"http://127.0.0.1:{ZAP_PORT}"
    zap_proc = None

    def _zap_get(path: str, params: "dict | None" = None, t: int = 15) -> dict:
        full = ZAP_API + path
        if params:
            full += "?" + _up3.urlencode(params)
        try:
            with _ur2.urlopen(full, timeout=t) as r:
                return json.loads(r.read().decode())
        except Exception:
            return {}

    try:
        zap_log = zap_dir / "zap.log"
        zap_cmd = [zap_path, "-daemon", "-port", str(ZAP_PORT),
                   "-config", "api.disablekey=true",
                   "-dir", str(zap_dir / "data")]
        zap_proc = _popen(zap_cmd, stdout=open(str(zap_log), "w"), stderr=subprocess.STDOUT)
        _tprint(f"  {Fore.CYAN}[*] ZAP: starting daemon...{Style.RESET_ALL}")
        for _ in range(90):
            try:
                if _zap_get("/JSON/core/view/version/", t=2).get("version"):
                    break
            except Exception:
                pass
            _time.sleep(1)
        else:
            _tprint(f"  {Fore.YELLOW}[~] ZAP: daemon did not start — skipping{Style.RESET_ALL}")
            return
        _tprint(f"  {Fore.GREEN}[+] ZAP ready — scanning {len(web_targets)} target(s){Style.RESET_ALL}")
        all_alerts: list[dict] = []
        for url in web_targets[:15]:
            spider_id = _zap_get("/JSON/spider/action/scan/", {"url": url, "recurse": "true"}).get("scan", "0")
            for _ in range(120):
                if str(_zap_get("/JSON/spider/view/status/", {"scanId": spider_id}).get("status", "0")) == "100":
                    break
                _time.sleep(1)
            ascan_id = _zap_get("/JSON/ascan/action/scan/", {"url": url, "recurse": "true"}).get("scan", "0")
            deadline = _time.time() + 300
            while _time.time() < deadline:
                if str(_zap_get("/JSON/ascan/view/status/", {"scanId": ascan_id}).get("status", "0")) == "100":
                    break
                _time.sleep(5)
            for a in (_zap_get("/JSON/alert/view/alerts/", {"baseurl": url, "start": "0", "count": "200"}).get("alerts") or []):
                all_alerts.append({"url": a.get("url", url), "name": a.get("name", ""),
                                   "risk": a.get("risk", "Info"), "description": a.get("description", ""),
                                   "cwe": a.get("cweid", "")})
        alerts_file = zap_dir / f"zap_alerts_{scope}.json"
        alerts_file.write_text(json.dumps(all_alerts, indent=2), encoding="utf-8")
        risk_map = {"High": "HIGH", "Medium": "MEDIUM", "Low": "LOW", "Informational": "INFO"}
        # ZAP alerts that duplicate an existing SS3 finding — map to the
        # canonical title so they merge as a validation instead of creating
        # a separate finding.  Risk is overridden to the canonical level.
        _ZAP_MERGE_MAP = {
            "HTTP Only Site": ("Insecure Protocol Detected: HTTP", "MEDIUM"),
            "Cookie No HttpOnly Flag": ("Cookies: Missing HttpOnly Flag", "LOW"),
            "Cookie Without Secure Flag": ("Cookies: Missing Secure Flag", "LOW"),
            "Cookie without SameSite Attribute": ("Cookies: Missing SameSite Attribute", "LOW"),
            "Strict-Transport-Security Header Not Set": ("Missing Security Header: Strict-Transport-Security", "LOW"),
        }
        # CSP-related alerts are consolidated into a single finding per
        # scan — individual directives (unsafe-inline, wildcard, missing
        # fallback) are sub-issues of the same root misconfiguration.
        _ZAP_CSP_PREFIXES = (
            "CSP:", "CSP: ", "Content Security Policy",
            "Content-Security-Policy",
        )
        for a in all_alerts:
            risk = risk_map.get(a.get("risk", ""), "INFO")
            if risk in ("HIGH", "CRITICAL", "MEDIUM", "LOW"):
                try:
                    host = _up3.urlparse(a["url"]).hostname or ""
                    port = int(_up3.urlparse(a["url"]).port or 80)
                except Exception:
                    host, port = "", 0
                _zap_name = a.get("name", "")
                _merged   = _ZAP_MERGE_MAP.get(_zap_name)
                # CSP consolidation: all CSP sub-alerts → one finding
                _is_csp = any(_zap_name.startswith(pfx) for pfx in _ZAP_CSP_PREFIXES)
                if _is_csp:
                    # Match Fracture's canonical title for cross-tool merge
                    _title = "Permissive Security Header: Content-Security-Policy"
                    risk   = "MEDIUM"
                    _aff   = f"{_zap_name} — {a['url']}"
                elif _merged:
                    _title = _merged[0]
                    risk   = _merged[1]
                    _aff   = a["url"]
                else:
                    _title = f"ZAP DAST: {_zap_name}"
                    _aff   = a["url"]
                output_mgr.log_finding(
                    title=_title, ip=host, port=port,
                    command=f"ZAP active scan: {a['url']}", risk=risk,
                    description=f"{a.get('description', '')}  CWE-{a.get('cwe', '?')}",
                    sources="zap",
                    affected=_aff,
                    output=(
                        f"Alert: {a.get('name', '')}\n"
                        f"URL: {a.get('url', '')}\n"
                        f"Risk: {a.get('risk', '')}\n"
                        f"CWE: {a.get('cwe', '')}\n\n"
                        f"Description:\n{a.get('description', '')}"
                    ),
                    output_file=str(alerts_file),
                )
        high_n = sum(1 for a in all_alerts if a.get("risk") == "High")
        _tprint(f"  {Fore.RED if high_n else Fore.GREEN}[{'!' if high_n else '+'}] "
                f"ZAP: {len(all_alerts)} alert(s), {high_n} High{Style.RESET_ALL}")
    finally:
        if zap_proc and zap_proc.poll() is None:
            zap_proc.terminate()
            try:
                zap_proc.wait(timeout=15)
            except Exception:
                zap__kill_proc_tree(proc)


