_MULTI_PART_TLDS = frozenset({
    "co.uk", "org.uk", "ac.uk", "gov.uk", "net.uk",
    "com.au", "org.au", "net.au", "edu.au", "gov.au",
    "co.nz", "org.nz", "net.nz", "co.za", "org.za",
    "co.in", "org.in", "net.in", "co.jp", "or.jp",
    "co.kr", "or.kr", "com.br", "org.br", "com.mx",
    "co.il", "org.il", "com.cn", "org.cn", "com.tw",
    "com.sg", "com.hk", "co.th", "com.ar", "com.co",
    "com.tr", "com.de", "com.es", "com.fr", "com.it",
    "com.pl", "com.ru", "com.ua",
})


def _extract_parent_domain(fqdn: str) -> str:
    fqdn = fqdn.rstrip(".").lower().strip()
    parts = fqdn.split(".")
    if len(parts) <= 2:
        return fqdn
    suffix_2 = ".".join(parts[-2:])
    if suffix_2 in _MULTI_PART_TLDS and len(parts) >= 3:
        return ".".join(parts[-3:])
    return ".".join(parts[-2:])


def _derive_ext_domains(
    hostnames: "dict[str, str | None]",
    all_results: dict,
) -> "set[str]":
    domains: set = set()
    for _ip, _hn in hostnames.items():
        if _hn and "." in _hn:
            d = _extract_parent_domain(_hn)
            if d and "." in d:
                domains.add(d)
    for _ip, _hr in all_results.items():
        for _port, _fqdn in _hr.get("hostnames_by_port", {}).items():
            if _fqdn and "." in str(_fqdn):
                d = _extract_parent_domain(str(_fqdn))
                if d and "." in d:
                    domains.add(d)
    _priv = {"localhost", "localdomain", "local", "arpa", "in-addr.arpa",
             "ip6.arpa", "example.com", "invalid"}
    return {d for d in domains if d not in _priv and not d.endswith(".local")}


def _detect_o365(domain: str, timeout: int = 10) -> bool:
    try:
        mx_proc = subprocess.run(
            ["dig", "+short", "MX", domain],
            capture_output=True, text=True, timeout=timeout,
        )
        if re.search(r'protection\.outlook\.com|mail\.protection\.outlook',
                      mx_proc.stdout, re.I):
            return True
    except Exception:
        pass
    try:
        import urllib.request as _ur3
        resp = _ur3.urlopen(
            f"https://login.microsoftonline.com/{domain}/"
            f".well-known/openid-configuration",
            timeout=8,
        )
        data = json.loads(resp.read().decode())
        if data.get("issuer"):
            return True
    except Exception:
        pass
    return False


_O365_COMMON_PREFIXES = [
    "admin", "administrator", "info", "it", "helpdesk", "support",
    "hr", "finance", "accounting", "sales", "marketing", "security",
    "noreply", "postmaster", "webmaster", "abuse", "contact",
    "reception", "office", "operations", "ceo", "cfo", "cto", "ciso",
]


def _o365_enum_builtin(
    domain: str,
    emails: "list[str]",
    timeout: int = 8,
) -> "list[str]":
    """Enumerate valid O365 accounts via Azure AD GetCredentialType API.

    No external tool required. Returns list of confirmed-valid addresses.
    """
    import urllib.request as _ur
    valid: list = []
    url = "https://login.microsoftonline.com/common/GetCredentialType"
    for email in emails:
        try:
            body = json.dumps({"Username": email}).encode()
            req = _ur.Request(url, data=body,
                              headers={"Content-Type": "application/json"})
            resp = _ur.urlopen(req, timeout=timeout)
            data = json.loads(resp.read().decode())
            if_exists = data.get("IfExistsResult", -1)
            # 0 = exists, 1 = does not exist, 5/6 = exists (different tenant)
            if if_exists in (0, 5, 6):
                valid.append(email)
        except Exception:
            pass
    return valid


def _find_osift_emails(project_dir: str) -> "list[str]":
    p = Path(project_dir)
    candidates = list(p.parent.glob("osift/*/findings.json"))
    candidates += list(p.parent.glob("osift/*/findings_vantage.json"))
    emails: set = set()
    for f in candidates:
        try:
            data = json.loads(f.read_text(encoding="utf-8"))
            items = data if isinstance(data, list) else data.get("findings", [])
            for item in items:
                if item.get("type_") == "email_identified" or \
                   item.get("type_") == "primary_email":
                    detail = item.get("detail", "")
                    for m in re.findall(r'[\w.+-]+@[\w.-]+\.\w{2,}', detail):
                        emails.add(m.lower())
                if item.get("data") and isinstance(item["data"], list):
                    for val in item["data"]:
                        if isinstance(val, str) and "@" in val:
                            for m in re.findall(r'[\w.+-]+@[\w.-]+\.\w{2,}', val):
                                emails.add(m.lower())
        except Exception:
            pass
    return sorted(emails)


def run_o365_enum(
    domain: str,
    emails: "list[str]",
    output_mgr: "OutputManager",
    o365spray_path: str,
    timeout: int = 600,
) -> "list[str]":
    enum_dir = output_mgr.scope_tool_path("o365spray")
    email_file = enum_dir / "emails.txt"
    email_file.write_text("\n".join(emails) + "\n", encoding="utf-8")
    results_file = enum_dir / f"o365enum_{domain.replace('.', '_')}.txt"

    cmd = [
        o365spray_path, "--enum",
        "-U", str(email_file),
        "--domain", domain,
        "--output", str(enum_dir),
    ]
    _tprint(f"  {Fore.CYAN}[>] o365spray --enum {domain} "
            f"({len(emails)} email(s)){Style.RESET_ALL}")
    output_mgr.log_command("o365spray", o365spray_path, cmd, results_file)

    valid_accounts: list = []
    try:
        proc = subprocess.run(
            cmd, capture_output=True, text=True, timeout=timeout,
        )
        raw = proc.stdout + (proc.stderr or "")
        results_file.write_text(raw, encoding="utf-8")

        for line in raw.splitlines():
            m = re.search(r'\[VALID\]\s+(\S+@\S+)', line, re.I)
            if m:
                valid_accounts.append(m.group(1).strip())
    except subprocess.TimeoutExpired:
        _tprint(f"  {Fore.YELLOW}[~] o365spray timed out after {timeout}s"
                f"{Style.RESET_ALL}")
    except Exception as exc:
        _tprint(f"  {Fore.RED}[!] o365spray error: {exc}{Style.RESET_ALL}")

    return valid_accounts


def scan_scope(
    scope: str,
    targets: list,
    args,
    nmap_path: str,
    sslscan_path,
    testssl_path,
    nuclei_path: "str | None" = None,
    raw_specs: "list[str] | None" = None,
    snmpwalk_path: "str | None" = None,
    smbmap_path:   "str | None" = None,
    enum4linux_path: "str | None" = None,
    adenum_path:   "str | None" = None,
    cred_store: "CredentialStore | None" = None,
    gobuster_path: "str | None" = None,
    wpscan_path:   "str | None" = None,
    webanalyze_path: "str | None" = None,
    shcheck_path:  "str | None" = None,
    searchsploit_path: "str | None" = None,
    wpscan_token:  "str | None" = None,
    showmount_path: "str | None" = None,
    ipmitool_path:  "str | None" = None,
    nbtscan_path:   "str | None" = None,
    nmblookup_path: "str | None" = None,
    avahi_resolve_path: "str | None" = None,
    rustscan_path:   "str | None" = None,
    kerbrute_path:   "str | None" = None,
    bloodhound_path: "str | None" = None,
    hydra_path:      "str | None" = None,
    sqlmap_path:     "str | None" = None,
    xsstrike_path:   "str | None" = None,
    odat_path:       "str | None" = None,
    msdat_path:      "str | None" = None,
    enumdb_path:     "str | None" = None,
    zap_path:        "str | None" = None,
    o365spray_path:  "str | None" = None,
    target_count:    int = 0,
    exclude_ips:     "set | None" = None,
    exclude_nets:    "list | None" = None,
) -> dict:
    """
    Run a complete discovery + port + web + banner + SSL scan pass for one
    scope ("int" or "ext") against the given list of IPs.

    Pipeline (two modes)
    --------------------
    Large ranges (>4096 targets with raw_specs):
      Chunked /20 discovery — each chunk runs nmap -sn via direct subprocess
      with -oA for native file output, then submits alive hosts to the Phase 2
      worker pool immediately.  Port scanning starts concurrently with the next
      chunk's discovery.  Per-chunk supplemental probes and rustscan rescue.
      Hostname resolution is per-host inside each port-scan worker.
      Checkpoint file enables crash recovery.

    Small target sets (≤4096 targets or no raw_specs):
      Original monolithic pipeline — single nmap -sn call for all targets,
      batch hostname resolution, then concurrent port scans with background
      rustscan rescue thread.

    Phase 2 — Concurrent port scans + secondary tasks (20 workers)
        Each alive host gets its own worker thread (up to
        args.port_scan_workers, default 20).  Each worker calls port_scan()
        then dispatches web probe, banner grab, sslscan, testssl, and
        web-file download concurrently for that host's open ports.
    """
    scope_colour = Fore.GREEN if scope == "int" else Fore.YELLOW
    scope_label  = f"{scope_colour}[{scope.upper()}]{Style.RESET_ALL}"

    _lazy = target_count > 0 and not targets
    _n_targets = target_count if _lazy else len(targets)
    _exclude = exclude_ips or set()
    _exclude_nets = exclude_nets or []

    def _is_excluded_ip(ip_str):
        if ip_str in _exclude:
            return True
        if _exclude_nets:
            try:
                _addr = ipaddress.ip_address(ip_str)
                return any(_addr in _net for _net in _exclude_nets)
            except ValueError:
                pass
        return False

    print(f"\n{Fore.CYAN}{'═'*60}{Style.RESET_ALL}")
    print(f"{Fore.CYAN}[*] {scope_label} {Fore.CYAN}pass — {_n_targets:,} target(s){Style.RESET_ALL}")
    print(f"{Fore.CYAN}{'═'*60}{Style.RESET_ALL}")

    _sod = getattr(args, "scope_output_dirs", {})
    _scope_dir = _sod.get(scope, "")
    output_mgr = OutputManager(args.project, scope, scope_output_dir=_scope_dir)
    output_mgr.print_summary()
    eng = getattr(args, "engagement", {}) or {}
    _write_project_meta(
        Path(args.project),
        tool="scattershot3",
        client_short=eng.get("client_short", ""),
        year=(eng.get("start_date", "") or "")[:4] or datetime.now().strftime("%Y"),
        version=VERSION,
    )
    # Dual-write universal meta.json (schema 1.0) for Prometheus UniversalParser.
    _u_dual_write_meta(
        Path(args.project),
        tool="scattershot3", version=VERSION,
        client_short=eng.get("client_short", ""),
        client_name=eng.get("client_name", ""),
        engagement_name=eng.get("engagement_name", ""),
        target=", ".join(raw_specs) if raw_specs else (args.targets_file or ""),
    )
    try:
        import pr0t31n_dep_snapshot as _ds
        _ds.write_snapshot(
            Path(args.project), "scattershot3", VERSION,
            binaries=["nmap", "sslscan", "nuclei", "gobuster", "wpscan", "hydra", "enum4linux", "rpcclient", "smbmap", "smbclient", "snmpwalk", "searchsploit", "showmount", "ipmitool", "testssl.sh", "rustscan", "msfconsole", "nbtscan", "kerbrute", "sqlmap", "ike-scan", "webanalyze"],
            pip_packages=["python-nmap", "scapy", "requests", "colorama", "impacket", "ldap3", "openpyxl", "dnspython", "selenium", "bloodhound"],
        )
    except Exception:
        pass
    print()

    # ── Discovery + Phase 2 pipeline ─────────────────────────────────────────
    # When raw_specs describe large ranges (>4096 IPs), discovery is chunked
    # into /20 subnets.  Each chunk's alive hosts are submitted to the Phase 2
    # port-scan pool immediately, so discovery and port scanning overlap.
    # Hostname resolution moves per-host (inside the port-scan worker) and
    # rescue runs per-chunk instead of as a single background thread.
    #
    # For smaller target sets, the original monolithic pipeline is used.
    _use_chunked = bool(raw_specs) and _n_targets > 4096

    _1b_timeout  = "30s" if scope == "ext" else "10s"
    _1b_retries  = "2"  if scope == "ext" else "1"
    _1b_min_par = getattr(args, "discovery_min_parallelism", None) or 20
    _1b_rate = getattr(args, "discovery_min_rate", None)
    _1b_timing = getattr(args, "timing_template", None)
    _1b_rate_flag = f" --min-rate {_1b_rate}" if _1b_rate else ""
    _1b_timing_flag = f" -T{_1b_timing}" if _1b_timing else ""
    _1b_nmap_args = (
        "-n -sn --reason "
        "-PS21,22,23,25,53,80,110,111,135,139,143,179,389,443,445,"
        "465,587,636,993,995,1433,1723,2525,3306,3389,5432,5900,"
        "8080,8443,8888,9090,9443 "
        "-PU53,69,123,161,500,1194 "
        "-PA80,443 "
        "-PR "
        f"--max-retries {_1b_retries} --min-parallelism {_1b_min_par}"
        f"{_1b_rate_flag}{_1b_timing_flag} "
        f"--host-timeout {_1b_timeout}"
    )

    if _use_chunked:
        # ══════════════════════════════════════════════════════════════════════
        # CHUNKED DISCOVERY PIPELINE — /20 chunks, pipelined with port scans
        # ══════════════════════════════════════════════════════════════════════
        hostnames: dict[str, "str | None"] = {}
        alive_map: dict[str, bool] = {}
        all_results: dict = {}

        chunks = _chunk_ranges(raw_specs, chunk_prefix=20)
        total_chunks = len(chunks)
        disc_dir = output_mgr.scope_tool_path("nmap_discovery")

        # Check for checkpoint (resume from crash)
        _ckpt = _load_discovery_checkpoint(disc_dir)
        _completed_specs: set[str] = set()
        if _ckpt:
            _completed_specs = set(_ckpt[0])
            for _ck_ip in _ckpt[1]:
                alive_map[_ck_ip] = True
            _tprint(
                f"  {Fore.CYAN}[*] Resuming from checkpoint: "
                f"{len(_completed_specs)} chunks done, "
                f"{len(_ckpt[1])} alive hosts{Style.RESET_ALL}"
            )

        print(
            f"{Fore.CYAN}[*] {scope_label} {Fore.CYAN}Phase 1: chunked host "
            f"discovery ({total_chunks} chunk(s) of /20, "
            f"{_n_targets:,} target(s))...{Style.RESET_ALL}",
            flush=True,
        )
        _vc.status(
            f"{scope}_p1_discovery",
            label="Phase 1: Host Discovery",
            status="running",
            step=f"{total_chunks} chunks · /20 · {_n_targets:,} targets",
        )

        scope_source_ip   = None
        scope_iface_name  = None
        scope_source_host = platform.node()

        n_workers = min(
            getattr(args, "port_scan_workers", _SCAN_CONCURRENCY),
            _SCAN_SEM.limit,
        )
        run_nuclei_flag = bool(
            nuclei_path and not getattr(args, "no_nuclei", False)
        )

        print(
            f"\n{Fore.CYAN}[*] {scope_label} Phase 2: port scanning "
            f"(pipelined with discovery, {n_workers} workers)..."
            f"{Style.RESET_ALL}"
        )
        _vc.status(
            f"{scope}_p2_portscan",
            label="Phase 2: Port Scan & Service Analysis",
            status="running",
            step=f"pipelined · {n_workers} workers",
            active_tools=[
                "nmap", "banners", "web", "sslscan", "testssl",
                "gobuster", "wpscan", "webanalyze", "shcheck",
                "snmp", "smb", "enum4linux", "adenum", "rdp",
                "ipmi", "nfs", "smtp", "mysql", "sip",
                "printer", "redis",
            ],
        )

        port_futures: dict = {}
        _nuclei_batch_ips: list = []

        _start_concurrency_monitor(_SCAN_SEM)
        _start_oom_watchdog()
        with ThreadPoolExecutor(max_workers=n_workers) as pool:
            # ── Feed discovery chunks into the port-scan pool ─────────────
            for _ci, _cs in enumerate(chunks, 1):
                if _cs in _completed_specs:
                    continue

                _check_pause()

                _ca, _cd = _discover_chunk(
                    _cs, _ci, total_chunks,
                    output_mgr, nmap_path, scope,
                    supp_nmap_args=_1b_nmap_args,
                    rustscan_path=rustscan_path,
                    discovery_min_rate=getattr(args, "discovery_min_rate", None),
                    discovery_min_parallelism=getattr(args, "discovery_min_parallelism", None),
                    timing_template=getattr(args, "timing_template", None),
                )

                _check_pause()

                if _exclude or _exclude_nets:
                    _ca = [ip for ip in _ca if not _is_excluded_ip(ip)]

                for ip in _ca:
                    alive_map[ip] = True

                # Detect source IP from first alive host
                if scope_source_ip is None and _ca:
                    scope_source_ip = get_source_ip_for(_ca[0])
                    if scope_source_ip:
                        _ri = get_interface_info(scope_source_ip)
                        scope_iface_name = _ri.split()[0] if _ri else None

                # Submit port-scan workers for this chunk's alive hosts
                for ip in _ca:
                    port_futures[pool.submit(
                        _port_scan_worker,
                        ip,
                        None,
                        args.fast,
                        output_mgr,
                        nmap_path,
                        args,
                        sslscan_path,
                        testssl_path,
                        snmpwalk_path,
                        smbmap_path,
                        enum4linux_path,
                        adenum_path,
                        scope,
                        cred_store,
                        gobuster_path,
                        wpscan_path,
                        webanalyze_path,
                        shcheck_path,
                        wpscan_token,
                        showmount_path,
                        ipmitool_path,
                        rustscan_path,
                        True,
                        nmblookup_path,
                        avahi_resolve_path,
                        hostnames,
                    )] = ip

                # Update checkpoint
                _completed_specs.add(_cs)
                _write_discovery_checkpoint(
                    disc_dir,
                    sorted(_completed_specs),
                    sorted(ip for ip, v in alive_map.items() if v),
                    total_chunks,
                )

                # Progress
                _in_flight = sum(1 for f in port_futures if not f.done())
                _ta = sum(1 for v in alive_map.values() if v)
                _vc.status(
                    f"{scope}_p1_discovery",
                    label="Phase 1: Host Discovery",
                    status="running",
                    step=(
                        f"Chunk {_ci}/{total_chunks} · "
                        f"{_ta} alive · {_in_flight} in-flight"
                    ),
                )

            # ── Discovery complete ────────────────────────────────────────
            alive_ips = sorted(
                [ip for ip, v in alive_map.items() if v],
                key=lambda a: int(ipaddress.ip_address(a)),
            )
            dead_ips: list[str] = []
            alive_count = len(alive_ips)
            _dead_count = _n_targets - alive_count

            active_ips_file: "Path | None" = None
            if alive_ips:
                try:
                    active_ips_file = (
                        output_mgr.root / "targets" / "active_ips.txt"
                    )
                    active_ips_file.write_text(
                        "\n".join(alive_ips) + "\n", encoding="utf-8",
                    )
                except Exception:
                    active_ips_file = None

            print(
                f"{Fore.GREEN}[+] {scope_label} Discovery complete: "
                f"{alive_count} alive / {_n_targets:,} total"
                f"{Style.RESET_ALL}"
            )
            _vc.status(
                f"{scope}_p1_discovery",
                label="Phase 1: Host Discovery",
                status="complete",
                step=f"{alive_count} alive / {_n_targets:,} total",
            )
            if _dead_count > 0:
                print(
                    f"    {Fore.RED}[-] {_dead_count:,} host(s) — "
                    f"no response{Style.RESET_ALL}"
                )

            # ── Collect port-scan results ─────────────────────────────────
            _nuclei_base = getattr(args, "nuclei_timeout", 600)
            for future in as_completed(port_futures):
                _check_pause()
                ip = port_futures[future]
                try:
                    result_ip, host_result = future.result()
                    host_result["scope"]        = scope
                    host_result["source_ip"]    = scope_source_ip
                    host_result["source_iface"] = scope_iface_name
                    host_result["source_host"]  = scope_source_host
                    all_results[result_ip] = host_result

                    with _PRINT_LOCK:
                        print_host_header(result_ip, True)
                        for port, info in host_result[
                                "open_ports"].items():
                            fqdn = host_result.get(
                                "hostnames_by_port", {}
                            ).get(port)
                            print_port(
                                port, info, info.get("web"),
                                info.get("banner"))
                            if fqdn:
                                print(
                                    f"           {Fore.CYAN}FQDN "
                                    f"(port {port}): "
                                    f"{fqdn}{Style.RESET_ALL}")
                        for port, ssl_data in host_result.get(
                            "ssl_results", {}
                        ).items():
                            print_ssl_results(
                                result_ip, port,
                                ssl_data.get("sslscan"),
                                ssl_data.get("testssl"))

                    if run_nuclei_flag and host_result.get("open_ports"):
                        _nuclei_batch_ips.append(result_ip)

                except Exception as exc:
                    _tprint(
                        f"{Fore.RED}  [!] Worker failed for {ip}: "
                        f"{exc}{Style.RESET_ALL}")
                    try:
                        _w_tb  = traceback.format_exc()
                        _w_msg = (
                            f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] "
                            f"PORT SCAN WORKER CRASH — {ip}: "
                            f"{type(exc).__name__}: {exc}\n{_w_tb}\n")
                        with output_mgr._log_lock:
                            with output_mgr.error_log.open(
                                    "a", encoding="utf-8") as _ef:
                                _ef.write(_w_msg)
                            with output_mgr.log_file.open(
                                    "a", encoding="utf-8") as _lf:
                                _lf.write(_w_msg)
                    except Exception:
                        pass
                    all_results[ip] = {
                        "alive": True, "hostname": hostnames.get(ip),
                        "scope": scope, "source_ip": scope_source_ip,
                        "source_iface": scope_iface_name,
                        "source_host": scope_source_host,
                        "open_ports": {}, "web_services": [],
                        "ssl_results": {}, "hostnames_by_port": {},
                        "web_files": {},
                    }

            # ── Batch Nuclei IP scan ──────────────────────────────────────
            if _nuclei_batch_ips:
                _tprint(
                    f"\n{Fore.CYAN}[*] {scope_label} Nuclei IP scan "
                    f"({len(_nuclei_batch_ips)} host(s))..."
                    f"{Style.RESET_ALL}"
                )
                _vc.status(
                    f"{scope}_p2_nuclei",
                    label="Phase 2: Nuclei IP Scan",
                    status="running",
                    step=f"{len(_nuclei_batch_ips)} hosts",
                )
                nuclei_timeout = max(
                    _nuclei_base, len(_nuclei_batch_ips) * 60
                )
                try:
                    run_nuclei(
                        _nuclei_batch_ips, scope, output_mgr,
                        nuclei_path,
                        timeout=nuclei_timeout,
                        all_results=all_results,
                    )
                except Exception as exc:
                    _tprint(
                        f"{Fore.RED}[!] Nuclei batch scan error: "
                        f"{exc}{Style.RESET_ALL}"
                    )
                    try:
                        with output_mgr._log_lock:
                            with output_mgr.error_log.open(
                                    "a", encoding="utf-8") as _ef:
                                _ef.write(
                                    f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] "
                                    f"NUCLEI SCAN ERROR: "
                                    f"{type(exc).__name__}: {exc}\n"
                                )
                    except Exception:
                        pass
                _vc.status(
                    f"{scope}_p2_nuclei",
                    label="Phase 2: Nuclei IP Scan",
                    status="complete",
                )
                _tprint(
                    f"{Fore.GREEN}[+] {scope_label} Nuclei IP scan "
                    f"complete{Style.RESET_ALL}"
                )

        # Remove checkpoint on successful completion
        try:
            _ckpt_path = disc_dir / "checkpoint.json"
            if _ckpt_path.exists():
                _ckpt_path.unlink()
        except Exception:
            pass

        _vc.status(
            f"{scope}_p2_portscan",
            label="Phase 2: Port Scan & Service Analysis",
            status="complete" if alive_ips else "skipped",
        )

    else:
        # ══════════════════════════════════════════════════════════════════════
        # ORIGINAL MONOLITHIC DISCOVERY PIPELINE — small target sets
        # ══════════════════════════════════════════════════════════════════════
        _spec_desc = (f"{len(raw_specs)} spec(s) → {_n_targets:,} IP(s)"
                      if raw_specs and len(raw_specs) != _n_targets
                      else f"{_n_targets:,} target(s)")
        print(f"{Fore.CYAN}[*] {scope_label} {Fore.CYAN}Phase 1: host discovery "
              f"({_spec_desc} in one nmap pass)...{Style.RESET_ALL}",
              flush=True)
        _vc.status(f"{scope}_p1_discovery", label="Phase 1: Host Discovery",
                   status="running", step=_spec_desc)

        alive_map = host_discovery_range(
            targets,
            output_mgr=output_mgr,
            nmap_path=nmap_path,
            raw_specs=raw_specs,
            scope=scope,
            discovery_min_rate=getattr(args, "discovery_min_rate", None),
            discovery_min_parallelism=getattr(args, "discovery_min_parallelism", None),
            timing_template=getattr(args, "timing_template", None),
        )
        # In lazy mode, exclude local + project-excluded IPs from alive results
        if _lazy and (_exclude or _exclude_nets):
            for _eip in _exclude:
                alive_map.pop(_eip, None)
            if _exclude_nets:
                for _aip in list(alive_map):
                    if _aip not in _exclude and _is_excluded_ip(_aip):
                        alive_map.pop(_aip, None)

        # ── Phase 1b: Supplemental host discovery (-sn -PS -PA -PR) ───────
        if _lazy:
            _alive_before = sum(1 for v in alive_map.values() if v)
            print(f"{Fore.CYAN}[*] {scope_label} Phase 1b: supplemental discovery "
                  f"(-PS -PA -PR, full scope re-scan)...{Style.RESET_ALL}",
                  flush=True)
            _alive_map_2 = host_discovery_range(
                [],
                output_mgr=output_mgr,
                nmap_path=nmap_path,
                raw_specs=raw_specs,
                nmap_args=_1b_nmap_args,
                scope=scope,
            )
            _newly_alive = [ip for ip, alive in _alive_map_2.items()
                            if alive and not alive_map.get(ip)
                            and not _is_excluded_ip(ip)]
            for ip in _newly_alive:
                alive_map[ip] = True
                print(f"    {Fore.GREEN}[+] {ip} — ALIVE (supplemental probe){Style.RESET_ALL}")
            if not _newly_alive:
                print(f"    {Fore.YELLOW}[~] No additional hosts found in supplemental pass{Style.RESET_ALL}")
        else:
            _first_dead = [ip for ip in targets if not alive_map.get(ip)]
            if _first_dead:
                print(f"{Fore.CYAN}[*] {scope_label} Phase 1b: supplemental discovery "
                      f"(-PS -PA -PR, {len(_first_dead)} non-responsive host(s))...{Style.RESET_ALL}",
                      flush=True)
                _alive_map_2 = host_discovery_range(
                    _first_dead,
                    output_mgr=output_mgr,
                    nmap_path=nmap_path,
                    nmap_args=_1b_nmap_args,
                    scope=scope,
                )
                _newly_alive = [ip for ip, alive in _alive_map_2.items() if alive]
                for ip in _newly_alive:
                    alive_map[ip] = True
                    print(f"    {Fore.GREEN}[+] {ip} — ALIVE (supplemental probe){Style.RESET_ALL}")
                if not _newly_alive:
                    print(f"    {Fore.YELLOW}[~] No additional hosts found in supplemental pass{Style.RESET_ALL}")

        # Phase 1c (rustscan rescue) now runs in parallel with Phase 2.
        _still_dead = [] if _lazy else [ip for ip in targets if not alive_map.get(ip)]

        if _lazy:
            alive_ips = sorted(
                [ip for ip, v in alive_map.items() if v],
                key=lambda a: int(ipaddress.ip_address(a)))
            dead_ips    = []
        else:
            alive_ips   = [ip for ip in targets if alive_map.get(ip)]
            dead_ips    = [ip for ip in targets if not alive_map.get(ip)]
        alive_count = len(alive_ips)
        _dead_count = _n_targets - alive_count

        # ── Write persistent active-IPs file ─────────────────────────────
        active_ips_file: "Path | None" = None
        if alive_ips:
            try:
                active_ips_file = output_mgr.root / "targets" / "active_ips.txt"
                active_ips_file.write_text("\n".join(alive_ips) + "\n", encoding="utf-8")
            except Exception:
                active_ips_file = None

        print(f"{Fore.GREEN}[+] {scope_label} Discovery complete: "
              f"{alive_count} alive / {_n_targets:,} total{Style.RESET_ALL}")
        _vc.status(f"{scope}_p1_discovery", label="Phase 1: Host Discovery",
                   status="complete", step=f"{alive_count} alive / {_n_targets:,} total")
        if _lazy and _dead_count > 0:
            print(f"    {Fore.RED}[-] {_dead_count:,} host(s) — no response{Style.RESET_ALL}")
        else:
            for ip in dead_ips:
                print(f"    {Fore.RED}[-] {ip} — no response{Style.RESET_ALL}")
        for ip in alive_ips:
            print(f"    {Fore.GREEN}[+] {ip} — ALIVE{Style.RESET_ALL}")
            _vc.target(ip=ip, hostname=None, scope=scope, alive=True, source="nmap")

        # ── Phase 1.5: Hostname Resolution ────────────────────────────────
        hostnames: dict[str, "str | None"] = {}
        if alive_ips and not getattr(args, "no_hostname_scan", False):
            _vc.status(f"{scope}_p1_5_hostname",
                       label="Phase 1.5: Hostname Resolution",
                       status="running",
                       step=f"{len(alive_ips)} hosts · PTR"
                            + (" + nbtscan" if nbtscan_path else "")
                            + (" + nmblookup" if (nmblookup_path and not nbtscan_path) else "")
                            + (" + mDNS" if avahi_resolve_path else ""))
            print(f"\n{Fore.CYAN}[*] {scope_label} Phase 1.5: resolving hostnames "
                  f"({len(alive_ips)} host(s))...{Style.RESET_ALL}")
            run_hostname_resolution(
                alive_ips, output_mgr, hostnames,
                nbtscan_path, nmblookup_path, avahi_resolve_path,
            )
            enriched = output_mgr.enrich_hostnames(hostnames)
            if enriched:
                _tprint(f"  {Fore.CYAN}[*] Enriched {enriched} Phase 1 finding(s) "
                        f"with resolved hostnames{Style.RESET_ALL}")
            for _ip, _hn in hostnames.items():
                if _hn:
                    _vc.target(ip=_ip, hostname=_hn, scope=scope,
                               alive=True, source="hostname_resolution")
            _vc.status(f"{scope}_p1_5_hostname",
                       label="Phase 1.5: Hostname Resolution",
                       status="complete",
                       step=f"{sum(1 for h in hostnames.values() if h)}/{len(alive_ips)} resolved")
        elif alive_ips:
            for ip in alive_ips:
                hostnames[ip] = None
            _vc.status(f"{scope}_p1_5_hostname",
                       label="Phase 1.5: Hostname Resolution",
                       status="skipped")
        else:
            _vc.status(f"{scope}_p1_5_hostname",
                       label="Phase 1.5: Hostname Resolution",
                       status="skipped")

        # Initialise result dict
        all_results: dict = {}
        if not _lazy:
            for ip in dead_ips:
                all_results[ip] = {
                    "alive": False, "hostname": None, "scope": scope,
                    "open_ports": {}, "web_services": [], "ssl_results": {},
                }

        # ── Detect source IP / interface for this scope ───────────────────
        scope_source_ip    = None
        scope_iface_name   = None
        scope_source_host  = platform.node()
        if alive_ips:
            scope_source_ip  = get_source_ip_for(alive_ips[0])
            if scope_source_ip:
                raw_iface = get_interface_info(scope_source_ip)
                scope_iface_name = raw_iface.split()[0] if raw_iface else None

        # ── Phase 2: Concurrent port scans ───────────────────────────────
        n_workers    = min(getattr(args, "port_scan_workers", _SCAN_CONCURRENCY), _SCAN_SEM.limit)
        run_nuclei_flag = (
            nuclei_path
            and not getattr(args, "no_nuclei", False)
            and alive_ips
        )

        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 2: port scanning "
              f"{alive_count} host(s) ({n_workers} workers)...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p2_portscan", label="Phase 2: Port Scan & Service Analysis",
                   status="running" if alive_ips else "skipped",
                   step=f"{alive_count} hosts · {n_workers} workers",
                   active_tools=["nmap", "banners", "web", "sslscan", "testssl",
                                 "gobuster", "wpscan", "webanalyze", "shcheck",
                                 "snmp", "smb", "enum4linux", "adenum", "rdp",
                                 "ipmi", "nfs", "smtp", "mysql", "sip",
                                 "printer", "redis"] if alive_ips else None)

        port_futures: dict = {}

        _start_concurrency_monitor(_SCAN_SEM)
        _start_oom_watchdog()
        with ThreadPoolExecutor(max_workers=n_workers) as pool:
                _nuclei_base       = getattr(args, "nuclei_timeout", 600)
                _nuclei_batch_ips: list = []

                # ── Submit one port-scan worker per alive host ────────────
                for ip in alive_ips:
                    port_futures[pool.submit(
                        _port_scan_worker,
                        ip,
                        hostnames.get(ip),
                        args.fast,
                        output_mgr,
                        nmap_path,
                        args,
                        sslscan_path,
                        testssl_path,
                        snmpwalk_path,
                        smbmap_path,
                        enum4linux_path,
                        adenum_path,
                        scope,
                        cred_store,
                        gobuster_path,
                        wpscan_path,
                        webanalyze_path,
                        shcheck_path,
                        wpscan_token,
                        showmount_path,
                        ipmitool_path,
                        rustscan_path,
                    )] = ip

                # ── Phase 1c: Background rustscan rescue ──────────────────
                _rescue_lock    = threading.Lock()
                _rescue_pending: list[tuple] = []
                _rescue_done    = threading.Event()

                def _bg_rustscan_rescue():
                    if not _still_dead:
                        _rescue_done.set()
                        return
                    _eff_rs = rustscan_path or shutil.which("rustscan")
                    _tprint(f"\n{Fore.CYAN}[*] {scope_label} Phase 1c: background "
                            f"host rescue ({len(_still_dead)} non-responsive "
                            f"host(s), {'rustscan' if _eff_rs else 'nmap -Pn'} "
                            f"all 65535 ports)...{Style.RESET_ALL}")
                    _vc.status(f"{scope}_p1c_rescue",
                               label="Phase 1c: Host Rescue (parallel)",
                               status="running",
                               step=f"{len(_still_dead)} host(s) · "
                                    f"{'rustscan' if _eff_rs else 'nmap'}")
                    _rescued: list[str] = []
                    for _r_ip in _still_dead:
                        _r_ports: list[int] = []
                        try:
                            if _eff_rs:
                                _rs_cmd = [_eff_rs, "-a", _r_ip, "--ulimit",
                                           "5000", "--greppable", "-p", "1-65535"]
                                _rs_timeout = 120 if scope == "ext" else 60
                                _rs_p = subprocess.run(
                                    _rs_cmd, capture_output=True,
                                    timeout=_rs_timeout)
                                _rs_txt = _rs_p.stdout.decode(
                                    "utf-8", errors="replace")
                                for _rl in _rs_txt.splitlines():
                                    _rm = (re.search(r'Open\s+[\d.]+:(\d+)',
                                                     _rl) or
                                           re.search(r'Open\s+(\d+)', _rl))
                                    if _rm:
                                        _r_ports.append(int(_rm.group(1)))
                            else:
                                _pn_args = ("-n -Pn -sS -p- -T4 "
                                            "--max-retries 2 "
                                            "--max-rtt-timeout 3000ms "
                                            "--host-timeout 300s")
                                _pn_nm = nmap.PortScanner()
                                _pn_nm.scan(hosts=_r_ip, arguments=_pn_args)
                                if _r_ip in _pn_nm.all_hosts():
                                    for _pr in _pn_nm[_r_ip].all_protocols():
                                        for _pp in _pn_nm[_r_ip][_pr]:
                                            if _pn_nm[_r_ip][_pr][_pp].get(
                                                    "state", ""
                                            ).startswith("open"):
                                                _r_ports.append(int(_pp))
                        except (subprocess.TimeoutExpired, OSError,
                                ValueError, Exception):
                            pass
                        if _r_ports:
                            alive_map[_r_ip] = True
                            _rescued.append(_r_ip)
                            _r_hn = None
                            try:
                                _r_hn_name, _, _ = socket.gethostbyaddr(_r_ip)
                                _r_hn = _r_hn_name
                            except Exception:
                                pass
                            hostnames[_r_ip] = _r_hn
                            _tprint(f"    {Fore.GREEN}[+] {_r_ip} — ALIVE "
                                    f"({len(_r_ports)} port(s), "
                                    f"{'rustscan' if _eff_rs else 'nmap'} "
                                    f"rescue){Style.RESET_ALL}")
                            _vc.target(ip=_r_ip, hostname=_r_hn, scope=scope,
                                       alive=True,
                                       source="rustscan-rescue"
                                              if _eff_rs else "nmap-pn-rescue")
                            _f = pool.submit(
                                _port_scan_worker,
                                _r_ip, _r_hn, args.fast, output_mgr,
                                nmap_path, args, sslscan_path, testssl_path,
                                snmpwalk_path, smbmap_path, enum4linux_path,
                                adenum_path, scope, cred_store, gobuster_path,
                                wpscan_path, webanalyze_path, shcheck_path,
                                wpscan_token, showmount_path, ipmitool_path,
                                rustscan_path)
                            with _rescue_lock:
                                _rescue_pending.append((_f, _r_ip))
                    if not _rescued:
                        _tprint(f"    {Fore.YELLOW}[~] No additional hosts found "
                                f"in rescue pass{Style.RESET_ALL}")
                    _vc.status(f"{scope}_p1c_rescue",
                               label="Phase 1c: Host Rescue (parallel)",
                               status="complete",
                               step=f"{len(_rescued)} rescued")
                    _rescue_done.set()

                _rescue_thread = threading.Thread(
                    target=_bg_rustscan_rescue, daemon=True)
                _rescue_thread.start()

                # ── Collect port-scan results ─────────────────────────────
                _pending = set(port_futures.keys())
                _fut_to_ip = dict(port_futures)

                while _pending or not _rescue_done.is_set():
                    with _rescue_lock:
                        for _rf, _rip in _rescue_pending:
                            _pending.add(_rf)
                            _fut_to_ip[_rf] = _rip
                        _rescue_pending.clear()

                    if not _pending:
                        time.sleep(0.5)
                        continue

                    _done, _pending = wait(
                        _pending, timeout=2.0,
                        return_when=FIRST_COMPLETED)

                    for future in _done:
                        ip = _fut_to_ip[future]
                        try:
                            result_ip, host_result = future.result()
                            host_result["scope"]        = scope
                            host_result["source_ip"]    = scope_source_ip
                            host_result["source_iface"] = scope_iface_name
                            host_result["source_host"]  = scope_source_host
                            all_results[result_ip] = host_result

                            with _PRINT_LOCK:
                                print_host_header(result_ip, True)
                                for port, info in host_result[
                                        "open_ports"].items():
                                    fqdn = host_result.get(
                                        "hostnames_by_port", {}
                                    ).get(port)
                                    print_port(
                                        port, info, info.get("web"),
                                        info.get("banner"))
                                    if fqdn:
                                        print(
                                            f"           {Fore.CYAN}FQDN "
                                            f"(port {port}): "
                                            f"{fqdn}{Style.RESET_ALL}")
                                for port, ssl_data in host_result.get(
                                    "ssl_results", {}
                                ).items():
                                    print_ssl_results(
                                        result_ip, port,
                                        ssl_data.get("sslscan"),
                                        ssl_data.get("testssl"))

                            if run_nuclei_flag and host_result.get("open_ports"):
                                _nuclei_batch_ips.append(result_ip)

                        except Exception as exc:
                            _tprint(
                                f"{Fore.RED}  [!] Worker failed for {ip}: "
                                f"{exc}{Style.RESET_ALL}")
                            try:
                                _w_tb  = traceback.format_exc()
                                _w_msg = (
                                    f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] "
                                    f"PORT SCAN WORKER CRASH — {ip}: "
                                    f"{type(exc).__name__}: {exc}\n{_w_tb}\n")
                                with output_mgr._log_lock:
                                    with output_mgr.error_log.open(
                                            "a", encoding="utf-8") as _ef:
                                        _ef.write(_w_msg)
                                    with output_mgr.log_file.open(
                                            "a", encoding="utf-8") as _lf:
                                        _lf.write(_w_msg)
                            except Exception:
                                pass
                            all_results[ip] = {
                                "alive": True, "hostname": hostnames.get(ip),
                                "scope": scope, "source_ip": scope_source_ip,
                                "source_iface": scope_iface_name,
                                "source_host": scope_source_host,
                                "open_ports": {}, "web_services": [],
                                "ssl_results": {}, "hostnames_by_port": {},
                                "web_files": {},
                            }

                # Ensure rescue thread is fully done before moving on
                _rescue_thread.join(timeout=10)

                # Final sweep — any futures added in the last rescue cycle
                with _rescue_lock:
                    for _rf, _rip in _rescue_pending:
                        _pending.add(_rf)
                        _fut_to_ip[_rf] = _rip
                    _rescue_pending.clear()
                for future in as_completed(_pending):
                    _check_pause()
                    ip = _fut_to_ip[future]
                    try:
                        result_ip, host_result = future.result()
                        host_result["scope"]        = scope
                        host_result["source_ip"]    = scope_source_ip
                        host_result["source_iface"] = scope_iface_name
                        host_result["source_host"]  = scope_source_host
                        all_results[result_ip] = host_result
                        if run_nuclei_flag and host_result.get("open_ports"):
                            _nuclei_batch_ips.append(result_ip)
                    except Exception:
                        all_results.setdefault(ip, {
                            "alive": True, "hostname": hostnames.get(ip),
                            "scope": scope, "source_ip": scope_source_ip,
                            "source_iface": scope_iface_name,
                            "source_host": scope_source_host,
                            "open_ports": {}, "web_services": [],
                            "ssl_results": {}, "hostnames_by_port": {},
                            "web_files": {},
                        })

                # ── Batch Nuclei scan ─────────────────────────────────────
                if _nuclei_batch_ips:
                    _tprint(
                        f"\n{Fore.CYAN}[*] {scope_label} Nuclei IP scan "
                        f"({len(_nuclei_batch_ips)} host(s))...{Style.RESET_ALL}"
                    )
                    _vc.status(f"{scope}_p2_nuclei", label="Phase 2: Nuclei IP Scan",
                               status="running", step=f"{len(_nuclei_batch_ips)} hosts")
                    nuclei_timeout = max(_nuclei_base, len(_nuclei_batch_ips) * 60)
                    try:
                        run_nuclei(
                            _nuclei_batch_ips, scope, output_mgr, nuclei_path,
                            timeout=nuclei_timeout, all_results=all_results,
                        )
                    except Exception as exc:
                        _tprint(
                            f"{Fore.RED}[!] Nuclei batch scan error: "
                            f"{exc}{Style.RESET_ALL}"
                        )
                        try:
                            with output_mgr._log_lock:
                                with output_mgr.error_log.open("a", encoding="utf-8") as _ef:
                                    _ef.write(
                                        f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] "
                                        f"NUCLEI SCAN ERROR: {type(exc).__name__}: {exc}\n"
                                    )
                        except Exception:
                            pass
                    _vc.status(f"{scope}_p2_nuclei", label="Phase 2: Nuclei IP Scan",
                               status="complete")
                    _tprint(
                        f"{Fore.GREEN}[+] {scope_label} Nuclei IP scan "
                        f"complete{Style.RESET_ALL}"
                    )

        _vc.status(f"{scope}_p2_portscan", label="Phase 2: Port Scan & Service Analysis",
                   status="complete" if alive_ips else "skipped")

    # Recompute after rescue — rescued hosts are now in alive_map
    if _lazy:
        alive_ips = sorted(
            [ip for ip, v in alive_map.items() if v],
            key=lambda a: int(ipaddress.ip_address(a)))
        dead_ips = []
    else:
        alive_ips   = [ip for ip in targets if alive_map.get(ip)]
        dead_ips    = [ip for ip in targets if not alive_map.get(ip)]
    alive_count = len(alive_ips)

    # Rewrite active_ips.txt with all alive hosts (including rescued)
    if alive_ips:
        try:
            active_ips_file = output_mgr.root / "targets" / "active_ips.txt"
            active_ips_file.write_text(
                "\n".join(alive_ips) + "\n", encoding="utf-8")
        except Exception:
            pass

    # Ensure dead stubs exist for truly-dead hosts only
    # (skipped in lazy mode)
    if not _lazy:
        for ip in dead_ips:
            if ip not in all_results:
                all_results[ip] = {
                    "alive": False, "hostname": None, "scope": scope,
                    "open_ports": {}, "web_services": [], "ssl_results": {},
                }

    # ── Scope-level summary ───────────────────────────────────────────────────
    print(f"\n{scope_label} {Fore.CYAN}Scope complete — "
          f"{Fore.GREEN}{alive_count} alive{Fore.CYAN} / "
          f"{_n_targets:,} total{Style.RESET_ALL}")

    web_hosts = [ip for ip, r in all_results.items() if r.get("web_services")]
    if web_hosts:
        print(f"{Fore.MAGENTA}[+] Web services found:{Style.RESET_ALL}")
        for ip in web_hosts:
            for svc in all_results[ip]["web_services"]:
                url   = f"{svc['scheme']}://{ip}:{svc['port']}/"
                title = f" \"{svc['title']}\"" if svc.get("title") else ""
                print(f"    {Fore.MAGENTA}{url}{Style.RESET_ALL}{title}")

    ssl_issues = []
    for ip, r in all_results.items():
        for port, ssl_data in r.get("ssl_results", {}).items():
            for tool_key, tool_result in ssl_data.items():
                vulns       = [v for v in tool_result.get("vulnerabilities", [])
                               if v["severity"] == "VULNERABLE"]
                weak_protos = [p for p in tool_result.get("protocols", [])
                               if p.get("status") in ("offered", "enabled")
                               and _RE_WEAK_PROTO.search(p["protocol"])]
                if vulns or weak_protos:
                    ssl_issues.append((ip, port, tool_key, vulns, weak_protos))

    if ssl_issues:
        print(f"\n{Fore.RED}[!] SSL/TLS issues in {scope.upper()} scope:{Style.RESET_ALL}")
        for ip, port, tool, vulns, weak_protos in ssl_issues:
            print(f"    {Fore.RED}{ip}:{port} ({tool}){Style.RESET_ALL}")
            for v in vulns:
                print(f"        VULNERABLE: {v['name']}")
            for p in weak_protos:
                print(f"        Weak protocol: {p['protocol']}")

    if not args.no_banner:
        banner_hits = [
            (ip, port, pd["banner"])
            for ip, r in all_results.items()
            for port, pd in r.get("open_ports", {}).items()
            if pd.get("banner") and pd["banner"].get("banner")
        ]
        if banner_hits:
            print(f"\n{Fore.GREEN}[+] Banners captured: {len(banner_hits)}{Style.RESET_ALL}")
            for ip, port, br in banner_hits:
                tls_tag    = " [TLS]" if br.get("tls") else ""
                first_line = br["banner"].splitlines()[0][:80]
                print(f"    {Fore.CYAN}{ip}:{port}{tls_tag}{Style.RESET_ALL}  {first_line}")

    # ── Web target lists ────────────────────────────────────────────────────
    # Build target lists now (needed for Nuclei web-URL pass below) but do NOT
    # write results.json / correlated.json / findings summary yet — those are
    # deferred until after Phase 3 (Nuclei web-URL pass) so all findings from
    # all Nuclei passes are included in the final output files.
    web_ports_path = web_targets_path = None
    try:
        web_ports_path, web_targets_path = output_mgr.write_web_target_lists(all_results)
        wc = sum(1 for ln in web_ports_path.read_text(encoding="utf-8").splitlines() if ln.strip())
        if wc:
            print(f"{Fore.MAGENTA}[+] Web target lists written: "
                  f"{wc} port(s){Style.RESET_ALL}")
        else:
            print(f"{Fore.YELLOW}[~] No web ports found — target lists empty.{Style.RESET_ALL}")
    except Exception as exc:
        print(f"{Fore.RED}[!] Web target list generation failed: {exc}{Style.RESET_ALL}")

    # ── Write web_responses.json — lightweight HTTP status map ───────────
    try:
        resp_map: dict = {}
        for r_ip, hr in all_results.items():
            for ws in (hr.get("web_services") or []):
                ws_port = ws.get("port")
                ws_code = ws.get("status_code")
                if r_ip and ws_port is not None and ws_code is not None:
                    resp_map.setdefault(r_ip, {})[str(ws_port)] = ws_code
        if resp_map:
            resp_out = output_mgr.root / "web_responses.json"
            resp_out.write_text(json.dumps(resp_map, indent=2), encoding="utf-8")
    except Exception:
        pass

    # ── Phase 3: Nuclei web-URL top-up pass ─────────────────────────────────
    # Now that port scans are complete we know which URLs are live.  Run a
    # second, focused Nuclei pass against confirmed HTTP/HTTPS endpoints so
    # web-specific templates (sql-injection, xss, misconfig, etc.) fire with
    # real scheme+port URLs.  Bare IPs already covered by the concurrent pass
    # are excluded to avoid redundant work.
    # NOTE: results.json, correlated.json and the findings summary are written
    # AFTER this pass completes so they capture all Nuclei findings.
    if not nuclei_path or getattr(args, "no_nuclei", False):
        _vc.status(f"{scope}_p3_nuclei", label="Phase 3: Nuclei Web Scan", status="skipped")
    if run_nuclei_flag and alive_ips:
        web_url_targets: list[str] = []
        # Collect confirmed web URLs from port-scan results
        for ip, r in all_results.items():
            for svc in r.get("web_services", []):
                port   = svc.get("port", 80)
                scheme = (svc.get("scheme")
                          or ("https" if port_is_tls(port, svc) else "http"))
                web_url_targets.append(_clean_url(scheme, ip, port))

        if web_url_targets:
            print(
                f"\n{Fore.CYAN}[*] {scope_label} Nuclei web-URL pass "
                f"({len(web_url_targets)} endpoint(s))...{Style.RESET_ALL}"
            )
            _vc.status(f"{scope}_p3_nuclei", label="Phase 3: Nuclei Web Scan",
                       status="running", step=f"{len(web_url_targets)} endpoints",
                       active_tools=["nuclei"])
            _nuclei_web_base = getattr(args, "nuclei_timeout", 600)
            nuclei_timeout = max(_nuclei_web_base, len(web_url_targets) * 45)
            run_nuclei(
                web_url_targets, scope, output_mgr, nuclei_path,
                timeout=nuclei_timeout, all_results=all_results,
            )
            _vc.status(f"{scope}_p3_nuclei", label="Phase 3: Nuclei Web Scan",
                       status="complete")
        else:
            print(
                f"{Fore.YELLOW}[~] No confirmed web endpoints — "
                f"skipping Nuclei web-URL pass.{Style.RESET_ALL}"
            )
            _vc.status(f"{scope}_p3_nuclei", label="Phase 3: Nuclei Web Scan",
                       status="skipped", step="no web endpoints")
    elif nuclei_path and getattr(args, "no_nuclei", False):
        pass   # user disabled nuclei — already noted at startup
    elif not nuclei_path and not getattr(args, "no_nuclei", False):
        print(f"{Fore.YELLOW}[~] Nuclei not available — web-URL pass skipped.{Style.RESET_ALL}")

    # ── Phase 4: searchsploit — exploit-DB lookup against nmap XML files ────
    # Run after all port scans and Nuclei passes so that all nmap XML files
    # are fully written before searchsploit reads them.
    if searchsploit_path and not getattr(args, "no_searchsploit", False) and alive_ips:
        print(
            f"\n{Fore.CYAN}[*] {scope_label} Phase 4: searchsploit "
            f"(nmap XML exploit lookup)...{Style.RESET_ALL}"
        )
        _vc.status(f"{scope}_p4_exploit", label="Phase 4: Searchsploit",
                   status="running")
        try:
            run_searchsploit(
                output_mgr,
                searchsploit_path,
                timeout=getattr(args, "searchsploit_timeout", 120),
            )
            _vc.status(f"{scope}_p4_exploit", label="Phase 4: Searchsploit",
                       status="complete")
        except Exception as exc:
            print(f"{Fore.RED}[!] searchsploit error: {exc}{Style.RESET_ALL}")
            _vc.status(f"{scope}_p4_exploit", label="Phase 4: Searchsploit",
                       status="error", step=str(exc)[:80])
    elif not searchsploit_path and not getattr(args, "no_searchsploit", False):
        print(
            f"{Fore.YELLOW}[~] searchsploit not available — exploit lookup skipped.{Style.RESET_ALL}"
        )
        _vc.status(f"{scope}_p4_exploit", label="Phase 4: Searchsploit",
                   status="skipped", step="not installed")

    # ── Phase 4b: Sploitus exploit lookup ────────────────────────────────────
    _all_cves: list[str] = []
    try:
        if output_mgr.findings_json.exists():
            _fraw = json.loads(output_mgr.findings_json.read_text(encoding="utf-8"))
            for _f in (_fraw if isinstance(_fraw, list) else []):
                for _cv in re.findall(r'CVE-\d{4}-\d+', _f.get("cves", "") + " " + _f.get("description", "")):
                    if _cv not in _all_cves:
                        _all_cves.append(_cv)
    except Exception:
        pass
    if _all_cves and not getattr(args, "no_sploitus", False):
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 4b: Sploitus ({len(_all_cves)} CVE(s))...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p4b_sploitus", label="Phase 4b: Sploitus", status="running")
        run_sploitus(_all_cves, output_mgr, scope)
        _vc.status(f"{scope}_p4b_sploitus", label="Phase 4b: Sploitus", status="complete")

    # ── Phase 4c: Metasploit module search ───────────────────────────────────
    if _all_cves and not getattr(args, "no_metasploit", False):
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 4c: Metasploit module search "
              f"({len(_all_cves)} CVE(s))...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p4c_metasploit",
                   label="Phase 4c: Metasploit Search", status="running")
        try:
            run_metasploit_search(
                _all_cves, output_mgr,
                msfconsole_path=getattr(args, "msfconsole_path", ""),
                timeout=getattr(args, "msf_timeout", 60),
            )
            _vc.status(f"{scope}_p4c_metasploit",
                       label="Phase 4c: Metasploit Search", status="complete")
        except Exception as _msf_exc:
            print(f"{Fore.RED}[!] Metasploit search error: {_msf_exc}{Style.RESET_ALL}")
            _vc.status(f"{scope}_p4c_metasploit",
                       label="Phase 4c: Metasploit Search", status="error")

    # ── Phase 4d: CVE Correlation — OSV + NVD + CPE matching ────────────────
    if alive_ips and not getattr(args, "no_cve_correlation", False):
        print(
            f"\n{Fore.CYAN}[*] {scope_label} Phase 4d: CVE Correlation "
            f"(software inventory → OSV/NVD)...{Style.RESET_ALL}"
        )
        _vc.status(f"{scope}_p4d_cve", label="Phase 4d: CVE Correlation",
                   status="running")
        try:
            _cve_count = correlate_software_cves(output_mgr, all_results, scope)
            _vc.status(f"{scope}_p4d_cve", label="Phase 4d: CVE Correlation",
                       status="complete",
                       step=f"{_cve_count} CVE match(es)")
            if _cve_count:
                print(
                    f"{Fore.GREEN}[+] {scope_label} CVE correlation: "
                    f"{_cve_count} new finding(s){Style.RESET_ALL}"
                )
            else:
                print(
                    f"{Fore.YELLOW}[~] {scope_label} CVE correlation: "
                    f"no additional matches{Style.RESET_ALL}"
                )
        except Exception as exc:
            print(f"{Fore.RED}[!] CVE correlation error: {exc}{Style.RESET_ALL}")
            _vc.status(f"{scope}_p4d_cve", label="Phase 4d: CVE Correlation",
                       status="error", step=str(exc)[:80])

    # ── Phase 5: Database Attack Suite ───────────────────────────────────────
    _any_db_tool = odat_path or msdat_path or enumdb_path
    _db_ports_present = any(
        p in (_ORACLE_PORTS | _MSSQL_PORTS | _MYSQL_PORTS)
        for _d in all_results.values() for p in _d.get("open_ports", {})
    )
    if _any_db_tool and _db_ports_present and alive_ips:
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 5: Database Attacks (odat/msdat/enumdb)...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p5_db", label="Phase 5: Database Attacks", status="running")
        for _db_ip, _db_data in all_results.items():
            _db_op = _db_data.get("open_ports", {})
            if any(p in (_ORACLE_PORTS | _MSSQL_PORTS | _MYSQL_PORTS) for p in _db_op):
                run_db_attacks(_db_ip, _db_op, output_mgr, hostname=_db_data.get("hostname"),
                               odat_path=odat_path, msdat_path=msdat_path,
                               enumdb_path=enumdb_path, cred_store=cred_store)
        _vc.status(f"{scope}_p5_db", label="Phase 5: Database Attacks", status="complete")

    # ── Phase 6: Hydra Credential Brute Force ────────────────────────────────
    if hydra_path and alive_ips and not getattr(args, "no_brute", False):
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 6: Hydra credential brute force...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p6_brute", label="Phase 6: Hydra Brute Force", status="running")
        _known_users: list[str] = []
        if cred_store:
            for _c in cred_store.get_all():
                if _c.get("username"):
                    _known_users.append(_c["username"])
        for _hyd_ip, _hyd_data in all_results.items():
            _hyd_op = _hyd_data.get("open_ports", {})
            if any(p in _HYDRA_SERVICES for p in _hyd_op):
                run_hydra_brute(_hyd_ip, _hyd_op, output_mgr, hydra_path=hydra_path,
                                hostname=_hyd_data.get("hostname"), cred_store=cred_store,
                                extra_users=_known_users or None,
                                scope_ips=set(targets))
        _vc.status(f"{scope}_p6_brute", label="Phase 6: Hydra Brute Force", status="complete")

    # ── Phase 6b: BruteSpray — default credential spray against nmap XML ─────
    if alive_ips and not getattr(args, "no_brute", False):
        _nmap_xmls = sorted(
            output_mgr.root.rglob("portscan_*.xml"),
            key=lambda p: p.stat().st_mtime, reverse=True,
        )
        if _nmap_xmls:
            print(
                f"\n{Fore.CYAN}[*] {scope_label} Phase 6b: BruteSpray "
                f"(default credential spray)...{Style.RESET_ALL}"
            )
            run_brutespray(
                _nmap_xmls[0], output_mgr, scope=scope, args=args,
                timeout=getattr(args, "brutespray_timeout", 600),
            )
        else:
            _vc.status(f"{scope}_p6b_brutespray", label="Phase 6b: BruteSpray",
                       status="skipped", step="no nmap XML found")

    # ── Phase 12: Active Directory Assessment ────────────────────────────────
    _dcs = _detect_domain_controllers(all_results)
    _domain_hint = getattr(args, "domain", None)
    if scope == "int" and _dcs and not getattr(args, "no_ad", False):
        _dc_ip, _dc_hn = _dcs[0]
        _ad_domain = _domain_hint or (_dc_hn.split(".", 1)[-1] if _dc_hn and "." in _dc_hn else "WORKGROUP")
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 12: AD Assessment "
              f"(domain={_ad_domain}, DC={_dc_ip})...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p12_ad", label="Phase 12: AD Assessment",
                   status="running", step=f"DC={_dc_ip}")
        _ad_creds = cred_store.get_all() if cred_store else []
        _ad_u = _ad_creds[0].get("username") if _ad_creds else None
        _ad_p = _ad_creds[0].get("password") if _ad_creds else None
        print(f"{Fore.CYAN}  [12a] ldapdomaindump{Style.RESET_ALL}")
        run_ldapdomaindump(_dc_ip, output_mgr, domain=_ad_domain,
                           username=_ad_u, password=_ad_p, hostname=_dc_hn)
        if kerbrute_path:
            print(f"{Fore.CYAN}  [12b] Kerbrute userenum{Style.RESET_ALL}")
            run_kerbrute(_dc_ip, _ad_domain, output_mgr, kerbrute_path,
                         hostname=_dc_hn, cred_store=cred_store)
        else:
            print(f"{Fore.YELLOW}  [12b] kerbrute not available{Style.RESET_ALL}")
        if bloodhound_path:
            print(f"{Fore.CYAN}  [12c] BloodHound-Python{Style.RESET_ALL}")
            run_bloodhound_python(_dc_ip, _ad_domain, output_mgr, bloodhound_path,
                                  hostname=_dc_hn, username=_ad_u, password=_ad_p)
        else:
            print(f"{Fore.YELLOW}  [12c] bloodhound-python not available{Style.RESET_ALL}")
        # ── 12d: Kerberoasting (GetUserSPNs) ────────────────────────────
        print(f"{Fore.CYAN}  [12d] Kerberoasting (GetUserSPNs){Style.RESET_ALL}")
        try:
            probe_kerberoast(
                _dc_ip, _ad_domain,
                output_dir=output_mgr.root,
                output_mgr=output_mgr,
                cred_user=_ad_u, cred_pass=_ad_p,
            )
        except Exception as _kerb_exc:
            _tprint(f"  {Fore.RED}[!] Kerberoasting error: {_kerb_exc}{Style.RESET_ALL}")
        _vc.status(f"{scope}_p12_ad", label="Phase 12: AD Assessment", status="complete")
    elif scope == "int":
        print(f"{Fore.YELLOW}[~] Phase 12: No DC detected — AD assessment skipped{Style.RESET_ALL}")
        _vc.status(f"{scope}_p12_ad", label="Phase 12: AD Assessment",
                   status="skipped", step="no DC detected")

    # ── Phase 13: Web Application Deep Attack ────────────────────────────────
    _web_svc_urls: list[str] = []
    for _ws_ip, _ws_data in all_results.items():
        if _ws_ip not in alive_ips:
            continue
        for _ws in _ws_data.get("web_services", []):
            _ws_port   = _ws.get("port", 80)
            _ws_scheme = (_ws.get("scheme")
                          or ("https" if port_is_tls(_ws_port, _ws) else "http"))
            # Always use the original target IP — discovered hostnames (from
            # reverse-DNS or SSL SANs) may belong to out-of-scope domains.
            _web_svc_urls.append(f"{_ws_scheme}://{_ws_ip}:{_ws_port}/")
    _run_p13 = (zap_path or sqlmap_path or xsstrike_path) and alive_ips
    if _run_p13 and not getattr(args, "no_dast", False):
        print(f"\n{Fore.CYAN}[*] {scope_label} Phase 13: Web App Deep Attack "
              f"(ZAP/sqlmap/XSStrike)...{Style.RESET_ALL}")
        _vc.status(f"{scope}_p13_webapp", label="Phase 13: Web App Attack", status="running")
        if zap_path and _web_svc_urls:
            print(f"{Fore.CYAN}  [13a] OWASP ZAP DAST{Style.RESET_ALL}")
            run_zap_dast(_web_svc_urls, output_mgr, zap_path, scope)
        if sqlmap_path:
            print(f"{Fore.CYAN}  [13b] sqlmap SQLi testing{Style.RESET_ALL}")
            run_sqlmap(_collect_param_urls(output_mgr, all_results),
                       output_mgr, sqlmap_path, scope_ips=alive_ips)
        if xsstrike_path and _web_svc_urls:
            print(f"{Fore.CYAN}  [13c] XSStrike XSS testing{Style.RESET_ALL}")
            run_xsstrike(_web_svc_urls, output_mgr, xsstrike_path)
        _vc.status(f"{scope}_p13_webapp", label="Phase 13: Web App Attack", status="complete")
    elif not _run_p13:
        _vc.status(f"{scope}_p13_webapp", label="Phase 13: Web App Attack",
                   status="skipped", step="no tools available")

    # ── Phase 14: O365 Account Enumeration (external scope only) ─────────
    if scope == "ext" and alive_ips:
        _ext_domains = _derive_ext_domains(hostnames, all_results)
        _o365_domains: list = []
        for _ed in sorted(_ext_domains):
            if _detect_o365(_ed):
                _o365_domains.append(_ed)

        if _o365_domains:
            print(f"\n{Fore.CYAN}[*] {scope_label} Phase 14: O365 Account "
                  f"Enumeration ({len(_o365_domains)} domain(s))..."
                  f"{Style.RESET_ALL}")
            _vc.status(f"{scope}_p14_o365", label="Phase 14: O365 Enumeration",
                       status="running")

            for _o365d in _o365_domains:
                _o365_ev_dir = output_mgr.root / "o365"
                _o365_ev_dir.mkdir(parents=True, exist_ok=True)
                _o365_det_file = _o365_ev_dir / f"{_o365d}_detection.txt"
                _o365_det_file.write_text(
                    f"O365 Tenant Detection Evidence\n"
                    f"Domain: {_o365d}\n"
                    f"Method: DNS MX lookup + OpenID endpoint check\n"
                    f"Result: O365 tenant confirmed\n",
                    encoding="utf-8",
                )
                _o365_det_rel = str(_o365_det_file.relative_to(output_mgr.root))
                output_mgr.log_finding(
                    title="Discovery: O365 Tenant Detected",
                    ip="", port=0, hostname=_o365d,
                    risk="INFO",
                    command=f"dig +short MX {_o365d}",
                    description=(
                        f"The domain '{_o365d}' uses Microsoft 365 / Azure AD "
                        f"for email and authentication. MX records point to "
                        f"*.protection.outlook.com or the OpenID configuration "
                        f"endpoint confirms an Azure AD tenant. This enables "
                        f"O365 account enumeration and credential spray attacks."
                    ),
                    output=f"O365 tenant confirmed for {_o365d}",
                    output_file=_o365_det_rel,
                    affected=_o365d,
                    sources="o365-detection",
                    remediation=(
                        "Implement conditional access policies, enforce MFA, "
                        "and configure Azure AD Smart Lockout to mitigate "
                        "enumeration and credential spray attacks."
                    ),
                )

                _o365_emails: list = []
                _email_file_arg = getattr(args, "email_file", None)
                if _email_file_arg and Path(_email_file_arg).exists():
                    _ef_lines = Path(_email_file_arg).read_text(
                        encoding="utf-8").splitlines()
                    _o365_emails = [
                        e.strip() for e in _ef_lines
                        if e.strip() and e.strip().endswith(f"@{_o365d}")
                    ]
                if not _o365_emails:
                    _o365_emails = _find_osift_emails(args.project)
                    _o365_emails = [
                        e for e in _o365_emails
                        if e.endswith(f"@{_o365d}")
                    ]
                if not _o365_emails:
                    _o365_emails = [
                        f"{p}@{_o365d}" for p in _O365_COMMON_PREFIXES
                    ]

                _valid: list = []
                _enum_source = ""
                if o365spray_path:
                    _valid = run_o365_enum(
                        _o365d, _o365_emails, output_mgr, o365spray_path,
                    )
                    _enum_source = "o365spray"
                else:
                    _tprint(
                        f"  {Fore.YELLOW}[~] o365spray not installed — "
                        f"using built-in GetCredentialType enum for "
                        f"{_o365d}{Style.RESET_ALL}")
                    _valid = _o365_enum_builtin(_o365d, _o365_emails)
                    _enum_source = "GetCredentialType API"

                if _valid:
                    _sample = ", ".join(_valid[:10])
                    _extra = (f" (+{len(_valid)-10} more)"
                              if len(_valid) > 10 else "")
                    _enum_cmd = (
                        f"o365spray --enum -d {_o365d}"
                        if _enum_source == "o365spray"
                        else f"POST login.microsoftonline.com"
                             f"/common/GetCredentialType"
                    )
                    _enum_ev_file = _o365_ev_dir / f"{_o365d}_enum_results.txt"
                    _enum_ev_file.write_text(
                        f"O365 Account Enumeration Results\n"
                        f"Domain: {_o365d}\n"
                        f"Source: {_enum_source}\n"
                        f"Valid accounts ({len(_valid)}):\n"
                        + "\n".join(f"  {e}" for e in _valid) + "\n",
                        encoding="utf-8",
                    )
                    _enum_ev_rel = str(_enum_ev_file.relative_to(output_mgr.root))
                    output_mgr.log_finding(
                        title="Enumeration: O365 Account Enumeration",
                        ip="", port=0, hostname=_o365d,
                        risk="MEDIUM",
                        command=_enum_cmd,
                        description=(
                            f"{_enum_source} confirmed {len(_valid)} valid "
                            f"O365 account(s) for {_o365d}. Valid accounts "
                            f"can be targeted with password spray attacks, "
                            f"phishing campaigns, and social engineering. "
                            f"Account enumeration is possible because the "
                            f"Azure AD authentication endpoint returns "
                            f"different responses for valid and invalid "
                            f"accounts."
                        ),
                        output=(
                            f"Valid accounts ({len(_valid)}):\n"
                            f"{_sample}{_extra}"
                        ),
                        output_file=_enum_ev_rel,
                        affected=_o365d,
                        sources=_enum_source,
                        remediation=(
                            "Implement conditional access policies, enforce "
                            "MFA on all accounts, and configure Azure AD "
                            "Smart Lockout. Consider disabling legacy "
                            "authentication protocols that bypass MFA. "
                            "Monitor Azure AD sign-in logs for enumeration "
                            "patterns."
                        ),
                    )
                    _tprint(
                        f"  {Fore.RED}[!] {len(_valid)} valid O365 "
                        f"account(s) confirmed for {_o365d}"
                        f"{Style.RESET_ALL}")
                else:
                    _tprint(
                        f"  {Fore.GREEN}[+] No valid accounts confirmed "
                        f"for {_o365d}{Style.RESET_ALL}")

            _vc.status(f"{scope}_p14_o365", label="Phase 14: O365 Enumeration",
                       status="complete")
        else:
            _vc.status(f"{scope}_p14_o365", label="Phase 14: O365 Enumeration",
                       status="skipped", step="no O365 domains detected")

    # ── Write final output files (AFTER all Nuclei passes are complete) ──────
    # results.json, correlated.json, and the findings summary are written here
    # so they include findings from both the IP-pass and web-URL Nuclei passes.
    scope_results_path = output_mgr.root / "results.json"
    save_json(all_results, str(scope_results_path))

    tool_paths = {
        "nmap":    nmap_path,
        "sslscan": sslscan_path or "sslscan",
        "testssl": testssl_path or "testssl",
    }
    print(f"\n{Fore.CYAN}[*] Building correlated report...{Style.RESET_ALL}",
          end="", flush=True)
    try:
        corr_path = output_mgr.build_correlated_report(all_results, tool_paths)
        print(f"\r{Fore.GREEN}[+] correlated.json written: {corr_path}{Style.RESET_ALL}")
    except Exception as exc:
        print(f"\r{Fore.RED}[!] correlated report failed: {exc}{Style.RESET_ALL}")

    # ── Findings summary (reflects all passes including Nuclei web-URL) ───────
    try:
        n = _count_findings(output_mgr.findings_json)
        if n:
            print(f"\n{Fore.RED}[!] {n} security finding(s) — "
                  f"see {scope}/findings.json and {scope}/findings.csv{Style.RESET_ALL}")
        else:
            print(f"\n{Fore.GREEN}[+] No security findings recorded for {scope.upper()}.{Style.RESET_ALL}")
    except Exception:
        pass

    # ── Sweep findings for manual-testing action items ─────────────────────
    # Catches findings with exploit metadata (exploitdb, metasploit, CVEs
    # with known tools) that weren't already covered by a specific action
    # item emitted inline during the scan.
    try:
        _sweep_findings_for_action_items(output_mgr)
    except Exception as exc:
        print(f"{Fore.YELLOW}  [!] Action item sweep error: {exc}{Style.RESET_ALL}")

    output_mgr.finalize()

    try:
        tgt_path = output_mgr.write_targets_json(all_results)
        if tgt_path:
            print(f"{Fore.GREEN}[+] targets.json written: {tgt_path}{Style.RESET_ALL}")
    except Exception as exc:
        print(f"{Fore.RED}[!] targets.json generation failed: {exc}{Style.RESET_ALL}")

    try:
        xl_path = output_mgr.write_excel()
        if xl_path:
            print(f"{Fore.GREEN}[+] findings.xlsx written: {xl_path}{Style.RESET_ALL}")
    except Exception as exc:
        print(f"{Fore.RED}[!] findings.xlsx generation failed: {exc}{Style.RESET_ALL}")

    try:
        _tu_path = output_mgr.root / "tools_used.json"
        _tools_list = sorted(
            [
                {"name": _n, "version": _v, "queried_at": ""}
                for _n, _v in output_mgr._tool_versions.items()
            ],
            key=lambda x: x["name"].lower(),
        )
        _tu_path.write_text(
            json.dumps(_tools_list, indent=2),
            encoding="utf-8",
        )
        print(f"{Fore.GREEN}[+] tools_used.json written: {_tu_path}{Style.RESET_ALL}")
    except Exception as exc:
        print(f"{Fore.RED}[!] tools_used.json generation failed: {exc}{Style.RESET_ALL}")

    print(f"\n{Fore.CYAN}{'─'*60}{Style.RESET_ALL}")
    print(f"{scope_label} {Fore.CYAN}output files:{Style.RESET_ALL}")
    log_files = [
        ("scan.log",              output_mgr.log_file),
        ("scan.log.json",         output_mgr.json_log_file),
        ("errors.log",            output_mgr.error_log),
        ("findings.json",         output_mgr.findings_json),
        ("findings.csv",          output_mgr.findings_csv),
        ("software_inventory.json", output_mgr.software_inventory),
        ("web_ports.txt",         web_ports_path  or output_mgr.root / "web_ports.txt"),
        ("web_targets.txt",       web_targets_path or output_mgr.root / "web_targets.txt"),
        ("correlated.json",       output_mgr.root / "correlated.json"),
        ("targets.json",          output_mgr.root / "targets.json"),
        ("findings.xlsx",         output_mgr.root / "findings.xlsx"),
        ("results.json",          scope_results_path),
    ]
    for fname, fpath in log_files:
        print(f"    {Fore.WHITE}{fname:<18}{Style.RESET_ALL} "
              f"{Fore.YELLOW}{_fsize(fpath):>8}{Style.RESET_ALL}")

    print()
    for _out_subdir in ["hosts", "tools"]:
        _top = output_mgr.root / _out_subdir
        if not _top.exists():
            continue
        _all_files = [f for f in _top.rglob("*") if f.is_file()]
        if _all_files:
            total    = sum(f.stat().st_size for f in _all_files)
            size_str = f"{total/1024:.1f} KB" if total >= 1024 else f"{total} B"
            print(f"    {Fore.CYAN}{scope}/{_out_subdir}/{Style.RESET_ALL}  "
                  f"{Fore.YELLOW}{len(_all_files)} file(s), {size_str}{Style.RESET_ALL}")

    return all_results


def resolve_target_sources(args: argparse.Namespace) -> list[str]:
    """
    Collect, deduplicate, and confirm all target specs before scanning begins.

    There are up to four independent sources of targets:

        1. CLI positional args          (args.targets)
        2. --targets-file FILE          (args.targets_file)
        3. settings scan.targets array  (args._settings_targets)
        4. settings scan.target_file    (args._settings_target_file)

    When only one source is populated the targets are returned immediately with
    no user interaction.  When two or more sources are non-empty the operator is
    warned, asked whether to combine them, shown the deduplicated list for a
    final confirmation, and the process exits if they decline at either prompt.

    Deduplication is performed on the raw spec strings (CIDRs / ranges / single
    IPs) with case-insensitive comparison and whitespace normalisation.  The
    order is deterministic: sources are processed in the priority order above,
    and within each source the original ordering is preserved.  Exact-duplicate
    specs are silently dropped; semantically overlapping specs (e.g. a CIDR that
    contains an individual IP that appears in another source) are kept — the
    operator can review them in the confirmation prompt.

    Returns
    -------
    list[str]
        The resolved, deduplicated list of raw target specs, ready to pass to
        expand_targets().  Guaranteed non-empty (function exits on empty result
        or user refusal).
    """
    # ── Step 1: load each source independently ───────────────────────────────

    sources: list[tuple[str, list[str]]] = []   # (label, [raw_spec, ...])

    # Source A — CLI positional targets
    cli_positional = [t for t in (args.targets or []) if t.strip()]
    if cli_positional:
        sources.append(("CLI positional args", cli_positional))

    # Source B — --targets-file
    if args.targets_file:
        tf_path = Path(args.targets_file)
        if not tf_path.exists():
            print(f"{Fore.RED}[!] --targets-file not found: {args.targets_file}{Style.RESET_ALL}")
            sys.exit(1)
        try:
            b_targets = load_targets_from_file(str(tf_path))
        except OSError as exc:
            print(f"{Fore.RED}[!] Cannot read --targets-file: {exc}{Style.RESET_ALL}")
            sys.exit(1)
        if b_targets:
            sources.append((f"--targets-file ({args.targets_file})", b_targets))

    # Source C — settings scan.targets array
    settings_inline = getattr(args, "_settings_targets", [])
    if settings_inline:
        sources.append(("settings scan.targets", list(settings_inline)))

    # Source D — settings scan.target_file
    settings_tf = getattr(args, "_settings_target_file", "")
    if settings_tf:
        stf_path = Path(settings_tf)
        if not stf_path.exists():
            print(
                f"{Fore.RED}[!] settings scan.target_file not found: {settings_tf}{Style.RESET_ALL}"
            )
            sys.exit(1)
        try:
            d_targets = load_targets_from_file(str(stf_path))
        except OSError as exc:
            print(f"{Fore.RED}[!] Cannot read settings target_file: {exc}{Style.RESET_ALL}")
            sys.exit(1)
        if d_targets:
            sources.append((f"settings target_file ({settings_tf})", d_targets))

    if not sources:
        print(f"{Fore.RED}[!] No targets found in any source. Exiting.{Style.RESET_ALL}")
        sys.exit(1)

    # ── Step 2: single source — no interaction needed ────────────────────────
    if len(sources) == 1:
        label, specs = sources[0]
        print(f"{Fore.CYAN}[*] Targets loaded from {label}: "
              f"{len(specs)} spec(s){Style.RESET_ALL}")
        return specs

    # ── Step 3: multiple sources — warn and prompt ───────────────────────────
    cols, _ = _term_size()
    divider  = f"{Fore.YELLOW}{'─' * min(cols, 72)}{Style.RESET_ALL}"

    print(f"\n{divider}")
    print(f"{Fore.YELLOW}[!] Multiple target sources are active:{Style.RESET_ALL}")
    total_raw = 0
    for label, specs in sources:
        print(f"    {Fore.WHITE}• {label}{Style.RESET_ALL}  "
              f"({Fore.CYAN}{len(specs)} spec(s){Style.RESET_ALL})")
        total_raw += len(specs)
    print(divider)

    try:
        answer = input(
            f"\n{Fore.YELLOW}Combine all {total_raw} entries into one target list? [y/N]: "
            f"{Style.RESET_ALL}"
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        answer = "n"

    if answer not in ("y", "yes"):
        print(f"{Fore.YELLOW}[~] Scan cancelled — please specify a single target source "
              f"or re-run and confirm the merge.{Style.RESET_ALL}")
        sys.exit(0)

    # ── Step 4: deduplicate (preserving order, case-insensitive) ─────────────
    seen:    set[str]  = set()
    merged:  list[str] = []
    dupes:   int       = 0

    for _label, specs in sources:
        for spec in specs:
            key = spec.strip().lower()
            if key not in seen:
                seen.add(key)
                merged.append(spec.strip())
            else:
                dupes += 1

    # ── Step 5: display merged list + final confirmation ─────────────────────
    print(f"\n{divider}")
    if dupes:
        print(f"{Fore.CYAN}[*] {dupes} duplicate spec(s) removed.{Style.RESET_ALL}")
    print(f"{Fore.CYAN}[*] Combined target list ({len(merged)} unique spec(s)):{Style.RESET_ALL}\n")

    # Annotate each line with its origin for transparency
    spec_origin: dict[str, str] = {}
    for label, specs in sources:
        for spec in specs:
            key = spec.strip().lower()
            if key not in spec_origin:
                spec_origin[key] = label

    # Print in columns: index, spec, source label — truncated to terminal width
    idx_w   = len(str(len(merged)))
    spec_w  = max((len(s) for s in merged), default=20)
    spec_w  = min(spec_w, 40)   # cap so source label always fits
    for i, spec in enumerate(merged, 1):
        origin = spec_origin.get(spec.strip().lower(), "")
        line   = (f"  {Fore.CYAN}{i:>{idx_w}}.{Style.RESET_ALL} "
                  f"{Fore.WHITE}{spec:<{spec_w}}{Style.RESET_ALL}  "
                  f"{Fore.YELLOW}[{origin}]{Style.RESET_ALL}")
        # Hard-truncate to terminal width to avoid wrapping noise
        print(line[:cols + 80])   # +80 accounts for non-printing ANSI bytes

    print(f"\n{divider}")

    try:
        confirm = input(
            f"\n{Fore.CYAN}Proceed with these {len(merged)} target spec(s)? [y/N]: "
            f"{Style.RESET_ALL}"
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        confirm = "n"

    if confirm not in ("y", "yes"):
        print(f"{Fore.YELLOW}[~] Scan cancelled at final confirmation.{Style.RESET_ALL}")
        sys.exit(0)

    print()
    return merged


# ── Passive Seed — concurrent tcpdump → Trawler analysis ─────────────────────
# Runs a short tcpdump capture concurrently with Phase 1 discovery.  After
# capture completes, hands the pcap to Trawler in hunt mode (with the testing
# server excluded via --ignore).  Discovered hosts and services supplement the
# scan queue: any IP found by Trawler that is not already in the target list
# gets added as a supplemental target.

_PASSIVE_SEED_LOCK = threading.Lock()
_passive_seed_results: dict = {}


def _passive_seed_thread(
    duration: int,
    iface: str,
    server_ip: str,
    project_dir: "Path",
    trawler_path: "str | None",
):
    global _passive_seed_results
    seed_dir = project_dir / "passive_seed"
    seed_dir.mkdir(parents=True, exist_ok=True)
    pcap_path = seed_dir / "passive_seed.pcap"
    ts_start = datetime.now().strftime("%Y-%m-%dT%H:%M:%S")

    tcpdump_path = shutil.which("tcpdump")
    if not tcpdump_path:
        _vc.log("[passive-seed] tcpdump not found — skipping", "WARN")
        return

    if not trawler_path:
        _vc.log("[passive-seed] Trawler not found — skipping", "WARN")
        return

    _vc.log(f"[passive-seed] starting {duration}s capture on {iface} "
            f"(excluding {server_ip})")
    _vc.status("passive_seed", label="Passive Seed",
               status="running", step=f"tcpdump {duration}s on {iface}")

    cmd = [
        tcpdump_path, "-i", iface, "-w", str(pcap_path),
        "-c", "0",
        "not", "host", server_ip,
    ]
    try:
        proc = subprocess.Popen(
            cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
        )
        proc.wait(timeout=duration)
    except subprocess.TimeoutExpired:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait()
    except Exception as exc:
        _vc.log(f"[passive-seed] tcpdump failed: {exc}", "ERROR")
        _vc.status("passive_seed", label="Passive Seed", status="error",
                   step=str(exc))
        return

    if not pcap_path.exists() or pcap_path.stat().st_size == 0:
        _vc.log("[passive-seed] capture empty — skipping analysis", "WARN")
        _vc.status("passive_seed", label="Passive Seed", status="complete",
                   step="no packets captured")
        return

    _vc.log(f"[passive-seed] capture complete — "
            f"{pcap_path.stat().st_size:,} bytes")
    _vc.status("passive_seed", label="Passive Seed",
               status="running", step="Trawler analysis")

    trawler_out = seed_dir / "trawler"
    trawler_out.mkdir(parents=True, exist_ok=True)
    trawler_cmd = [
        sys.executable, trawler_path,
        "--pcap", str(pcap_path),
        "--hunt",
        "--ignore", server_ip,
        "--output-dir", str(trawler_out),
        "--client", "passive_seed",
    ]
    try:
        result = subprocess.run(
            trawler_cmd, capture_output=True, text=True, timeout=300,
        )
        if result.returncode != 0:
            _vc.log(f"[passive-seed] Trawler exited {result.returncode}: "
                    f"{result.stderr[:500]}", "WARN")
    except subprocess.TimeoutExpired:
        _vc.log("[passive-seed] Trawler timed out", "WARN")
    except Exception as exc:
        _vc.log(f"[passive-seed] Trawler failed: {exc}", "ERROR")
        _vc.status("passive_seed", label="Passive Seed", status="error",
                   step=str(exc))
        return

    discovered_ips: list[str] = []
    discovered_services: dict[str, list[str]] = {}
    findings_path = trawler_out / "findings.json"
    targets_path = trawler_out / "targets.json"
    traffic_path = trawler_out / "traffic.json"

    if targets_path.exists():
        try:
            targets = json.loads(targets_path.read_text(encoding="utf-8"))
            for t in targets:
                ip = t.get("ip", "")
                if ip and ip != server_ip:
                    discovered_ips.append(ip)
        except Exception:
            pass

    if traffic_path.exists():
        try:
            traffic = json.loads(traffic_path.read_text(encoding="utf-8"))
            for ip, data in traffic.items():
                if ip == server_ip:
                    continue
                services = []
                for peer_list_key in ("external_peers", "internal_peers"):
                    for peer in data.get(peer_list_key, []):
                        for p in peer.get("tcp_ports", []):
                            services.append(f"tcp/{p}")
                        for p in peer.get("udp_ports", []):
                            services.append(f"udp/{p}")
                if services:
                    discovered_services[ip] = list(set(services))
        except Exception:
            pass

    finding_count = 0
    if findings_path.exists():
        try:
            findings = json.loads(findings_path.read_text(encoding="utf-8"))
            finding_count = len(findings)
        except Exception:
            pass

    with _PASSIVE_SEED_LOCK:
        _passive_seed_results = {
            "discovered_ips": discovered_ips,
            "discovered_services": discovered_services,
            "finding_count": finding_count,
            "pcap_path": str(pcap_path),
            "trawler_output": str(trawler_out),
        }

    n_ips = len(discovered_ips)
    n_svc = sum(len(v) for v in discovered_services.values())
    _vc.log(f"[passive-seed] complete — {n_ips} IPs, {n_svc} services, "
            f"{finding_count} findings")
    _vc.status("passive_seed", label="Passive Seed", status="complete",
               step=f"{n_ips} IPs · {n_svc} services · {finding_count} findings")


def _get_passive_seed_supplemental_ips(existing_ips: "set[str]") -> list[str]:
    with _PASSIVE_SEED_LOCK:
        results = _passive_seed_results
    if not results:
        return []
    return [ip for ip in results.get("discovered_ips", [])
            if ip not in existing_ips]


def main():
    args = parse_args()
    print_banner()

    # ── Engagement context (shown when a settings file was loaded) ────────────
    eng = getattr(args, "engagement", {})
    if eng:
        cols, _ = _term_size()
        divider  = f"{Fore.CYAN}{'─' * min(cols, 72)}{Style.RESET_ALL}"
        print(divider)
        print(f"{Fore.CYAN}  Engagement{Style.RESET_ALL}")
        if eng.get("client_name"):
            label = eng.get("client_short", "")
            label_str = f"  [{label}]" if label else ""
            print(f"  {Fore.WHITE}Client     :{Style.RESET_ALL} "
                  f"{eng['client_name']}{Fore.CYAN}{label_str}{Style.RESET_ALL}")
        if eng.get("client_POC") or eng.get("client_email"):
            poc   = eng.get("client_POC", "")
            email = eng.get("client_email", "")
            poc_str = poc + (f"  <{email}>" if email else "")
            print(f"  {Fore.WHITE}Client POC :{Style.RESET_ALL} {poc_str}")
        if eng.get("consultant") or eng.get("consultant_email"):
            con   = eng.get("consultant", "")
            email = eng.get("consultant_email", "")
            con_str = con + (f"  <{email}>" if email else "")
            print(f"  {Fore.WHITE}Consultant :{Style.RESET_ALL} {con_str}")
        if eng.get("start_date") or eng.get("end_date"):
            d1 = eng.get("start_date", "?")
            d2 = eng.get("end_date",   "?")
            print(f"  {Fore.WHITE}Period     :{Style.RESET_ALL} {d1}  →  {d2}")
        if args.settings_file:
            print(f"  {Fore.WHITE}Settings   :{Style.RESET_ALL} "
                  f"{Fore.YELLOW}{args.settings_file}{Style.RESET_ALL}")
        print(divider)
        print()

    # ── Privilege check ───────────────────────────────────────────────────────
    check_privileges()

    # ── Vantage ProgressManager ────────────────────────────────────────────
    global _pm, _pause, _CRASH_PROJECT_ROOT
    _early_proj_root = Path(args.project).resolve()
    _early_proj_root.mkdir(parents=True, exist_ok=True)
    _CRASH_PROJECT_ROOT = _early_proj_root
    try:
        signal.signal(signal.SIGTERM, _handle_sigterm)
    except OSError:
        pass
    _pm = ProgressManager(_early_proj_root / "checkpoint.json")
    if _pm.get_state().get("completed_phases"):
        OutputManager._resume_mode = True
        _vc.log(
            f"Checkpoint found — {len(_pm.get_state()['completed_phases'])} "
            f"phase(s) already complete: {_pm.get_state()['completed_phases']}",
            "INFO",
        )

    if _pp is not None:
        _pause = _pp.PauseManager(_early_proj_root, "scattershot3")
        _pause.start_watcher(
            checkpoint_callback=lambda: _pm.save_runtime_state({"paused": True}),
            grace_period=30,
        )
        _pause.log_run_type(bool(_pm.get_state().get("completed_phases")))

    # ── Tool discovery (done once, shared across both scope passes) ───
    _vc.status("init_tools", label="INIT: Tool Discovery", status="running",
               step="Checking nmap")
    _pm.set_phase_status("init_tools", "running", label="INIT: Tool Discovery")
    nmap_path = check_nmap()
    print(f"{Fore.CYAN}[*] nmap: {nmap_path}{Style.RESET_ALL}")

    # ── Vulners NSE script ─────────────────────────────────────────────
    vulners_available = check_vulners_nse()
    if vulners_available:
        print(f"{Fore.CYAN}[*] Vulners NSE script: available{Style.RESET_ALL}")
    else:
        print(f"{Fore.YELLOW}[~] Vulners NSE script: not available (vulners script will be skipped){Style.RESET_ALL}")

    sslscan_path = testssl_path = None
    if not args.no_ssl:
        print(f"{Fore.CYAN}[*] Checking SSL/TLS tools...{Style.RESET_ALL}")
        sslscan_path = check_ssl_tool("sslscan")
        testssl_path = check_ssl_tool("testssl")
        if sslscan_path:
            print(f"{Fore.CYAN}[*] sslscan : {sslscan_path}{Style.RESET_ALL}")
        else:
            print(f"{Fore.YELLOW}[~] sslscan : not found (skipping){Style.RESET_ALL}")
        if testssl_path:
            print(f"{Fore.CYAN}[*] testssl : {testssl_path}{Style.RESET_ALL}")
        else:
            print(f"{Fore.YELLOW}[~] testssl : not found (skipping){Style.RESET_ALL}")
        if not sslscan_path and not testssl_path:
            print(f"{Fore.YELLOW}[~] No SSL tools available — SSL/TLS analysis skipped.{Style.RESET_ALL}")
    else:
        print(f"{Fore.YELLOW}[~] SSL/TLS scanning disabled (--no-ssl){Style.RESET_ALL}")

    # ── Nuclei ────────────────────────────────────────────────────────
    nuclei_path = None
    if not getattr(args, "no_nuclei", False):
        nuclei_path = check_nuclei()
        if nuclei_path:
            print(f"{Fore.CYAN}[*] Nuclei : {nuclei_path}{Style.RESET_ALL}")
        else:
            print(f"{Fore.YELLOW}[~] Nuclei : not available (skipping){Style.RESET_ALL}")
    else:
        print(f"{Fore.YELLOW}[~] Nuclei scanning disabled (--no-nuclei){Style.RESET_ALL}")

    # ── Enumeration tools ─────────────────────────────────────────────
    print(f"{Fore.CYAN}[*] Checking enumeration tools...{Style.RESET_ALL}")
    snmpwalk_path: "str | None" = None
    smbmap_path:   "str | None" = None
    enum4linux_path: "str | None" = None
    adenum_path:   "str | None" = None

    # ── Hostname resolution tools ─────────────────────────────────────
    nbtscan_path:        "str | None" = None
    nmblookup_path:      "str | None" = None
    avahi_resolve_path:  "str | None" = None
    if not getattr(args, "no_hostname_scan", False):
        print(f"{Fore.CYAN}[*] Checking hostname resolution tools...{Style.RESET_ALL}")
        nbtscan_path = check_tool_generic(
            "nbtscan", find_nbtscan,
            "sudo apt install nbtscan  |  brew install nbtscan  |  choco install nbtscan",
        )
        nmblookup_path = check_tool_generic(
            "nmblookup", find_nmblookup,
            "sudo apt install samba-common-bin  |  brew install samba",
        )
        if platform.system() in ("Linux", "Darwin"):
            avahi_resolve_path = check_tool_generic(
                "avahi-resolve", find_avahi_resolve,
                "sudo apt install avahi-utils  |  brew install avahi",
            )
    else:
        print(f"{Fore.YELLOW}[~] Hostname scanning disabled (--no-hostname-scan){Style.RESET_ALL}")

    if not getattr(args, "no_snmp", False):
        snmpwalk_path = check_tool_generic(
            "snmpwalk", find_snmpwalk,
            "sudo apt install snmp  (Debian/Ubuntu)  |  brew install net-snmp",
        )
    else:
        print(f"{Fore.YELLOW}[~] SNMP scanning disabled (--no-snmp){Style.RESET_ALL}")

    if not getattr(args, "no_enum", False):
        smbmap_path = check_tool_generic(
            "smbmap", find_smbmap,
            "pip install smbmap  |  sudo apt install smbmap",
        )
        enum4linux_path = check_tool_generic(
            "enum4linux", find_enum4linux,
            "sudo apt install enum4linux  |  https://github.com/CiscoCXSecurity/enum4linux",
        )
        adenum_path = check_tool_generic(
            "ADenum", find_adenum,
            "git clone https://github.com/SecuProject/ADenum.git /opt/ADenum",
        )
        print(
            f"{Fore.CYAN}[*] Credentials    : discovered automatically via "
            f"Responder and web-source extraction{Style.RESET_ALL}"
        )
    else:
        print(f"{Fore.YELLOW}[~] Enumeration checks disabled (--no-enum){Style.RESET_ALL}")

    # ── Responder (Linux / internal-scope only) ───────────────────────
    responder_path: "str | None" = None
    if not getattr(args, "no_responder", False):
        responder_path = check_tool_generic(
            "responder", find_responder,
            "sudo apt install responder  |  "
            "git clone https://github.com/lgandx/Responder /opt/Responder",
        )
    else:
        print(f"{Fore.YELLOW}[~] Responder disabled (--no-responder){Style.RESET_ALL}")

    # ── Web analysis tools ────────────────────────────────────────────
    print(f"{Fore.CYAN}[*] Checking web analysis tools...{Style.RESET_ALL}")
    shcheck_path: "str | None" = None
    gobuster_path: "str | None" = None
    webanalyze_path: "str | None" = None
    wpscan_path: "str | None" = None
    searchsploit_path: "str | None" = None
    wpscan_token: "str | None" = getattr(args, "wpscan_token", None)

    if not getattr(args, "no_web", False):
        if not getattr(args, "no_shcheck", False):
            shcheck_path = check_tool_generic(
                "shcheck", find_shcheck,
                "git clone https://github.com/santoru/shcheck.git /opt/shcheck",
            )
        else:
            print(f"{Fore.YELLOW}[~] shcheck disabled (--no-shcheck){Style.RESET_ALL}")

        if not getattr(args, "no_gobuster", False):
            gobuster_path = check_tool_generic(
                "gobuster", find_gobuster,
                "sudo apt install gobuster  |  go install github.com/OJ/gobuster/v3@latest",
            )
            if gobuster_path and not _find_gobuster_wordlist():
                _ensure_gobuster_wordlist()
        else:
            print(f"{Fore.YELLOW}[~] GoBuster disabled (--no-gobuster){Style.RESET_ALL}")

        if not getattr(args, "no_webanalyze", False):
            webanalyze_path = check_tool_generic(
                "webanalyze", find_webanalyze,
                "go install github.com/rverton/webanalyze/cmd/webanalyze@latest",
            )
        else:
            print(f"{Fore.YELLOW}[~] webanalyze disabled (--no-webanalyze){Style.RESET_ALL}")

        if not getattr(args, "no_wpscan", False):
            wpscan_path = check_tool_generic(
                "wpscan", find_wpscan,
                "sudo apt install wpscan  |  gem install wpscan",
            )
            if wpscan_path and not wpscan_token:
                print(
                    f"{Fore.YELLOW}[~] wpscan: no API token set — "
                    f"vulnerability data limited. Use --wpscan-token TOKEN{Style.RESET_ALL}"
                )
        else:
            print(f"{Fore.YELLOW}[~] WPScan disabled (--no-wpscan){Style.RESET_ALL}")
    else:
        print(f"{Fore.YELLOW}[~] Web tools (shcheck/gobuster/webanalyze/wpscan) "
              f"skipped — web scanning disabled (--no-web){Style.RESET_ALL}")

    if not getattr(args, "no_searchsploit", False):
        searchsploit_path = check_tool_generic(
            "searchsploit", find_searchsploit,
            "sudo apt install exploitdb  |  brew install exploitdb",
        )
    else:
        print(f"{Fore.YELLOW}[~] searchsploit disabled (--no-searchsploit){Style.RESET_ALL}")

    # ── New phase tools (Phase 5-13) ──────────────────────────────────
    rustscan_path: "str | None" = None
    if not getattr(args, "no_rustscan", False):
        rustscan_path = check_tool_generic(
            "rustscan", lambda: _find_cargo_binary("rustscan"),
            "sudo apt install rustscan  |  cargo install rustscan",
        )

    kerbrute_path:   "str | None" = None
    bloodhound_path: "str | None" = None
    if not getattr(args, "no_ad", False):
        kerbrute_path = check_tool_generic(
            "kerbrute", lambda: _find_go_binary("kerbrute"),
            "sudo apt install kerbrute  |  go install github.com/ropnop/kerbrute@latest",
        )
        bloodhound_path = check_tool_generic(
            "bloodhound-python",
            lambda: shutil.which("bloodhound-python"),
            "pip install --break-system-packages bloodhound",
        )

    hydra_path: "str | None" = None
    if not getattr(args, "no_brute", False):
        hydra_path = check_tool_generic(
            "hydra", lambda: shutil.which("hydra"),
            "sudo apt install hydra  |  brew install hydra",
        )

    sqlmap_path:   "str | None" = None
    xsstrike_path: "str | None" = None
    zap_path:      "str | None" = None
    if not getattr(args, "no_dast", False) and not getattr(args, "no_web", False):
        sqlmap_path = check_tool_generic(
            "sqlmap", lambda: shutil.which("sqlmap"),
            "sudo apt install sqlmap  |  pip install sqlmap",
        )
        xsstrike_path = check_tool_generic(
            "xsstrike",
            lambda: next((p for p in [
                shutil.which("xsstrike"),
                "/opt/XSStrike/xsstrike.py",
                "/usr/local/share/XSStrike/xsstrike.py",
                "C:/tools/XSStrike/xsstrike.py",
            ] if p and os.path.exists(p)), None),
            "git clone https://github.com/s0md3v/XSStrike /opt/XSStrike"
            "  &&  pip install requests bs4 fuzzywuzzy",
        )
        zap_path = check_tool_generic(
            "zaproxy",
            lambda: next((p for p in [
                shutil.which("zaproxy"),
                shutil.which("zap.sh"),
                "/usr/share/zaproxy/zap.sh",
                "/opt/zaproxy/zap.sh",
            ] if p and os.path.exists(p)), None),
            "sudo apt install zaproxy  |  brew install --cask owasp-zap"
            "  |  snap install zaproxy --classic",
        )

    o365spray_path: "str | None" = check_tool_generic(
        "o365spray", lambda: shutil.which("o365spray"),
        "pip install o365spray",
    )

    odat_path:   "str | None" = check_tool_generic(
        "odat", find_odat,
        "git clone https://github.com/quentinhardy/odat /opt/odat  &&  pip install impacket colorlog",
    )
    msdat_path:  "str | None" = check_tool_generic(
        "msdat", find_msdat,
        "git clone https://github.com/quentinhardy/msdat /opt/msdat  &&  pip install impacket",
    )
    enumdb_path: "str | None" = check_tool_generic(
        "enumdb", lambda: shutil.which("enumdb"),
        "pip install enumdb",
    )

    # ── Gap-analysis tools: showmount + ipmitool ─────────────────────
    showmount_path: "str | None" = None
    ipmitool_path:  "str | None" = None
    if not getattr(args, "no_enum", False):
        showmount_path = check_tool_generic(
            "showmount", find_showmount,
            "sudo apt install nfs-common  |  sudo dnf install nfs-utils",
        )
        ipmitool_path = check_tool_generic(
            "ipmitool", find_ipmitool,
            "sudo apt install ipmitool  |  brew install ipmitool",
        )

    # ── Target collection ─────────────────────────────────────────────
    # resolve_target_sources() handles all four possible target inputs:
    #   (a) CLI positional args  (b) --targets-file  (c) settings scan.targets
    #   (d) settings scan.target_file
    # When multiple sources are non-empty it warns the operator, asks for
    # confirmation, deduplicates, and presents the final list for review.
    # Also handles the legacy path of positional args that name existing files.
    raw_specs = resolve_target_sources(args)

    # Legacy compatibility: if any resolved spec is itself an existing file,
    # expand it (e.g. user passed a file path as a positional arg before
    # --targets-file existed).
    resolved: list[str] = []
    for t in raw_specs:
        p = Path(t)
        if p.exists() and p.is_file():
            print(f"{Fore.CYAN}[*] Expanding file reference in targets: {t}{Style.RESET_ALL}")
            resolved.extend(load_targets_from_file(str(p)))
        else:
            resolved.append(t)

    # Resolve any URL/FQDN targets to IPs (substitutes in-place)
    resolved = _resolve_url_fqdn_targets(resolved)

    # ── Count and conditionally expand targets ──────────────────────────
    _target_count = count_targets(resolved)
    if _target_count == 0:
        print(f"{Fore.RED}[!] No valid targets after expansion. Exiting.{Style.RESET_ALL}")
        sys.exit(1)

    _lazy_targets = _target_count > _LAZY_EXPAND_THRESHOLD

    if _lazy_targets:
        print(f"{Fore.CYAN}[*] Large target space ({_target_count:,} IPs) — "
              f"passing CIDRs directly to nmap (no pre-expansion){Style.RESET_ALL}")
        all_ips = []
    else:
        all_ips = expand_targets(resolved)
        if not all_ips:
            print(f"{Fore.RED}[!] No valid targets after expansion. Exiting.{Style.RESET_ALL}")
            sys.exit(1)

    # ── Project-level exclusions (--exclude / scan.exclude) ──────────
    _excl_specs = getattr(args, "exclude", []) or []
    _project_exclude_addrs: set = set()
    _project_exclude_nets: list = []
    if _excl_specs:
        for _es in _excl_specs:
            _es = _es.strip()
            if not _es:
                continue
            try:
                _net = ipaddress.ip_network(_es, strict=False)
                if _net.prefixlen == _net.max_prefixlen:
                    _project_exclude_addrs.add(str(_net.network_address))
                else:
                    _project_exclude_nets.append(_net)
            except ValueError:
                pass
        if _project_exclude_addrs or _project_exclude_nets:
            _n_rules = len(_project_exclude_addrs) + len(_project_exclude_nets)
            print(f"\n{Fore.YELLOW}[~] Applying {_n_rules} exclusion rule(s){Style.RESET_ALL}")
            for _es in _excl_specs:
                if _es.strip():
                    print(f"    {Fore.YELLOW}✗ {_es.strip()}{Style.RESET_ALL}")
        if not _lazy_targets and (_project_exclude_addrs or _project_exclude_nets):
            def _proj_excluded(ip_str):
                if ip_str in _project_exclude_addrs:
                    return True
                try:
                    _addr = ipaddress.ip_address(ip_str)
                    return any(_addr in _net for _net in _project_exclude_nets)
                except ValueError:
                    return False
            _before = len(all_ips)
            all_ips = [ip for ip in all_ips if not _proj_excluded(ip)]
            _removed = _before - len(all_ips)
            if _removed:
                print(f"    {Fore.YELLOW}Removed {_removed:,} IP(s) from target list{Style.RESET_ALL}")
            if not all_ips:
                print(f"{Fore.RED}[!] All targets excluded. Exiting.{Style.RESET_ALL}")
                sys.exit(1)
            _target_count = len(all_ips)

    # ── Remove originating-host IPs — never scan ourselves ────────────
    local_ips = _get_local_ips()
    _local_in_scope: set = set()
    if local_ips:
        if _lazy_targets:
            _local_in_scope = {lip for lip in local_ips
                               if any(_ip_in_spec(lip, s) for s in resolved)}
            if _local_in_scope:
                print(f"{Fore.YELLOW}[~] Local IP(s) in target scope (will be "
                      f"excluded from alive results): "
                      f"{', '.join(sorted(_local_in_scope))}{Style.RESET_ALL}")
        else:
            excluded = [ip for ip in all_ips if ip in local_ips]
            if excluded:
                print(f"{Fore.YELLOW}[~] Excluding {len(excluded)} local interface IP(s) from scope: "
                      f"{', '.join(sorted(excluded))}{Style.RESET_ALL}")
            all_ips = [ip for ip in all_ips if ip not in local_ips]
    if not _lazy_targets and not all_ips:
        print(f"{Fore.RED}[!] No valid targets remain after excluding local IPs. Exiting.{Style.RESET_ALL}")
        sys.exit(1)

    # Merge project-level exclusion single-IPs into _local_in_scope so
    # they are forwarded to scan_scope's exclude_ips for lazy-mode filtering.
    _local_in_scope |= _project_exclude_addrs

    # ── Preserve raw specs per scope for compact nmap discovery calls ──
    raw_scopes    = partition_raw_targets(resolved)
    raw_internal  = raw_scopes.get("int", [])
    raw_external  = raw_scopes.get("ext", [])

    # ── Classify into internal / external ─────────────────────────────
    if _lazy_targets:
        internal_ips = []
        external_ips = []
        _int_count = count_targets(raw_internal)
        _ext_count = count_targets(raw_external)
    else:
        scopes = partition_targets(all_ips)
        internal_ips = scopes.get("int", [])
        external_ips = scopes.get("ext", [])
        _int_count = len(internal_ips)
        _ext_count = len(external_ips)

    # Print target breakdown before scanning starts
    print(f"\n{Fore.CYAN}[*] Mode   : {'Fast (top-1000)' if args.fast else 'Full (all 65535 ports)'}{Style.RESET_ALL}")
    print(f"{Fore.CYAN}[*] Started: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}{Style.RESET_ALL}")
    print(f"\n{Fore.CYAN}[*] Target breakdown:{Style.RESET_ALL}")
    print(f"    {Fore.GREEN}[INT]{Style.RESET_ALL}  {_int_count:>8,} target(s)  "
          f"(RFC-1918 / private address space)")
    print(f"    {Fore.YELLOW}[EXT]{Style.RESET_ALL}  {_ext_count:>8,} target(s)  "
          f"(publicly routable)")
    print(f"    {'─'*50}")
    print(f"    {'Total':>10}  {_target_count:>8,} target(s)  "
          f"(after deduplication + expansion)")

    if not args.no_web:
        print(f"{Fore.CYAN}[*] HTTP probing   : enabled (timeout={args.web_timeout}s){Style.RESET_ALL}")
    if not args.no_banner:
        print(f"{Fore.CYAN}[*] Banner grabbing: enabled (timeout={args.banner_timeout}s){Style.RESET_ALL}")
    if not args.no_web and not getattr(args, "no_screenshots", False):
        if check_selenium_ready():
            print(f"{Fore.CYAN}[*] Screenshots    : enabled (Selenium / Chrome){Style.RESET_ALL}")
        else:
            print(f"{Fore.YELLOW}[~] Screenshots    : disabled (Selenium not available){Style.RESET_ALL}")
    elif getattr(args, "no_screenshots", False):
        print(f"{Fore.YELLOW}[~] Screenshots    : disabled (--no-screenshots){Style.RESET_ALL}")

    # ── Internal route setup (Linux only) ─────────────────────────────
    # Add kernel routes for internal subnets before scanning begins so
    # that nmap and other tools reach the correct network interface.
    # Runs only when there are internal targets and --no-route-setup is
    # not set.  Silently skips on non-Linux platforms and when not root.
    #
    # If setup is attempted and every candidate (interface, gateway)
    # fails reachability validation, scan execution is aborted — there
    # is no point scanning targets that cannot be reached.
    route_setup_result: dict = {}
    if (internal_ips or (_lazy_targets and raw_internal)) and not getattr(args, "no_route_setup", False):
        dry = getattr(args, "dry_run_routes", False)
        route_setup_result = setup_internal_routes(
            raw_internal,
            dry_run=dry,
            gateway_hint=getattr(args, "route_gateway", None),
            interface_hint=getattr(args, "route_interface", None),
            validation_threshold=getattr(
                args, "route_validation_threshold", 0.33),
            validation_probe_timeout=getattr(
                args, "route_validation_timeout", 2),
        )
        # Abort if route setup was attempted (added something or tried to)
        # AND every attempt failed validation.  Skipped-everything is fine
        # (existing routes still apply); only "tried and failed everywhere"
        # is an abort condition.
        if (not route_setup_result.get("success", False)
                and not dry
                and route_setup_result.get("attempts")
                and any(a.get("added") for a in route_setup_result["attempts"])):
            if external_ips or raw_external:
                print(f"{Fore.YELLOW}[!] Internal route setup failed — "
                      f"dropping {_int_count} internal target(s) and "
                      f"continuing with {_ext_count} external target(s)."
                      f"{Style.RESET_ALL}")
                internal_ips = []
                raw_internal = []
                _int_count = 0
            else:
                print(f"{Fore.RED}[!] Aborting scan: internal-route setup "
                      f"could not confirm reachability on any candidate "
                      f"interface and no external targets exist. Fix the "
                      f"routing configuration or pass --route-interface "
                      f"and --route-gateway explicitly, then re-run."
                      f"{Style.RESET_ALL}")
                sys.exit(2)
        if route_setup_result.get("success", False):
            _n_added = len(route_setup_result.get("routes_added", []))
            _n_skip = len(route_setup_result.get("routes_skipped", []))
            _n_fail = len(route_setup_result.get("routes_failed", []))
            _vc.log(f"Route setup complete: {_n_added} added, "
                    f"{_n_skip} skipped, {_n_fail} failed")
    elif not internal_ips and not (_lazy_targets and raw_internal):
        pass  # no internal targets — nothing to route
    else:
        print(f"{Fore.YELLOW}[~] Internal route setup disabled (--no-route-setup){Style.RESET_ALL}")

    # Mark tool-discovery complete; emit tool availability map to Vantage UI
    _pm.set_phase_status("init_tools", "complete", label="INIT: Tool Discovery")
    _init_tool_results = {
        "nmap":          {"installed": bool(nmap_path),        "path": nmap_path or ""},
        "vulners NSE":   {"installed": bool(vulners_available),"path": ""},
        "sslscan":       {"installed": bool(sslscan_path),     "path": sslscan_path or ""},
        "testssl":       {"installed": bool(testssl_path),     "path": testssl_path or ""},
        "nuclei":        {"installed": bool(nuclei_path),      "path": nuclei_path or ""},
        "snmpwalk":      {"installed": bool(snmpwalk_path),    "path": snmpwalk_path or ""},
        "smbmap":        {"installed": bool(smbmap_path),      "path": smbmap_path or ""},
        "enum4linux":    {"installed": bool(enum4linux_path),  "path": enum4linux_path or ""},
        "ADenum":        {"installed": bool(adenum_path),      "path": adenum_path or ""},
        "responder":     {"installed": bool(responder_path),   "path": responder_path or ""},
        "shcheck":       {"installed": bool(shcheck_path),     "path": shcheck_path or ""},
        "gobuster":      {"installed": bool(gobuster_path),    "path": gobuster_path or ""},
        "webanalyze":    {"installed": bool(webanalyze_path),  "path": webanalyze_path or ""},
        "wpscan":        {"installed": bool(wpscan_path),      "path": wpscan_path or ""},
        "searchsploit":  {"installed": bool(searchsploit_path),"path": searchsploit_path or ""},
        "showmount":     {"installed": bool(showmount_path),   "path": showmount_path or ""},
        "ipmitool":      {"installed": bool(ipmitool_path),    "path": ipmitool_path or ""},
    }
    _vc.status("init_tools", label="INIT: Tool Discovery", status="complete",
               tools=_init_tool_results)

    _check_pause()

    # ── Plugin / database updates ─────────────────────────────────────
    # Use each tool's native update mechanism to refresh scripts and
    # vulnerability databases before scanning begins.
    _vc.status("init_updates", label="INIT: Plugin Updates", status="running")
    _pm.set_phase_status("init_updates", "running", label="INIT: Plugin Updates")

    # Track per-tool update results for status emission at completion
    _update_results: dict = {}

    # nmap --script-updatedb  (refreshes the NSE script catalogue)
    if nmap_path:
        _vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                   step="nmap --script-updatedb")
        print(f"{Fore.CYAN}[*] Updating nmap NSE script database...{Style.RESET_ALL}",
              flush=True)
        sudo_prefix = [] if os.geteuid() == 0 else (["sudo", "-n"] if shutil.which("sudo") else [])
        _nmap_upd_result = "failed"
        try:
            _nmap_upd = subprocess.run(
                sudo_prefix + [nmap_path, "--script-updatedb"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=120,
            )
            if _nmap_upd.returncode == 0:
                _nmap_upd_result = "updated"
                print(f"{Fore.GREEN}[+] nmap NSE script database updated.{Style.RESET_ALL}")
            else:
                _nmap_upd_result = "skipped"
                print(f"{Fore.YELLOW}[~] nmap --script-updatedb returned "
                      f"{_nmap_upd.returncode} — continuing.{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _nmap_upd_result = "timed out"
            print(f"{Fore.YELLOW}[~] nmap --script-updatedb timed out — continuing.{Style.RESET_ALL}")
        except Exception as _exc:
            _nmap_upd_result = "failed"
            print(f"{Fore.YELLOW}[~] nmap --script-updatedb failed: {_exc}{Style.RESET_ALL}")
        _update_results["nmap"] = {"installed": True, "path": nmap_path, "result": _nmap_upd_result}
    else:
        _update_results["nmap"] = {"installed": False, "path": "", "result": "not-installed"}

    # wpscan --update  (refreshes the WPVulnDB plugin/theme/core database)
    if wpscan_path:
        _vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                   step="wpscan --update")
        print(f"{Fore.CYAN}[*] Updating wpscan vulnerability database...{Style.RESET_ALL}",
              flush=True)
        _wp_upd_result = "failed"
        try:
            _wp_upd = subprocess.run(
                [wpscan_path, "--update"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=180,
            )
            if _wp_upd.returncode == 0:
                _wp_upd_result = "updated"
                print(f"{Fore.GREEN}[+] wpscan database updated.{Style.RESET_ALL}")
            else:
                _wp_upd_result = "skipped"
                print(f"{Fore.YELLOW}[~] wpscan --update returned "
                      f"{_wp_upd.returncode} — continuing.{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _wp_upd_result = "timed out"
            print(f"{Fore.YELLOW}[~] wpscan --update timed out — continuing.{Style.RESET_ALL}")
        except Exception as _exc:
            _wp_upd_result = "failed"
            print(f"{Fore.YELLOW}[~] wpscan --update failed: {_exc}{Style.RESET_ALL}")
        _update_results["wpscan"] = {"installed": True, "path": wpscan_path, "result": _wp_upd_result}
    else:
        _update_results["wpscan"] = {"installed": False, "path": "", "result": "not-installed"}

    # nuclei -update-templates  (refreshes the Nuclei community template library)
    if nuclei_path:
        _vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                   step="nuclei -update-templates")
        print(f"{Fore.CYAN}[*] Updating nuclei templates...{Style.RESET_ALL}", flush=True)
        _nuc_upd_result = "failed"
        try:
            _nuc_upd = subprocess.run(
                [nuclei_path, "-update-templates"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=300,
            )
            if _nuc_upd.returncode == 0:
                _nuc_upd_result = "updated"
                print(f"{Fore.GREEN}[+] Nuclei templates updated.{Style.RESET_ALL}")
            else:
                _nuc_upd_result = "skipped"
                print(f"{Fore.YELLOW}[~] nuclei -update-templates returned "
                      f"{_nuc_upd.returncode} — continuing.{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _nuc_upd_result = "timed out"
            print(f"{Fore.YELLOW}[~] nuclei -update-templates timed out — continuing.{Style.RESET_ALL}")
        except Exception as _exc:
            _nuc_upd_result = "failed"
            print(f"{Fore.YELLOW}[~] nuclei -update-templates failed: {_exc}{Style.RESET_ALL}")
        _update_results["nuclei"] = {"installed": True, "path": nuclei_path, "result": _nuc_upd_result}
    else:
        _update_results["nuclei"] = {"installed": False, "path": "", "result": "not-installed"}

    # webanalyze -update  (refreshes the technologies.json fingerprint database)
    # Use a shared location so the 2 MB database is not copied into every scan dir.
    _WA_DB_DIR = Path("/var/lib/pr0t31n/webanalyze")
    if webanalyze_path:
        _vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                   step="webanalyze -update")
        print(f"{Fore.CYAN}[*] Updating webanalyze technology database...{Style.RESET_ALL}",
              flush=True)
        _wa_upd_result = "failed"
        _WA_DB_DIR.mkdir(parents=True, exist_ok=True)
        try:
            _wa_upd = subprocess.run(
                [webanalyze_path, "-update"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=120, cwd=str(_WA_DB_DIR),
            )
            if _wa_upd.returncode == 0:
                _wa_upd_result = "updated"
                print(f"{Fore.GREEN}[+] webanalyze technologies database updated.{Style.RESET_ALL}")
            else:
                _wa_upd_result = "skipped"
                print(f"{Fore.YELLOW}[~] webanalyze -update returned "
                      f"{_wa_upd.returncode} — continuing.{Style.RESET_ALL}")
        except subprocess.TimeoutExpired:
            _wa_upd_result = "timed out"
            print(f"{Fore.YELLOW}[~] webanalyze -update timed out — continuing.{Style.RESET_ALL}")
        except Exception as _exc:
            _wa_upd_result = "failed"
            print(f"{Fore.YELLOW}[~] webanalyze -update failed: {_exc}{Style.RESET_ALL}")
        _update_results["webanalyze"] = {"installed": True, "path": webanalyze_path, "result": _wa_upd_result}
    else:
        _update_results["webanalyze"] = {"installed": False, "path": "", "result": "not-installed"}

    _pm.set_phase_status("init_updates", "complete", label="INIT: Plugin Updates")
    _vc.status("init_updates", label="INIT: Plugin Updates", status="complete",
               tools=_update_results)

    _check_pause()

    # ── Nessus action item — emit the full scope immediately ────────
    # Gives the operator a one-click prompt to launch a parallel Nessus
    # vulnerability scan against the same target set while SS3 runs.
    _nessus_scope_str = ", ".join(resolved[:50])
    if len(resolved) > 50:
        _nessus_scope_str += f" (+{len(resolved) - 50} more)"
    _nessus_ai = {
        "id":               str(_uuid.uuid4()),
        "type":             "vulnerability_scan",
        "recommended_tool": "nessus",
        "target":           _nessus_scope_str,
        "ip":               "",
        "port":             0,
        "hostname":         "",
        "title":            "Launch Nessus Vulnerability Scan",
        "description":      (f"Run a Nessus vulnerability scan against the full "
                             f"project scope ({_target_count:,} target(s)). Nessus "
                             f"can run in parallel with Scattershot3 for maximum "
                             f"coverage."),
        "source_finding":   "",
        "priority":         "HIGH",
        "scope":            "int" if (internal_ips or raw_internal) else "ext",
        "status":           "pending",
        "datetime":         datetime.now().isoformat(),
        "metadata":         {
            "scope_targets": resolved,
            "all_ips":       all_ips if all_ips else resolved,
            "internal_count": _int_count,
            "external_count": _ext_count,
        },
        "_scope":           "int",
    }
    _vc.action_item(_nessus_ai)
    # Also write to project-level action_items.json (outside scope dirs)
    _proj_ai_path = Path(args.project).resolve() / "action_items.json"
    try:
        _proj_ai_existing = json.loads(
            _proj_ai_path.read_text(encoding="utf-8")
        ) if _proj_ai_path.exists() else []
        if not isinstance(_proj_ai_existing, list):
            _proj_ai_existing = []
        # Dedup by title
        if not any(e.get("title") == _nessus_ai["title"] for e in _proj_ai_existing):
            _proj_ai_existing.append(_nessus_ai)
            _proj_ai_path.write_text(
                json.dumps(_proj_ai_existing, indent=2, default=str) + "\n",
                encoding="utf-8",
            )
    except Exception:
        pass  # best-effort; Nessus action item also reaches Vantage via SocketIO

    # ── Scan passes ───────────────────────────────────────────────────
    # Run internal first (typically faster — LAN speeds, no firewall),
    # then external. Scopes with zero targets are skipped entirely.
    combined_results = {}

    # ── CredentialStore — shared across all scan passes ───────────────
    # Initialised once here; passed to scan_scope → _port_scan_worker.
    # Responder and web-credential extraction both write into it in real time.
    project_root_early = Path(args.project).resolve()
    project_root_early.mkdir(parents=True, exist_ok=True)
    # CredentialStore uses scope="int" so Responder hashes are written to
    # <project>/int/responder/ alongside the internal scan data.
    cred_store = CredentialStore(project_root_early, scope="int")

    # ── Start Responder when internal IPs are in scope ────────────────
    # Responder poisons LLMNR/NBT-NS/mDNS on the internal network and
    # captures NTLMv2 hashes (and occasionally cleartext credentials) from
    # Windows hosts.  It runs from scan start to scan finish so that any
    # broadcast name-resolution requests during the scan window are captured.
    # Linux-only; skipped silently on Windows/macOS.
    responder_proc: "subprocess.Popen | None" = None
    _has_internal = bool(internal_ips) or (_lazy_targets and bool(raw_internal))
    if (_has_internal
            and responder_path
            and platform.system() == "Linux"
            and not getattr(args, "no_responder", False)):
        _responder_sample = internal_ips or _expand_sample_ips(raw_internal, 10)
        if not _server_shares_segment_with_targets(_responder_sample, raw_specs=raw_internal):
            print(
                f"{Fore.YELLOW}[~] Responder: server is not on the same network "
                f"segment as any internal target — skipping{Style.RESET_ALL}"
            )
        else:
            iface = _detect_responder_interface(_responder_sample)
            if iface:
                responder_proc = run_responder_background(
                    responder_path, iface,
                    project_root_early,
                    cred_store,
                    smbmap_path=smbmap_path,
                    target_ips=_responder_sample,
                )
            else:
                print(
                    f"{Fore.YELLOW}[~] Responder: could not detect internal "
                    f"interface — skipping{Style.RESET_ALL}"
                )

    # ── Passive Seed — concurrent tcpdump → Trawler analysis ──────────
    _ps_thread: "threading.Thread | None" = None
    _ps_duration = getattr(args, "passive_seed_duration", 300) or 0
    _no_ps = getattr(args, "no_passive_seed", False)
    if (_has_internal and _ps_duration > 0 and not _no_ps
            and platform.system() in ("Linux", "Darwin")):
        _ps_sample = internal_ips or _expand_sample_ips(raw_internal, 10)
        _ps_server_ip = get_source_ip_for(_ps_sample[0]) if _ps_sample else None
        _ps_iface = _detect_responder_interface(_ps_sample) if _ps_sample else None
        _ps_trawler = str(Path("/opt/pr0t31n/Trawler/trawler.py"))
        if not Path(_ps_trawler).exists():
            _ps_trawler = shutil.which("trawler") or shutil.which("trawler.py")
        if _ps_iface and _ps_server_ip and _ps_trawler:
            _ps_thread = threading.Thread(
                target=_passive_seed_thread,
                args=(_ps_duration, _ps_iface, _ps_server_ip,
                      project_root_early, _ps_trawler),
                daemon=True,
                name="passive-seed",
            )
            _ps_thread.start()
            print(
                f"{Fore.CYAN}[*] Passive seed: {_ps_duration}s tcpdump on "
                f"{_ps_iface} (excluding {_ps_server_ip}){Style.RESET_ALL}"
            )
        else:
            if not _ps_iface:
                print(f"{Fore.YELLOW}[~] Passive seed: no interface detected — skipping{Style.RESET_ALL}")
            elif not _ps_server_ip:
                print(f"{Fore.YELLOW}[~] Passive seed: no server IP detected — skipping{Style.RESET_ALL}")
            elif not _ps_trawler:
                print(f"{Fore.YELLOW}[~] Passive seed: Trawler not found — skipping{Style.RESET_ALL}")
    elif _no_ps:
        print(f"{Fore.YELLOW}[~] Passive seed disabled (--no-passive-seed){Style.RESET_ALL}")
    elif _ps_duration == 0:
        print(f"{Fore.YELLOW}[~] Passive seed disabled (duration=0){Style.RESET_ALL}")

    def _run_scope_int():
        if not internal_ips and not (_lazy_targets and raw_internal):
            print(f"\n{Fore.CYAN}[~] No INT targets — skipping internal pass.{Style.RESET_ALL}")
            _pm.set_phase_status("scope_int", "skipped", label="Scan: Internal")
            _vc.status("scope_int", label="Scan: Internal", status="skipped")
            return
        if _pm.is_phase_complete("scope_int"):
            _vc.log("Scope INT already complete — resuming from checkpoint.", "INFO")
            _vc.status("scope_int", label="Scan: Internal", status="complete")
        else:
            _pm.set_phase_status("scope_int", "running", label="Scan: Internal")
            _vc.status("scope_int", label="Scan: Internal", status="running",
                       step=f"{_int_count:,} targets")
        results = scan_scope("int", internal_ips, args,
                             nmap_path, sslscan_path, testssl_path,
                             nuclei_path=nuclei_path,
                             raw_specs=raw_internal,
                             snmpwalk_path=snmpwalk_path,
                             smbmap_path=smbmap_path,
                             enum4linux_path=enum4linux_path,
                             adenum_path=adenum_path,
                             cred_store=cred_store,
                             gobuster_path=gobuster_path,
                             wpscan_path=wpscan_path,
                             webanalyze_path=webanalyze_path,
                             shcheck_path=shcheck_path,
                             searchsploit_path=searchsploit_path,
                             wpscan_token=wpscan_token,
                             showmount_path=showmount_path,
                             ipmitool_path=ipmitool_path,
                             nbtscan_path=nbtscan_path,
                             nmblookup_path=nmblookup_path,
                             avahi_resolve_path=avahi_resolve_path,
                             rustscan_path=rustscan_path,
                             kerbrute_path=kerbrute_path,
                             bloodhound_path=bloodhound_path,
                             hydra_path=hydra_path,
                             sqlmap_path=sqlmap_path,
                             xsstrike_path=xsstrike_path,
                             odat_path=odat_path,
                             msdat_path=msdat_path,
                             enumdb_path=enumdb_path,
                             zap_path=zap_path,
                             target_count=_int_count,
                             exclude_ips=_local_in_scope,
                             exclude_nets=_project_exclude_nets)
        combined_results["int"] = results
        _pm.set_phase_status("scope_int", "complete", label="Scan: Internal")
        _vc.status("scope_int", label="Scan: Internal", status="complete")

    def _run_scope_ext():
        if not external_ips and not (_lazy_targets and raw_external):
            print(f"\n{Fore.CYAN}[~] No EXT targets — skipping external pass.{Style.RESET_ALL}")
            _pm.set_phase_status("scope_ext", "skipped", label="Scan: External")
            _vc.status("scope_ext", label="Scan: External", status="skipped")
            return
        if _pm.is_phase_complete("scope_ext"):
            _vc.log("Scope EXT already complete — resuming from checkpoint.", "INFO")
            _vc.status("scope_ext", label="Scan: External", status="complete")
        else:
            _pm.set_phase_status("scope_ext", "running", label="Scan: External")
            _vc.status("scope_ext", label="Scan: External", status="running",
                       step=f"{_ext_count:,} targets")
        results = scan_scope("ext", external_ips, args,
                             nmap_path, sslscan_path, testssl_path,
                             nuclei_path=nuclei_path,
                             raw_specs=raw_external,
                             snmpwalk_path=snmpwalk_path,
                             smbmap_path=smbmap_path,
                             enum4linux_path=enum4linux_path,
                             adenum_path=adenum_path,
                             cred_store=cred_store,
                             gobuster_path=gobuster_path,
                             wpscan_path=wpscan_path,
                             webanalyze_path=webanalyze_path,
                             shcheck_path=shcheck_path,
                             searchsploit_path=searchsploit_path,
                             wpscan_token=wpscan_token,
                             showmount_path=showmount_path,
                             ipmitool_path=ipmitool_path,
                             nbtscan_path=nbtscan_path,
                             nmblookup_path=nmblookup_path,
                             avahi_resolve_path=avahi_resolve_path,
                             rustscan_path=rustscan_path,
                             kerbrute_path=kerbrute_path,
                             bloodhound_path=bloodhound_path,
                             hydra_path=hydra_path,
                             sqlmap_path=sqlmap_path,
                             xsstrike_path=xsstrike_path,
                             odat_path=odat_path,
                             msdat_path=msdat_path,
                             enumdb_path=enumdb_path,
                             zap_path=zap_path,
                             o365spray_path=o365spray_path,
                             target_count=_ext_count,
                             exclude_ips=_local_in_scope,
                             exclude_nets=_project_exclude_nets)
        combined_results["ext"] = results
        _pm.set_phase_status("scope_ext", "complete", label="Scan: External")
        _vc.status("scope_ext", label="Scan: External", status="complete")

    _check_pause()

    try:
        with ThreadPoolExecutor(max_workers=2) as scope_pool:
            int_fut = scope_pool.submit(_run_scope_int)
            ext_fut = scope_pool.submit(_run_scope_ext)
            for fut in as_completed([int_fut, ext_fut]):
                fut.result()  # re-raises any exception from the scope thread

    except (KeyboardInterrupt, Exception) as _scope_crash:
        _scope_tb = traceback.format_exc()
        _write_crash_log(
            f"Scan aborted during scope execution — "
            f"{type(_scope_crash).__name__}: {_scope_crash}\n{_scope_tb}"
        )
        try:
            _vc.log(
                f"Scope execution crashed: "
                f"{type(_scope_crash).__name__}: {_scope_crash}",
                "ERROR",
            )
        except Exception:
            pass
        raise

    finally:
        # Always stop Responder even on exception or KeyboardInterrupt
        if responder_proc is not None:
            stop_responder(responder_proc)
            # Parse any final log entries written after the scan completed
            parse_responder_logs(project_root_early, cred_store,
                                   smbmap_path=smbmap_path)
            n_creds = len(cred_store.get_all())
            n_hashes = len(cred_store.get_hashes())
            if n_creds or n_hashes:
                _hash_dir = project_root_early / "int" / "responder"
                hash_files = (
                    f"{_hash_dir}/hashes.txt, hashes.json, "
                    f"hashes_ntlmv2.txt, hashes_ntlmv1.txt, hashes_lmnt.txt"
                )
                print(
                    f"{Fore.RED}[!] Responder total: "
                    f"{n_creds} plaintext credential(s), "
                    f"{n_hashes} hash(es) captured — "
                    f"see {project_root_early}/credentials.json "
                    f"and {hash_files}{Style.RESET_ALL}"
                )
                # Write per-scope findings for all captured hashes and credentials
                scanned = [s for s in ("int", "ext")
                           if (project_root_early / s).exists()]
                log_responder_findings(project_root_early, cred_store, scanned,
                                      target_ips=internal_ips or _expand_sample_ips(raw_internal, 10))
                _resp_ai = {
                    "id":              str(_uuid.uuid4()),
                    "type":            "credential_reuse",
                    "recommended_tool": "Isotope",
                    "target":          "Responder credentials",
                    "ip":              "",
                    "port":            0,
                    "hostname":        "",
                    "title":           "Isotope: Crack and test Responder-captured credentials",
                    "description":     (
                        f"Responder captured {n_creds} plaintext credential(s) and "
                        f"{n_hashes} hash(es). Isotope can crack NTLMv1/v2 hashes "
                        f"via hashcat/John, test plaintext credentials for reuse "
                        f"across services, and perform NTLM relay attacks against "
                        f"hosts with SMB signing disabled."
                    ),
                    "source_finding":  "Responder Captured Credentials",
                    "priority":        "CRITICAL",
                    "scope":           "int",
                    "status":          "pending",
                    "datetime":        datetime.now().isoformat(),
                    "metadata":        {"n_creds": n_creds, "n_hashes": n_hashes},
                }
                _vc.action_item(_resp_ai)
                _resp_ai_path = project_root_early / "action_items.json"
                try:
                    _resp_existing = json.loads(_resp_ai_path.read_text(encoding="utf-8")) if _resp_ai_path.exists() else []
                    if not isinstance(_resp_existing, list):
                        _resp_existing = []
                except Exception:
                    _resp_existing = []
                _resp_existing.append(_resp_ai)
                try:
                    _resp_tmp = _resp_ai_path.with_suffix(".json.tmp")
                    _resp_tmp.write_text(json.dumps(_resp_existing, indent=2, default=str) + "\n", encoding="utf-8")
                    _resp_tmp.replace(_resp_ai_path)
                except Exception:
                    pass
            else:
                print(f"{Fore.CYAN}[*] Responder: no credentials captured.{Style.RESET_ALL}")

    # ── Collect passive seed results ─────────────────────────────────
    if _ps_thread is not None:
        _ps_thread.join(timeout=_ps_duration + 60)
        with _PASSIVE_SEED_LOCK:
            _psr = dict(_passive_seed_results)
        if _psr:
            _psr_ips = _psr.get("discovered_ips", [])
            _psr_svcs = _psr.get("discovered_services", {})
            _psr_fc = _psr.get("finding_count", 0)
            _psr_trawler_out = _psr.get("trawler_output", "")
            print(
                f"\n{Fore.CYAN}[*] Passive seed: {len(_psr_ips)} IP(s), "
                f"{sum(len(v) for v in _psr_svcs.values())} service(s), "
                f"{_psr_fc} finding(s){Style.RESET_ALL}"
            )
            if _psr_fc and _psr_trawler_out:
                _pr_findings_path = Path(_psr_trawler_out) / "findings.json"
                if _pr_findings_path.exists():
                    _int_dir = project_root_early / "int"
                    if _int_dir.exists():
                        _int_findings = _int_dir / "findings.json"
                        try:
                            _existing = json.loads(
                                _int_findings.read_text(encoding="utf-8")
                            ) if _int_findings.exists() else []
                            if not isinstance(_existing, list):
                                _existing = []
                            _existing_keys = {
                                (f.get("title", ""), f.get("ip", ""),
                                 str(f.get("port", 0)))
                                for f in _existing
                            }
                            _trawler_findings = json.loads(
                                _pr_findings_path.read_text(encoding="utf-8"))
                            if not isinstance(_trawler_findings, list):
                                _trawler_findings = []
                            _merged_count = 0
                            for f in _trawler_findings:
                                key = (f.get("title", ""), f.get("ip", ""),
                                       str(f.get("port", 0)))
                                if key not in _existing_keys:
                                    f["source_tools"] = ["trawler"]
                                    f.setdefault("scope", "int")
                                    _existing.append(f)
                                    _existing_keys.add(key)
                                    _merged_count += 1
                            if _merged_count:
                                _int_findings.write_text(
                                    json.dumps(_existing, indent=2,
                                               default=str) + "\n",
                                    encoding="utf-8",
                                )
                                _vc.log(f"[passive-seed] merged {_merged_count} "
                                        f"finding(s) into int/findings.json")
                        except Exception as _merge_exc:
                            _vc.error(f"[passive-seed] findings merge failed: "
                                      f"{_merge_exc}")
        else:
            print(f"{Fore.CYAN}[*] Passive seed: no results (capture may "
                  f"have been empty).{Style.RESET_ALL}")

    # ── Cross-scope summary.json ──────────────────────────────────────
    # Written to the project root (one level above int/ and ext/).
    # Structured for AI ingestion (Codex import function): all paths are
    # relative from the project root, all tools include command + output file,
    # and findings are nested under the IP → port that produced them.
    project_root  = Path(args.project).resolve()
    summary_path  = project_root / "summary.json"

    def _rel(p: "Path | str | None") -> "str | None":
        """Return a path relative to the project root, or None."""
        if not p:
            return None
        try:
            return str(Path(p).relative_to(project_root))
        except ValueError:
            return str(p)

    def _load_json_array(fpath: "Path") -> list:
        try:
            data = json.loads(fpath.read_text(encoding="utf-8"))
            return data if isinstance(data, list) else []
        except Exception:
            return []

    def _build_scope_systems(scope: str, scope_results: dict) -> dict:
        """
        Build the nested observed_systems dict for one scope.

        Structure:
          {ip: {hostname, alive, ports: {port: {service, product, version,
                findings: [{title, risk, command, description, output_file}],
                tools: [{tool, command, output_file}]}}}}
        """
        scope_root = project_root / scope
        findings   = _load_json_array(scope_root / "findings.json")
        cmds       = _load_json_array(scope_root / "scan.log.json")

        # Index findings by ip:port
        findings_by_port: dict = {}
        for f in findings:
            key = (str(f.get("ip", "")), int(f.get("port", 0)))
            findings_by_port.setdefault(key, []).append({
                "title":       f.get("title", ""),
                "risk":        f.get("risk", ""),
                "command":     f.get("command", ""),
                "description": f.get("description", ""),
                "datetime":    f.get("datetime", ""),
            })

        # Index commands by target ip:port string
        cmds_by_port: dict = {}
        for c in cmds:
            if c.get("type") == "error":
                continue
            target = c.get("target", "")
            if ":" in target:
                cmds_by_port.setdefault(target, []).append({
                    "tool":        c.get("tool", ""),
                    "command":     c.get("command", ""),
                    "output_file": _rel(scope_root / c["output_file"])
                                   if c.get("output_file") and c["output_file"] != "n/a"
                                   else None,
                })

        systems: dict = {}
        for ip, host in scope_results.items():
            if not host.get("alive"):
                systems[ip] = {"alive": False, "hostname": host.get("hostname"),
                               "ports": {}}
                continue
            ports_out: dict = {}
            for port, pinfo in sorted((host.get("open_ports") or {}).items()):
                pkey = (ip, port)
                port_cmds = cmds_by_port.get(f"{ip}:{port}", [])
                ports_out[port] = {
                    "service":  pinfo.get("name", ""),
                    "product":  pinfo.get("product", ""),
                    "version":  pinfo.get("version", ""),
                    "proto":    pinfo.get("proto", "tcp"),
                    "banner":   (pinfo.get("banner") or {}).get("banner", ""),
                    "findings": findings_by_port.get(pkey, []),
                    "tools":    port_cmds,
                }
            systems[ip] = {
                "alive":    True,
                "hostname": host.get("hostname"),
                "fqdn_by_port": host.get("hostnames_by_port", {}),
                "ports":    ports_out,
            }
        return systems

    # Build AI-ingestible summary
    engagement = getattr(args, "engagement", {})
    summary = {
        "_schema_version": "2",
        "_description": (
            "Scattershot3 cross-scope scan summary. "
            "All paths are relative to the project root directory. "
            "Structure: consultant_data → customer_data → provided_targets → "
            "observed_systems[ip] → ports[port] → findings / tools."
        ),
        "hostname": socket.gethostname(),
        "consultant_data": {
            "consultant":  engagement.get("consultant", ""),
            "company":     engagement.get("company", ""),
            "email":       engagement.get("email", ""),
        },
        "customer_data": {
            "client_name": engagement.get("client_name", ""),
            "client_short": engagement.get("client_short", ""),
            "poc":         engagement.get("poc", ""),
            "poc_email":   engagement.get("poc_email", ""),
        },
        "scan_meta": {
            "project":        args.project,
            "project_root":   str(project_root),
            "generated":      datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "scanner":        "scattershot3.py",
            "scanner_host":   platform.node(),
            "scanner_os":     f"{platform.system()} {platform.release()}",
            "mode":           "fast (top-1000)" if args.fast else "full (all 65535 ports)",
            "nuclei":         nuclei_path or "not available",
            "route_setup":    route_setup_result,
        },
        "provided_targets": {
            "int":   internal_ips if internal_ips else raw_internal,
            "ext":   external_ips if external_ips else raw_external,
            "total": _target_count,
        },
        "alive_counts": {
            scope: sum(1 for r in res.values() if r.get("alive"))
            for scope, res in combined_results.items()
        },
        "findings_counts": {
            scope: _count_findings(project_root / scope / "findings.json")
            for scope in combined_results
        },
        "scope_files": {
            scope: {
                "results_json":        _rel(project_root / scope / "results.json"),
                "correlated_json":     _rel(project_root / scope / "correlated.json"),
                "findings_json":       _rel(project_root / scope / "findings.json"),
                "findings_csv":        _rel(project_root / scope / "findings.csv"),
                "software_inventory":  _rel(project_root / scope / "software_inventory.json"),
                "scan_log":            _rel(project_root / scope / "scan.log"),
                "scan_log_json":       _rel(project_root / scope / "scan.log.json"),
                "errors_log":          _rel(project_root / scope / "errors.log"),
                "hashes_txt":          _rel(project_root / scope / "responder" / "hashes.txt"),
                "hashes_json":         _rel(project_root / scope / "responder" / "hashes.json"),
                "source_ip":    next(
                    (r.get("source_ip") for r in combined_results[scope].values()
                     if r.get("source_ip")), None
                ),
                "source_iface": next(
                    (r.get("source_iface") for r in combined_results[scope].values()
                     if r.get("source_iface")), None
                ),
                "source_host":  next(
                    (r.get("source_host") for r in combined_results[scope].values()
                     if r.get("source_host")), platform.node()
                ),
            }
            for scope in combined_results
        },
        "observed_systems": {
            scope: _build_scope_systems(scope, res)
            for scope, res in combined_results.items()
        },
    }

    with summary_path.open("w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2, default=str)
    print(f"\n{Fore.GREEN}[+] summary.json written: {summary_path}{Style.RESET_ALL}")

    # ── directory_structure.json ──────────────────────────────────────
    # Describes the expected project layout for Codex or other AI tools
    # that need to locate and parse scan artefacts.
    _scope_dirs: dict = {}
    for _s in ("int", "ext"):
        _scope_dirs[f"{_s}/"] = {
            "description": (
                "Internal (RFC-1918) scope scan data" if _s == "int"
                else "External (publicly-routable) scope scan data"
            ),
            "files": {
                "results.json":           "Raw scan results keyed by IP address",
                "correlated.json":        "Results correlated by IP → port → tool",
                "findings.json":          "Security findings array (matches summary observed_systems)",
                "findings.csv":           "Security findings in CSV format",
                "software_inventory.json":"Detected software versions",
                "scan.log":               "Human-readable activity log (timestamped tool invocations + phase EVENT transitions)",
                "scan.log.json":          "Structured JSON log: tool, command, output_file per invocation",
                "errors.log":             "Tool errors with timestamps",
            },
            "directories": {
                "hosts/": "Per-host output directories (hosts/<ip>/)",
                "tools/": "Scope-wide tool output directories (tools/<toolname>/)",
                "targets/": "Target list files (active_ips.txt)",
            },
        }
        _scope_dirs[f"{_s}/"]["directories"]["responder/"] = (
            "Responder output: responder_output.txt, hashes.txt, hashes.json, "
            "hashes_ntlmv2.txt, hashes_ntlmv1.txt, hashes_lmnt.txt"
        )

    _dir_structure = {
        "_description": (
            "Scattershot3 project directory layout. "
            "Parse summary.json for all findings and tool invocations. "
            "All paths in summary.json are relative to this directory."
        ),
        "files": {
            "summary.json":            "AI-ingestible cross-scope scan summary (primary entry point)",
            "directory_structure.json": "This file — describes the expected file layout",
            "credentials.json":        "Captured plaintext credentials (structured array)",
            "credentials.txt":         "Human-readable domain\\user:password lines",
        },
        "directories": _scope_dirs,
    }
    _dir_struct_path = project_root / "directory_structure.json"
    try:
        _dir_struct_path.write_text(
            json.dumps(_dir_structure, indent=2), encoding="utf-8"
        )
        print(f"{Fore.GREEN}[+] directory_structure.json written: {_dir_struct_path}{Style.RESET_ALL}")
    except OSError as e:
        print(f"{Fore.YELLOW}[~] Could not write directory_structure.json: {e}{Style.RESET_ALL}")

    if args.output:
        save_json(summary, args.output)

    # Augment each scope's findings.json with universal-required fields
    # (id, tool, scope, phase, catalogue_id). Idempotent — re-runs are no-ops.
    try:
        from pathlib import Path as _P
        _project_path = _P(args.project)
        for _scope in ("int", "ext"):
            _scope_findings = _project_path / _scope / "findings.json"
            if _scope_findings.exists():
                _u_augment_findings_path(_scope_findings, tool="scattershot3", scope=_scope)
                _enrich_remediation(_scope_findings)
    except Exception:
        pass

    if _pause is not None:
        _pause.write_stop_reason("completed", "all_phases_done")

    # ── Final project-level overview ──────────────────────────────────
    print(f"\n{Fore.CYAN}{'═'*60}{Style.RESET_ALL}")
    print(f"{Fore.CYAN}[*] Scan complete: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}{Style.RESET_ALL}")
    print(f"{Fore.CYAN}[*] Project root : {project_root}{Style.RESET_ALL}")
    print(f"\n{Fore.CYAN}    Project structure:{Style.RESET_ALL}")
    print(f"    {Fore.WHITE}{args.project}/{Style.RESET_ALL}")

    for scope in ("int", "ext"):
        if scope not in combined_results:
            continue
        scope_colour  = Fore.GREEN if scope == "int" else Fore.YELLOW
        scope_results = combined_results[scope]
        alive         = sum(1 for r in scope_results.values() if r.get("alive"))
        findings_n    = _count_findings(project_root / scope / "findings.json")
        findings_col  = Fore.RED if findings_n else Fore.GREEN
        print(f"    {Fore.WHITE}├── {scope_colour}{scope}/{Style.RESET_ALL}  "
              f"({alive}/{len(scope_results)} alive"
              f"  {findings_col}{findings_n} finding(s){Style.RESET_ALL})")
        for fname in ["results.json", "correlated.json",
                      "findings.json", "findings.csv",
                      "software_inventory.json",
                      "scan.log", "scan.log.json", "errors.log"]:
            fpath = project_root / scope / fname
            print(f"    {Fore.WHITE}│   ├── {fname:<18}{Style.RESET_ALL} "
                  f"{Fore.YELLOW}{_fsize(fpath):>8}{Style.RESET_ALL}")
        # Nuclei directory
        nuclei_d = project_root / scope / "nuclei"
        if nuclei_d.exists():
            nuclei_files = list(nuclei_d.glob("*"))
            if nuclei_files:
                total = sum(f.stat().st_size for f in nuclei_files if f.is_file())
                size_str = f"{total/1024:.1f} KB" if total >= 1024 else f"{total} B"
                print(f"    {Fore.WHITE}│   ├── nuclei/           {Style.RESET_ALL}"
                      f"{Fore.CYAN}{len(nuclei_files)} file(s), {size_str}{Style.RESET_ALL}")

    print(f"    {Fore.WHITE}└── summary.json       {Style.RESET_ALL} "
          f"{Fore.YELLOW}{_fsize(summary_path):>8}{Style.RESET_ALL}  "
          f"combined cross-scope summary")
    print(f"\n{Fore.CYAN}{'═'*60}{Style.RESET_ALL}")


def run_brutespray(
    nmap_xml_path: "str | Path",
    output_mgr: "OutputManager",
    scope: str = "int",
    args: "argparse.Namespace | None" = None,
    timeout: int = 600,
) -> None:
    """Run brutespray against nmap XML to spray default credentials on all services."""
    brutespray_bin = shutil.which("brutespray")
    if not brutespray_bin:
        _tprint(f"  {Fore.YELLOW}[~] brutespray not installed — skipping credential spray{Style.RESET_ALL}")
        return
    if args and getattr(args, "no_brute", False):
        return

    nmap_xml = Path(nmap_xml_path)
    if not nmap_xml.is_file():
        return

    bs_dir = output_mgr.scope_tool_path("brutespray")
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    bs_out_dir = bs_dir / f"brutespray_{ts}"
    bs_out_dir.mkdir(parents=True, exist_ok=True)

    _tprint(f"\n{Fore.CYAN}[*] Running brutespray credential spray...{Style.RESET_ALL}")
    _vc.status(f"{scope}_p6b_brutespray", label="Phase 6b: BruteSpray", status="running")

    cmd = [
        brutespray_bin, "--file", str(nmap_xml),
        "--threads", "5", "--hosts", "3",
        "-o", str(bs_out_dir),
    ]

    _bs_started = datetime.now().astimezone()
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        _bs_ended = datetime.now().astimezone()
        output_mgr.log_command(
            "brutespray", brutespray_bin, cmd, bs_out_dir,
            stdout=result.stdout, stderr=result.stderr,
            started=_bs_started, ended=_bs_ended,
            exit_code=result.returncode,
            extra={"target": f"nmap-xml:{nmap_xml.name}"},
        )

        _DEFAULT_USERNAMES = {
            "admin", "root", "administrator", "guest", "user", "test",
            "sa", "postgres", "mysql", "oracle", "ftp", "anonymous",
            "tomcat", "manager", "nagios", "cisco", "ubnt", "pi",
        }

        found_creds: list[dict] = []

        # Parse stdout for "ACCOUNT FOUND:" lines
        for line in (result.stdout or "").splitlines():
            m = re.match(
                r"ACCOUNT FOUND:\s+\[(\w+)\]\s+Host:\s+(\S+)\s+User:\s+(\S+)\s+Password:\s+(\S+)",
                line,
            )
            if m:
                svc, host, user, pwd = m.groups()
                found_creds.append({
                    "service": svc, "host": host,
                    "user": user, "password": pwd,
                })

        # Also scan per-service output files brutespray creates
        for f in bs_out_dir.rglob("*.txt"):
            try:
                content = f.read_text(errors="replace")
            except Exception:
                continue
            for line in content.splitlines():
                m = re.match(
                    r".*Host:\s+(\S+).*User:\s+(\S+).*Password:\s+(\S+)", line,
                )
                if m:
                    bs_svc_name = f.stem.split("_")[0] if "_" in f.stem else f.stem
                    host, user, pwd = m.groups()
                    if not any(
                        c["host"] == host and c["user"] == user
                        for c in found_creds
                    ):
                        found_creds.append({
                            "service": bs_svc_name, "host": host,
                            "user": user, "password": pwd,
                        })

        for cred in found_creds:
            _cred_ip = cred["host"].split(":")[0] if ":" in cred["host"] else cred["host"]
            _port_str = cred["host"].split(":")[1] if ":" in cred["host"] else "0"
            _cred_port = int(_port_str) if _port_str.isdigit() else 0
            is_default = cred["user"].lower() in _DEFAULT_USERNAMES

            _cred_title = (
                f"Default Credentials: {cred['service'].upper()}"
                if is_default
                else f"Weak Credentials: {cred['service'].upper()}"
            )
            _cred_risk = "CRITICAL" if is_default else "HIGH"

            output_mgr.log_finding(
                title=_cred_title,
                ip=_cred_ip, port=_cred_port,
                command=" ".join(cmd),
                risk=_cred_risk,
                description=(
                    f"brutespray confirmed {'default' if is_default else 'weak'} "
                    f"credentials on {cred['service']} service at {cred['host']}. "
                    f"Username: {cred['user']}. "
                    f"{'Default credentials must be changed immediately.' if is_default else 'Weak credentials should be replaced with strong, unique passwords.'} "
                    f"Implement account lockout policies and monitor for brute force attempts."
                ),
                output=(
                    f"Service: {cred['service']}\n"
                    f"Host: {cred['host']}\n"
                    f"Username: {cred['user']}\n"
                    f"Password: [REDACTED]"
                ),
                sources="brutespray",
                affected=cred["host"],
                output_file=str(bs_out_dir.relative_to(output_mgr.root)),
            )

            try:
                output_mgr.log_action_item(
                    item_type="cross_tool",
                    recommended_tool="Manual",
                    target=cred["host"],
                    ip=_cred_ip, port=_cred_port,
                    title=f"Validate {cred['service'].upper()} Credentials",
                    description=(
                        f"brutespray found valid credentials for {cred['service']} on "
                        f"{cred['host']}.\n"
                        f"Next steps:\n"
                        f"  1. Manually verify: connect to {cred['service']}://{cred['host']} "
                        f"with user '{cred['user']}'\n"
                        f"  2. Document access level and data exposure\n"
                        f"  3. Test for privilege escalation from this access"
                    ),
                    hostname=None,
                    source_finding=_cred_title,
                    priority="CRITICAL" if is_default else "HIGH",
                )
            except Exception:
                pass

        if not found_creds:
            _tprint(f"  {Fore.GREEN}[+] brutespray: No default credentials found{Style.RESET_ALL}")
        else:
            _tprint(
                f"  {Fore.RED}[!!] brutespray: {len(found_creds)} credential(s) found!{Style.RESET_ALL}"
            )

    except subprocess.TimeoutExpired:
        _bs_ended = datetime.now().astimezone()
        _tprint(f"  {Fore.YELLOW}[~] brutespray timed out after {timeout}s{Style.RESET_ALL}")
        output_mgr.log_command(
            "brutespray", brutespray_bin, cmd, bs_out_dir,
            stdout="", stderr=f"Timed out after {timeout}s",
            started=_bs_started, ended=_bs_ended, exit_code=-1,
            extra={"target": f"nmap-xml:{nmap_xml.name}"},
        )
    except Exception as exc:
        _tprint(f"  {Fore.YELLOW}[~] brutespray error: {exc}{Style.RESET_ALL}")

    _vc.status(f"{scope}_p6b_brutespray", label="Phase 6b: BruteSpray", status="done")


def _count_findings(findings_json_path) -> int:
    """Return the number of entries in a findings.json pretty JSON array."""
    try:
        data = json.loads(Path(findings_json_path).read_text(encoding="utf-8"))
        return len(data) if isinstance(data, list) else 0
    except Exception:
        return 0


