def _sweep_findings_for_action_items(output_mgr) -> None:
    """Post-scan sweep: generate action items for findings with exploit
    metadata or that match known manual-testing patterns.

    Runs once after all scan phases complete.  Reads the finalized
    findings.json, checks each finding against:
      1. exploitdb / metasploit flags → Manual exploit verification AI
      2. Pattern rules → tool-specific manual testing AI
    Skips findings that already have a matching action item (deduped
    by log_action_item's internal key).
    """
    try:
        data = json.loads(
            output_mgr.findings_json.read_text(encoding="utf-8")
        )
        if not isinstance(data, list):
            return
    except Exception:
        return

    count = 0
    # Track (tool_lower, ip:port) to avoid flooding
    seen_tool_target: set[tuple] = set()

    for f in data:
        ip        = (f.get("ip") or "").strip()
        port      = int(f.get("port") or 0)
        risk      = (f.get("risk") or "").upper()
        title     = f.get("title") or ""
        desc      = f.get("description") or ""
        hostname  = f.get("hostname") or ""
        has_msf   = f.get("metasploit", False)
        has_edb   = f.get("exploitdb", False)
        details   = f.get("exploit_details") or []
        cves      = f.get("cves") or ""
        combined  = f"{title} {desc}".lower()
        target_str = f"{ip}:{port}" if port else ip

        if risk == "INFO":
            continue

        # ── 1. Metasploit / ExploitDB exploit available ───────────────
        if (has_msf or has_edb) and risk in ("CRITICAL", "HIGH"):
            _tk = ("manual_exploit", target_str)
            if _tk not in seen_tool_target:
                steps = []
                if has_msf:
                    msf_mod = ""
                    for d in details:
                        if d.get("type") == "metasploit":
                            msf_mod = d.get("name", "")
                            break
                    if msf_mod:
                        steps.append(f"  Metasploit: msfconsole → use {msf_mod}")
                    else:
                        steps.append(f"  Metasploit: search {title[:40]}")
                    steps.append(f"    set RHOSTS {ip}  •  set RPORT {port}")
                if has_edb:
                    edb_refs = [d.get("id", "") for d in details
                                if d.get("type") == "exploitdb"]
                    if edb_refs:
                        steps.append(
                            f"  ExploitDB: searchsploit {' '.join(edb_refs)}")
                    else:
                        steps.append(f"  ExploitDB: searchsploit {title[:40]}")
                if cves:
                    steps.append(f"  CVEs: {cves}")

                try:
                    output_mgr.log_action_item(
                        item_type="manual_exploit",
                        recommended_tool="Manual (Exploit Available)",
                        target=target_str,
                        ip=ip, port=port,
                        title="Public Exploit Available — Manual Verification Recommended",
                        description=(
                            f"Finding \"{title}\" on {target_str} has a public "
                            f"exploit ({risk}).\n"
                            "Next steps:\n" + "\n".join(steps)
                        ),
                        hostname=hostname,
                        source_finding=title,
                        priority=risk,
                    )
                    count += 1
                    seen_tool_target.add(_tk)
                except Exception:
                    pass

        # ── 2. Pattern-matched manual testing rules ───────────────────
        for keywords, tool, ai_title, desc_tmpl, priority in _SWEEP_MANUAL_RULES:
            if any(kw in combined for kw in keywords):
                _tk_rule = (tool.lower(), target_str)
                if _tk_rule not in seen_tool_target:
                    try:
                        output_mgr.log_action_item(
                            item_type="manual_verification",
                            recommended_tool=tool,
                            target=target_str,
                            ip=ip, port=port,
                            title=ai_title,
                            description=desc_tmpl.format(ip=ip, port=port),
                            hostname=hostname,
                            source_finding=title,
                            priority=priority,
                        )
                        count += 1
                        seen_tool_target.add(_tk_rule)
                    except Exception:
                        pass
                break  # first matching rule wins per finding

        # ── 3. Trawler: cleartext protocols → traffic capture ────────
        _TRAWLER_KW = (
            "snmpv1/v2c", "snmp public community", "snmp default community",
            "cleartext ftp", "cleartext telnet", "unencrypted http",
            "llmnr", "nbt-ns", "nbns", "ssdp", "ldap without tls",
        )
        for kw in _TRAWLER_KW:
            if kw in combined:
                _tk_tr = ("trawler", ip)
                if _tk_tr not in seen_tool_target:
                    try:
                        output_mgr.log_action_item(
                            item_type="traffic_capture",
                            recommended_tool="Trawler",
                            target=ip, ip=ip, port=port,
                            title=f"Traffic capture: {kw.split('/')[0].strip()} detected",
                            description=(
                                f"SS3 found {kw} on {target_str}. "
                                f"Trawler pcap analysis can capture live traffic "
                                f"for credential exposure and protocol analysis."),
                            hostname=hostname,
                            source_finding=title,
                            priority="MEDIUM",
                            metadata={"source_category": "ss3_cleartext_protocol"},
                        )
                        count += 1
                        seen_tool_target.add(_tk_tr)
                    except Exception:
                        pass
                break

        # ── 4. Bastion: network appliance → config audit ─────────────
        _BASTION_KW = (
            ("snmp.*sysdescr",), ("firewall",), ("fortinet", "fortigate"),
            ("palo alto",), ("cisco ios", "cisco asa"), ("sonicwall",),
            ("juniper",), ("checkpoint",), ("mikrotik",),
        )
        for kw_group in _BASTION_KW:
            if any(kw in combined for kw in kw_group):
                _tk_ba = ("bastion", ip)
                if _tk_ba not in seen_tool_target:
                    appliance = kw_group[0].replace(".*", " ")
                    try:
                        output_mgr.log_action_item(
                            item_type="config_audit",
                            recommended_tool="Bastion",
                            target=ip, ip=ip, port=port,
                            title=f"Config audit: {appliance} appliance detected",
                            description=(
                                f"SS3 identified a network appliance ({appliance}) "
                                f"at {target_str}. Bastion can audit the firewall "
                                f"ruleset for misconfigurations."),
                            hostname=hostname,
                            source_finding=title,
                            priority="HIGH",
                            metadata={"source_category": "ss3_appliance_detection"},
                        )
                        count += 1
                        seen_tool_target.add(_tk_ba)
                    except Exception:
                        pass
                break

        # ── 5. Forge: cloud / virtualisation → cloud audit ───────────
        _FORGE_KW = (
            "cloud metadata", "esxi", "kubernetes", "k8s api",
            "docker daemon", "docker api", "aws metadata",
            "azure metadata", "gcp metadata", "openstack",
            "vcenter", "vmware", "consul",
        )
        for kw in _FORGE_KW:
            if kw in combined:
                _tk_fg = ("forge", ip)
                if _tk_fg not in seen_tool_target:
                    try:
                        output_mgr.log_action_item(
                            item_type="cloud_audit",
                            recommended_tool="Forge",
                            target=ip, ip=ip, port=port,
                            title=f"Cloud audit: {kw} infrastructure detected",
                            description=(
                                f"SS3 identified {kw} at {target_str}. "
                                f"Forge can perform comprehensive cloud "
                                f"infrastructure security auditing."),
                            hostname=hostname,
                            source_finding=title,
                            priority="HIGH",
                            metadata={"source_category": "ss3_cloud_detection"},
                        )
                        count += 1
                        seen_tool_target.add(_tk_fg)
                    except Exception:
                        pass
                break

        # ── 6. Isotope: accessible file shares → deep file analysis ──
        _ISOTOPE_KW = (
            "smb null session", "smb anonymous", "nfs export",
            "ftp anonymous", "writable share", "world-readable",
        )
        for kw in _ISOTOPE_KW:
            if kw in combined:
                _tk_iso = ("isotope", f"{ip}:{kw}")
                if _tk_iso not in seen_tool_target:
                    try:
                        output_mgr.log_action_item(
                            item_type="file_analysis",
                            recommended_tool="Isotope",
                            target=target_str, ip=ip, port=port,
                            title=f"File analysis: {kw} — download and analyse",
                            description=(
                                f"SS3 found {kw} on {target_str}. "
                                f"Isotope can download accessible files and "
                                f"perform deep analysis for secrets, IOCs, "
                                f"and embedded credentials."),
                            hostname=hostname,
                            source_finding=title,
                            priority="HIGH",
                            metadata={"source_category": "ss3_file_access"},
                        )
                        count += 1
                        seen_tool_target.add(_tk_iso)
                    except Exception:
                        pass
                break

    if count:
        _vc.log(f"Action item sweep: generated {count} action item(s) "
                f"(manual testing + cross-tool recommendations)")
        print(f"{Fore.CYAN}[*] Generated {count} action item(s) "
              f"from findings (manual + cross-tool){Style.RESET_ALL}")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        if _pause is not None:
            _pause.write_stop_reason("killed_user", "KeyboardInterrupt / Ctrl-C",
                                     initiated_by="user")
        _write_crash_log("Scan interrupted by user (KeyboardInterrupt / Ctrl-C)")
        print(f"\n{Fore.YELLOW}[!] Scan interrupted by user.{Style.RESET_ALL}")
        sys.exit(0)
    except Exception as _fatal_exc:
        _fatal_tb = traceback.format_exc()
        if _pause is not None:
            _pause.write_stop_reason("crashed",
                                     f"{type(_fatal_exc).__name__}: {_fatal_exc}",
                                     initiated_by="system")
        _write_crash_log(
            f"Unhandled exception crashed the scan — "
            f"{type(_fatal_exc).__name__}: {_fatal_exc}\n{_fatal_tb}"
        )
        try:
            _vc.log(f"FATAL: {type(_fatal_exc).__name__}: {_fatal_exc}", "ERROR")
        except Exception:
            pass
        print(f"\n{Fore.RED}[!] Fatal error: {_fatal_exc}{Style.RESET_ALL}")
        sys.exit(1)
